window.EXAM_PAPERS=window.EXAM_PAPERS||{};window.EXAM_PAPERS["1756566960"]={"id":"1756566960","title":"【判断推理】逻辑判断刷题题库","group":"专项练习","items":[{"id":"1718789646800","type":"single","material":"","stem":"没有人能够否认A在这次事件中所起到的不容忽视的作用。如果上述论断为真，则下列各项说法中正确的是：","options":[{"label":"A","content":"有人想要否认A在这次事件中的作用"},{"label":"B","content":"所有人都赞同A在这次事件中的作用"},{"label":"C","content":"所有人都承认A在这次事件中没有起到作用"},{"label":"D","content":"所有人都承认A在这次事件中的作用不容忽视"}],"answer":"D","explanation":"题干中的“没有人能够否认”等价于“所有人都承认”。B选项中的“赞同”词义表达不恰当，因为“作用不容忽视”不等于“赞同这种作用”故选择D项。","no":1},{"id":"1718789646801","type":"single","material":"","stem":"许多创业成功的人士都没有漂亮的学历，但这并没有妨碍他们成功。事实告诉我们，漂亮的学历对于成功具有重要作用。但是，一个人，只要有准确的信息分析能力、高度的经济敏感和果断的个人勇气，就能很快学会如何作出正确的决定，对于一个缺少以上三种素养的人，漂亮的学历没有什么价值。<br>如果上述论断为真，则以下哪项为真：","options":[{"label":"A","content":"信息分析能力、高度的经济敏感和果断的个人勇气是创业成功的必要条件"},{"label":"B","content":"漂亮的学历是创业成功的必要条件，但不是充分条件"},{"label":"C","content":"在条件相同的情况下，学历漂亮，就会创业成功"},{"label":"D","content":"漂亮的学历对于创业者而言既不是充分条件也不是必要条件"}],"answer":"D","explanation":"根据题干最后一句可知，准确的信息分析能力、高度的经济敏感和果断的个人勇气是创业成功的充分条件，A项错误；结合前面两句可知，漂亮的学历只是对创业成功有重要作用，但既非必要条件，也非充分条件，只有D项正确。故答案选D。","no":2},{"id":"1718789646802","type":"single","material":"","stem":"如果德才兼备，就能得到提升。<br>假设（）能得出结论：小李德行有亏。","options":[{"label":"A","content":"小李很有才能，但没有得到提升"},{"label":"B","content":"小李很有才能，并且得到了提升"},{"label":"C","content":"小李才能欠缺，并且没有得到提升"},{"label":"D","content":"小李才能欠缺，但得到了提升"}],"answer":"A","explanation":"根据假言命题和选言命题的推理规则，要得出结论“小李德行有亏”，需否定充分条件假言命题的后件和选言命题的另一个肢命题。故答案选A。","no":3},{"id":"1718789646803","type":"single","material":"","stem":"某书店进一批书，包含三类：高中数学，高中语文，高中英语，每类又分三种，高一，高二，高三，该书店内部规定，这三类中最多两类同时上架。<br>如以上说法为真，则以下哪个为真：","options":[{"label":"A","content":"高中数学，三册全上，那高中语文，英语最多只能上一类"},{"label":"B","content":"高一数学，高二英语，高三语文可能会同时出现"},{"label":"C","content":"高二数学，高二语文都上则高二英语必上"},{"label":"D","content":"高一数学不上，高一语文和高一英语必上"}],"answer":"A","explanation":"由于三类中最多上两类，则数学上之后，语文和英语只能上一类，A项正确。故答案选A。","no":4},{"id":"1718789646804","type":"single","material":"","stem":"一个旅行者要去火车站，早上从旅馆出发，到达一个十字路口。十字路口分别通向东南西北四个方向，四个方向上分别有饭店、旅馆、书店和火车站。书店在饭店的东北方，饭店在火车站的西北方。<br>该旅行者要去火车站，应当往哪个方向走：","options":[{"label":"A","content":"东"},{"label":"B","content":"南"},{"label":"C","content":"西"},{"label":"D","content":"北"}],"answer":"B","explanation":"两个已知条件均涉及饭店，可以首先确定饭店的位置，根据“书店在饭店的东北方”“饭店在火车站的西北方”可以确定饭店的位置只能在西方，画图如下：<img src=\"assets/img/a6ca21ab5e1828.png\" alt=\"图片_rId6\">\n火车站在南方，故答案选B。","no":5},{"id":"1718789646805","type":"single","material":"","stem":"意大利帕维亚大学研究显示，刚刚坠入爱河的男女的大脑会发出指令，使人体分泌出一种化学物质，研究人员称这种物质为“爱情荷尔蒙”。这种化学物质令恋爱中的人相互吸引，产生拥抱时的那种安全感和满足感。有科学家认为，爱情荷尔蒙正是产生爱情的原因。<br>以下最能加强上述论证的是：","options":[{"label":"A","content":"“爱情荷尔蒙”能刺激后叶催产素的分泌，但是它在人体内仅仅能够存在大约一年时间"},{"label":"B","content":"在一些田鼠的脑中，注入一组可以不断增加荷尔蒙感受体的基因，这些田鼠会变得对异性依依不舍"},{"label":"C","content":"虽然大多数雌鼠都愿意与伴侣在一起，但如果有机会，也会发生“一夜情”，甚至抛弃“丈夫”"},{"label":"D","content":"科学家正致力于研究如何治疗“感情紊乱”，如孤独症、跟踪他人、强烈的嫉妒感等病态行为"}],"answer":"B","explanation":"题干结论为：爱情荷尔蒙是产生爱情的原因。A项未说明后叶催产素对爱情的作用，且其存在时间短，不能加强题干论证；B项为田鼠注入增加荷尔蒙感受体的基因，田鼠会变得对异性依依不舍，即荷尔蒙导致爱情的产生，加强了题干论证；C项未表明爱情荷尔蒙的作用，且田鼠的行为背弃了爱情，排除；D项科学家研究治疗其他行为，与题干论证无关。故答案选B。","no":6},{"id":"1718789646806","type":"single","material":"","stem":"近八年来，万溪村通过引进优良水稻种子，使得水稻产量大为提高，即在单位面积里，较少的投入获得了较多的收益。<br>以下哪个选项一定能支持上述结论：","options":[{"label":"A","content":"只要有优良种子，就一定能够获得大丰收"},{"label":"B","content":"优良的种子绝对能够生产出高产量的稻谷"},{"label":"C","content":"优良种子是水稻产量得到提高的重要条件之一"},{"label":"D","content":"水稻产量的提高使万溪村村民收入提高了一倍"}],"answer":"C","explanation":"题干是由于引进了优良的水稻种子而使水稻产量大为提高。A项获得大丰收、B项产出高产量都与产量提高不能等同，排除；C项说明优良种子是产量提高的重要条件之一，在两者之间建立了联系，从而支持了题干结论；D项是无关项。故答案选C。","no":7},{"id":"1718789646807","type":"single","material":"","stem":"电视屏幕面对的是一个家庭化、低互动的环境，因此这些互动内容和方式的设计需要针对电视屏幕做定制。将一些互联网内容生搬到电视上，不做重新修改的话，用户体验很差，达不到在电视上更好的效果。<br>以下哪一条属于上文结论中的默认论据：","options":[{"label":"A","content":"互联网内容具备相对较高的互动性"},{"label":"B","content":"互动性越低的内容用户体验越差"},{"label":"C","content":"目前电视上专门定制的互动内容还很少"},{"label":"D","content":"电视上的互动内容多是从互联网上生搬来的"}],"answer":"A","explanation":"前提型题目。题干由“家庭化、低互动的设计是针对电视屏幕定制的”得出“将一些互联网内容生搬到电视上，用户体验很差，达不到电视上更好的效果”的结论。要推出结论，需要在“家庭化、低互动”与“互联网内容”之间建立联系，A项说明互联网内容具备相对较高的互动性，由此可得出结论，因此A项是结论中的默认论据。B项削弱了论据；C项与题干结论无关；D项削弱了结论。故答案选A。","no":8},{"id":"1718789646808","type":"single","material":"","stem":"所谓“罢黜百家、独尊儒术”是指汉武帝采纳董仲舒建议罢黜其他学术思想，尊崇儒家学术思想的政策。汉武帝认为“罢黜百家，独尊儒术”可以达到统一思想文化的目的，进而巩固汉朝的统治。<br>以下哪项为真，最能削弱上述判断：","options":[{"label":"A","content":"“罢黜百家，独尊儒术”的主要目的是为了消灭其他学术思想"},{"label":"B","content":"“罢黜百家，独尊儒术”之后，汉朝时的其他学术思想仍在民间特别兴盛"},{"label":"C","content":"汉武帝仅在其执政的后期实行了“罢黜百家，独尊儒术”的政策"},{"label":"D","content":"历史上并无“罢黜百家，独尊儒术”一事，纯属后人的杜撰"}],"answer":"B","explanation":"题干中汉武帝的判断是“罢黜百家，独尊儒术”可以达到统一思想文化的目的，B项为真则说明达不到这一目的，削弱了题干判断。A项与题干说法一致，C、D两项均为无关项。故答案选B。","no":9},{"id":"1718789646809","type":"single","material":"","stem":"<p>曾有媒体报道，某大学将五十四名正副教授“正式解聘”，并对这一所谓教授“下课”事件欢欣鼓舞，理由是我国实质上的“终身教授”制度形同大锅饭，一来“导致高校冗员众多”，二来致使教授不思进取，抑制竞争和创新。</p><p>以下哪项为真，能有力地对上述措施提出质疑？</p>","options":[{"label":"A","content":"解聘教授会在大学教师中形成一种不安全感，增加了教师工作的后顾之忧"},{"label":"B","content":"教授应该是大学的主人，解聘教授不利于大学学术的发展"},{"label":"C","content":"大学行政领导制定的解聘条件不科学，会打击在职教授的工作积极性"},{"label":"D","content":"解聘教授并不能解决目前大学存在的一些问题，达不到预期效果"}],"answer":"D","explanation":"题干认为“解聘教授”可以解决高校冗员、教授不思进取以及竞争创新不足等问题，因此支持这一措施。D项指出，解聘教授并不能解决这些问题，也达不到预期效果，直接否定了该措施与预期目标之间的有效联系，质疑力度最强。A项只是说明可能增加教师的不安全感，属于副作用；B项表述主观，缺乏具体论证；C项只说明“解聘条件不科学”可能带来负面影响，针对的是具体执行方式，而非解聘措施本身。所以应选D。","no":10},{"id":"1718789646810","type":"single","material":"","stem":"一些城市，由于作息时间比较统一，加上机动车太多，很容易造成交通早高峰和晚高峰，市民们在高峰时间上下班很不容易，为了缓解上下班时间的交通压力，市政法顾问提议采取不同时间段上下班制度，即不同单位可以在不同的时间段上下班。<br>如果以下各项为真，最能质疑该政府顾问提议的是：","options":[{"label":"A","content":"该城市机动车数量持续增加，即使不在早晚高峰期，交通拥堵现象也时有发生"},{"label":"B","content":"许多单位的大部分工作需要员工一起讨论，集体合作才能完成"},{"label":"C","content":"上班时间段与员工的作息时间不协调，员工需要较长一段时间来调整适应，这段时间的工作效率难以保证"},{"label":"D","content":"有些单位员工的住处与单位非常近，步行即可上下班"}],"answer":"A","explanation":"市政法顾问的提议是：为了缓解人们上下班的交通压力，采取不同时间段上下班制度。A项为真说明即使错开时间上班，也会堵车，该方案不能有效地缓解交通拥堵的现象。B项单位内部的“集体合作”与不同单位错峰上班不矛盾。C、D两项均与能否缓解交通压力无关。故答案选A。","no":11},{"id":"1718789646811","type":"single","material":"","stem":"某地山区有个石灰岩洞，人们带着牛马等大牲畜通过岩洞没有任何问题，但是鸡鸭等小动物走进洞里就倒地而死，后来人们经过检查发现，小动物的死亡与吸入大量二氧化碳有关。<br>据此可以推断出：","options":[{"label":"A","content":"石灰岩洞内严重缺氧"},{"label":"B","content":"大牲畜更适应缺氧的环境"},{"label":"C","content":"人和牛马都带有吸氧设备"},{"label":"D","content":"石灰岩洞地面沉积着二氧化碳"}],"answer":"D","explanation":"结论型题目。题干指出大牲畜能通过岩洞而小动物不能，而小动物死亡的原因与吸入大量二氧化碳有关，因此A、B、C三项都不能推出，题干并没有说小动物死亡的原因是缺氧。由大牲畜能通过岩洞可知并未吸入大量二氧化碳，而大牲畜与小动物的差别在于离地高度的不同，故可以推出D项。","no":12},{"id":"1718789646812","type":"single","material":"","stem":"研究人员挑选了600多名学生，让他们在屏幕背景分别为红、蓝两色的电脑上接受测试。结果用红色背景电脑的人在记忆、校对等准确性测试方面得分较高，而使用蓝色背景电脑的人则表现出了更出色的想象力和创造力。2004年夏季奥运会上，穿红色服装的运动员在拳击、跆拳道、摔跤等比赛中的获胜率为60%。蓝天、海洋给人带来开放和宁静感。<br>由此推出：","options":[{"label":"A","content":"红色在潜意识中象征着某种优势"},{"label":"B","content":"蓝色易促使人表现出更多的创造力"},{"label":"C","content":"红色和蓝色容易影响人的认知和行为"},{"label":"D","content":"红色易使人联想起愤怒、进攻性和勇气"}],"answer":"C","explanation":"题干主要说明了红色和蓝色对人在认知实验和体育比赛方面的影响，因此C项正确。而A、B、D三项都属于主观臆断，不能由题干内容推出。","no":13},{"id":"1718789646813","type":"single","material":"","stem":"凡是色泽鲜艳的菌子都是有毒的。由此可知：","options":[{"label":"A","content":"有毒的菌子绝对是色泽鲜艳"},{"label":"B","content":"色泽鲜艳的菌子一般不能吃"},{"label":"C","content":"凡色泽不鲜艳的菌子都是无毒的"},{"label":"D","content":"有少部分色泽鲜艳的菌子没有毒"}],"answer":"B","explanation":"题干可以看成一个充分条件假言命题。A项肯后不能肯前，属于无效推理；B项有毒的菌子一般不能吃，正确；C项否前不能否后，属于无效推理；D项与题干矛盾，错误。故答案选B。","no":14},{"id":"1718789646814","type":"single","material":"","stem":"专业人士预测：如果粮食价格保持稳定，那么蔬菜价格也将保持稳定，如果食用油价格不稳，那么蔬菜价格也将出现波动。老李由此断定：粮食价格将保持稳定，但是肉类食品价格将上涨。<br>根据上述专业人士的预测，以下哪项如果为真，最能对老李的观点提出质疑：","options":[{"label":"A","content":"如果食用油价格稳定，那么肉类食品价格将会上涨"},{"label":"B","content":"如果食用油价格稳定，那么肉类食品价格将不会上涨"},{"label":"C","content":"如果肉类食品价格不上涨，那么食用油价格将会上涨"},{"label":"D","content":"如果食用油价格出现波动，那么肉类食品价格不会上涨"}],"answer":"B","explanation":"题干预测是两个充分条件假言命题，可表示为：①粮价稳定⇒菜价稳定，②油价不稳⇒菜价不稳，即粮价稳定⇒菜价稳定⇒油价稳定。老李的观点是“粮价稳定，肉类价格上涨”。B项“如果食用油价格稳定，则肉类价格不上涨”若为真，则结合题干前提可推出，如果粮价稳定，则肉类价格不上涨，与老李的观点矛盾，最能对老李的观点提出质疑。故答案选B。","no":15},{"id":"1718789646815","type":"single","material":"","stem":"丙中毒而死。为此，甲和乙受到了法官的审讯。甲：如果这是谋杀，那肯定是乙干的。<br>乙：如果这不是自杀，那就是谋杀。法官作了如下的假定：<br>（1）如果甲和乙都没有撒谎，那么这就是一次意外事故。<br>（2）如果甲和乙两人中有一人撒谎，那么这就不是一次意外事故。<br>最后的事实表明，法官的假定是正确的。则丙：","options":[{"label":"A","content":"是意外事故而死"},{"label":"B","content":"是自杀"},{"label":"C","content":"是被谋杀"},{"label":"D","content":"有可能被谋杀，也有可能自杀"}],"answer":"C","explanation":"根据题干，丙的死因有三种：意外事故、自杀和谋杀。已知法官的假定是正确的，所以，如果甲乙都说真话，那么丙死于意外。但乙肯定丙不是自杀，就是被谋杀，所以，甲、乙不可能都说真话，甲乙必有撒谎者。这样，根据法官的假定（2）可知，丙不是死于意外，他不是自杀就是被谋杀。这就说明乙的话正确，甲撒谎由此可以推出“这是谋杀，但不是乙干的”。所以正确答案为C。","no":16},{"id":"1718789646816","type":"single","material":"","stem":"爸爸问正在上高一的孩子最喜欢学习的课程。孩子回答：我不像讨厌语文那样讨厌数学，我不像讨厌英语那样讨厌物理，我不像喜欢化学那样喜欢数学，我对物理不像对语文那样喜欢。请问孩子最喜欢：","options":[{"label":"A","content":"化学"},{"label":"B","content":"物理"},{"label":"C","content":"数学"},{"label":"D","content":"语文"}],"answer":"A","explanation":"由题干孩子的回答“我不像讨厌语文那样讨厌数学”，可知孩子更喜欢数学，即数学﹥语文；同理可知物理﹥英语、化学﹥数学、语文﹥物理，综上可得：化学﹥数学﹥语文﹥物理﹥英语。故答案为A。","no":17},{"id":"1718789646817","type":"single","material":"","stem":"有四盒磁带，标号为1到4，磁带正反两面分别是民族音乐、摇滚、爵士、轻音乐四种音乐的一种，且符合以下条件：（1）每种类型的音乐都各占两面磁带；（2）比含有轻音乐的磁带号码大1的磁带上没有民族音乐；（3）1号磁带至少有一面是爵士，但没有摇滚和轻音乐；（4）2号磁带没有爵士。由上述信息可以推出下列哪项可能正确：","options":[{"label":"A","content":"磁带1两面都是爵士且磁带4一面是民族音乐一面是摇滚"},{"label":"B","content":"磁带2一面是摇滚且磁带3一面是爵士一面是摇滚"},{"label":"C","content":"磁带3两面都是民族音乐且磁带4一面是爵士一面是轻音乐"},{"label":"D","content":"磁带3一面是爵士且磁带4两面都是民族音乐"}],"answer":"B","explanation":"可采用代入法。A项，磁带1两面都是爵士且磁带4一面是民族音乐一面是摇滚，则根据条件（2）可知轻音乐只能在磁带2的正反面，则磁带3一面是民族音乐一面是摇滚，依然与条件（2）矛盾，不可能为真；B项，当磁带1是爵士和民族音乐，磁带2是摇滚和民族音乐，磁带4都是轻音乐时，符合题干所有条件，可能为真；C项，根据已知条件（2）和磁带3两面是民族音乐，则轻音乐不在磁带2上，再根据条件（3）可知轻音乐不在磁带1上，因此C项不可能为真；D项，磁带3一面是爵士且磁带4两面都是民族音乐，则根据条件（1），磁带1另一面只能是摇滚或轻音乐，与条件（3）矛盾，不可能为真。故答案选B。","no":18},{"id":"1718789646818","type":"single","material":"","stem":"某报登出了国内20家大医院的名单，名单按它们在近3年中病人死亡率的高低排序。但是，有专家指出不能把名单排列的顺序作为评这些医院的医疗水平高低的一个标准。<br>以下各项如果是真的，都能作为论据支持专家的结论，除了：","options":[{"label":"A","content":"这20家医院中，有5家依靠国家资助从国外进口了多项先进、大型和配套的医疗设备，其余的都没有"},{"label":"B","content":"有些医院，留病人住院的时间长，病人死亡率因此就较高；有些医院，及早地动员患绝症而救治无望的病人出院，病人死亡率因此就较低"},{"label":"C","content":"这20家医院中，有2家老人医院和3家儿童医院"},{"label":"D","content":"有几家医院专门负责接收周围县区医院转送的晚期癌症患者"}],"answer":"A","explanation":"加强型题目。结论是：不能把死亡率的排名作为评价医疗水平高低的标准。死亡率高低的原因是解答本题的关键。B项把求治无望的病人动员出院可能降低该医院的死亡率，C项老人医院的死亡率更高；D项接受晚期癌症患者的医院的死亡率要高。这三项均表示出影响死亡率“另有他因”，故不能以死亡率高低判断医疗水平，加强了结论。A项影响死亡率的原因是医疗设备，也属于医疗水平的范围，不能加强结论。","no":19},{"id":"1718789646819","type":"single","material":"","stem":"科研经费没有用在正道上，不仅浪费科研资源，更让部分科学研究人员迷失本心，滋生歪门邪道，影响正常活动。<br>以下哪项为真能支持上述观点：","options":[{"label":"A","content":"广东多名官员频频落马，揭露财政投入科研资金管理领域诸多乱象"},{"label":"B","content":"浙大教授陈英旭将外部公司挂课题上，贪污千万经费"},{"label":"C","content":"2014年，教育部通报称5名大学老师骗取1600多万元"},{"label":"D","content":"山东大学刘兆平通过开虚假发票等手段骗取科研经费341万"}],"answer":"B","explanation":"A、C、D三项没有体现贪污对科研项目活动的影响，B项说明贪污已经影响了正常科研活动的进行，外部公司对科研项目产生了不良影响，最能支持题干观点。故答案选B。","no":20},{"id":"1718789646820","type":"single","material":"","stem":"民主政体的法律一般保护最大多数人的利益，因为他们源于大多数的公民，这些公民易于犯错，但他们不会站在自己利益的反面。相反，寡头政治的法律有助于将财富和权力集中在少数人手中，因为从本质上看，寡头政治是由少数人建构起来的。因此可以断定，一般情况下，民主政体的立法宗旨比寡头政治的立法宗旨对人类更有益。以下哪项如果成立，最有助于削弱上述断定？","options":[{"label":"A","content":"一般说来，寡头政治的立法成本比民主政体要低，且在效率上要高"},{"label":"B","content":"相比于寡头政治，民主政体下的法律经常会出现众多漏洞，而导致整个社会的利益遭到重大损害"},{"label":"C","content":"寡头政治亦可能是精英政治，立法未必只会从自身的利益出发，而牺牲整个社会的利益"},{"label":"D","content":"从现实情况看，寡头政治国家要比民主政体国家的国民经济生产增加值更高"}],"answer":"B","explanation":"题干由民主政体和寡头政治的法律对比得出结论：民主政体的立法宗旨对人类更有益。A项说的是立法成本，与立法宗旨是否对人类更有益无关；B项说明民主政体的法律更不利于社会，削弱了结论；C项“可能”、“未必”，削弱程度不如B项；D项国民经济生产增加值更高不一定说明其法律对人类更有益，削弱程度有限。故答案选B。","no":21},{"id":"1718789646821","type":"single","material":"","stem":"统计显示，在大学生课外科技作品竞赛中，由指导教师推荐的作品所取得的成绩要好于大学生自荐的作品。因此，相较于大学生自身的问题意识、科学素养和动手能力，是否有指导教师的推荐对于一个作品能否在课外科技作品竞赛中获奖更为重要。下列哪项如果为真，最能削弱上述论证：","options":[{"label":"A","content":"指导教师比大学生本人更了解一个科技作品是否具有创新性"},{"label":"B","content":"指导教师在决定一个科技作品能否参赛时，通常要与该作品的设计者面谈，了解其问题意识、科学素养和动手能力"},{"label":"C","content":"在获奖的科技作品中，大多数都无法吸引风险投资公司的兴趣"},{"label":"D","content":"对于一个科技作品能否注册专利、能否吸引风险投资来说，指导教师的作用相较于大学生自身的素质，就显得不那么重要了"}],"answer":"B","explanation":"题干结论为“相较于大学生自身的问题意识、科学素养和动手能力，是否有指导教师的推荐对于一个作品能否在课外科技作品竞赛中获奖更为重要”。A项加强了题干论述；B项意在说明指导教师的推荐也是基于对设计者的问题意识、科学素养和动手能力的了解，直接削弱了题干结论；C、D两项为无关项。故答案选B。","no":22},{"id":"1718789646822","type":"single","material":"","stem":"一个医生在进行健康检查时，如果检查得足够彻底，就会使那些本没有疾病的被检查者无谓地饱经折腾，并白白地支付了昂贵的检查费用；如果检查得不够彻底，又可能错过一些严重的疾病，给病人一种虚假的安全感而延误治疗。问题在于，一个医生往往很难确定该把一个检查进行到何种程度。因此，对普通人来说，没有感觉不适就去接受医疗检查是不明智的。<br>以下各项如果为真，都能削弱上述论证，除了：","options":[{"label":"A","content":"有些严重疾病早期就有病人自己能察觉的明显症状"},{"label":"B","content":"有些疾病早期虽无病人能察觉的明显症状，但这些症状并不难被医生发现"},{"label":"C","content":"有些严重疾病只有经过彻底检查才能发现"},{"label":"D","content":"有些经验丰富的医生可以恰如其分地把握检查的彻底程度"}],"answer":"A","explanation":"题干的观点是：没有感觉不适就去接受医疗检查是不明智的。A项指出病人自己能够在早期感觉出疾病的明显症状，因此感觉不适后再去接受医疗检查即可，在一定程度上支持了题干的观点；而B、C、D三项均从不同的角度削弱了题干结论。故答案选A。","no":23},{"id":"1718789646823","type":"single","material":"","stem":"有3/4的医院会给患有牙龈肿痛的病人开一种叫ADPT的药物，所以说，当你不幸出现牙龈肿痛的时候，ADPT是一个非常好的选择。<br>以下哪项如果正确，最能质疑上述论断：","options":[{"label":"A","content":"有临床研究表明，与其他药物相比，ADPT更加有效"},{"label":"B","content":"与其他治疗牙龈肿痛的药物不同，即便没有医生处方，在药店也可以买到ADPT"},{"label":"C","content":"一些与ADPT相似的药物，还可以缓解牙龈肿痛以外的疼痛"},{"label":"D","content":"ADPT的价格非常昂贵，对于治疗常规的牙龈肿痛而言很不划算"}],"answer":"D","explanation":"题干论断是：患有牙龈肿痛时，ADPT是个好选择。D项，ADPT的价格昂贵、不划算，说明并不是一个好的选择，质疑了题干论断。A、B两项，说明ADPT有效、方便，是一个很好的选择，加强了题干论断。C项“牙龈肿痛以外的疼痛”与题干无关。故选择D项。","no":24},{"id":"1718789646824","type":"single","material":"","stem":"某个推销员对顾客说：机芯是洗衣机的核心部件。白鸽牌洗衣机采用与小汤姆牌洗衣机相同的机芯——产自德国菲洛品牌的高质量机芯。但是小汤姆牌洗衣机的价格远远高于白鸽牌洗衣机，所以，如果你想花少的钱却能得到好的洗衣效果，那你就应该选择购买白鸽牌洗衣机而不是小汤姆牌洗衣机。<br>以下哪项如果被证实，能合理地推出该推销员的结论：","options":[{"label":"A","content":"白鸽牌洗衣机是国产的、小汤姆牌洗衣机是进口的，白鸽牌洗衣机的保修更方便快捷"},{"label":"B","content":"推销员推销一台白鸽牌洗衣机所得到的收入比卖出一台小汤姆牌洗衣机得到的收入要多"},{"label":"C","content":"生产白鸽牌洗衣机的工厂与德国菲洛公司的合作历史悠久，而小汤姆牌洗衣机只是最近才采用德国菲洛公司的机芯"},{"label":"D","content":"洗衣机的洗衣效果仅仅是由它的机芯质量决定的"}],"answer":"D","explanation":"前提型题目。题干结论是最后一句，论据是：白鸽牌洗衣机价格更低但机芯与小汤姆牌洗衣机相同。要由论据推出结论，需要排除机芯以外的其他部件对洗衣效果的影响，即需要D项作为前提。A、B两项都明显与论证无关，C项合作时间长短与机芯质量无关，也不能作为前提。故答案选D。","no":25},{"id":"1718789646825","type":"single","material":"","stem":"根据医学理论，一个人想要健康就必须有足够的运动量，但是城里人往往是以汽车等交通工具代步，没有足够的运动量。所以，这个医学理论不成立。<br>下列最可能是上述论证的预设前提的是：","options":[{"label":"A","content":"城市生活节奏快"},{"label":"B","content":"有些城里人为了健康很注意运动"},{"label":"C","content":"以交通工具代步对城里人来说是必须的"},{"label":"D","content":"城里人不可能不健康"}],"answer":"D","explanation":"前提型题目。医学理论为“一个人想要健康就必须有足够的运动量”。这个结论不成立，说明“没有足够的运动量的人也可能健康”。题干材料指出，城里人没有足够运动量，那么必须加上前提“城里人健康”，即D项，才能说明这个医学结论不成立。","no":26},{"id":"1718789646826","type":"single","material":"","stem":"我国政府一直高度重视扶贫工作。前些年政府拨给贫困地区大量救济物资，但结果却是越救济越贫穷。后来，政府改变了政策，帮助贫困地区建立大批项目，引导当地人自己扶贫，并取得了明显成效。以下哪一项能从上述题干中推出：","options":[{"label":"A","content":"扶贫既要治穷更要治愚"},{"label":"B","content":"金钱和物质不是万能的"},{"label":"C","content":"“扶贫扶贫越扶越贫”"},{"label":"D","content":"授人以鱼不如授人以渔"}],"answer":"D","explanation":"题干由直接物资救济的失败和改变政策后建立项目自主扶贫取得成功的对比，说明直接给予别人物质上的帮助不如帮助他人自己去取得财富，D项表达最为合适，故答案选D。","no":27},{"id":"1718789646827","type":"single","material":"","stem":"S市发生了一起案件，现在警方在破案过程中，确定了犯罪是甲、乙、丙、丁四个人中的一个。通过问讯，他们提供了以下信息：<br>甲：这个案件不是我做的<br>乙：这个案件是丙做的<br>丙：这个案件不是我做的<br>丁：这个案件是乙做的<br>现在确定四个人中只有一个人说了真话，请问谁是罪犯：","options":[{"label":"A","content":"甲"},{"label":"B","content":"乙"},{"label":"C","content":"丙"},{"label":"D","content":"丁"}],"answer":"A","explanation":"乙、丙的话矛盾，必有一真一假。只有一人说真话，则甲、丁说假话，根据甲的话为假可以推出，这个案件是甲做的。故答案选A。","no":28},{"id":"1718789646828","type":"single","material":"","stem":"尽管治疗哮喘病的手段有所提高，但是在过去的10年里，哮喘病的死亡率比以前提高了一倍。死亡率的升高有两个可能的原因。其一，在过去的10年里，对哮喘病死亡的记录和以前相比变得更加广泛和准确；其二，城市污染有所增加。然而，即使在很少或者没有污染，且具有长期综合医疗记录的城市里，哮喘病的死亡率也呈急剧增加之势，因此，一定可以得出相反的结论：死亡率的升高起因于哮喘病患者为减轻症状而使用支气管吸入器。<br>下面每一项，如果正确，除了哪一项之外都可对上述论述构成支持？","options":[{"label":"A","content":"只是暂时地解除哮喘病的症状，吸入器使患者错过了其他更有益治疗的机会"},{"label":"B","content":"有证据表明，支气管吸入器使肺对空中传播的花粉更易发生过敏反应"},{"label":"C","content":"在过去20年中对哮喘病死亡的记录与过去10年中的一样准确"},{"label":"D","content":"城市人口在过去10年中增加了一倍"}],"answer":"D","explanation":"题干结论是死亡率的升高源于使用支气管吸入器。A、B两项均说明了使用吸入器的缺点，加强了结论。C项，加强了论据，因而加强了结论。D项，城市人口的增加与死亡率的提高没有关系，无法支持结论。故选D。","no":29},{"id":"1718789646829","type":"single","material":"","stem":"现在，在黄金领域进行投资将是一项有利可图的商业活动。《中国黄金》杂志的一项调查表明，该杂志读者中有88%的人正在计划最近购买一批金条，而对于黄金投资市场的研究显示，目前每年推出的金条购赎业务只能满足购买需求的70%。<br>下面哪项如果为真，最能对上文投资建议的正确性构成质疑：","options":[{"label":"A","content":"购买金条的人中大约有一半的人为了购买金条而进行抵押贷款"},{"label":"B","content":"在金条购赎业务开展的前两个星期里，金条只卖出了总数的20%"},{"label":"C","content":"购买金条的人中大约有一半的人曾经有过黄金投资行为"},{"label":"D","content":"那些宣称购买金条的人中仅仅只有20%的人最后真的购买了金条"}],"answer":"D","explanation":"题干中认为“在黄金领域进行投资是一项有利可图的行为”，依据是“调查表明有88%的人都计划购买金条，而目前推出的金条购赎业务只能满足70%”。D项则指出那些宣称购买的仅有20%的人最后购买了，因此也就不存在购赎业务不能满足的状况，也就不能证明在黄金领域进行投资有利可图，是对题干的质疑。其他几个选项均不能对题干投资建议的正确性进行质疑。故答案选D。","no":30},{"id":"1718789646830","type":"single","material":"","stem":"已知下列判断中前两个假，后两个真。<br>（1）如果A没有被录用，那么B就被录用；<br>（2）A和B两个人中只有一人被录用；<br>（3）只有A被录用，C才不被录用；<br>（4）如果C被录用，D就被录用。<br>据此可以推出：","options":[{"label":"A","content":"A和B被录用，C和D未被录用"},{"label":"B","content":"A和B未被录用，C和D被录用"},{"label":"C","content":"A和C被录用，B和D未被录用"},{"label":"D","content":"A和C未被录用，B和D被录用"}],"answer":"B","explanation":"考查复言命题推理。由题干可知（1）和（2）假，（3）和（4）真。由（1）为假可知，其矛盾命题为真，（1）为充分条件假言命题，其矛盾命题为肯定的前件和否定的后件组成的联言命题，即A没有被录用，且B没有被录用。进而由（3）为真可知，C被录用；再由（4）为真可得，D被录用。故答案选B。","no":31},{"id":"1718789646831","type":"single","material":"","stem":"一般情况下，女性比男性更为健谈。而一项涉及交谈习惯的报告显示，许多时候男性比女性更能主导谈话，在讨论中平均说出更多的词汇。因此，有人认为，以话语量衡量，两性在语言方面的差异并不大。<br>以下哪项如果为真，最不能支持上述结论：","options":[{"label":"A","content":"成年人中，女性在和同学、父母、子女谈话时，大多占据主导地位，而男性则较为收敛，要稍逊一筹"},{"label":"B","content":"在辩论赛或一些富有争议的话题中，男性往往滔滔不绝，而在涉及情感的话题中，女性则发言更多"},{"label":"C","content":"研究发现，在夫妻之间的交谈中，男女双方的平均谈话量差异不大，只是因地域不同而有差异"},{"label":"D","content":"一般年纪小的女孩比男孩平均说话更多，这与其语言学习速度较快有关；但13岁以后，男孩平均比女孩说话更多"}],"answer":"A","explanation":"题干结论为，以话语量衡量，两性在语言方面的差异并不大。A项说明，在语言方面男性要差一些，与题干结论不同，不能支持题干结论；B项说明两性各有均衡，与题干结论较一致；C项和D项也都说明男女在不同方面各有优势，与题干结论较一致。故答案选A。","no":32},{"id":"1718789646832","type":"single","material":"","stem":"<p>从人的本性来说，大部分人做了好事都希望受到表扬、得到肯定，企业也是如此。因此，做公益慈善高调一点，希望得到肯定、赢得名声、获得尊重是正常的，也是符合现代慈善理念的。</p><p>以下哪项如果为真，不能削弱上述观点：</p>","options":[{"label":"A","content":"做公益慈善目的是为了帮助别人，只要别人受到了帮助，目的就达到了"},{"label":"B","content":"一些企业高调宣传自己的公益慈善行为是为了打广告以求经济效益"},{"label":"C","content":"高调宣传慈善行为导致受助群体的信息被公开，往往会给受助群体带来伤害"},{"label":"D","content":"企业做公益慈善是一种回报社会的方式，与高调、低调无关"}],"answer":"D","explanation":"本题属于削弱论证题目。题干中给出的论点为:做公益慈善高调一点，希望得到肯定、赢得名声、获得尊重是正常的，也是符合现代慈善理念的。论据为:大部分人做了好事都希望受到表扬、得到肯定，企业也是如此。A项，做公益慈善的目的是为了帮助他人，高调做慈善还有其他的目的，不符合现代慈善理念，可以削弱;B项，企业做慈善是为了经济利益，并不是希望得到肯定、赢得名声、获得尊重，可以削弱;；C项，高调宣传慈善行为，可能会给受助群体带来伤害，不符合现代慈善理念，可以削弱;D项，企业做公益慈善是一种回报社会的方式，与高调和低调无关，无法削弱。选择D选项。","no":33},{"id":"1718789646833","type":"single","material":"","stem":"只有公司相应部门的所有员工都考评合格了，该部门的员工才能得到年终奖金：财务部有些员工考评合格了；综合部所有员工都得到了年终奖金；行政部的赵强考评合格了。如果以上陈述为真，则以下哪项可能为真：<br>Ⅰ.财务部员工都考评合格了。Ⅱ.赵强得到了年终奖金。Ⅲ.综合部有些员工没有考评合格。Ⅳ.财务部员工没有得到年终奖金。","options":[{"label":"A","content":"Ⅰ、Ⅱ"},{"label":"B","content":"Ⅱ、Ⅲ"},{"label":"C","content":"Ⅰ、Ⅱ、Ⅳ"},{"label":"D","content":"Ⅰ、Ⅱ、Ⅲ"}],"answer":"C","explanation":"由“综合部所有员工都得到了年终奖金”和题干第一句，可以推出“综合部所有员工都考评合格了”，所以，其矛盾命题“综合部有些员工没有考评合格”必定为假。由“财务部有些员工考评合格了”，不能推出“财务部员工都考评合格了”。但不排除其可能为真，即Ⅰ可能为真；同理，由题干第一句和第二句不能排除Ⅳ可能为真；由“行政部的赵强考评合格了”，可能“该部门的员工能得到年终奖金”，即Ⅱ也可能为真。故答案选C。","no":34},{"id":"1718789646834","type":"single","material":"","stem":"近来，月嫂收入成为人们讨论的热门话题。有人要求政府加强监管，并质疑月嫂的收入为何能高过一个医学博士的月薪。也有人反驳说，月嫂的收入为什么不能高过医学博士呢？月嫂收入的提高，一方面是市场调节的结果，另一方面反映了我国越来越重视体力劳动，尊重体力劳动者是社会的进步。<br>下列哪项陈述不能支持反驳者的观点：","options":[{"label":"A","content":"收入高低不完全取决于学历高低"},{"label":"B","content":"有些月嫂非常优秀，具有博士学位"},{"label":"C","content":"随着新生儿的增多，出现“一嫂难求”的现象"},{"label":"D","content":"谁能放下身段去赚辛苦钱，谁就值得尊重"}],"answer":"B","explanation":"反驳者的观点是月嫂的收入可以超过医学博士。A项支持了反驳者的观点；B项说明有些月嫂具有博士学位，不能支持；C项和D项分别说明月嫂收入提高是市场调节和尊重体力劳动者的结果，支持了反驳者的观点。故答案选B。","no":35},{"id":"1718789646835","type":"single","material":"","stem":"期望效用理论认为，人做某件事情的动机强度是该事件成功的概率与成功后获得的收益的乘积，而且从理性角度分析，当动机强度一致时，人们从事该事件的概率是一样的。但是有实验研究表明，在收益的情景中，面对两个选项：A.100%获得250元，B.有25%的可能性获得1000元，75%的可能性获得0元，则有80%的人会选择A。在损失的情景中，面对另外两个选项：C.100%损失750元，D.有75%的可能性损失1000元，有25%的可能性损失0元，则有80%的人会选择D。一般认为，选择成功概率小的行为是冒险行为，而选择成功概率大的行为是保守行为。<br>根据以上信息推断：","options":[{"label":"A","content":"可以从理性的角度用期望理论来解释该现象"},{"label":"B","content":"在收益和损失这两种情景中，人们的冒险行为是一样的"},{"label":"C","content":"在收益情景中，人们更倾向于冒险"},{"label":"D","content":"在损失情景中，人们更倾向于冒险"}],"answer":"D","explanation":"由题干可知，从理性的角度用期望理论解释不了该现象，A项错误；由题干“选择成功概率小的行为是冒险行为，而选择成功概率大的行为是保守行为”可知，在收益情景中，人们更倾向于保守；在损失情景中，人们更倾向于冒险，所以B、C两项错误，D正确。故答案选D。","no":36},{"id":"1718789646836","type":"single","material":"","stem":"科学家发现，将一定数量的银纳米粒子加入取自北极极地的土壤中后，会造成土壤中的许多种类的细菌数量减少，还会使一种有益的慢生菌全部消失。因此，科学家担心纳米粒子进入自然环境后，可能破坏土壤生态系统。<br>以下哪一项如果为真，最能打消科学家的顾虑：","options":[{"label":"A","content":"北极地区的生态环境和其他地区不一样"},{"label":"B","content":"银纳米粒子目前的应用并不广泛"},{"label":"C","content":"目前已经开发出银纳米粒子的完全替代材料"},{"label":"D","content":"银纳米粒子在自然界中的浓度与实验环境相差甚远"}],"answer":"D","explanation":"削弱型题目。科学家的顾虑是“纳米粒子进入自然环境后，可能破坏土壤生态系统”。论据是“科学家通过将一定数量的银纳米粒子加入取自北极极地的土壤中的实验，发现会造成土壤中的许多种类的细菌数量减少，还会使一种有益的慢生菌全部消失”。D项说明银纳米粒子在自然界中的浓度与实验环境相差甚远，即说明实验样本的不科学，题干论证犯了“以偏概全”的错误，削弱了科学家的顾虑。该实验是取自北极极地的土壤，A项是说北极地区的生态环境，与“取自北极极地的土壤”不是同一个概念，且A项的“不一样”程度不如D项的“相差甚远”，故削弱程度不如D项；B、C两项与题干结论无关；故答案选D。","no":37},{"id":"1718789646837","type":"single","material":"","stem":"所有秃顶的人都是很聪明的人，老王很聪明，所以，老王是秃顶的。以下哪项最能揭示上述推理的错误：","options":[{"label":"A","content":"所有的青蛙都有四条腿，但这种动物有两条腿，所以它不是青蛙"},{"label":"B","content":"龟是四条腿的爬行动物，鳄鱼是四条腿的爬行动物，所以，鳄鱼是龟"},{"label":"C","content":"所有的高考状元都高度近视，林妙一定高度近视，因为林妙是高考状元"},{"label":"D","content":"我是个粗心男人，因为所有的细心男人平时都不留胡子，而且胡子是拉渣的"}],"answer":"B","explanation":"题干的论述结构为：A是B，C是B，所以C是A。属于充分条件假言命题“肯后则肯前”的错误。<br>A项的论述结构为：A是B，C非B，所以C非A。是正确的推理。<br>B项的论述结构为：A是B，C是B，所以C是A。与题干推理错误相同。<br>C项的论述结构为：A是B，C是B，因为C是A。是正确的推理。<br>D项中涉及的概念有5个，明显与题干的论述不同。综上，故答案选B。","no":38},{"id":"1718789646838","type":"single","material":"","stem":"甲乙丙丁四人外出旅游，旅游地点为桂林、三亚、杭州、张家界。一个人只去一个地方，且每个地方都有人去。在问到他们各自去哪旅游时，甲说：“乙没有去桂林。”乙说：“丁没有去杭州。”丙说：“我去了张家界。”如果甲乙丙三人有一个人去了张家界，而且只有这个人的陈述与事实相符。那么去桂林旅游的人是：","options":[{"label":"A","content":"甲或乙"},{"label":"B","content":"乙或丙"},{"label":"C","content":"丙或丁"},{"label":"D","content":"丁或甲"}],"answer":"B","explanation":"假设甲去了张家界，则乙没有去桂林，丁去了杭州，丙没有去张家界，则丙去了桂林，乙去了三亚；假设乙去了张家界，则由甲的话为假可知，乙去了桂林，矛盾；假设丙去了张家界，则乙去了桂林，丁去了杭州，则甲只能去三亚。故可能去桂林的人是乙或丙。故答案选B。","no":39},{"id":"1718789646839","type":"single","material":"","stem":"通常来说，某件商品的价格提高了，那么它的销售量就会相应减少，除非商品的质量有所提升。然而，葡萄酒却不一样。一家特定生产商生产的葡萄酒的价格提高了，经常会导致其销售量也相应提高，哪怕葡萄酒本身并没有任何的改变。<br>以下哪项如果为真，最能解释上述论述中的矛盾之处：","options":[{"label":"A","content":"许多消费者都是根据杂志或报纸上的评论来选购葡萄酒的"},{"label":"B","content":"消费者在商店中选购葡萄酒时，倾向于根据葡萄酒的价格来评估其质量"},{"label":"C","content":"葡萄酒零售商和生产商一般会采用价格折扣来短暂地促进某一葡萄酒品种的销售量"},{"label":"D","content":"通常葡萄酒的固定消费群对于自己喜欢什么品种的葡萄酒都有自己的主见"}],"answer":"B","explanation":"题干中的矛盾在于葡萄酒的价格提高了，其销售量不但没减少，反而也相应提高。B项指出消费者倾向于根据价格来评估质量，则价格越高，质量越好，因此销售量也提高了，可以解释题干的矛盾。A项为无关项；C项“价格折扣”与题干“价格提高”不符，不能解释；D项也无法解释销售量提高的现象。故答案选B。","no":40},{"id":"1718789646840","type":"single","material":"","stem":"空气污染已成为危害人类健康的“隐形杀手”。研究表明，包括汽车尾气在内的各种悬浮颗粒物（即悬浮在大气中不易沉降的所有颗粒物，主要来源于燃料燃烧时产生的烟尘、生产加工过程中产生的粉尘以及建筑和交通扬尘）对心脏有很大损伤，而且颗粒物体积越小，这种危害越大。<br>以下哪项如果为真，不能支持上述结论：","options":[{"label":"A","content":"动物实验发现，较小颗粒物（0.18微米以下）比较大颗粒物（2.5微米以上）更容易引发心血管病变"},{"label":"B","content":"较小颗粒物直径可能只有头发丝的1%，很容易沉积在动物血管壁的脂肪物质上，进而增加罹患心脏病和中风的风险"},{"label":"C","content":"微小颗粒不容易被过滤，难以检测，日常防护不能抵御它的侵袭，因此很容易引发过敏"},{"label":"D","content":"微小颗粒会“关闭”高密度脂蛋白对人体的保护作用，从而导致动脉粥样硬化"}],"answer":"C","explanation":"题干结论是悬浮颗粒物对心脏有很大损伤，而且体积越小，危害越大。A、B、D三项均从不同角度说明了悬浮颗粒物对心脏的危害，支持了题干结论；C项说明微小颗粒会引发过敏，属于无关项。故答案选C。","no":41},{"id":"1718789646841","type":"single","material":"","stem":"小明今天上学又迟到了。班主任批评他说：“小明，你今天怎么又迟到了？”小明解释说：“因为来晚了，所以迟到了。”<br>下列说法中，正确描述了上文推论中的错误的是：","options":[{"label":"A","content":"这是一种偷换概念的说法"},{"label":"B","content":"这是一种自圆其说的说法"},{"label":"C","content":"这是一种强词夺理的说法"},{"label":"D","content":"这是一种循环论证的说法"}],"answer":"D","explanation":"迟到的意思是来晚了，班主任批评小明为什么又迟到了，而小明用来晚来解释迟到的理由，显然是一种循环论证。故答案为D。","no":42},{"id":"1718789646842","type":"single","material":"","stem":"一起诈骗案经过侦查将目标锁定在赵、李二人身上，赵、李二人都可能是诈骗犯或目击者。已知诈骗犯只说假话，而目击者则只说真话，审讯人员问赵：“你们俩人中肯定有一个是目击者？”赵回答：“没有。”则赵和李分别是：","options":[{"label":"A","content":"赵是目击者，李是诈骗犯"},{"label":"B","content":"赵和李都是目击者"},{"label":"C","content":"赵是诈骗犯，李是目击者"},{"label":"D","content":"赵和李都是诈骗犯"}],"answer":"C","explanation":"由于目击者只说真话，根据赵的回答可知赵不是目击者，只能是诈骗犯，说的是假话，则两人中必然有一个目击者，即李。故答案选C。","no":43},{"id":"1718789646843","type":"single","material":"","stem":"历时10年跟踪研究了1038名冠心病患者的实验发现运动强度和心脏健康之间的关系类似U字形曲线，每天都进行高强度锻炼的人的心血管疾病率远高于适度锻炼的人，由此说明长期高强度锻炼影响身体健康。<br>以下哪项如果为真，最能支持上述观点：","options":[{"label":"A","content":"长期进行高强度锻炼的人往往会有严重的膝盖损伤"},{"label":"B","content":"所有人的运动强度和心脏健康的关系曲线与冠心病患者类似"},{"label":"C","content":"长期高强度锻炼的人群的肌肉健康状况明显更好"},{"label":"D","content":"1038名冠心病患者包含了每个年龄段的人"}],"answer":"B","explanation":"题干推理是：通过调查1038名冠心病患者，发现高强度锻炼的人心血管疾病高于适度锻炼的人，推出结论高强度锻炼影响身体。B项所有人的运动强度和心脏健康的关系曲线与冠心病患者类似，加强了调查对象的代表性，支持了题干结论；A项严重的膝盖损伤与“心血管疾病”无关；D项虽然也能加强，但相较B项，并非影响推论的主要因素，加强力度较弱。C项削弱了题干结论。故答案选B。","no":44},{"id":"1718789646844","type":"single","material":"","stem":"近年来，A凉茶饮料的销量有了明显的增长，同时，生产该饮料的公司用于该饮料的保健效用的研发费用也同样明显的增长。业内人士认为，A凉茶饮料销量的增长，得益于其保健效用的提升。<br>以下哪项为真，最能削弱上述结论：","options":[{"label":"A","content":"在饮料消费市场中，凉茶饮料所占的份额只有10%"},{"label":"B","content":"市面上保健效用被公认为最好的B凉茶饮料的销量并不如A凉茶饮料"},{"label":"C","content":"近年来，市面上不少品牌的凉茶饮料的销售量都有了大幅度提升"},{"label":"D","content":"消费者购买A凉茶饮料，是因为该饮料的口味宜人、包装时尚"}],"answer":"D","explanation":"题干观点是最后一句，即认为A凉茶饮料销量的增长是因为其保健效用的提升。D项说明题干现象是“另有他因”，直接削弱了题干观点，是最强削弱项；A、C两项是无关项；B项B凉茶饮料的销量可能还受到其他因素的影响，削弱程度不如D项。故答案选D。","no":45},{"id":"1718789646845","type":"single","material":"","stem":"某律师事务所共有6名工作人员，这里有三个陈述：所里有的人会用Win8操作系统；所里有的人不会用Win8操作系统；主任不会用Win8操作系统。已知其中只有一个陈述为真，可以推出该所会用Win8操作系统的人数为：","options":[{"label":"A","content":"6人"},{"label":"B","content":"1人"},{"label":"C","content":"0人"},{"label":"D","content":"不能确定"}],"answer":"A","explanation":"“所里有的人会用WIN8操作系统”和“所里有的人不会用WIN8操作系统”是下反对关系，必有一真，由“只有一真”可知“主任不会用WIN8操作系统”为假，所以“主任会用WIN8操作系统”，由此可知“所里有的人会用WIN8操作系统”为真，则“所里有的人不会用WIN8操作系统”为假，进而推出所里所有的人都会用WIN8操作系统，故答案选A。","no":46},{"id":"1718789646846","type":"single","material":"","stem":"道德与法律，都是用以协调人与人之间关系的。当然，两者在协调对象、内容和手段方面都不同，但不能因为道德的作用有很大的局限性而忽视道德建设。<br>可见：","options":[{"label":"A","content":"必须加强道德建设，坚持“以德治国”的基本方针"},{"label":"B","content":"在社会生活中，只有法制才能维持人与人之间的关系"},{"label":"C","content":"必须把道德与法制结合起来，才能有效地治理社会"},{"label":"D","content":"目前，道德在协调人际关系中的作用已越来越小了"}],"answer":"C","explanation":"结论型题目。题干的描述旨在说明道德和法律两者在协调对象、内容和手段上各有不同，不能忽视道德建设。C项最好地表达了这个观点。题干没有提到要以德治国为基本方针和当前道德的协调作用，A、D两项错误；B项明显不符合题干第一句。故答案选C。","no":47},{"id":"1718789646847","type":"single","material":"","stem":"近些年，越来越多的家具制作者被称为艺术大师。但是，因为家具必须具有实用性，所以家具制作者在追求艺术的同时必须在提高家具的实用性上下工夫。正是由于这个原因，家具制作不能称为艺术。<br>以下哪项如果为真，最能作为前提支持上述结论：","options":[{"label":"A","content":"有些家具是专门用于博物馆或艺术区展示的"},{"label":"B","content":"有些艺术家比消费者更关注家具的实用性"},{"label":"C","content":"艺术家不关心他们创作出的物品的实际货币价值"},{"label":"D","content":"如果一个物品的制作者需要关注物品的实用性，那么这种制作过程就不是艺术"}],"answer":"D","explanation":"题干指出家具制作者需要提高家具的实用性，因此家具制作不能称为艺术。A、B、C三项作为前提均不能得到题干结论，只有D项是得出题干结论必需的前提。故选D。","no":48},{"id":"1718789646848","type":"single","material":"","stem":"在过去的十年里，古代宫廷小说占全部小说的销售比例从2%提高到15%。其间，对这种小说的评论也有明显增加。部分经销商认为，古代宫廷小说销量的上升得益于有促销作用的评论。<br>以下哪项如果为真，最能削弱题干中经销商的看法：","options":[{"label":"A","content":"古代宫廷小说的评论，几乎没有读者"},{"label":"B","content":"古代宫廷小说的读者中，几乎没有人读古代宫廷小说的评论"},{"label":"C","content":"古代宫廷小说评论文章的读者，几乎都不购买古代宫廷小说"},{"label":"D","content":"古代宫廷小说评论文章的作者中，包括著名的历史学家"}],"answer":"B","explanation":"题干的观点是：宫廷小说销量得益于有促销作用的评论。B项说明大部分读者并没有看过评论，也就是说评论对促进小说销量的作用不大，削弱了题干观点。D项是无关项；A、C两项虽然也能削弱，但有可能是少部分购买的读者使得小说销量上升，程度不如B项。故答案选B。","no":49},{"id":"1718789646849","type":"single","material":"","stem":"某单位拟举行一次年终晚会，工会三位职员对晚会分别提出了自己的意见：甲：假如不举行知识竞赛，那么就不要举行猜谜<br>乙：假如不举行猜谜，那么就举行知识竞赛丙：要么举行知识竞赛，要么猜谜<br>由此可以推出，能使甲、乙、丙三人同时满意的方案是：","options":[{"label":"A","content":"知识竞赛与猜谜都举行"},{"label":"B","content":"举行猜谜，不举行知识竞赛"},{"label":"C","content":"举行知识竞赛，不举行猜谜"},{"label":"D","content":"知识竞赛与猜谜都不举行"}],"answer":"C","explanation":"A、D两项不符合丙的意见；甲的意见的矛盾命题是不举行知识竞赛，且举行猜谜，即B项与甲的意见矛盾，排除。故答案选C。","no":50},{"id":"1718789646850","type":"single","material":"","stem":"“子非鱼，安知鱼乐。”“子亦非鱼，安知鱼之非乐。”下面哪一项与上述对话最为类似：","options":[{"label":"A","content":"“你为什么不读书？”“你怎么知道我没有读书？”"},{"label":"B","content":"“陈圆圆葬在昆明，你有什么证据？”“你又有什么证据说陈圆圆没葬在昆明？”"},{"label":"C","content":"“你为什么要迟到？”“难道只有你可以迟到吗？”"},{"label":"D","content":"“你不是我，怎么知道我的痛苦？”“我如果是你，我就不会那么痛苦了。”"}],"answer":"B","explanation":"题干中两个人是围绕“鱼到底快不快乐”展开，都是通过很难提出证据说明相反情况存在来证明自己的观点，且两人的观点针锋相对。B项的对话与此类似，围绕“陈圆圆是否葬在昆明”展开，且观点针锋相对。C项明显与题干不同，A项的前半句、D项的后半句也与题干的形式不同，故答案选B。","no":51},{"id":"1718789646851","type":"single","material":"","stem":"某国最大的方便面生产企业计划于4月份把方便面价格提高一至两成，这将是该国方便面价格自2006年度以来又一次大幅上涨，逼近历史最高价。该企业表示，之所以要提高方便面价格，主要是为了应对粮食等原材料价格的上涨。<br>最能支持上述论断的一项是：","options":[{"label":"A","content":"面对国际市场粮食等原材料价格上涨的趋势，甲国政府出台政策，禁止国内粮食加工企业提高粮食产品价格，以防止甲国人民生活成本增加，负担加重"},{"label":"B","content":"乙国国内粮食等原料供应充足，但由于劳动力价格上涨，导致粮食加工企业生产成本增加，因而造成方便面等粮食产品价格上涨"},{"label":"C","content":"丙国国内粮食等原料供应一直非常充足，近来又大规模提高农业生产技术，提高粮食产量，该国的方便面等粮食产品价格平稳"},{"label":"D","content":"丁国粮食加工企业工人举行大罢工，导致该国粮食加工企业瘫痪，国内方便面等粮食产品供应不足，丁国不得不依赖进口粮食产品"}],"answer":"A","explanation":"题干观点是“之所以提高方便面价格，主要是为了应对粮食等原材料价格的上涨”。<br>A项说明国际市场粮食等原材料价格确实上涨，且这些原材料价格的上涨可能导致粮食产品价格的上涨，直接支持了题干论断。B、D两项都说明方便面价格的上涨可能“另有他因”，削弱了结论；C项也说明粮食等原料价格与方便面的价格有关系，但并没有明确指出价格上涨的问题，支持力度不如A项。因此，正确答案是A。","no":52},{"id":"1718789646852","type":"single","material":"","stem":"一位高中生在互联网上贴出了鉴别地沟油的方法。他的方法是这样的：橄榄油零下十多度才凝结，普通植物油也要零度，而地沟油在8℃即凝结。将自家购买的食用油放进温度8℃左右的冰箱，如凝结，即为“地沟油”。<br>最能对上述推论方法提出质疑的一项是：","options":[{"label":"A","content":"有些食用油的成分并不全都是植物油"},{"label":"B","content":"有些地沟油在8℃左右不会凝结"},{"label":"C","content":"有些正品的食用油在8℃左右也会凝结"},{"label":"D","content":"高中生的推论方法未经过权威科学实验证明，不可信"}],"answer":"C","explanation":"题干鉴别地沟油的方法是：将自家购买的食用油放进温度8℃左右的冰箱，如凝结，即为“地沟油”。其隐含的假设是所有在8℃左右凝结的食用油都是地沟油，即凝结→是地沟油。如果C项为真，则说明并非所有在8℃左右凝结的食用油都是地沟油，直接质疑了该方法。A、D两项与题干结论无关；B项是说有些地沟油在8℃左右不会凝结，否定了前件，属于无效推理，故不能质疑该方法。故答案选C。","no":53},{"id":"1718789646853","type":"single","material":"","stem":"公司有人建议，只要员工都在承诺书上签字承诺不迟到，公司就取消上下班打卡制度，如果有人迟到那么所有员工的当月奖金均被扣除，公司采纳了建议，结果还是有员工迟到，但员工小刘仍拿到了奖金。从这段文字可以推出：","options":[{"label":"A","content":"小刘从未迟到过"},{"label":"B","content":"其他员工没有拿到奖金"},{"label":"C","content":"公司有人没在承诺书上签字"},{"label":"D","content":"迟到的人不是该公司的正式员工"}],"answer":"C","explanation":"题干包含两个充分条件假言命题，其中第二个充分条件假言命题是依赖“公司取消上下班打卡制度”为条件的，即“如果公司取消上下班打卡制度，那么‘如果有人迟到那么所有员工的当月奖金均被扣除’”，是多重假言命题。“有员工迟到，但是员工小刘仍拿到了当月奖金”即否定了这一多重假言命题的后件，可以推出否定的前件，即公司并未取消上下班制度；则否定了第一个充分条件假言命题的后件，根据有效推理规则，可以推出否定的前件，有员工没有在承诺书上签字，C项正确。","no":54},{"id":"1718789646854","type":"single","material":"","stem":"美国南加州大学的科学报告说，他们在实验鼠脑部的海马区植入电极，训练它们进行一系列杠杆操作并给予相应奖励，并通过电极记录这一过程中实验鼠的脑部活动。此前的研究表明，海马区能把短期记忆转换成长期记忆。科学家随后在实验鼠的海马区注入某种物质，阻断与长期记忆有关的神经信号。观察表明，这使实验鼠忘记了所受的训练。然而，当研究人员用电极向实验鼠脑部输入信号、模拟训练过程中的脑部活动时，实验鼠又暂时记起了正确的操作顺序。但是如果输入的是打乱过的信号，就没有这种效果。<br>以下推论正确的是：","options":[{"label":"A","content":"实验鼠大脑的海马区如果受到损害，将无法记起刚刚学过的内容"},{"label":"B","content":"向大脑输入特定序列的电信号，可以为实验鼠重建失去的记忆"},{"label":"C","content":"将某项工作编辑成特定的信号输入大脑，可以让人自动学会该项工作"},{"label":"D","content":"实验鼠学习杠杆操作的过程，就是海马区处理和传输神经信号的过程"}],"answer":"B","explanation":"根据研究人员向实验鼠脑部输入电信号后，实验鼠又记起之前所受的训练，可知B项正确；题干中只是在实验鼠海马区注入某种阻断神经信号的物质，并未损害海马区，A项错误；题干论述的是实验鼠，而C项的主体是人，属于偷换概念；D项“就是”属于过度推断，错误。故答案选B。","no":55},{"id":"1718789646855","type":"single","material":"","stem":"众所周知，西医利用现代科学技术手段可以解决很多中医无法解决的病症，而中医依靠对人体经络和气血的特殊理解也治愈了很多令西医束手无策的难题。据此，针对某些复杂疾病，很多人认为中西医结合的治疗方法是有必要的。<br>上述这些人在论断时作的假设是：","options":[{"label":"A","content":"针对这些疾病的中医和西医的治疗方法可以相互结合，扬长避短"},{"label":"B","content":"这些疾病单独用中医疗法或者单独用西医疗法并不能有效治疗"},{"label":"C","content":"针对这些疾病，医疗界已经掌握了中西医疗法结合的方法"},{"label":"D","content":"针对这些疾病，医学界已经尝试了中西医结合的疗法并取得了良好的效果"}],"answer":"B","explanation":"题干论断为：针对某些复杂的疾病，很多人认为中西医结合的治疗方法是有必要的。如果这些疾病单独用中医或者西医都能单独治疗，那么中西医结合就完全没有必要了。因此B项是作出题干论断时必须假设的。A项二者是否能结合、C项和D项二者结合的现状都不是作出“有必要中西医结合治疗”这个论断时必须假设的。因此答案选B。","no":56},{"id":"1718789646856","type":"single","material":"","stem":"某大型晚会的导演组在对节目进行终审时，有六个节目尚未确定是否通过，这六个节目分别是歌曲A、歌曲B、相声C、相声D、舞蹈E和魔术F，综合考虑各种因素，导演组确定了如下方案：<br>（1）歌曲A和歌曲B至少要上一个；<br>（2）如果相声C不能通过或相声D不能通过，则歌曲A也不能通过；<br>（3）如果相声C不能通过，那么魔术F也不能通过；<br>（4）只有舞蹈E通过，歌曲B才能通过。<br>导演组最终确定舞蹈E不能通过。由此可以推出：","options":[{"label":"A","content":"无法确定魔术F是否能通过"},{"label":"B","content":"歌曲A不能通过"},{"label":"C","content":"无法确定两个相声节目是否能通过"},{"label":"D","content":"歌曲B能通过"}],"answer":"A","explanation":"E不能通过，根据（4）必要条件“否前否后”可知，B不能通过，又根据（1）可知A可以通过，再根据（2）充分条件“否后否前”可知C和D都能通过，再根据（3）充分条件“否定前件无法进行有效推理”可知无法确定F是否能通过。故答案选A。","no":57},{"id":"1718789646857","type":"single","material":"","stem":"有黄、绿、红三个盒子，分别写有三句话，其中只有一个盒子放有一颗珍珠。三个盒子上刻的三句话分别是：<br>（1）黄盒子：“珍珠不在此盒中。”<br>（2）绿盒子：“珍珠在红盒中。”<br>（3）红盒子：“不在此盒中。”<br>已知上述三句话只有一句话为真，那么珍珠所在盒子是：","options":[{"label":"A","content":"绿盒子"},{"label":"B","content":"黄盒子"},{"label":"C","content":"红盒子"},{"label":"D","content":"不能确定"}],"answer":"B","explanation":"由题干可知，绿盒子的话和红盒子的话为矛盾关系，必有一真一假，由三句话中只有一句话为真可知黄盒子的话为假，即珍珠在黄盒子中。故答案选B。","no":58},{"id":"1718789646858","type":"single","material":"","stem":"有些不是鱼的动物外表像鱼。与以上判断等值的是：","options":[{"label":"A","content":"有些外表像鱼的动物不是鱼"},{"label":"B","content":"有些外表像鱼的动物是鱼"},{"label":"C","content":"有些不是鱼的动物外表不像鱼"},{"label":"D","content":"有些鱼外表不像鱼"}],"answer":"A","explanation":"直言命题推理。“有些不是鱼的动物外表像鱼”等价于“有些外表像鱼的动物不是鱼”，即答案选A。","no":59},{"id":"1718789646859","type":"single","material":"","stem":"<p>下面是一段教授跟学生的对话，教授说：“在长子继承权的原则下，男人的第一个妻子生下第一个男性婴儿总是首先有继承家庭财产的权利。”学生说：“那不正确，华尔顿夫人是其父亲的唯一妻子的唯一活着的孩子，她继承了他所有遗产。”学生误解了教授的意思，他理解为：</p>","options":[{"label":"A","content":"男人才可以是孩子的父亲"},{"label":"B","content":"女儿不能算是第一个出生的孩子"},{"label":"C","content":"只有儿子才能继承遗产"},{"label":"D","content":"私生子不能继承遗产"}],"answer":"C","explanation":"学生的观点是：华尔顿夫人并不是男性婴儿，却继承了财产，因此教授的话是不正确的。即学生将教授的话理解为只有儿子才能继承遗产。故答案选C。","no":60},{"id":"1718789646860","type":"single","material":"","stem":"一所好的学校必然是由多方面因素造成的：要有好的生源，要有好的师资力量，要有好的教学方法和教学管理，上述条件缺一不可。<br>据此，以下论述正确的是：","options":[{"label":"A","content":"有好的生源就能成为好的学校"},{"label":"B","content":"有好的师资必然是好的学校"},{"label":"C","content":"好的教学方法是成为好的学校的必要条件"},{"label":"D","content":"好的教学管理是好学校的最重要标志"}],"answer":"C","explanation":"由题干可知，好的生源、好的师资力量、好的教学方法和教学管理三者一同构成好的学校的必要条件。根据必要条件推理规则，A、B两项错误，C项正确，D项“最重要标志”由题干无法得出，因此答案选C。","no":61},{"id":"1718789646861","type":"single","material":"","stem":"储存在专业电脑中的某财团的商业核心机密被盗窃。该财团的三名高级雇员甲、乙、丙三人涉嫌被拘审。经审讯，查明了以下事实：<br>第一，机密是在电脑密码被破解以后窃取的；破译电脑密码必须受过专门训练。第二，如果甲作案，那么丙一定参与。<br>第三，乙没有受过破译电脑密码的专门训练。第四，作案者就是这三人中的一人或一伙。从上述条件，可推出以下哪项结论？","options":[{"label":"A","content":"作案者中有甲"},{"label":"B","content":"作案者中有乙"},{"label":"C","content":"作案者中有丙"},{"label":"D","content":"作案者中有甲和丙"}],"answer":"C","explanation":"由“机密是在电脑密码被破解以后窃取的；破译电脑密码必须受过专门训练”和“乙没有受过破译电脑密码的专门训练”可知，乙无法破译电脑密码，所以无法窃取机密，所以乙不可能单独作案。假设丙不是作案者，则由“如果甲作案，那么丙一定参与”，否定后件就能否定前件，甲也不是作案者，与“作案者就是这三人中的一人或一伙”矛盾；所以，丙一定是作案者。但肯定后件并不能肯定前件，因此甲是否参与并不能推出。","no":62},{"id":"1718789646862","type":"single","material":"","stem":"在一次奥运会中，甲、乙、丙是来自美国、俄罗斯和中国的选手，他们获得了金、银、铜三块奖牌。已知：Ⅰ.甲的成绩比俄罗斯选手成绩好；Ⅱ.中国选手的成绩比乙的差；Ⅲ.丙的成绩不如中国选手。<br>以下哪项肯定为真？","options":[{"label":"A","content":"甲、乙、丙分别获得了金、银、铜牌"},{"label":"B","content":"美国选手是冠军，俄罗斯选手是亚军，中国选手是季军"},{"label":"C","content":"甲、乙、丙分别来至美国、中国、俄罗斯"},{"label":"D","content":"乙是美国选手，甲是中国选手，分别获得金牌、银牌"}],"answer":"D","explanation":"由“中国选手的成绩比乙的差”和“丙的成绩不如中国选手”可知中国选手是甲。则有乙＞甲（中国）＞丙，再由“甲的成绩比俄罗斯成绩好”，可得乙（美国）＞甲（中国）＞丙（俄罗斯）。故答案选D。","no":63},{"id":"1718789646863","type":"single","material":"","stem":"甲企业生产和销售与乙企业一样的仪表。甲企业和乙企业中员工的工资都占了生产仪表成本的40%。甲企业正在寻求强于乙企业的竞争优势。因此，为促使达到这个目的，甲企业应该降低员工的工资。<br>以下哪项如果是正确的，将最能削弱以上论述？","options":[{"label":"A","content":"因为他们生产少量的精密仪器，仪表制造商们不能在原材料上获得批量折扣"},{"label":"B","content":"工资降低会降低员工工作质量，这种质量降低将导致销量的下降"},{"label":"C","content":"甲企业去年抢走了乙企业20%的生意"},{"label":"D","content":"甲企业付给它的员工的工资，平均来说，比乙企业高10%"}],"answer":"B","explanation":"“工资降低”→“降低员工工作质量”→“导致销量下降”，继而公司的销售额会下降。所以B项无法达到提高公司竞争优势这一根本的目的。","no":64},{"id":"1718789646864","type":"single","material":"","stem":"甲：“你不能再抽烟了。抽烟确实对你的健康非常不利。”<br>乙：“你错了，我这样抽烟已经15年了，但没有患肺癌，上个月我才做的体检。”有关上述对话，以下哪项如果为真，最能加强和支持甲的意见？","options":[{"label":"A","content":"对健康的危害不仅指患肺癌或其他明显疾病，还包括潜在的影响"},{"label":"B","content":"如果不断抽烟，那么烟瘾将越来越大，以后就更难戒除了"},{"label":"C","content":"抽烟不仅影响健康，而且还污染环境"},{"label":"D","content":"与名牌的优质烟相比，冒牌劣质烟对健康的危害更甚"}],"answer":"A","explanation":"题干中乙用自己没有患肺癌来反驳甲的话：吸烟不利健康。A项指出吸烟对健康的危害包括很多种以及潜在影响，即使没患肺癌也不能否定吸烟有害健康，最能加强和支持甲的意见。B、C、D三项均为无关项。故答案选A。","no":65},{"id":"1718789646865","type":"single","material":"","stem":"一项新的研究表明，存在于舌头上的能检测甜味的蛋白质，也存在于肠道。研究人员据此推测，肠道同样能尝出糖果的味道。这项研究的负责人说：“其实，肠道与舌头品尝甜味的方式是一样的。”<br>下列哪项最能支持上述推测？","options":[{"label":"A","content":"只要有这种检测甜味的蛋白质，就能尝到甜味"},{"label":"B","content":"除了甜味，肠道还能尝到酸味"},{"label":"C","content":"除了肠道，还有其它器官能够尝到甜味"},{"label":"D","content":"味觉可以通过其它感觉表达出来"}],"answer":"A","explanation":"加强型题目。题干由“肠道和舌头上都存在一种能检测甜味的蛋白质”，推测出“肠道也能品尝到甜味”。<br>A项如果为真，根据肠道中存在这种蛋白质，即可推出肯定的后件，也即题干的推测，从而支持了题干推测。肠道是否能尝到酸味、是否有其它器官能尝到甜味、味觉是否能通过其它感觉表达出来，都与题干的推理无关，B、C、D三项都是无关项。故答案选A。","no":66},{"id":"1718789646866","type":"single","material":"","stem":"有研究资料表明，颈椎病患者往往缺钙，而大量实际事例表明，通过食用钙片可改善人体内缺钙的状况，因此有人认为，可以通过食用钙片来治疗颈椎病。<br>以下哪项最可能是上述观点依赖的假设？","options":[{"label":"A","content":"在食用钙片的过程中不会产生副作用"},{"label":"B","content":"具体服用钙片的量与颈椎病患者的年龄有关"},{"label":"C","content":"颈椎病患者体内钙的缺乏量不会因为其他原因而有太大变化"},{"label":"D","content":"钙的缺乏是导致颈椎病的原因，而不是颈椎病引起的结果"}],"answer":"D","explanation":"题干指出可通过食用钙片来补钙从而治疗颈椎病，所以需要的假设就是钙与颈椎病之间的关系，即缺钙会导致颈椎病，而不是颈椎病导致了缺钙。","no":67},{"id":"1718789646867","type":"single","material":"","stem":"研究表明，由于啤酒含有碳酸，刺激胃和肠蠕动，加快人体血液循环和吸收，所以在同等酒精浓度的情况下，喝啤酒比喝白酒更容易醉。但根据统计，人们喝白酒时酒醉的几率比喝啤酒时要大得多。<br>以下哪一项如果成立，可以解释上述现象？","options":[{"label":"A","content":"很多人更爱喝白酒，因为喝白酒更能调动气氛"},{"label":"B","content":"不少人把白酒和啤酒混着喝，导致喝醉"},{"label":"C","content":"喝啤酒比喝白酒感觉胃会更好受些"},{"label":"D","content":"现在人们常喝的白酒的酒精浓度普遍比啤酒要高很多"}],"answer":"D","explanation":"题干中存在的矛盾是：同等酒精浓度的情况下，喝啤酒比喝白酒更容易醉，但是喝白酒时酒醉的几率比喝啤酒时要大得多。A、B项不能体现出啤酒和白酒在导致人醉酒方面有何不同，C项若为真则应推导出啤酒更易多喝更易让人喝醉，均排除。D项说明白酒的酒精浓度比啤酒高很多，即少量的白酒所含的酒精即可让人喝醉，很好的解释了题干的矛盾。因此答案为D。","no":68},{"id":"1718789646868","type":"single","material":"","stem":"钱财如粪土，仁义值千金，所以，仁义如粪土。这个推理与以下哪个选项的逻辑结构最为一致？","options":[{"label":"A","content":"凡属中华人民共和国政府管辖的都是中国人，美国人不受中华人民共和国政府管辖，所以，美国人不是中国人"},{"label":"B","content":"所有成功人士都要穿衣吃饭，我要穿衣吃饭，所以，我是成功人士"},{"label":"C","content":"商品都有使用价值，空气当然有使用价值，所以，空气当然是商品"},{"label":"D","content":"所有技术骨干都是刻苦学习的人，小张是技术骨干，所以，小张是刻苦学习的人"}],"answer":"D","explanation":"题干推理的结构是：所有P是Q，R是P，所以R是Q。<br>A项的推理结构为：所有P是Q，R不是P，所以R不是Q。与题干推理不同。<br>B项和C项的推理结构均为：所有P是Q，R是Q，所以R是P。也与题干推理不同。<br>D项的推理结构为：所有P是Q，R是P，所以R是Q。与题干结构一致。故答案选D。","no":69},{"id":"1718789646869","type":"single","material":"","stem":"医学家指出：吸烟者不一定都患肺癌，但不少肺癌患者都有10年至20年以上的吸烟史，其中绝大多数是烟瘾过大者。<br>由此可以推出：","options":[{"label":"A","content":"吸烟与肺癌没有关系"},{"label":"B","content":"肺癌与吸烟特别是大量吸烟有很大关系"},{"label":"C","content":"肺癌患者都是烟瘾过大者"},{"label":"D","content":"肺癌患者都有10年至20年的吸烟史"}],"answer":"B","explanation":"由题干知，肺癌和吸烟有关系，A项错误；由“绝大多数是烟瘾过大者”知C项错误；由“不少肺癌患者都有10年至20年以上的吸烟史”知D项错误。故答案选B。","no":70},{"id":"1718789646870","type":"single","material":"","stem":"伦敦经济学院教授理查德·莱亚德说：“我们的生活存在悖论。多数人希望收入越来越高，并为此不懈努力。但是尽管西方社会越来越富足，人们却没有感到越来越幸福。”经济增长并不一定让人们更幸福，大众追求物质财富往好处说是徒劳的，可能性更大的结果是让人更加不幸福。<br>根据理查德·莱亚德的观点，下列说法正确的是：","options":[{"label":"A","content":"幸福和人们的收入没有关系"},{"label":"B","content":"收入越高的人就越不幸福"},{"label":"C","content":"要幸福的人就不应该有高收入"},{"label":"D","content":"幸福不只是通过收入来衡量"}],"answer":"D","explanation":"结论型题目。文中写的是幸福与收入之间的关系，虽然并不一定收入越高就越幸福，但也不能得出这二者没有关系，A项错误；B、C两项过于绝对，明显错误；而文中观点为尽管人们收入越来越富足，但却没感到越来越幸福，由此可以得出D项。","no":71},{"id":"1718789646871","type":"single","material":"","stem":"要制服坏人，有时候要以坏治坏，以小坏对付大坏，以假坏对付真坏，坏人也会做好事，但好人只要做过坏事就变成坏人。<br>由此可以推出：","options":[{"label":"A","content":"好人不可能制服坏人"},{"label":"B","content":"世界上不可能有好人"},{"label":"C","content":"做过好事的人未必是好人"},{"label":"D","content":"做过坏事的人未必是坏人"}],"answer":"C","explanation":"由“坏人也会做好事”可以推出C项。故正确答案为C。","no":72},{"id":"1718789646872","type":"single","material":"","stem":"懂得接受失败的人，才会真正理解“虚怀若谷，谦虚谨慎”这八个字，也只有懂得接受自己的失败，才能更好地去发挥自己的优势，也才能更好地去实现自我。<br>如果以上为真，则以下哪项为真？","options":[{"label":"A","content":"懂得接受失败的人都能真正理解“虚怀若谷，谦虚谨慎”"},{"label":"B","content":"坦然接受失败的人比一味追求成功更容易发挥自身的优势"},{"label":"C","content":"成功实现自我的人都通过失败学会了发挥自身优势"},{"label":"D","content":"不懂得接受失败的人不能真正理解“虚怀若谷，谦虚谨慎”"}],"answer":"D","explanation":"题干是必要条件假言命题，其逻辑关系为：①真正理解“虚怀若谷，谦虚谨慎”这八个字⇒懂得接受失败的人；②实现自我⇒发挥自己的优势⇒懂得接受自己的失败。A项肯定①的后件不能肯定前件，错误；B项从题干推理不能得出；C项，由“发挥自己的优势⇒懂得接受自己的失败”无法推出“通过失败学会了发挥自身优势”；D项否定①的后件可以推出否定的前件，正确。故答案选D。","no":73},{"id":"1718789646873","type":"single","material":"","stem":"<p>没有人力资本就不可能存在社会再生产。人力资本来源于人类自身的再生产，而商业资本和货币资本等其他资本来源于社会再生产。</p><p>由此可以推出：</p>","options":[{"label":"A","content":"人力资本越丰富货币资本便越多"},{"label":"B","content":"人类自身的再生产会影响货币资本的规模"},{"label":"C","content":"社会再生产不会影响人类自身的再生产"},{"label":"D","content":"人类自身的再生产与社会再生产同时存在"}],"answer":"D","explanation":"“没有人力资本就不可能存在社会再生产”说明社会再生产以人力资本为必要条件，而人力资本来源于人类自身的再生产，因此社会再生产存在时，人类自身的再生产也应存在。A、B涉及数量或规模关系，题干没有说明；C也无法推出。因此选D。","no":74},{"id":"1718789646874","type":"single","material":"","stem":"某公共娱乐场所发生了一起恶性火灾事件，造成了重大经济损失和人员伤亡。现场的人有以下猜测：<br>甲：发生事故的原因是舞台燃放烟花所致。<br>乙：有人故意纵火，发生事故的原因不是舞台燃放烟花所致。丙：如果发生事故的原因是舞台燃放烟花所致，则有人故意纵火。丁：发生事故的原因是舞台燃放烟花所致，但没有人故意纵火。如果上述四人的断定只有一个人为真，则以下哪一项可能为真？","options":[{"label":"A","content":"甲的断定为真"},{"label":"B","content":"乙的断定为真"},{"label":"C","content":"丁的断定为真"},{"label":"D","content":"丙的断定为真，没有人故意纵火"}],"answer":"D","explanation":"考查复言命题的矛盾关系。丙的猜测是一个充分条件假言命题，其矛盾命题是“p且非q”，即丁的猜测，故丙和丁的猜测必有一真一假，则甲和乙的猜测都为假。由甲的猜测为假可知，发生事故的原因不是舞台燃放烟花所致，乙的后半句为真。乙的猜测是一个联言命题，其为假至少有一个肢命题为假，所以乙的前半句为假，即没有人故意纵火。故丙的猜测为真，丁的猜测为假，没有人故意纵火。答案选D。","no":75},{"id":"1718789646875","type":"single","material":"","stem":"对某班学生喜欢的体育活动进行调查后发现：该班的学生或者喜欢打篮球，或者喜欢打羽毛球；如果喜欢打排球，则不喜欢打羽毛球；该班的班长喜欢打排球，因此他也喜欢打乒乓球。<br>以下哪项最可能是上述论证的假设？","options":[{"label":"A","content":"该班的班长至少喜欢三项体育活动"},{"label":"B","content":"喜欢打乒乓球的学生都喜欢打羽毛球"},{"label":"C","content":"喜欢打篮球的学生都喜欢打乒乓球"},{"label":"D","content":"该班学生喜欢的体育活动只有篮球、羽毛球、排球和乒乓球四项"}],"answer":"C","explanation":"结合题干条件，由“如果喜欢打排球，则不喜欢打羽毛球”和“班长喜欢打排球”可推出“班长不喜欢打羽毛球”，再由“该班学生或者喜欢打篮球，或者喜欢打羽毛球”可推出“班长喜欢打篮球”，要推出班长喜欢打乒乓球，需要保证“喜欢打篮球的学生都喜欢打乒乓球”，即C项。","no":76},{"id":"1718789646876","type":"single","material":"","stem":"某学院的一个宿舍住着四个留学生，分别来自美国、英国、俄罗斯和瑞典。他们分别在中文、国际贸易和社会学三个系就读，其中：<br>①瑞典留学生单独在国际贸易系<br>②俄罗斯留学生不在中文系<br>③美国留学生和另外某个留学生在某个系<br>④英国留学生不和美国留学生同在一个系<br>以上条件可以推出美国留学生所在的系为：","options":[{"label":"A","content":"中文系"},{"label":"B","content":"国际贸易系"},{"label":"C","content":"社会学系"},{"label":"D","content":"中文系和社会学系都可以"}],"answer":"C","explanation":"由①②可知俄罗斯留学生在社会学系，根据①③④可知美国留学生只能和俄罗斯留学生在一个系，即美国学生也在社会学系。故答案为C。","no":77},{"id":"1718789646877","type":"single","material":"","stem":"某公司下设公关部、财务部、产品销售部和人力资源部四个部门，部门经理分别由赵、钱、孙、李四位担任，其中人力资源部经理不是李经理就是孙经理，产品销售部经理比财务部经理的工资要低，人力资源部经理比公关部经理的工资高，赵经理比财务部经理的工资高，孙经理比钱经理的工资低。<br>根据以上条件，几位经理所属的部门可以确定？","options":[{"label":"A","content":"1位"},{"label":"B","content":"2位"},{"label":"C","content":"3位"},{"label":"D","content":"4位"}],"answer":"D","explanation":"由人力资源部经理不是李经理就是孙经理可知，赵、钱不是人力资源部经理；由题干中对四部门工资比较可知，人力资源部＞公关部，财务部＞产品销售部；由赵＞财务部可知赵经理不是财务部经理也不是产品销售部经理，则赵为公关部经理。四部门的工资比较为：人力资源部＞公关部（赵）＞财务部＞产品销售部。又孙＜钱，则孙不是人力资源部经理，即李是人力资源部经理。则钱是财务部经理且孙是产品销售部经理。因此答案为D。","no":78},{"id":"1718789646878","type":"single","material":"","stem":"学校组织学生春游，共60名学生，男女生各半。有40个学生喜欢划船，50个学生喜欢登山。这表明可能会有：","options":[{"label":"A","content":"20个男生喜欢划船而不喜欢登山"},{"label":"B","content":"20个喜欢登山的男生不喜欢划船"},{"label":"C","content":"30个喜欢登山的女生不喜欢划船"},{"label":"D","content":"30个喜欢划船的男生只有10个喜欢登山"}],"answer":"B","explanation":"由于一共60人，所以最少有30人同时喜欢登山和划船，则只喜欢划船的人最多有40-30=10人，A错误。只喜欢登山的人最多有50-30=20人，B正确，C错误。不喜欢登山的人有60-50=10个，D错误。故答案选B。","no":79},{"id":"1718789646879","type":"single","material":"","stem":"光线的照射，有助于缓解冬季忧郁症。研究人员曾对九名患者进行研究，他们均因冬季白天变短而患上冬季忧郁症。研究人员让患者在清晨和傍晚各接收三小时伴有花香的强光照射。一周之内，七名患者完全摆脱了抑郁，另外两人也表现出了显著的好转。由于光照会使人误以为夏季已经来临，这样便治好了冬季忧郁症。<br>以下哪项如果为真，最能削弱上述论证的结论？","options":[{"label":"A","content":"研究人员在强光照射时有意使用花香伴随，对于改善冬季忧郁症患者的适应症有不小的作用"},{"label":"B","content":"该试验均在北半球的温带气候中，无法区分南北半球的实验差异，但也无法预先排除"},{"label":"C","content":"九名患者中最先痊愈的三位均为女性，而对男性患者治疗效果较为迟缓"},{"label":"D","content":"每天六小时的非工作状态，改变了患者原来的生活环境，改善了他们的心态，这是对抑郁患者的主要影响"}],"answer":"D","explanation":"题干通过有光照和无光照情况下患者情况的对比，推出光照有助于缓解冬季忧郁症。A项指出花香有可能影响实验，削弱了题干。B项与实验无关。C项男女性患者治疗效果的差异对题干的结论没有影响。D项说明患者好转的主要原因是改变了生活环境，而不是光照，直接削弱了题干论证，削弱程度强于A项。故答案选D。","no":80},{"id":"1718789646880","type":"single","material":"","stem":"为了调查当代大学生的阅读现状，某调查小组列举了40部文学作品，请60名在校大学生选择他们已经阅读或正在阅读的作品。调查结果显示：大多数大学生只读过或正在阅读其中的6到8部作品，仅少数大学生读过30部以上，甚至有的大学生一部也没有读过。其中，《小时代》读过的人最多，60个人中有50个大学生都读过或正在阅读；《安娜·卡列尼娜》则所有的大学生都没有读过。由此，该实验小组得出结论，当前大学生很少阅读文学作品，甚至根本不接触文学作品。<br>以下哪项如果为真，最能对该实验小组的结论构成质疑？","options":[{"label":"A","content":"实验小组选取的40部文学作品不具有代表性"},{"label":"B","content":"实验小组选取的60名大学生喜爱玩游戏，不喜欢阅读文学作品"},{"label":"C","content":"实验小组选取的40部文学作品在大学图书馆中不容易被找到"},{"label":"D","content":"《安娜·卡列尼娜》这部作品很多中文系的学生也没有读过"}],"answer":"A","explanation":"题干由“60名在校大学生很少接触所列举的40部文学作品”推出“当前大学生很少阅读文学作品”。若需构成质疑，则应证明这60名学生或40本文学作品都是特例。四个选项都可以质疑，其中A项直接说明40部文学作品不具有代表性，质疑结论的力度最强。故答案选A。","no":81},{"id":"1718789646881","type":"single","material":"","stem":"随着统计学的发展，越来越多的统计结果发现，不同性格特征的人会在不同的职业领域里取得相对较高的成就。如具有某种性格的人容易在IT领域获得成功，而另一种性格特征的人容易在科研领域取得成就等。随着对性格特征的进一步完善分类，通过主动修正行为和调整性格特征以达到职业领域的成功，将变得具有可能性。<br>以下哪项，最能反驳上述观点？","options":[{"label":"A","content":"某种性格特征与其相关的职业能力是由相同的生理遗传因素所导致"},{"label":"B","content":"某种性格特征与某种职业能力可能只是数字上的巧合"},{"label":"C","content":"人们往往是在被逼无奈的情况下才愿意修正自己的行为，但是通常为时已晚"},{"label":"D","content":"用心理测试的形式验证、调整人们的职业选择准确性并不高，因此人们普遍认为心理测试没有用处"}],"answer":"A","explanation":"题干观点是通过主动修正行为和调整性格特征以达到职业领域的成功，将变得可能。A项为真说明性格特征和职业能力都是由生理遗传因素所致，因此调整性格特征并不能达到职业领域的成功，削弱了题干观点；B项削弱力度较弱；C、D为无关项。故选A。","no":82},{"id":"1718789646882","type":"single","material":"","stem":"一则公益广告劝告人们，酒后不要开车，直到你感到能安全驾驶的时候才开。然而，在医院进行的一项研究中，酒后立即被询问的对象往往低估他们恢复驾驶能力所需要的时间。这个结果表明，在驾驶前饮酒的人很难遵循这个广告的劝告。下面哪项如果为真，能最有力地支持以上结论？","options":[{"label":"A","content":"医院中被研究的对象估计他们恢复驾驶的能力通常比其他人更保守"},{"label":"B","content":"医院中被研究的对象也被询问恢复对安全驾驶不起重要作用的能力所需要的时间"},{"label":"C","content":"一些不得不开车回家的人就不饮酒"},{"label":"D","content":"一般的人，对公益广告的警觉比医院研究对象的警觉高"}],"answer":"A","explanation":"对选项A中“保守”这个词含义的理解很重要。选项A说明其他饮酒的人可能会比医院中的那些研究对象更冒险，也就是更加低估他们恢复驾驶能力所需要的时间，支持了题干的结论。B项和C项为无关项，D项削弱了题干结论。","no":83},{"id":"1718789646883","type":"single","material":"","stem":"某商场销售中心统计数据分析表明：2010年第四季度商场销售业绩为200万元，比第三季度多了50万元。日化用品、烟酒、水果、杂粮的销售量，与第三季度相比分别上升了约41.3%、25.6%、26.2%、15.4%。商场销售部负责人指出，这得益于第四季度商场持续采取的有效的促销措施。<br>以下除哪项外，均能支持上述商场销售部负责人的看法？","options":[{"label":"A","content":"该商场邀请了一名医生，向顾客宣讲一些日常卫生知识"},{"label":"B","content":"该商场规定每天晚上9点之后，部分商品半价销售"},{"label":"C","content":"商场管理人员制定了一项措施：春节买商品买一赠一"},{"label":"D","content":"该商场实行购物积分活动，规定每消费1元积1分，满300分抵30元现金券"}],"answer":"C","explanation":"销售部负责人的观点是销售量的增加得益于第四季度商场采取的促销措施。A项通过医生的宣讲，可以使顾客关注自身及家庭的卫生，从而可以使日化用品销售量上升；B、D两项都是通过价格上的优惠措施来吸引顾客。C项的促销手段在春节进行的，不属于第四季度，不能支持销售部负责人的看法。故答案选C。","no":84},{"id":"1718789646884","type":"single","material":"","stem":"作家出版社出版的某种正版图书每本售价为25元，赢利10元。而这样的图书的盗版每本仅售价5元。因此，如果这样的盗版书销售10万本，就会给出版社造成100万元的利润损失。<br>要使上述论证成立，以下哪项是必须假设的？","options":[{"label":"A","content":"每个已购买各种盗版书的人，若没有盗版书可买，都仍会购买相应的正版书"},{"label":"B","content":"上述盗版书的单价不可能低于5元钱"},{"label":"C","content":"与上述的正版书相比，盗版书的质量无实质性的缺陷"},{"label":"D","content":"如果没有盗版书，作家出版社的上述正版书的销售量不会少于10万本"}],"answer":"A","explanation":"本题考查前提型题目，应用搭桥思想解题。题干前提是“购买10万本盗版书”，结论是“给出版社造成100万元的利润损失”。应该补充的前提是“买盗版的10万本的人，本来应该购买10万本正版书，建立这两个10万本之间的联系。”A项，强调没有盗版书的前提下，购买盗版10万本的人，回去买正版10万本，是本题必须假设的前提条件。D项，具有较强的迷惑性，题干结论是说在盗版书卖10万本时，出版社亏损100万，与此同时正版也是在卖的，D项“如果没有盗版书，作家出版社的上述正版书的销售量不会少于10万本”，所以要想得到亏损100万，一定得销售10万本以上，但是这10万多本书必须包括销售10万本盗版的都买正版，还有正版本身在卖的，才能得到亏损100万这个结论，D项未说清；要想得到100完利润损失，A项是必须的假设，故本题答案选A。","no":85},{"id":"1718789646885","type":"single","material":"","stem":"“衣、食、住、行”是老百姓关注的头等大事。然而，这些年“衣”已经被医院的“医”所取代。看病贵、看病难已经成为社会关注的热点问题之一。因此，必须迅速推进医疗体制改革。<br>与上述论证最为相关一个问题是：","options":[{"label":"A","content":"药品推销商的贿赂行为以及医生收红包在看病贵中起多大作用"},{"label":"B","content":"造成看病贵、看病难的最根本的原因究竟是什么"},{"label":"C","content":"政府拨款不足在导致医疗价格上涨中起多大作用"},{"label":"D","content":"平价医院在抑制医疗价格方面起多大作用"}],"answer":"B","explanation":"题干的论点是：必须迅速推进医疗体制改革，论据是：看病贵、看病难已经成为社会关注的热点问题之一。与题干论证最相关的问题是造成这种现象的根本原因是什么，是不是医疗体制的问题，如果是的话就应该推进医疗体制改革，如果不是的话就应该针对其他原因进行改革。答案选B。","no":86},{"id":"1718789646886","type":"single","material":"","stem":"A国有40%的家庭的男主人认为，只要家里有学龄前儿童，妻子就不应该外出工作，而应留在家里照顾小孩。B国有80%的家庭的男主人则不这么认为，他们认为妻子外出工作体现了男人对女权的尊重。据调查，A国每两个家庭中就有一个家中有学龄前儿童；B国每三个家庭中就有两个家中有学龄前儿童。<br>如果上述断定为真，以下哪项必定为真？","options":[{"label":"A","content":"A国的儿童人数多于B国"},{"label":"B","content":"题干中缺乏足够的条件，对A国和B国的丈夫们对自己有学龄前儿童的妻子外出工作的支持率来进行确定性的比较"},{"label":"C","content":"A国的丈夫们对自己有学龄前儿童的妻子外出工作的支持率低于B国的丈夫们"},{"label":"D","content":"B国的丈夫们对自己有学龄前儿童的妻子外出工作的支持率低于A国的丈夫们"}],"answer":"B","explanation":"题干只给出了A、B两国支持妻子外出工作的丈夫在全部丈夫中所占的百分比，以及有学龄前儿童的家庭在全部家庭中所占的百分比，但并未给出具体的儿童数量。因此根据题干信息无法判断A项的真假。由于题干没有给出A、B两国的丈夫们对自己有学龄前儿童的妻子外出工作的支持率，因此也无法得知C、D两项的真假。故答案选B。","no":87},{"id":"1718789646887","type":"single","material":"","stem":"在一次选拔赛中，有评委给所有参赛者都投了通过票，由此可以必然推出的是：","options":[{"label":"A","content":"所有参赛者都至少得了一张通过票"},{"label":"B","content":"所有的参赛者都通过了"},{"label":"C","content":"有评委没有投参赛者通过票"},{"label":"D","content":"对所有的参赛者投通过票不止一个评委"}],"answer":"A","explanation":"有评委给所有参赛者都投了通过票，则所有参赛者都至少得了这个评委的这一张通过票，所以A是对的。其他选项都无法在题中找到依据。","no":88},{"id":"1718789646888","type":"single","material":"","stem":"小雨期末考试前，妈妈对她说：“如果这次考试进入全班前三名，我就奖励你一台iPad或者带你去香港旅游。”<br>以下哪项如果为真，说明妈妈没有兑现承诺？","options":[{"label":"A","content":"小雨进入全班前三名，妈妈没有带她去香港旅游，但奖励了她一部iPhone"},{"label":"B","content":"小雨进入全班前三名，妈妈奖励了她一部iPad并送了一双回力板鞋"},{"label":"C","content":"小雨没有进入全班前三名，妈妈没有带她去香港旅游，但送了她一台iPad"},{"label":"D","content":"小雨没有进入全班前三名，妈妈没有送她iPad，也没有带她去香港旅游"}],"answer":"A","explanation":"题干是一个后件为选言命题的充分条件的假言命题，只有在“前件真且后件假”时为假，选言命题只有在两个肢命题都为假的情况下才为假，即考试进入的前三，但既不奖励iPad，也不去香港旅游。故答案选A。","no":89},{"id":"1718789646889","type":"single","material":"","stem":"为了保证航运的安全性，航空公司对旅客的随身行李有严格要求，除非行李的重量符合规定，否则航空公司不允许登机。而且，所有被准许登机的行李中都不能有超过100毫升的液体物品。<br>如果以上陈述为真，则以下哪项也必然为真？","options":[{"label":"A","content":"航空公司的准许标准要参考行李的大小尺寸"},{"label":"B","content":"只要行李的重量符合规定，航空公司就一定会准许登机"},{"label":"C","content":"如果某旅客的行李重量符合规定并且没有超过100毫升的液体物品，则航空公司准许登机"},{"label":"D","content":"一件重量符合规定，但是装有超过100毫升液体物品的行李，绝不会被准许登机"}],"answer":"D","explanation":"第一个命题可转化为：只有行李的重量符合规定，航空公司才允许登机。第二个命题转化为：只有行李中没有超过100毫升的液体物品，才被准许登机。B、C项都是肯定前件不能推出肯定的后件；D项是第二个命题否定前件得到否定的后件，正确。选D。","no":90},{"id":"1718789646890","type":"single","material":"","stem":"经济学家指出：任何经济有效率的国家都能创造财富。这样的国家只在财富平均分配时才能保持政治稳定。财富平均分配又会消灭风险，而风险正是经济运转必不可少的前提条件。<br>以下结论正确的是：","options":[{"label":"A","content":"没有一个国家能无限期地既保持政治稳定，又有巨额财富"},{"label":"B","content":"没有一个国家能无限期地既能保持经济有效率，又能保持政治稳定"},{"label":"C","content":"经济效率的提高会刺激风险的出现，而风险又反过来促进了经济效率的提高"},{"label":"D","content":"只要能平均分配财富的国家就能无限期地保持政治的稳定"}],"answer":"B","explanation":"题干的逻辑关系如下：①有效率地运作经济⇒富有；②政治稳定⇒财富平均分配；③财富平均分配⇒无风险⇒无法有效率地运作经济。<br>由②③可知，政治稳定⇒无法有效率地运作经济，根据假言命题与选言命题的转化关系，即可推出“或者政治不稳定或者无法有效率地运作经济”，B项正确；<br>否定前件无法否定后件，因此无法得出政治稳定与富有之间的关系，即无法推出A项；<br>“风险”与“有效率地运作经济”不是充分必要条件关系，所以C项错误；<br>由②可知，“政治稳定”是“财富平均分配”的充分条件，D项错误。","no":91},{"id":"1718789646891","type":"single","material":"","stem":"对于本届世界杯足球赛，德国队和巴西队谁能进入决赛，甲乙丙丁四人作出下列预测：<br>甲：我认为巴西队不可能进入决赛乙：或者是德国，或者是巴西<br>丙：如果德国能进决赛，那么巴西队一定进不了决赛丁：德国和巴西都能进决赛<br>结果只有一人的预测是假的，由此可以推出：","options":[{"label":"A","content":"德国和巴西都能进入决赛"},{"label":"B","content":"甲的话是假的"},{"label":"C","content":"德国能进入决赛，并且丙的话是真的"},{"label":"D","content":"巴西队能进决赛，德国队进不了决赛"}],"answer":"C","explanation":"分析甲、乙、丙、丁四个人的话，可知丙和丁的话矛盾，必有一真一假，由只有一假可知甲和乙的话为真。故巴西不可能进入决赛，德国可以进决赛，即丙的话为真。故答案为C。","no":92},{"id":"1718789646892","type":"single","material":"","stem":"小明、小王、小李，分别是教育学、化学、数学专业的学生。现在知道：小李比数学专业的年龄大，小明和化学专业的不同岁，化学专业的比小王年龄小。<br>由此，可以推断出：","options":[{"label":"A","content":"数学专业的年龄最小"},{"label":"B","content":"化学专业的比教育学专业的年龄大"},{"label":"C","content":"化学专业的比小明年龄小"},{"label":"D","content":"小明不是数学专业的"}],"answer":"A","explanation":"由“小李比数学专业的年龄大”可得“小李＞数学专业的”，由“化学专业的比小王年龄小”可得“小王＞化学专业的”，再因“小明和化学专业的不同岁”可知小李是化学专业的，则可得“小王＞小李（化学专业的）＞数学专业的”，即“小王（教育学专业的）＞小李（化学专业的）＞小明（数学专业的）”。故答案选A。","no":93},{"id":"1718789646893","type":"single","material":"","stem":"为了缓解城市交通拥挤的状况，市长建议对每天进入市区的私家车收取5元的拥堵费。市长说，这个费用超过了乘公交车进出市区的车费，所以很多人不会再开私家车上班，而改乘公交车。<br>下列哪项为真，最能削弱市长的结论？","options":[{"label":"A","content":"汽油价格的大幅上涨将增加开车上下班的成本"},{"label":"B","content":"对多数开私家车进入市区的人来说，在市区内停车的费用已经远远超过了乘公交车的费用"},{"label":"C","content":"现在多数乘公交车的人没有私家车"},{"label":"D","content":"很多开车上下班的人反对市长的计划，他们宁愿承受交通阻塞也不愿交那5元钱"}],"answer":"B","explanation":"削弱型题目。市长由“收取5元的拥堵费超过了乘公交车进出市区的车费”得出“很多人不会再开私家车上班，而改乘公交车”的结论。A项成本增加与题干论证无关；B项指出开私家车的人停车的费用已经远远超过了乘公交车的费用，即表明收取拥堵费对开私家车的人不起作用，说明采用这种方法并不能达到目的，从而削弱结论；C项乘公交车的人和D项的交通阻塞都与题干结论无关。故答案选B。","no":94},{"id":"1718789646894","type":"single","material":"","stem":"挪威研究人员分析了该国过去几十年里230万份出生记录，以及相应孕妇的健康数据，结果发现，如果母亲怀孕期间出现妊娠剧吐症状，女儿后来怀孕时也出现该症状的可能性是其他人的3倍。研究还表明，孕妇妊娠剧吐与腹中胎儿是否含有来自丈夫一方的相关基因没有关系，导致这一症状的基因只可能来自母亲。因此研究人员认为妊娠剧吐与父亲的基因无关，而是由母亲遗传给女儿。<br>以下哪项如果为真，最能削弱上述结论？","options":[{"label":"A","content":"女儿和母亲生活的自然和家庭环境（气候、饮食习惯等）比较类似"},{"label":"B","content":"一项亚洲研究表明，母亲有妊娠剧吐，女儿出现的可能性是其他人的1.5倍"},{"label":"C","content":"研究表明，外婆怀孕时有妊娠剧吐，外孙女出现的可能性是其他人的3倍"},{"label":"D","content":"在过去几十年中，挪威妇女吸烟的比例逐年上升，而吸烟与妊娠剧吐有关"}],"answer":"A","explanation":"题干结论是妊娠剧吐与父亲的基因无关，而是由母亲遗传给女儿。A项说明妊娠剧吐并不是由母亲遗传给女儿，而是由于自然和家庭环境的原因引起的，即题干结果是另有他因，削弱了题干结论；B、C两项加强了题干结论；D项是无关项。故答案选A。","no":95},{"id":"1718789646895","type":"single","material":"","stem":"“有用”和“有害”是一对相对的概念，由于人的视角不同，同一物质可以成为有用的，也可以成为有害的，“有用”和“有害”是可以相互转化的。<br>下列哪项为真，最不能支持“有用”和“有害”是可以相互转化的？","options":[{"label":"A","content":"海藻经常在湖泊中大量繁殖，窒息鱼类，但是可以被用作一些动物的食物"},{"label":"B","content":"麻雀秋季在农作物区，由于嗜食农作物籽实，常被人看作是有害的"},{"label":"C","content":"苍蝇由于传播疾病被人们称为四害之一，但它在无菌状态下饲养，则可以成为工程蝇，幼虫蛋白质含量高，成为人类的高级食品"},{"label":"D","content":"虽然苍蝇可以传播疾病，但其表皮中提取的甲壳素，可用于制作化妆品、减肥品"}],"answer":"B","explanation":"加强型题目。题干要支持的观点是：“有用”和“有害”是可以相互转化的，即“同一物质可以成为有用的，也可以成为有害的”。A、C、D三项都说明了同一物质可以成为有用的，也可以成为有害的，加强了题干观点。B项是说麻雀嗜食农作物籽被人看作是有害的，而没有提到有用的一面，无法支持题干观点。故答案选B。","no":96},{"id":"1718789646896","type":"single","material":"","stem":"威尔和埃克斯这两家公司，对使用他们的字处理软件的顾客，提供24小时的热线电话服务。既然顾客仅在使用软件有困难时才打电话，并且威尔收到的热线电话比埃克斯收到的热线电话多四倍，因此，威尔的字处理软件一定是比埃克斯的字处理软件难用。<br>下列哪项如果为真，则最能够有效地支持上述论证？","options":[{"label":"A","content":"拥有埃克斯字处理软件的顾客数比拥有威尔字处理软件的顾客数多三倍"},{"label":"B","content":"埃克斯收到的关于字处理软件的投诉信比威尔多两倍"},{"label":"C","content":"这两家公司收到的热线电话数量逐渐上升"},{"label":"D","content":"威尔热线电话的号码比埃克斯的号码更公开"}],"answer":"A","explanation":"加强型题目。题干由“威尔收到的热线电话比埃克斯收到的多四倍”得出结论：威尔的字处理软件比埃克斯的难用。如果A项为真，则拥有埃克斯的字处理软件的顾客更多，但埃克斯收到的热线电话更少，加强了题干的论据，从而支持了结论；B项和D项都削弱了结论；C项是无关项。","no":97},{"id":"1718789646897","type":"single","material":"","stem":"美国科学家发明一种新药，可欺骗服用者身体，让服用者以为自己已经吃饱了进而开始燃烧脂肪。这种药会激活一种分子开关，而这种开关让胆汁酸向肠道内释放，以此作为对食物的反应。<br>以下哪条是推出“这种药物对减肥有很大帮助”的前提？","options":[{"label":"A","content":"肠道内胆汁分解脂肪"},{"label":"B","content":"胆汁通常在真正吃饱后才向肠释放"},{"label":"C","content":"只有胆汁充足，才能消化食物"},{"label":"D","content":"所有热量源中只有脂肪会被胆汁分解"}],"answer":"B","explanation":"题干由这种药激活一种分子开关让胆汁酸向肠道内释放推出该药可以欺骗服用者身体，让服用者以为自己吃饱从而开始燃烧脂肪，起到减肥作用。要使论证成立，就必须在论据与论点之间建立联系，保证“胆汁酸向肠道内释放”是吃饱的信号，即B项。否则题干结论就不能成立。A项不是必须假设的，即使胆汁不分解脂肪，还可能是身体的其他物质在燃烧脂肪。故答案为B。","no":98},{"id":"1718789646898","type":"single","material":"","stem":"亚洲并非棕榈树的原产地，在这儿传统上用手工为棕榈树传递花粉，这种办法使棕榈果实产量非常低。当1980年将作为棕榈花的有效授粉者而被熟知的象鼻虫引进亚洲后，棕榈的产量上升——在某些地区上升了50%——但在1984年急剧下降。<br>以下哪一项如果是正确的，将对1984年产量的下降提出最好的解释？","options":[{"label":"A","content":"随着产量的上升同时需求下降，1980～1984年之间，棕榈果实的价格持续下跌"},{"label":"B","content":"进口树经常比本地树产量更大，因为进口树将它们的害虫与疾病留在它们本国的土地上"},{"label":"C","content":"产量的迅速提高耗尽了培育果实的雌花生长需要的营养物质"},{"label":"D","content":"在1980～1984年之间，亚洲象鼻虫的数量保持在相同的水平上"}],"answer":"C","explanation":"题干需要解释的现象是：引进象鼻虫后，棕榈果实的产量大幅度上升，却在1984年急剧下降。C项指出产量的迅速提高耗尽了雌花生长所需的营养物质，因此导致其产量下降，能够解释题干现象；A项只说明需求下降，并不能解释产量下降的原因；B项不能对题干现象进行解释，反而更加深了题干矛盾；D项象鼻虫的数量保持不变，同样不能解释产量下降的原因。故答案选C。","no":99},{"id":"1718789646899","type":"single","material":"","stem":"三角形任意两边之和大于第三边，这个水池任意两边长度之和都大于任意一边，所以水池为三角形。<br>以下哪种推论犯了同样的错误？","options":[{"label":"A","content":"I品牌手机都是F公司制造的，这部手机不是I品牌，所以不一定是F公司制造"},{"label":"B","content":"酒店为金卡会员提供早餐，酒店没有为小王提供免费早餐，所以他不是金卡会员"},{"label":"C","content":"A公司的航班一般在三号航站楼，小刘从三号航站楼登机，因此坐A公司航班"},{"label":"D","content":"职位高的参观者第一个发言，刘老师不是第一个发言，所以职位一定不是最高的"}],"answer":"C","explanation":"题干的推理为：A是B，C是B，所以C是A。<br>A项的推理为：A是B，C不是A，所以C不一定是B。<br>B项的推理为：A（金卡会员）是B（酒店提供早餐），C不是B，所以C不是A。<br>C项的推理为：A是B，C是B，所以C是A。<br>D项的推理为：A是B，C不是B，所以C不是A。<br>综上可知，只有C项与题干推理形式相同，犯了同样的错误。故答案为C。","no":100},{"id":"1718789646900","type":"single","material":"","stem":"新奇股份有限公司由甲、乙、丙、丁四个子公司组成，每个子公司承担的利润份额与每年该子公司员工在公司总员工中所占的比例相等。但去年该公司的财务报告显示，乙公司在员工增加的同时，向总公司上交的利润的比例却下降了。<br>如果上述为真，可得出以下哪项结论？","options":[{"label":"A","content":"四个子公司中，乙公司员工增加数量最少"},{"label":"B","content":"乙公司员工增加比例至少比其他三个子公司其中的一个小"},{"label":"C","content":"四个子公司中，乙公司员工最少"},{"label":"D","content":"甲、丙、丁公司员工增长比例都超过了乙公司的员工增加比例"}],"answer":"B","explanation":"乙公司员工增加但上交利润却下降了，上交利润份额主要由子公司员工在总员工中所占比例决定，可以推出乙公司员工占总员工比例下降了，即乙公司员工的增长比例小于公司总员工的增长比例，公司总员工的增长比例为各子公司员工增长比例的加权平均数，则其他三个子公司中至少有一个的员工增长比例大于乙公司。故答案选B。","no":101},{"id":"1718789646901","type":"single","material":"","stem":"远红外线被人体吸收后，可使生物细胞产生共振效应，可将远红外热能传递到人体皮下较深的部分，皮下深层温度上升，产生的温热由内向外散发。这种作用强度，使毛细血管扩张，促进血液循环，强化各组织之间的新陈代谢，增加组织的再生能力，提高机体的免疫能力，调节精神的异常兴奋状态。<br>从上段文字可以推出：","options":[{"label":"A","content":"远红外线可使生物细胞温度上升"},{"label":"B","content":"远红外线对人体有医疗保健作用"},{"label":"C","content":"远红外线能使人精神亢奋"},{"label":"D","content":"远红外线能量较高可以治疗疾病"}],"answer":"B","explanation":"题干逻辑为“远红外线被人体吸收→生物细胞产生共振效应→皮下深层温度升高→使毛细血管扩张，促进血液循环，强化各组织之间的新陈代谢，增加组织的再生能力，提高机体的免疫能力，调节精神的异常兴奋状态（医疗保健）”。<br>A项，题干中使皮下深层温度升高，不是使生物细胞温度上升，错误；B项正确；C项，远红外线可以调节精神的异常兴奋状态，而不是使人精神亢奋，错误；D项可以治疗疾病的说法也无法推出。故本题答案选B。","no":102},{"id":"1718789646902","type":"single","material":"","stem":"甲、乙、丙和丁是同班同学。甲说：“我班同学都是团员。”乙说：“丁不是团员。”丙说：“我班有人不是团员。”丁说：“乙不是团员。”<br>已知只有一个人说假话，则可以推出以下判断肯定是真的一项是：","options":[{"label":"A","content":"说假话的是甲，乙不是团员"},{"label":"B","content":"说假话的是丁，乙不是团员"},{"label":"C","content":"说假话的是乙，丙不是团员"},{"label":"D","content":"说假话的是甲，丙不是团员"}],"answer":"A","explanation":"甲和丙说的话矛盾，必为一真一假。根据已知只有一假，则乙和丁为真话，乙和丁的话说明，乙和丁都不是团员，即有人不是团员，则丙说的话为真，甲说的是假话。故答案选A。","no":103},{"id":"1718789646903","type":"single","material":"","stem":"假设“如果小李喜欢篮球或者小王不喜欢排球，那么小张喜欢篮球”为真，由以下哪个前提可以推出“小王喜欢排球”的结论？","options":[{"label":"A","content":"小李喜欢篮球"},{"label":"B","content":"小张喜欢排球"},{"label":"C","content":"小李或小张不喜欢篮球"},{"label":"D","content":"小张不喜欢篮球"}],"answer":"D","explanation":"题干的逆否命题是：小张不喜欢篮球⇒小李不喜欢篮球且小王喜欢排球。要得到小王喜欢排球，需要小张不喜欢篮球作为前提，故答案选D。","no":104},{"id":"1718789646904","type":"single","material":"","stem":"某发展中国家所面临的问题是，要维持它的经济发展，必须不断加强国内企业的竞争力；要保持社会稳定，必须不断建立健全养老、医疗、失业等社会保障体系。而要建立健全社会保障体系，则需要企业每年为职工缴纳一定比例的社会保险费。如果企业每年为职工缴纳这样比例的社会保险费，则会降低企业的竞争力。<br>以下哪项结论可以从上面的陈述中推出？","options":[{"label":"A","content":"这个国家无法维持它的经济发展，或者不能保持它的社会稳定"},{"label":"B","content":"这个国家或者可以维持它的经济发展，或者可以保持它的社会稳定"},{"label":"C","content":"如果降低企业每年为职工缴纳社会保险费的比例，则可以保持企业的竞争力量"},{"label":"D","content":"这个国家的经济发展会受到一定影响"}],"answer":"A","explanation":"题干包含四个充分条件假言命题，后三个命题又可形成假言连锁推理，故题干命题可整理如下：①维持经济发展⇒加强企业竞争力；②保持社会稳定⇒建立健全社会保障体系⇒企业每年为职工缴纳一定比例的社会保险费⇒降低企业竞争力。<br>由于加强企业竞争力和降低企业竞争力不可能同时实现，与①和②构成二难推理得，或者不能维持经济发展，或者不能保持社会稳定，即A项正确。","no":105},{"id":"1718789646905","type":"single","material":"","stem":"某单位事业编招聘录用名单已经公布，已知：（1）只要甲被录取，乙就不被录取；（2）只要乙不被录取，甲就被录取；（3）甲被录取。已知这三个判断只有一个真，两个假。由此推出：","options":[{"label":"A","content":"甲乙都被录取"},{"label":"B","content":"甲乙都未被录取"},{"label":"C","content":"甲被录取，乙未被录取"},{"label":"D","content":"甲未被录取，乙被录取"}],"answer":"B","explanation":"考查复言命题推理。（3）为真则（2）为真，由“只有一个真”可知，（3）为假，即甲未被录取。则可推出（1）为真，所以（2）为假。（2）是充分条件假言命题，其矛盾命题是肯定的前件和否定的后件组成的联言命题，即乙不被录取，甲也不被录取，故选B。","no":106},{"id":"1718789646906","type":"single","material":"","stem":"某年会由四个专家轮流主持，他们有2名来自北京，其余2名分别来自江苏和上海，他们的专业分布在数学、逻辑学、经济和计算机。现有相关信息如下：<br>（1）来自江苏的专家研究计算机。（2）来自上海的专家不研究经济。（3）研究数学的专家来自北京。请问来自上海的专家研究什么？","options":[{"label":"A","content":"数学"},{"label":"B","content":"逻辑学"},{"label":"C","content":"经济"},{"label":"D","content":"计算机"}],"answer":"B","explanation":"由（1）、（3）可知，另外一名来自北京的专家和来自上海的专家研究逻辑学、经济，由（2）可得，来自上海的专家研究逻辑学。答案选B。","no":107},{"id":"1718789646907","type":"single","material":"","stem":"<p>某市进行新区规划，决定以市民公园为中心，在东西南北方向分别建设特色社区，这四个特色社区为：行政服务区、商业区、文化区和休闲区。已知，行政服务区在文化区的西南方向，文化区在休闲区的东南方向。<br>根据以上陈述，可以得出下列哪项结论？</p>","options":[{"label":"A","content":"休闲区在文化区的西南方向"},{"label":"B","content":"商业区在休闲区的东南方向"},{"label":"C","content":"文化区在商业区的东北方向"},{"label":"D","content":"市民公园在行政服务区的北面"}],"answer":"D","explanation":"以市民公园为中心，由行政服务区在文化区的西南方向可知文化区可以在北面和东面，再由文化区在休闲区的东南方向可知文化区可以在南面和东面，则可以确定文化区在市民公园的东面。进而可知休闲区在北面、行政服务区在南面、商业区在西面，如下图所示，则可知市民公园在行政服务区的北面。故答案为D。<img src=\"assets/img/f0663369111a62.png\" alt=\"图片_rId7\" data-href=\"\"/>","no":108},{"id":"1718789646908","type":"single","material":"","stem":"退行性关节炎是一种罕见的关节疾病。一些科学家认为，这种疾病曾于2500年前在埃及流行，其根据是在现在所发现的那个时代的木乃伊中，有相当高的比例发现患有这种疾病的痕迹。<br>以上哪项为真，最能削弱上述论断？","options":[{"label":"A","content":"到目前为止，发现古埃及木乃伊的数量不超过10个"},{"label":"B","content":"有资料记载，古埃及曾流行过退行性关节炎这种疾病"},{"label":"C","content":"木乃伊上所显示的痕迹实际上是对尸体进行防腐处理时造成的"},{"label":"D","content":"在我国东部所发现的木乃伊中，同样发现患有此病的痕迹"}],"answer":"C","explanation":"题干由2500年前的木乃伊中，有相当高的比例发现患有退行性关节炎的痕迹推出结论，该疾病在2500年前在埃及流行。C项说明所发现的痕迹是“另有他因”，并非表示患有退行性关节炎，从而削弱了论证；A项通过数量不足来削弱，程度有限；B、D两项加强了结论。故答案选C。","no":109},{"id":"1718789646909","type":"single","material":"","stem":"通常人们总认为，赞助人向博物馆赠送展品，是对博物馆的一种财政上的支持。事实上，对捐赠品的日常保管和维护是笔昂贵的开支。这笔开支的累计甚至很快会超过捐赠品的市场价。因此，这些捐赠品事实上加剧而并非减轻了博物馆的财政负担。<br>以下哪项如果为真，最能削弱上述论证？","options":[{"label":"A","content":"博物馆一般只接受允许并易于出售的赠品"},{"label":"B","content":"捐赠品中包括珍贵的历史文物"},{"label":"C","content":"捐赠品的保管维护费用都将列入财政预算，可申请政府追加拨款"},{"label":"D","content":"博物馆对藏品的保管和维护费用因藏品的等级而异"}],"answer":"A","explanation":"题干由藏品维护的费用过高，推出接受捐赠品会导致财政上的负担。A项为真则表明，博物馆接受的藏品易于销售，可以很快售出，不但不会给财政上带来负担还会增加收入，有力地削弱了题干论证。C项如果政府同意拨款则不会增加负担，但相对于A项能减轻负担削弱力度较小。B、D两项与题干论证无关。故答案选A。","no":110},{"id":"1718789646910","type":"single","material":"","stem":"目前食品包装袋上没有把纤维素的含量和其他营养成分一起列出。因此，作为保护民众健康的一项措施，国家应该规定食品包装袋上明确列出纤维素的含量。<br>下列哪项如果为真，可作为论据支持上述论断？<br>Ⅰ.大多数消费者购买食品时能注意包装袋上关于营养成分的说明。Ⅱ.高纤维的食品对于预防心脏病、直肠癌和糖尿病有重要作用。Ⅲ.很多消费者都具有高纤维食品营养价值的常识。","options":[{"label":"A","content":"仅Ⅰ"},{"label":"B","content":"仅Ⅱ"},{"label":"C","content":"仅Ⅲ"},{"label":"D","content":"Ⅰ、Ⅱ、Ⅲ"}],"answer":"D","explanation":"要支持题干论断，即需在保护民众健康和列出纤维素含量之间建立联系。Ⅰ消费者关注食品营养成分、Ⅱ高纤维食品的作用、Ⅲ消费者对高纤维食品价值的认知都能支持题干论断。故答案选D。","no":111},{"id":"1718789646911","type":"single","material":"","stem":"有研究表明，晚期癌症患者的剧痛与脊髓内一种名为“CCL－1”的蛋白质增加密切相关。研究人员绑住实验鼠的坐骨神经，让实验鼠产生剧痛感后发现，实验鼠脊髓中负责信息传递的“CCL－1”蛋白质增加到一般水平的2倍以上。而向正常的实验鼠脊髓内注射“CCL－1”蛋白质后发现，即使轻微刺激，实验鼠也会做出通常感觉到剧痛时才会有的动作。<br>以下哪项如果为真，最能支持上面的研究结论？","options":[{"label":"A","content":"在感到非常痒的时候，脊髓内的“CCL－1”蛋白质数量基本不变"},{"label":"B","content":"每个实验鼠脊髓内的“CCL－1”蛋白质数量是不同的"},{"label":"C","content":"如果提前注射妨碍“CCL－1”蛋白质发挥作用的物质，则实验鼠就不会感受到剧痛"},{"label":"D","content":"糖尿病、化疗的副作用也会导致患者神经受损后出现慢性剧烈疼痛"}],"answer":"C","explanation":"A项痒的时候蛋白质数量基本不变，B项每个鼠的蛋白质数量属于无关项；C项说明向实验鼠注射妨碍CCL－1蛋白质发挥作用的物质对实验鼠感受疼痛有影响，支持了题干结论；D项也是无关项。故答案选C。","no":112},{"id":"1718789646912","type":"single","material":"","stem":"最近，在一百万年前的河姆渡氏族公社遗址发现了烧焦的羚羊骨残片，这证明人类在很早的时候就掌握了取火煮食肉类的技术。<br>上述推论中隐含着下列哪项假设？","options":[{"label":"A","content":"羚羊骨是被人类取火烧焦的"},{"label":"B","content":"河姆渡人不生食羚羊肉"},{"label":"C","content":"从河姆渡公社以来的所有人种都掌握了取火的技术"},{"label":"D","content":"只要发现烧焦的羚羊骨就能证明早期人类曾聚居于此"}],"answer":"A","explanation":"题干由“发现了烧焦的羚羊骨残片”推出“人类在很早的时候就掌握了取火煮食肉类的技术”。要使这一论证成立需要在两者间建立联系，排除其他原因。A项是必须假设的，否则烧焦的羚羊骨残片不能证明人类掌握了取火技术。故答案选A。","no":113},{"id":"1718789646913","type":"single","material":"","stem":"在最近一段时间内，红星电子在市内的各个连锁店中都只出售熊猫、蓝月、佳虹三种品牌的数码相机。在2011年，熊猫、蓝月、佳虹三种品牌的数码相机在该地区的市场占有率分别为20%、35%、45%。到2012年，三个品牌的市场占有率变成了熊猫第一、蓝月第二、佳虹第三，其次序刚好与2011年相反。<br>以下各项除哪项外，都可能对上文提到的市场占有率的变化作出合理解释？","options":[{"label":"A","content":"熊猫集团耗费巨资并购了一家濒临倒闭的大型电冰箱厂，并将大量精力转向生产智能洗衣机"},{"label":"B","content":"熊猫集团成立了市场信息部，应用信息网络技术收集市场信息并与客户建立了密切的联系"},{"label":"C","content":"蓝月集团设计了新的生产线，要等到2013年才能正式投产使用，在2012年难有作为"},{"label":"D","content":"佳虹集团新的董事会推行全面的质量监管，导致成本大幅增加，不得不提高价格"}],"answer":"A","explanation":"题干给出2012年与2011年三个品牌数码相机的市场占有率数据，B、C、D三项都可以作出合理解释，A项熊猫集团将大量精力转向智能洗衣机后，不能解释其市场占有率的增加，选A。","no":114},{"id":"1718789646914","type":"single","material":"","stem":"禁止步行者闯红灯的规定没有任何效果，总是违反该规定的步行者显然没有受到它的约束，而那些遵守规定的人显然又不需要它，因为即使不禁止步行者闯红灯，这些人也不会闯红灯。<br>下面哪一个选项最准确地指出了上述论证中的漏洞？","options":[{"label":"A","content":"在前提的结论中，它分别使用了意义不同的“规定”"},{"label":"B","content":"它没有提供任何证据证明，闯红灯比不闯红灯更危险"},{"label":"C","content":"它理所当然地认为，多数汽车司机会遵守禁止驾车闯红灯的规定"},{"label":"D","content":"它没有考虑到上述规定是否会对那些偶尔闯红灯但不经常闯红灯的人产生影响"}],"answer":"D","explanation":"题干通过分析总是违反规定和遵守规定的人这两种情况，得出该规定没有任何效果这一结论，但却忽略了偶尔闯红灯但不经常闯红灯的人这一情况。D项明确地指出了题干论证的漏洞。故答案选D。","no":115},{"id":"1718789646915","type":"single","material":"","stem":"最近15年，世界技术有很大革新，尤其在通讯、信息和电子等方面。无疑，技术的进步使生产得到了改进，加强技术力量是推动经济增长的一个重要因素。<br>据此可知：","options":[{"label":"A","content":"最近15年世界经济增长迅速"},{"label":"B","content":"技术革新可以推动生产发展"},{"label":"C","content":"生产发展对技术进步有反作用"},{"label":"D","content":"技术进步决定了经济的增长"}],"answer":"B","explanation":"由“技术的进步使生产得到了改进”知B项正确。A、C两项题干没有提及。D项“决定”的说法过于绝对，排除。故答案选B。","no":116},{"id":"1718789646916","type":"single","material":"","stem":"俗话说“心宽体胖”。但调查发现，与几乎没有精神压力的人相比，那些时常感到精神压力大的人更容易身体发胖或患肥胖症。同时，体重指数本来就超指标的人，如果时常感到精神的压力大，他们会更容易“胖上加胖”。<br>由此可以推出：","options":[{"label":"A","content":"肥胖对健康是没有好处的"},{"label":"B","content":"身体越瘦，精神越好"},{"label":"C","content":"身材瘦小的人，精神压力一般比较小"},{"label":"D","content":"精神压力可能更容易导致肥胖"}],"answer":"D","explanation":"题干指出精神压力大的人更容易发胖或患肥胖症，且体重本来就超指标的人时常感到压力的话就更容易胖上加胖。题干并未提到肥胖对身体是否没有好处，A项错误；也没有提到身材瘦小的情况，B、C两项错误；D项精神压力可能更容易导致肥胖，与题干描述相符。故答案选D。","no":117},{"id":"1718789646917","type":"single","material":"","stem":"全班只有一名学生没有参加植树活动，班主任只知道是甲、乙、丙、丁四人中的一个。班主任在讯问时，甲说：“乙没去。”乙说：“我不但去了，而且直到活动结束才离开。”丙说：“我晚去了一会，但我种的树是全班最多的。”丁说：“如果丙去了，那我就没去。”<br>他们四人中只有一人说谎。由此可以推知：","options":[{"label":"A","content":"甲没有参加"},{"label":"B","content":"乙没有参加"},{"label":"C","content":"丙没有参加"},{"label":"D","content":"丁没有参加"}],"answer":"D","explanation":"甲和乙的话矛盾，则必有一真一假，根据题干“只有一人说谎”可知，丙、丁二人说的都是真话，由此可推出，没有参加植树活动的学生是丁。答案选D。","no":118},{"id":"1718789646918","type":"single","material":"","stem":"孔子说：己所不欲，勿施于人。<br>以下哪一项不是上面这句话的逻辑推论？","options":[{"label":"A","content":"只有己所欲，才能施于人"},{"label":"B","content":"除非己所欲，否则不施于人"},{"label":"C","content":"若己所欲，则施于人"},{"label":"D","content":"凡施于人的都应该是己所欲的"}],"answer":"C","explanation":"考查充分条件和必要条件的转化。题干等值于“如果己所不欲，则不施于人”，否定前件不能否定后件，C项错误；否定后件可以否定前件，即“如果施于人，则是己所欲”，根据充分条件和必要条件的转化关系，可知A项正确。B项等值于“只有己所欲，才施于人”，即与A项相同。D项等值于“如果施于人，则是己所欲”，也与题干含义相同。故答案选C。","no":119},{"id":"1718789646919","type":"single","material":"","stem":"一公司被盗，警察掌握如下线索：①甲、乙、丙至少有一个是窃贼；②如果甲是窃贼，乙一定是同案犯；③发生时，乙在看电影。<br>由此推出：","options":[{"label":"A","content":"甲、乙、丙都是窃贼"},{"label":"B","content":"甲和乙都是窃贼"},{"label":"C","content":"丙是窃贼"},{"label":"D","content":"甲是窃贼"}],"answer":"C","explanation":"根据③可知，乙不是窃贼，再由②充分条件假言命题否后则否前可得，甲不是窃贼，最后根据①可知丙一定是窃贼。故答案选C。","no":120},{"id":"1718789646920","type":"single","material":"","stem":"在一次运动员选拔中，对人员选拔有如下要求：①或者选拔陈橙或者选拔李墨，②如果选择陈橙，则不能选拔吴蓝，③只有选拔吴蓝，才选拔林青。④李墨，林青只能选择一人。<br>由此可见，下列哪个选项正确体现了这次运动员的选拔方案？","options":[{"label":"A","content":"不选拔李墨，选拔吴蓝"},{"label":"B","content":"不选拔陈橙，选拔林青"},{"label":"C","content":"不选拔吴蓝，选拔林青"},{"label":"D","content":"不选拔林青，选拔李墨"}],"answer":"D","explanation":"代入排除法。A项，由①可知，不选李墨必选陈橙，由②可知不能选吴蓝，矛盾；B项，由①可知，不选陈橙必选李墨，由④可知不能选林青，矛盾；C项，由③可知，选林青则要选吴蓝，矛盾。D项代入满足条件。故答案选D。","no":121},{"id":"1718789646921","type":"single","material":"","stem":"甲、乙、丙三人各自买了一部不同品牌的新手机，手机的品牌是华为、酷派和联想。他们一起来找丁，让丁猜猜他们三人分别买了什么品牌的手机。丁说：“甲买的华为，乙买的肯定不是华为，丙买的不是联想。”<br>丁的猜测只有一句是对的。由此可以推知：","options":[{"label":"A","content":"甲买的联想，乙买的华为，丙买的酷派"},{"label":"B","content":"甲买的联想，乙买的酷派，丙买的华为"},{"label":"C","content":"甲买的华为，乙买的联想，丙买的酷派"},{"label":"D","content":"甲买的酷派，乙买的联想，丙买的华为"}],"answer":"A","explanation":"方法一：代入法。代入A项，符合题干中所说的“只有一句是对的”。答案选A。<br>方法二：“华为”在猜测中出现了两次，假设甲买的是华为，则乙买的不是华为，有两句为真，矛盾，所以甲买的不是华为；此时，若假设乙买的不是华为，则丙买的是华为，还是有两句为真，矛盾，所以乙买的是华为；则“丙买的不是联想”为真，可推出丙买的是酷派，甲买的是联想。故答案选A。","no":122},{"id":"1718789646922","type":"single","material":"","stem":"某机关田径运动会有3个短跑项目，分别是60米、100米和200米。老张、老王和老李分别参加了其中的一种，而且三人参赛的项目还不一样。小张、小王和小李作了以下猜测：<br>小张：老张参加了60米，老王参加了100米。小王：老李没参加100米，老王参加了60米。小李：老张没参加60米，老王参加了200米。如果他们的猜测都对了一半，则以下哪项为真？","options":[{"label":"A","content":"老张、老王和老李分别参加200米、100米和60米"},{"label":"B","content":"老张、老王和老李分别参加60米、200米和100米"},{"label":"C","content":"老张、老王和老李分别参加100米、60米和200米"},{"label":"D","content":"老张、老王和老李分别参加200米、60米和100米"}],"answer":"A","explanation":"排除法。根据题意，三人参赛的项目不一样，他们的猜测都对了一半。小张小李对老张陈述矛盾，所以老王参加了100米或200米中的一个，答案在A或B中，又根据小王的表述，老李没参加100米。所以正确答案是A。","no":123},{"id":"1718789646923","type":"single","material":"","stem":"某产油大国发生动乱，石油生产和出口受到严重影响，国际石油价格也因此上下波动，目前该国动乱局势已经得到控制。因此专家们预测，近期国际石油期货价格将大幅回落。<br>下列选项中，最能削弱上述论证的是：","options":[{"label":"A","content":"一些石油消费大国制定了节能减排的措施"},{"label":"B","content":"近期一些石油大国局势不明朗"},{"label":"C","content":"新能源在更加广泛的领域运用"},{"label":"D","content":"近期世界上自然灾害频发"}],"answer":"B","explanation":"削弱型题目。题干中的论证是由“某产油大国的动乱使石油价格受到影响，目前该国动乱局势已经得到控制”推出“近期国际石油期货价格将大幅回落”。A项节能减排的措施和C项新能源的广泛运用都会降低石油的需求，石油的价格会下降，加强了题干结论。B项“一些石油大国局势不明朗”说明仍有其他可能使石油价格受到影响的因素存在，从而削弱了题干论证；D项无法确定自然灾害频发与石油价格的关系。故选B。","no":124},{"id":"1718789646924","type":"single","material":"","stem":"研究院调查了27个县自来水中的锂含量，发现锂含量最高的地区比锂含量最低的地区自杀率少40%。不仅如此，在自来水锂含量最高的几个县，恶性案件发生率也在统计学上下降。因此，研究人员认为，政府如果在自来水中添加锂，有利于社会稳定。<br>以下哪项如果为真，最能驳斥研究结果？","options":[{"label":"A","content":"锂并非这些地区自来水唯一含量有差距的元素"},{"label":"B","content":"被调查的27个县的自杀率下降，是偶然现象"},{"label":"C","content":"自来水锂含量高的地区经济落后，人均收入低"},{"label":"D","content":"摄入过多锂元素会致命，且作为添加物的锂浓度难以控制"}],"answer":"A","explanation":"题干由“自来水锂含量最高的地区比含量最低的地区自杀率低，且恶性案件发生率也下降”得出“政府如果在自来水中添加锂，有利于社会稳定”。A项说明这些地区自来水中还有其他元素含量有差距，即可能另有他因，直接反驳了结论。B项不能反驳恶性案件发生率下降，力度有限；C项为无关项；D项说的是在自来水中添加锂不具有可操作性，但题干结论说的是添加锂所能带来的效果，故D项不能反驳。故答案为A。","no":125},{"id":"1718789646925","type":"single","material":"","stem":"在考古学研究中判断人类遗骸的性别对于了解古代社会结构具有重要意义。科学家发现牙釉质中含有釉原蛋白，编码这种蛋白的基因恰好位于性染色体——X染色体和Y染色体上，研究者认为，用牙齿判定遗骸性别的方法可用于考古研究。<br>以下哪项如果为真，最能支持上述论证？","options":[{"label":"A","content":"牙齿是古人类遗骸中最容易找到并且保存最完好的部分"},{"label":"B","content":"儿童遗骸的骨骼没有明显的性别差异"},{"label":"C","content":"人类遗骸的性别比例与当时人类社会的性别比例大致相同"},{"label":"D","content":"测量某些骨骼特征如骨盆的结构通常可以直接判定性别"}],"answer":"A","explanation":"题干通过编码牙釉质中釉原蛋白的基因位于性染色体上，得出用牙齿判定遗骸性别的方法可用于考古研究。<br>A项，指出古人类遗骸中牙齿最容易找到也保存最完好，说明用牙齿鉴别古人类遗骸性别的方法可行，支持了题干论证。<br>B项，儿童遗骸的骨骼没有明显性别差异，牙齿不属于骨骼，为无关项，不能支持题干论证。<br>C项，人类遗骸的性别比例与当时人类社会性别比例的关系属于无关项，不能支持题干论证。<br>D项，指出测量某些骨骼特征可以直接判定性别，提供了另一种判定性别的方法，不能支持题干论证。<br>故本题选A。","no":126},{"id":"1718789646926","type":"single","material":"","stem":"发达国家中冠心病的发病率大约是发展中国家的三倍。有人认为，这主要归咎于发达国家中人们的高脂肪、高蛋白、高热量的食物摄入。相对来说，发展中国家较少有人具备生这种“富贵病”的条件。其实，这种看法很难成立。因为，目前发达国家的人均寿命高于70岁，而发展中国家的人均寿命还不到50岁。<br>以下哪项如果成立，最能加强上述反驳？","options":[{"label":"A","content":"目前冠心病患者呈年轻化趋势"},{"label":"B","content":"发展中国家人们的高脂肪、高蛋白、高热量食物的摄入量，无论是总量还是人均量，都在逐年增长"},{"label":"C","content":"统计资料显示，冠心病患者相对集中在中老年年龄段，即45岁以上"},{"label":"D","content":"相对发展中国家来说，发达国家的人们具有较高的防治冠心病的常识和较好的医疗条件"}],"answer":"C","explanation":"题干中的论点是因为发达国家人均寿命比发展中国家长，所以冠心病的发病率也比发展中国家高。C选项统计资料显示，冠心病患者相对集中在中老年年龄段，即45岁以上，强调了年龄对冠心病的影响，加强了题干反驳。A项属于削弱。B、D两项无关。因此本题答案选C。","no":127},{"id":"1718789646927","type":"single","material":"","stem":"补充物A可以提升血浆中A物质的水平，从而影响B物质的合成。B物质是关键神经传递素，影响人的行为。B物质下降，产生焦虑、抑郁和攻击；增加会促进亲社会行为和服从。<br>要推导出“补充A物质能缓解焦虑状况”，以下不可缺少的条件是：<br>①血浆A物质水平与大脑B物质合成能力成正比<br>②正常人B物质合成足够让人处于焦虑<br>③除了提升血浆中A物质的水平，没有其他途径影响B物质的合成","options":[{"label":"A","content":"②③"},{"label":"B","content":"①③"},{"label":"C","content":"①②"},{"label":"D","content":"①②③"}],"answer":"B","explanation":"题干由血浆中A物质影响B物质的合成和B物质下降产生焦虑，增加会促进亲社会行为和服从得出“补充A物质能缓解焦虑状况”的结论。要使结论成立，则需假设补充A物质能增加B物质的合成，①是必须假设的，否则会得到相反的结论；③也是必须假设的，否则补充A物质未必就能增加B物质的合成。②与题干论证无关，不是必须假设的。故答案为B。","no":128},{"id":"1718789646928","type":"single","material":"","stem":"因为规定“黄灯亮时，已越过停止线的车辆可以继续通行”。所以，黄灯亮时，未越过停止线的车辆不能继续通行。<br>下列哪项的论证逻辑与此最为不同？","options":[{"label":"A","content":"因为规定“间歇性的精神病人在精神正常的时候犯罪，应当负刑事责任”。所以，间歇性的精神病人在精神不正常的时候犯罪，不应负刑事责任。"},{"label":"B","content":"因为规定“尚未制定法律的，行政法规可以设定行政许可”，所以，已经制定法律的，行政法规不可以设定行政许可。"},{"label":"C","content":"因为规定“申请小型汽车驾驶证的年龄条件为18周岁以上、70周岁以下”，所以，不满18周岁以及超过70周岁的公民不能申请小型汽车驾驶证。"},{"label":"D","content":"因为规定“18周岁以上的公民，可以独立进行民事活动”。所以，不满18周岁的公民，不能独立进行民事活动。"}],"answer":"C","explanation":"题干的论证逻辑为充分条件假言命题否定前件得出否定后件的错误逻辑。A、B、D三项都与题干相同，只有C项是通过否定后件得出否定前件，是正确的论证逻辑。故答案选C。","no":129},{"id":"1718789646929","type":"single","material":"","stem":"如果在化工厂工作，那么就是在有污染的环境下工作，如果长期在有污染的环境下工作，那么就会患肝脾肿大的病。<br>所以：","options":[{"label":"A","content":"在化工厂工作的人，一定会患肝脾肿大的病"},{"label":"B","content":"患肝脾肿大的病人，一定在化工厂工作"},{"label":"C","content":"在化工厂以外工作的人，不可能患肝脾肿大的病"},{"label":"D","content":"长期在化工厂工作的人，一定会患肝脾肿大的病"}],"answer":"D","explanation":"如果在化工厂工作，那么就是在有污染的环境下工作，可知在化工厂工作是在有污染的环境下工作的充分条件，如果长期在有污染的环境下工作，那么就会患肝脾肿大的病，可知长期在有污染的环境下工作是就会患肝脾肿大的病的充分条件。所以如果长期在化工厂工作就会患肝脾肿大的病，故选择D。","no":130},{"id":"1718789646930","type":"single","material":"","stem":"一个亿万富翁，在他自己的心目中，其生命至少值他那亿万家产。在他的妻子儿女看来，不值亿万也应该值千万。而在绑匪看来，其价值不过就是实施绑票的那些成本。<br>由此可以推出：","options":[{"label":"A","content":"亿万富翁在家人的眼中最值钱"},{"label":"B","content":"同一个人的生命，在不同的人那里有不同的估价"},{"label":"C","content":"命价由他人的支付能力决定"},{"label":"D","content":"支付人的支付意思决定了亿万富翁到底值多少钱"}],"answer":"B","explanation":"题干分别描述了亿万富翁的生命在他本人、他的妻子儿女以及绑匪眼中的不同价值，说明同一个人的生命，在不同的人那里有不同的估价，即B项；A项明显错误；C、D两项在题干中并未体现。故答案选B。","no":131},{"id":"1718789646931","type":"single","material":"","stem":"有人说：“只有肯花大价钱的足球俱乐部才进得了中超足球联赛。”如果以上判断是真的，可能出现的情况是：<br>①某足球俱乐部花了大价钱，没有进中超。<br>②某足球俱乐部没有花大价钱，进了中超。<br>③某足球俱乐部没有花大价钱，没有进中超。<br>④某足球俱乐部花了大价钱，进了中超。","options":[{"label":"A","content":"仅④"},{"label":"B","content":"仅①、②、③"},{"label":"C","content":"仅③、④"},{"label":"D","content":"仅①、③、④"}],"answer":"D","explanation":"题干中的话是一个必要条件假言命题。根据其与肢命题的真假关系，只有当“前件假，后件真”时才为假，即②没有花大价钱，进了中超必为假，其他情况下均可能为真，故选D。","no":132},{"id":"1718789646932","type":"single","material":"","stem":"用18世纪的乐器演奏18世纪的乐曲能提供这些乐曲最初听起来怎么样的有用信息。18世纪的乐器如果不修复就无法弹奏，然而，修复这种乐器却破坏了研究者可以从中获得18世纪乐器制造技术方面的所有信息。<br>如果上面的陈述是正确的，那么基于这些陈述的下面哪一项也一定是正确的？","options":[{"label":"A","content":"如果18世纪的乐器被修复，它们就不能被用来提供最初使用的演奏技巧方面的信息"},{"label":"B","content":"被修复过的18世纪的乐器只能提供18世纪的乐器最初听起来怎么样的信息"},{"label":"C","content":"18世纪的乐器是获得那个时代乐器制作技术方面信息的唯一来源"},{"label":"D","content":"一旦18世纪的乐器可以被用来演奏乐曲，那么它就不能作为获得18世纪乐器制作技术的一个新的信息来源"}],"answer":"D","explanation":"题干信息可转换为：不修复18世纪的乐器⇒无法弹奏；修复18世纪的乐器⇒破坏了研究者可以从中获得18世纪乐器制造技术方面的所有信息。即“可以弹奏⇒修复18世纪的乐器⇒破坏了研究者能从中获得的信息”，可知D项正确。A项中的“最初使用的演奏技巧”为无关项；B项中的“只能”和C项中的“唯一来源”属于过度推断，排除。故答案选D。","no":133},{"id":"1718789646933","type":"single","material":"","stem":"已知下列命题前两个假，后两个真。<br>（1）如果A没有被提拔，那么B就被提拔<br>（2）A和B两个人中只有一人被提拔<br>（3）只有A被提拔，C才不被提拔<br>（4）如果C被提拔，D也被提拔据此可以推出：","options":[{"label":"A","content":"A和B被提拔，C和D未被提拔"},{"label":"B","content":"A和B未被提拔，C和D被提拔"},{"label":"C","content":"A和C被提拔，B和D未被提拔"},{"label":"D","content":"A和C未被提拔，B和D被提拔"}],"answer":"B","explanation":"命题（1）（2）为假，则其负命题为真，可知A和B都没有被提拔；再结合（3）（4）为真，可知C和D被提拔。故答案选B。","no":134},{"id":"1718789646934","type":"single","material":"","stem":"有甲、乙、丙、丁、戊五个短跑运动员进行男子100米决赛。看台上，赵明和钱亮在预测他们的名次。赵明说，名次排序是戊、丁、丙、甲、乙；钱亮说，名次排序是甲、戊、乙、丙、丁。决赛结果表明：赵明既没有猜对任何一个运动员的正确名次，也没有猜对任何一对名次相邻运动员的顺序关系；钱亮既猜对了两个运动员的正确名次，又猜对了名次相邻运动员的顺序关系。<br>据此可知，五个短跑运动员的名次排序应该是：","options":[{"label":"A","content":"甲、乙、丙、丁、戊"},{"label":"B","content":"乙、甲、戊、丙、丁"},{"label":"C","content":"丁、戊、甲、乙、丙"},{"label":"D","content":"丙、丁、戊、甲、乙"}],"answer":"B","explanation":"代入排除法。由赵明没有猜对任何一个运动员的名次，可排除A、D。由赵明没有猜对任何一对名次相邻运动员的顺序关系，可排除C项。因此，选B。","no":135},{"id":"1718789646935","type":"single","material":"","stem":"甘蓝比菠菜更有营养，但是，因为绿芥兰比莴笋更有营养，所以甘蓝比莴笋更有营养。<br>下列各项，作为新的前提分别加入到题干的前提中，都能使题干的推理成立，除了：","options":[{"label":"A","content":"甘蓝与绿芥兰同样有营养"},{"label":"B","content":"菠菜与绿芥兰同样有营养"},{"label":"C","content":"菠菜比绿芥兰更有营养"},{"label":"D","content":"绿芥兰比甘蓝更有营养"}],"answer":"D","explanation":"由绿芥蓝＞甘蓝，绿芥蓝＞莴苣，甘蓝＞菠菜不能推出甘蓝＞莴苣。故答案选D。","no":136},{"id":"1718789646936","type":"single","material":"","stem":"要建立市场经济体制，就应建立相应的法律法规来规范市场竞争，从本质上说，市场经济是一种法制经济。因此，在一个法制不健全的国家是不可能建立市场经济体制的。<br>以下哪项如果为真，则最能削弱上述结论？","options":[{"label":"A","content":"市场经济与法制经济不是一个概念"},{"label":"B","content":"健全的法规体系可以有效地保障竞争的平等"},{"label":"C","content":"完备的法规体系对发展市场经济的作用非同小可"},{"label":"D","content":"法律法规体系的完善依赖于市场经济体制的完善"}],"answer":"D","explanation":"削弱型题目。要削弱的结论是：一个法制不健全的国家是不可能建立市场经济体制的。论据是：要建立市场经济体制，应当建立相对应的法律来规范市场竞争。D项指出，法制规范体系的完善依赖于市场经济体制的完善，即市场经济体制的完善，是国家法制健全的必要条件，说明题干的论证是因果倒置，削弱了论点。A、B、C三项均属于无关项，不能对题干论断提出质疑。故答案选D。","no":137},{"id":"1718789646937","type":"single","material":"","stem":"一只兔子没命地狂奔，路遇狼。狼说，你跑那么急干嘛？兔子说，他们要逮住我，给我钉掌。狼说，他们要逮住钉掌的是骆驼，而不是你。兔子说，他们要是逮住我钉了掌，你看我还怎么证明自己不是骆驼。<br>下列哪一项最能支持兔子的观点？","options":[{"label":"A","content":"兔子一旦钉了掌就变成了骆驼"},{"label":"B","content":"人一旦被冤枉，跳进黄河也洗不清"},{"label":"C","content":"赵高指鹿为马"},{"label":"D","content":"兔子终究是兔子，不是骆驼"}],"answer":"A","explanation":"兔子狂奔的理由是被逮住后钉了掌就无法证明自己不是骆驼，A项直接支持了兔子的观点；B项是该寓言的引申含义，但对兔子的观点的支持力度较弱；C项为无关项；D项削弱了兔子的观点。故答案选A。","no":138},{"id":"1718789646938","type":"single","material":"","stem":"美国睡眠专家设计了一项测试，让志愿者在睡眠实验室里连续度过13个夜晚。前4个夜晚，志愿者每晚能睡足8小时；接下来6天，他们的睡眠时间缩短至每晚6小时；最后3个晚上，志愿者出现“补觉”现象，每天要睡10小时。测试结果显示，持续几天睡眠不足后，志愿者反应速度变慢。补觉后，虽然感觉头脑清醒一些，但仍行动迟缓、笨拙。由此可见，连续工作一周、睡眠不足后，用3个晚上补觉可以改善困倦的状况，但是不能改善缺觉对认知功能造成的累积影响。<br>以下哪项如果为真，最能支持上述结论？","options":[{"label":"A","content":"很多志愿者难以适应睡眠实验室的环境，晚上经常做梦"},{"label":"B","content":"志愿者平时习惯的睡眠时间不等，平均睡眠时间为每晚6小时"},{"label":"C","content":"实验前后对志愿者进行大脑功能扫描，发现大脑结构并无明显异常"},{"label":"D","content":"补觉后让志愿者进行反应灵敏度测试，多数人的灵敏度明显低于平时"}],"answer":"D","explanation":"题干结论是补觉不能改善睡眠不足对认知功能造成的累积影响。A、B两项是无关项；C项实验前后对大脑进行扫描结果对结论无影响，不能加强题干观点；D项测试结果直接支持了题干结论。故答案选D。","no":139},{"id":"1718789646939","type":"single","material":"","stem":"为了获得一些工作经验，大学四年级的学生都需要参与社会活动，某高校某专业的学生向甲公司投递实习申请的同时都向乙公司投递了实习申请，甲乙两公司都决定给予其中半数的申请者每人三个月的实习机会。因此，所有的学生都找到了实习工作。<br>上述论述依据的假设是：","options":[{"label":"A","content":"所有申请者既能胜任甲公司的工作，又能胜任乙公司的工作"},{"label":"B","content":"不存在一个申请者能同时拿到两家公司发出的实习同意书"},{"label":"C","content":"这些学生没有一个向第三家公司提出实习申请"},{"label":"D","content":"所有的这些学生都愿意到两家公司去实习"}],"answer":"B","explanation":"根据题干条件，可知向甲公司投递实习申请的学生和向乙公司投递实习申请的学生为全同关系，又因为甲乙两个公司各同意给予其中半数的申请者每人三个月的实习机会，要使所有这些申请者都找到实习工作就必须保证这个公司所给实习机会的学生没有重合的，即不存在一个申请者能同时拿到两家公司的实习同意书，否则会出现有的同学有两个实习机会而有的同学没有的情况。故答案为B。","no":140},{"id":"1718789646940","type":"single","material":"","stem":"根据对一万个经常上网的人的抽样检查，承认上网后感到烦躁和恼火的人数达到了1/3，而20岁以下的网迷则有44%承认上网后感到紧张和烦躁。有关专家认为，确实存在着某种“互联网狂躁症”。<br>根据上述材料，以下哪项最不可能成为导致“互联网狂躁症”的原因？","options":[{"label":"A","content":"由于上网者的人数剧增，通道拥挤，如果要访问比较繁忙的网址，有时需要等待很长时间"},{"label":"B","content":"上网者经常是在不知道网址的情况下搜寻所需的资料和信息，成功的概率很小，有时花费了工夫也得不到预想的结果"},{"label":"C","content":"虽然在有些国家使用互联网是免费的，但在我国实行上网交费制，这对网络用户的上网时间起到了制约作用"},{"label":"D","content":"在互联网上能够接触到各种信息，但很多时候信息过量会使人们无所适从，失去信心，个人注意力丧失"}],"answer":"C","explanation":"A、B、D分别从上网等待时间、搜索信息成功率及接触信息方面说明上网后感觉紧张和烦躁，显然都可能导致“互联网狂躁症”。C项反而制约了公众上网，不可能成为导致“互联网狂躁症”的原因。因此答案选C。","no":141},{"id":"1718789646941","type":"single","material":"","stem":"有些大学生喜欢旅游，所有的登山爱好者都喜欢旅游。因此有些大学生也是登山爱好者。<br>以下哪个推理具有与上述推理最为类似的结构？","options":[{"label":"A","content":"垄断行业的利润都很高，能源行业是垄断行业，所以能源行业的利润也很高"},{"label":"B","content":"有些博士考取了法律职业资格证书，所有律师都必须有法律职业资格证书，因此律师中有些是博士"},{"label":"C","content":"有些理论是有应用价值的，真理都具有应用价值，因此有些理论是真理"},{"label":"D","content":"有些大学生考试不及格，所有考试不及格的学生都没有认真学习，所以有些大学生没有认真学习"}],"answer":"C","explanation":"题干结构为：有些A是B，所有C是B，因此有些A是C。<br>A项结构是：A是B，C是A，因此C是B。<br>B项结构是：有些A是B，所有C是B，因此有些C是A。<br>C项结构是：有些A是B，所有C是B，因此有些A是C。<br>D项结构是：有些A是B，所有B是C，因此有些A是C。故答案选C。","no":142},{"id":"1718789646942","type":"single","material":"","stem":"某国经济以农业为主，2009年遭受百年不遇的大旱，国际有关组织号召各国人民向该国伸出援助之手。<br>下面最可能的推断是：","options":[{"label":"A","content":"该国农业生产力水平低"},{"label":"B","content":"该国是一个经济发达国家"},{"label":"C","content":"该国国民收入低、生活水平低"},{"label":"D","content":"该国的经济受气候影响大"}],"answer":"D","explanation":"题干是说以农业为主的某国经济受到了大旱的影响，故D项正确。其他三项由题干无法推出。故答案选D。","no":143},{"id":"1718789646943","type":"single","material":"","stem":"中国文化不但对韩国、日本，甚至对东南亚、南亚一些国家和地区都产生了深远的影响，郑和七下西洋更是加深了这种影响。由此形成了世界所公认的以中国文化为核心的东亚文化圈。<br>从这段话我们可以得知：","options":[{"label":"A","content":"郑和七下西洋加深了中国文化对世界的影响"},{"label":"B","content":"东亚文化圈是以中国文化为核心的"},{"label":"C","content":"中国文化对世界上所有国家都有影响"},{"label":"D","content":"中国文化促进了东亚国家的经济发展"}],"answer":"B","explanation":"由题干最后一句可得B项正确；郑和下西洋加深的是对韩国、日本、东南亚、南亚一些国家和地区的影响，并非A项所说的“世界”；C项“所有国家”错误；D项的经济发展题干并未提到。故答案选B。","no":144},{"id":"1718789646944","type":"single","material":"","stem":"曾国藩天资并不聪慧，但却成为“内圣外王”式的人物，成为清朝的“中兴之臣”，与他注重自我修养，使自己不断完善是分不开的。而在其漫长的一生中，写这种类似“微博”的日记，并公之于亲人朋友，成为他最重要的自修方式。一个人最难战胜的，就是自己。即使你自制力再强，也有被自己打败的时候。所以真正强大的人，不是向外显现力量，而是能放下身段，放低自己，不断从外界汲取力量。由此可以推出：","options":[{"label":"A","content":"战胜自己是一个人成功的关键"},{"label":"B","content":"自我修养的提高需要长时间的坚持"},{"label":"C","content":"曾国藩的最聪明之处是对内注重自我修养，对外汲取力量"},{"label":"D","content":"曾国藩自制能力非常强"}],"answer":"C","explanation":"由“一个人最难战胜的，就是自己”无法推出A项。题干没有提到“长时间的坚持”以及曾国藩的自制力强弱，B、D两项无中生有。C项可以由题干推出，故答案选C。","no":145},{"id":"1718789646945","type":"single","material":"","stem":"有一个仓库失窃。有甲乙丙丁四个人。甲说：我当时在外地，所以不是我偷的。乙说：是丁偷的。丙说：是乙干的，我看到他进了仓库。丁说：乙诬陷我。<br>以上如果其中有一个人说的话是真的，那么：","options":[{"label":"A","content":"甲是小偷"},{"label":"B","content":"乙是小偷"},{"label":"C","content":"丙是小偷"},{"label":"D","content":"丁是小偷"}],"answer":"A","explanation":"乙和丁的话相互矛盾，必有一真一假，由只有一个人说的话为真可知甲和丙说的话为假，由甲的话为假可知是甲偷的。故答案选A。","no":146},{"id":"1718789646946","type":"single","material":"","stem":"如果“只有小王是大学生，小王才懂英语”为假，则下列哪句话为真？","options":[{"label":"A","content":"小王不是大学生，或者小王懂英语"},{"label":"B","content":"小王是大学生，并且小王不懂英语"},{"label":"C","content":"小王不是大学生，并且小王不懂英语"},{"label":"D","content":"如果小王不是大学生，那么小王不懂英语"}],"answer":"A","explanation":"根据题干，“只有小王是大学生，小王才懂英语”为假，则其负命题“小王不是大学生且小王懂英语”为真，则A项“小王不是大学生或者小王懂英语”为真，其余几项均不能推出。故答案选A。","no":147},{"id":"1718789646947","type":"single","material":"","stem":"本市白蚁防治所规定：“除非小区中住户家中发现白蚁，否则任何小区都不能免费领取高效杀蚁灵。”天水家园小区住户家中发现了白蚁，锦绣东城小区可以免费领取高效杀蚁灵。<br>如果上述断定都是真的，则据此不能断定以下哪项的真假？①天水家园小区有的住户家中没有发现白蚁②天水家园小区能免费领取高效杀蚁灵<br>③领取高效杀蚁灵的小区住户家中都发现了白蚁","options":[{"label":"A","content":"只有①和③"},{"label":"B","content":"只有①和②"},{"label":"C","content":"只有②和③"},{"label":"D","content":"①②和③"}],"answer":"D","explanation":"题干的推理关系为：小区能免费领取高效杀蚁灵⇒小区住户家中发现白蚁。由“有些……是”不能推出“有些……非”，①的真假无法推断；因天水家园小区住户家中发现了白蚁，但是肯后不能肯前，②的真假也无法推断；由题干只能推出，小区能免费领取高效杀蚁灵的话，则该小区中必然有的住户家中发现了白蚁，但不能推出领了高效杀蚁灵的小区住户家中都发现了白蚁，③的真假也不能断定。故答案选D。","no":148},{"id":"1718789646948","type":"single","material":"","stem":"现在有七张牌，需要选出来四张，并满足以下条件，若选出1，则一定要选2，若选3，则一定要选4，若选5则一定选6，如果同时选3和7，下列哪张牌不能选出？","options":[{"label":"A","content":"4"},{"label":"B","content":"2"},{"label":"C","content":"1"},{"label":"D","content":"6"}],"answer":"C","explanation":"题干推理为：①1⇒2；②3⇒4；③5⇒6。如果选3和7，由②可知4一定被选。因要选四张牌，则只剩一张的名额，由①③可知，如果选1或者5，则还需选2和6，牌数超出，与题干矛盾，则1和5肯定不能被选出。故答案选C。","no":149},{"id":"1718789646949","type":"single","material":"","stem":"只有理解才会宽容，只有宽容社会才会和谐，没有和谐，社会就不会幸福。如果以上陈述为真，以下各项都为真，除了：","options":[{"label":"A","content":"如果不理解，社会就不会幸福"},{"label":"B","content":"如果社会幸福，那么一定宽容"},{"label":"C","content":"如果没有宽容，就不会理解"},{"label":"D","content":"如果社会幸福，那么一定相互理解"}],"answer":"C","explanation":"题干的逻辑关系为：幸福⇒和谐⇒宽容⇒理解。A项否后则否前，正确；B项肯前则肯后，正确；C项否定前件无法推出后件；D项肯前则肯后，正确。故答案为C。","no":150},{"id":"1718789646950","type":"single","material":"","stem":"某商店在本市有三家分店：福山路店、南方路店和新华路店。其中，三家店分别主营日化用品、服装和食品。现在只知道：<br>（1）今年新华路店比主营食品的分店营业额要高；<br>（2）福山路店和主营服装的分店营业额不同；<br>（3）主营服装的分店营业额低于南方路店。<br>根据上文，下列说法正确的是：","options":[{"label":"A","content":"福山路店主营的不是食品"},{"label":"B","content":"主营食品的分店今年的营业额最低"},{"label":"C","content":"主营服装的分店营业额低于福山路店"},{"label":"D","content":"主营服装的分店营业额高于主营日化用品的分店"}],"answer":"B","explanation":"根据（2）（3）可知主营服装的分店是新华路店。结合营业额高低，可知：南方路（日化）>新华路（服装）>福山路（食品）。故答案选B。","no":151},{"id":"1718789646951","type":"single","material":"","stem":"一些政府官员相信，通过对某一地区房地产市场的开发，就能够带动其他行业的开发建设。这种观点基于下面的观点，即如果某一地区房地产市场繁荣，那么该地区其他产业也会繁荣。<br>下列哪项对上面所说的“房地产市场繁荣的地区”的描述最严重地质疑了上述假设？","options":[{"label":"A","content":"该地区位于市区中心"},{"label":"B","content":"一些行业，比如房屋装修，只要发展繁荣，就需要大量的装修工人"},{"label":"C","content":"该地区居民较多，能够让本地区一些相关的产业发展起来"},{"label":"D","content":"在产业类型较多的地区，一些发展较为缓慢的产业会更集中"}],"answer":"D","explanation":"题干假设是某一地区房地产市场繁荣，那么该地区其他产业也会繁荣。A项是无关项；B、C两项均能加强该假设；D项说明房地产市场繁荣的地区，由于产业类型较多，会存在一些发展较为缓慢的产业，并非其他产业也会繁荣，削弱了题干假设。故答案选D。","no":152},{"id":"1718789646952","type":"single","material":"","stem":"全校的本地户籍学生都出席了上周联谊会，小强出席了上周联谊会，因此小强是本地户籍。<br>下列有力削弱上述推理的是：","options":[{"label":"A","content":"出席上周联谊会的小华不是本地户籍"},{"label":"B","content":"有不少非本地户籍学生参加"},{"label":"C","content":"如果缺少工作人员，联谊会将邀请非本地学生出席，并担任工作人员"},{"label":"D","content":"小强曾出席过其他联谊会"}],"answer":"B","explanation":"题干是错误的三段论推理，“全校的本地户籍学生都出席了上周联谊会”不代表所有出席联谊会的都是本地户籍学生，也可能有非本地户籍的学生参加。B项指出了这一漏洞，最能削弱题干推理。","no":153},{"id":"1718789646953","type":"single","material":"","stem":"当鸟类面临栖息地破坏、天敌威胁和环境污染等生存压力时，自身就会分泌一种名为皮质醇的激素。因此，经常处于生存压力状态下的鸟类，其羽毛会变得较为稀疏。<br>以下哪项如果为真，能够支持上述论证？","options":[{"label":"A","content":"鸟类体内的皮质醇含量可能因全球变暖而发生变化"},{"label":"B","content":"一些鸟类更换栖息地后，体内的激素水平会增高"},{"label":"C","content":"皮质醇会影响鸟类羽毛的生长和代谢"},{"label":"D","content":"如果鸟类的羽毛变得稀疏，则它们一定处于长期的压力状态"}],"answer":"C","explanation":"题干根据“鸟类面临生存压力时会分泌皮质醇激素”，得出“经常处于生存压力状态下的鸟类，羽毛会变稀疏”这一结论。C项在“皮质醇激素”与“羽毛”之间建立联系，加强了题干论证；A项的“全球变暖”在题干中并未提及；B项是无关项；D项肯定后件不能肯定前件，也不能加强题干结论。故答案选C。","no":154},{"id":"1718789646954","type":"single","material":"","stem":"母乳喂养是否更有利于孩子的智能发展？某研究团队肯定了这一点。团队对1500个孩子在他们9个月、2岁和4岁时进行了追踪测试，研究发现母乳喂养超过3-5个月的儿童在智力测试中得分高于母乳喂养少于3个月的儿童，而后者的得分又比没有经过母乳喂养的儿童高。<br>下列选项如果正确，最能支持上述论述的是：","options":[{"label":"A","content":"提供母乳喂养的母亲对孩子情绪更为关注"},{"label":"B","content":"提供母乳喂养的母亲大多数都是中等以上文化水平"},{"label":"C","content":"母乳中某些促进大脑发育的营养成分是无法人工合成的"},{"label":"D","content":"父母在早期为孩子朗读书籍的频次能影响孩子的认知能力"}],"answer":"C","explanation":"题干通过追踪研究得出母乳喂养更有利于孩子的智能发展。A、D项为无关项；B项在一定程度上削弱了题干观点，属于另有他因；C项母乳中存在人工无法合成的营养成分，即母乳喂养比非母乳喂养存在更有利于孩子智力发展的优势，有力地支持了题干论述。故答案为C。","no":155},{"id":"1718789646955","type":"single","material":"","stem":"在大汶口文化的后期墓葬中，出现了夫妻合葬和夫妻带小孩的合葬，这标志着只知其母不知其父的母系社会的结束。<br>上述推论中隐含着的假设是：","options":[{"label":"A","content":"在母系社会，不存在夫妻合葬和夫妻带小孩的合葬"},{"label":"B","content":"在父系社会，夫妻死后必须合葬"},{"label":"C","content":"在父系社会，夫妻关系比较好"},{"label":"D","content":"在母系社会，不采取合葬的方式"}],"answer":"A","explanation":"题干由在大汶口文化的后期墓葬中，出现夫妻合葬和夫妻带小孩的合葬推出母系社会的结束。A项母系社会→不存在夫妻合葬和夫妻带小孩的合葬，即题干是否后即否前的正确推理，是推论中隐含的假设；题干没有涉及父系社会，B、C项错误；D项“合葬”和“夫妻合葬和夫妻带小孩合葬”有一定区别，不是必须假设的。故答案选A。","no":156},{"id":"1718789646956","type":"single","material":"","stem":"国产影片《夏洛特烦恼》显然是近期最好的电影。这部电影的主创人员不是明星大腕，这是一部低成本制作的影片，但其票房收入的明显领先说明观看该部影片的人数远多于同期上映的进口大片《蚁人》。<br>为使上述论证成立，必须假设的前提是：<br>Ⅰ.《夏洛特烦恼》和《蚁人》的票价基本相同Ⅱ.观众数量的多少是评价电影质量的一个重要参考标准Ⅲ.制作成本是评价电影质量的标准","options":[{"label":"A","content":"只有Ⅰ"},{"label":"B","content":"只有Ⅱ"},{"label":"C","content":"Ⅰ、Ⅱ"},{"label":"D","content":"Ⅰ、Ⅲ"}],"answer":"C","explanation":"只有在票价相同的情况下，票房收入明显领先才能说明观看影片的人数更多，Ⅰ是必须假设的；题干由影片《夏洛特烦恼》观看人数更多，得出该影片是近期最好的电影，要使论证成立则需要补充前提，即观看人数是评判电影质量的重要参考标准，所以Ⅱ是必须假设的；Ⅲ不是必须假设的。故答案为C。","no":157},{"id":"1718789646957","type":"single","material":"","stem":"“试点综合症”问题现在屡见不鲜。出台一项改革措施，先试点，然后再推广，这种以点带面的方法是人们经常采用的，但现在许多项目出现了“一试点成功，一推广就失败“的现象。<br>下列哪项最不可能是造成上述现象的原因？","options":[{"label":"A","content":"整个社会往往都倾向将注意力集中在试点上"},{"label":"B","content":"为保证试点成功，政府往往给予试点许多优惠政策"},{"label":"C","content":"在试点过程中，领导往往比较重视，各方面问题会解决得快"},{"label":"D","content":"试点尽管成功，但许多外部的政策，市场环境却并不相同"}],"answer":"A","explanation":"题干的矛盾为“一试点就成功，一推广就失败”。B、C、D三项分别从政府的优惠政策，领导的重视，政策和市场环境的差异几方面说明试点时和推广时外在条件的不同，均是可能造成上述结果的原因；A项整个社会对试点的关注不可能是造成上述现象的原因。故答案选A。","no":158},{"id":"1718789646958","type":"single","material":"","stem":"一百年来，婚俗也是在不断演变。到了上世纪50年代，这个婚礼就过于简单了，有一个说法是：50年代一张床，60年代一包糖，70年代红宝书，80年代三转一响。三转一响是哪些东西？自行车、手表、缝纫机，这是三转，一响则是收音机。到了90年代以后，生活水平有了极大的提高，于是婚礼就更加多样化、个性化了。<br>由此可推出：","options":[{"label":"A","content":"婚俗的演变史是一部社会经济发展史"},{"label":"B","content":"婚俗的变迁也反映了一个时代的政治背景和社会的变迁"},{"label":"C","content":"婚礼的简易程度和经济发展程度成正比"},{"label":"D","content":"婚礼形式的多样化和个性化是物质极大丰富的直接结果"}],"answer":"B","explanation":"根据题干可知，婚俗与经济发展程度和社会政治背景密切相关，B项正确。由“50年代一张床，60年代一包糖，70年代红宝书，80年代三转一响”，无法推出A、C两项；题干说的是“生活水平有了极大的提高，于是婚礼就更加多样化、个性化了”，D项偷换为“物质极大丰富”。故答案选B。","no":159},{"id":"1718789646959","type":"single","material":"","stem":"开车的人都知道，从短期看缩减日常保养可能节省用车成本，但从长远角度看，这样做成本很大。<br>以下哪项不是上述对比暗含的意思？","options":[{"label":"A","content":"为了让车辆正常行驶，需要对车辆进行日常保养"},{"label":"B","content":"车主可以带着侥幸心理不进行车辆的日常保养"},{"label":"C","content":"车辆都有正常的使用年限，年限届满必须报废"},{"label":"D","content":"如果车辆不正常保养，出了问题会花费更多的钱"}],"answer":"C","explanation":"“从短期看缩减日常保养可能节约用车成本”暗含着可以不对车辆进行日常保养的意思；“从长远角度看，这样做成本很大”说明了对车辆进行日常保养是非常必要的，如果不正常保养，出了问题成本会更高，故A、B、D三项都是题干暗含的意思。C项车辆报废与日常保养无关，不是题干暗含的信息。答案选C。","no":160},{"id":"1718789646960","type":"single","material":"","stem":"签订技术转让合同必须遵守国家的法律，符合国家政策的要求。否则，即使是当事人双方自愿签订的合同，非但不能受到法律保护，还要根据情况依法追究法律责任。<br>与以上论述等值的是：","options":[{"label":"A","content":"如果双方当事人的行为都是自愿的，就会受到法律的保护"},{"label":"B","content":"如果双方当事人的行为都是自愿的，就要承担法律责任"},{"label":"C","content":"只有双方当事人的行为合法，才能产生预期的法律后果，受到法律的保护"},{"label":"D","content":"如果双方当事人的行为合法，就会产生预期的法律后果，受到法律的保护"}],"answer":"C","explanation":"考查的是假言命题的两种形式即充分条件假言命题和必要条件假言命题。根据题干可知受法律保护则必定合法，不合法则必定不受法律保护，即合法是受法律保护的必要条件，而必要条件假言命题的形式是“只有…才…”，充分条件假言命题的形式“只要…就…”，因此选C。","no":161},{"id":"1718789646961","type":"single","material":"","stem":"建设和谐社区是和谐社会建设的重要组成部分。只有进一步完善社区的管理体制，才能明确社区的社会职责；如果不提高社区的服务水平，就不能满足居民快速增长的各种需求；社区管理的法规建设是社区基层民主自治的重要前提，而加强社区基层的民主自治也有利于完善社区的管理体制。<br>由此可见：","options":[{"label":"A","content":"如果不能提高社区的服务水平，就不能提高社区的服务质量"},{"label":"B","content":"如果不进一步完善社区的管理体制，就不能明确社区的社会职责"},{"label":"C","content":"只有加强社区管理的法规建设，才能明确社区的社会体制"},{"label":"D","content":"只有加强社区基层的民主自治，才能满足居民快速增长的各种需求"}],"answer":"B","explanation":"考查复言命题。根据题干，“进一步完善社区的管理体制”是“明确社区的社会职责”的必要条件，否定前件就能否定后件，B项正确。A项明显错误。C项和D项也无法由题干内容推出。","no":162},{"id":"1718789646962","type":"single","material":"","stem":"某公司需要派员工参加全国的专业论坛，人员选派标准有以下几个注意点：<br>（1）甲和乙两人至少要去一个人；<br>（2）甲和丁不能一起去；<br>（3）甲、戊、己三人中要派两人去；<br>（4）乙、丙两人中去一个人；<br>（5）丙、丁两人中去一个人；<br>（6）若丁不去，则戊也不去。<br>据此，可以推断出（   ）被选派去参加论坛了。","options":[{"label":"A","content":"甲、乙、丙、己"},{"label":"B","content":"乙、丙、戊、己"},{"label":"C","content":"乙、丙、丁、戊"},{"label":"D","content":"乙、丁、戊、己"}],"answer":"D","explanation":"代入排除法。根据四个选项，都含有乙，所以乙必然参加。如果乙去，那么根据（4）丙不能参加，则只有D项符合题干所有条件。故答案选D。","no":163},{"id":"1718789646963","type":"single","material":"","stem":"五对夫妻结伴自驾游。从出发点到目的地，正好有三个服务区，将他们的行程分为四段路，他们在每个服务区都休息了一会儿，有的夫妻也刚好可以换人驾车走下一段路。车队行进过程中，每对夫妻均在自家车中，一人驾车，一人休息。小孙因头晚喝了不少酒，所以今天一直未敢碰方向盘，只是与驾车的妻子说着闲话。已知：<br>第一段路驾车的是：张、王、李、赵、周；第二段路驾车的是：吴、王、张、赵、郑；第三段路驾车的是：李、钱、张、刘、吴；第四段路驾车的是：郑、张、王、钱、周。依据以上信息，可以推出这五对夫妻分别是：","options":[{"label":"A","content":"李吴、周郑、赵钱、孙张、刘王"},{"label":"B","content":"刘赵、钱王、孙李、郑张、周吴"},{"label":"C","content":"孙张、李郑、吴周、刘王、赵钱"},{"label":"D","content":"孙张、周郑、李吴、刘赵、王钱"}],"answer":"C","explanation":"根据题干可知，每对夫妻都是一人驾车一人休息，说明每段路中同时驾车的人不可能为夫妻，根据第二段路驾车的人可排除B项，因为郑、张不可能为夫妻；同理根据第三段路驾车的人可排除A、D两项，因为李、吴不可能为夫妻。故答案选C。","no":164},{"id":"1718789646964","type":"single","material":"","stem":"有三个人A、B、C，他们的身份分别是国王、王子、公主。其中，国王总是说真话；王子总是说假话；公主有时说假话有时说真话。下面是他们的话：A说：“我不是国王。”B说：“我不是公主。”C说：“我不是王子。”请问A、B、C的真实身份分别为：","options":[{"label":"A","content":"王子、国王、公主"},{"label":"B","content":"公主、国王、王子"},{"label":"C","content":"国王、公主、王子"},{"label":"D","content":"公主、王子、国王"}],"answer":"B","explanation":"分析A的话，他既不能是说真话的国王，也不能是说假话的王子，则A只能是公主，说的是真话；进而可知B说的是真话，B为国王；C为王子，说的话为假。故答案选B。","no":165},{"id":"1718789646965","type":"single","material":"","stem":"某酒店正在举办一个大型的国际经济论坛年会。住在酒店同一层朝南四间房间号分别为1、2、3、4号，分别住着来自俄罗斯，中国，英国和西班牙的四位经济学家，有记者准备采访他们，询问他们的具体房间号。<br>（1）俄罗斯人说：我的房间号大于西班牙人，且我不会说外语，也无法和邻居交流；<br>（2）中国人说：我会说西班牙语，但我却无法和邻居交流；<br>（3）英国人说：我会说俄语，但我只可以和一个邻居交流；<br>（4）西班牙人说：我会说我们这四个国家的语言。<br>按照房号从小到大的顺序来讲，房间里住的人的国籍分别是：","options":[{"label":"A","content":"英国西班牙俄罗斯中国"},{"label":"B","content":"中国英国西班牙俄罗斯"},{"label":"C","content":"西班牙英国中国俄罗斯"},{"label":"D","content":"西班牙英国俄罗斯中国"}],"answer":"C","explanation":"由（4）西班牙人会说四个国家的语言和（3）英国人会说俄语，结合（1）俄罗斯人无法和邻居交流可知俄罗斯人和西班牙人、英国人都不是邻居，即俄罗斯人和中国人相邻且只有中国人一个邻居，只有C项符合。故答案为C。","no":166},{"id":"1718789646966","type":"single","material":"","stem":"某些种类的海豚利用回声定位来发现猎物：它们发射出滴答的声音，然后接收水域中远处物体反射的回音。海洋生物学家推测这些滴答声可能有另一个作用：海豚用异常高频的滴答声使猎物的感官超负荷，从而击晕近距离的猎物。<br>以下哪项如果为真，最能对上述推测构成质疑？","options":[{"label":"A","content":"海豚用回声定位不仅能发现远距离的猎物，而且能发现中距离的猎物"},{"label":"B","content":"作为一种发现猎物的讯号，海豚发出的滴答声，是它的猎物的感官不能感知的，只有海豚能够感知，从而定位"},{"label":"C","content":"海豚发出的高频讯号即使能击晕猎物，这种效果也是很短暂的"},{"label":"D","content":"蝙蝠发出的声波不仅能使它发现猎物，而且这种声波能对猎物形成特殊刺激，从而有助于蝙蝠捕获它们"}],"answer":"B","explanation":"题干认为海豚用异常高频的滴答声使猎物的感官超负荷，从而击晕近距离的猎物。B项为真则说明海豚的猎物无法感知到这种声音，就不存在被击晕的情况，有力地反驳了题干结论。故答案选B。","no":167},{"id":"1718789646967","type":"single","material":"","stem":"一个已经公认的结论是，北美洲人的祖先来自亚洲，至于亚洲人是如何到达北美的呢？科学家们一直假设，亚洲人是跨越在14000年以前还连接着北美和亚洲后来沉入海底的陆地进入北美的，在艰难的迁徙途中，他们靠捕猎沿途陆地上的动物为食。最近的新发现导致了一个新的假设，亚洲人是驾船沿着上述陆地的南部海岸，沿途以鱼和海洋生物为食而进入北美的。<br>以下哪项如果为真，最能使人有理由在两个假设中更相信后者？","options":[{"label":"A","content":"当北美和亚洲还连在一起的时候，亚洲人主要以捕猎陆地上的动物为生"},{"label":"B","content":"上述连接北美和亚洲的陆地气候极为寒冷，植物品种和数量都极为稀少，无法维持动物的生存"},{"label":"C","content":"在欧洲，靠海洋生物为人的食物来源的海洋文化，最早发端于10000年以前"},{"label":"D","content":"存在于8000年以前的亚洲和北美洲文化，显示出极大的类似性"}],"answer":"B","explanation":"题干中涉及两种假设，一种是亚洲人是跨越当时还连接着北美和亚洲的陆地进入北美的，在途中靠捕猎沿途陆地上的动物为食；另一种是亚洲人是驾船沿着上述陆地的南部海岸进入北美的，沿途以鱼和海洋生物为食。B项说明不太可能在途中以陆地上的动物为食，削弱了第一种假设，从而加强第二种假设的可信性；A、C两项都加强了第一种假设，错误；D项属于无关项，排除。故答案选B。","no":168},{"id":"1718789646968","type":"single","material":"","stem":"一种部分可被生物分解的塑料饮料罐是将很小的塑料用玉米淀粉等黏合剂粘在一起而制造出来的。因为只有黏合剂分解掉了，留下了细小的塑料，这些饮料罐被丢弃时每个罐子产生的塑料垃圾并不比类似的不可被生物分解的罐子被丢弃时产生的塑料垃圾少。<br>以下哪项如果为真，最能支持上述论证？","options":[{"label":"A","content":"部分可被生物分解的和不可被生物分解的塑料饮料罐都能被垃圾压缩机完全压平"},{"label":"B","content":"部分可被生物分解的塑料饮料罐的生产程序比不可被生物分解的塑料饮料罐的生产程序产生更少的塑料废物"},{"label":"C","content":"为了弥补黏合剂的弱化效果，制造部分可以被生物分解的塑料饮料罐比制造不可被生物分解的塑料饮料罐需要更多的塑料"},{"label":"D","content":"许多消费者关心生态问题，他们宁愿购买装在可被生物分解的塑料饮料罐的产品而不愿购买装在不可被生物分解的塑料饮料罐的产品，即使前者价格高些"}],"answer":"C","explanation":"题干结论是：部分可被生物分解的塑料饮料罐产生的塑料垃圾不比不可被生物分解的塑料罐产生的塑料垃圾少。C项表明制造部分可被生物分解的塑料饮料罐比制造不可被生物分解的塑料饮料罐需要更多塑料，也说明了部分可被生物分解的塑料饮料罐产生的塑料垃圾比不可被生物分解的塑料罐产生的塑料垃圾多。","no":169},{"id":"1718789646969","type":"single","material":"","stem":"张教授说，矿泉水比纯净水含有更多的矿物质。所以，经常饮用矿泉水的人会增加患肾结石的危险，因为矿物质会在肾脏里沉淀。<br>以下哪项最能削弱张教授的论证？","options":[{"label":"A","content":"有些矿物质也是人体所必需的"},{"label":"B","content":"形成肾结石的只是某些种类的矿物质"},{"label":"C","content":"有些经常饮用纯净水的人也有肾结石"},{"label":"D","content":"矿物质在肾脏里沉淀的原因是肾功能出现了问题"}],"answer":"D","explanation":"张教授的论点是经常饮用矿泉水会增加患结石的危险，论据是矿物质会在肾脏里沉淀。D项为真说明张教授的论证是“因果倒置”，是因肾功能出问题而使矿物质沉淀，而非因饮用矿泉水使肾功能出问题，最能削弱张教授论证；A、C两项是无关项；B项说明有些矿物质确实会形成肾结石，不能削弱。故答案选D。","no":170},{"id":"1718789646970","type":"single","material":"","stem":"左撇子的人比右撇子的人更经常患有免疫功能失调症，比如过敏。但是左撇子往往在完成由大脑右半球控制的任务上比右撇子具有优势，并且大多数人的数学推理能力都受到大脑右半球的强烈影响。<br>如果以上的信息正确，它最能支持下面哪个假设？","options":[{"label":"A","content":"大多数患有过敏或其他免疫功能失调症的人是左撇子而非右撇子"},{"label":"B","content":"大多数左撇子的数学家患有某种过敏症"},{"label":"C","content":"数学推理能力强于平均水平的人中，左撇子的人的比例，要高于数学推理能力弱于平均水平的人中的左撇子比例"},{"label":"D","content":"如果一位左撇子患有过敏症，他很可能擅长数学"}],"answer":"C","explanation":"由“左撇子的人比右撇子的人更容易患某些免疫失调症”不能推出A项，因为如果右撇子的人数比左撇子的人数多很多，那么即使左撇子的人更容易患病，在患病的人中，可能还是右撇子多；C项可以由第二句推出，因为左撇子的数学推理能力更强；B、D两项显然错误。故答案选C","no":171},{"id":"1718789646971","type":"single","material":"","stem":"一个看电视的孩子经历了一个声音和图像迅速闪过屏幕的过程，其速度之快仅允许让眼睛和耳朵接收这些过程。不像书页，可以按其愿望或快或慢地看。电视画面过快的速度是在打击而不是提高孩子的想象力。<br>上面所表达的推理基于一个假设，下列哪一个最好地充当了那个假设？","options":[{"label":"A","content":"当被允许选择一种形式的娱乐时，孩子宁愿看书也不愿意看电视"},{"label":"B","content":"一个孩子的想象力不能被正确激发，除非那个孩子同时接触电视和书"},{"label":"C","content":"当能够控制娱乐步调时，孩子的想象力能够发展得更完全"},{"label":"D","content":"一旦孩子们能够理解电视上所看到的东西，他们就应当被教读书"}],"answer":"C","explanation":"题干首先指出电视画面过快，而看书可以自由控制速度的快慢，进而得出电视画面过快的速度是在打击孩子的想象力的结论。要得出上述结论，就必须假设只有娱乐的步调与孩子的接受能力相适应时，孩子的想象力才能得到更好地发展。故答案选C。","no":172},{"id":"1718789646972","type":"single","material":"","stem":"某高校规定，只有年龄不超过45岁，才有资格竞选二级学院院长的岗位。老张去年刚过40岁，所以，他一定有资格竞选二级学院院长的岗位。<br>以下哪项与题干的逻辑错误最为相似？","options":[{"label":"A","content":"只有绩效考核为优，才有资格获得全额奖金，我有资格获得全额奖金，所以我绩效考核一定为优"},{"label":"B","content":"只有绩效考核为优，才有资格获得全额奖金，我没有资格获得全额奖金，所以我绩效考核一定不好"},{"label":"C","content":"只有绩效考核为优，才有资格获得全额奖金，我绩效考核为优，所以我一定能获得全额奖金"},{"label":"D","content":"只有绩效考核为优，才有资格获得全额奖金，因此没有获得全额奖金的员工一定绩效考核不好"}],"answer":"C","explanation":"题干的推理形式是：只有A才B，A，所以B。C项与题干的推理形式一致，故选择C项。A项的形式：只有A才B，B，所以A。B项的形式：只有A才B，非B，所以非A。D项的形式：只有A才B，因此，非B一定非A。","no":173},{"id":"1718789646973","type":"single","material":"","stem":"上个世纪80年代末期，我国每年约有200万适龄儿童失学，其中三分之二是女童。尽管国家实行九年义务教育制度，并逐步在一些贫困地方实施“两免一补”政策，但由于种种原因，仍有一些适龄儿童、少年被迫辍学。20年来，失学辍学儿童、少年的命运受到日益广泛的社会关注。其中，有这样一个团体和行动（春蕾计划），二十年如一日地关心贫困失学女童的生存与发展。<br>由此可以推出：","options":[{"label":"A","content":"春蕾计划为失学儿童争取到了平等受教育的权利"},{"label":"B","content":"春蕾计划对政府普及九年义务教育起到了辅助作用"},{"label":"C","content":"春蕾计划的实施转变了我国重男轻女的传统现状"},{"label":"D","content":"失学、辍学儿童受到了春蕾计划的广泛关注"}],"answer":"B","explanation":"题干主要说有一个团体一直关心贫困失学女童的生存与发展。题干并未说取得了什么成果，A项属于过度推断；对贫困失学女童的生存与发展的关心属于义务教育阶段的内容，会对政府普及九年义务教育起到辅助作用，B项正确；C项属于无关项，题干并未提到；D项将“贫困失学女童”换为“失学、辍学儿童”，属于偷换概念。故答案选B。","no":174},{"id":"1718789646974","type":"single","material":"","stem":"甲：如果小张去，小李就去乙：小张去了但小李没去。","options":[{"label":"A","content":"既同真又同假"},{"label":"B","content":"可同真不可同假"},{"label":"C","content":"不同真可同假"},{"label":"D","content":"不可同真不可同假"}],"answer":"D","explanation":"分析可知，甲、乙二者的话互为矛盾关系，必有一真一假。故答案选D。","no":175},{"id":"1718789646975","type":"single","material":"","stem":"老师教导学生：“在考场上，没有自信一定会输”。以下哪项与老师的话的意思最为接近？","options":[{"label":"A","content":"只有赢了，才可能更加自信"},{"label":"B","content":"在考场上，如果自信，一定会赢"},{"label":"C","content":"在考场上，只有自信，才可能不输"},{"label":"D","content":"在考场上，除非自信，否则不可能输"}],"answer":"C","explanation":"题干推理为：没有自信⇒一定输。由否后得否前：不一定输⇒有自信，即自信是可能不输的必要条件，C项正确。故答案选C。","no":176},{"id":"1718789646976","type":"single","material":"","stem":"一个产品要创成名牌产品，必须质量过硬。一个产品，只有提高技术含量，才能质量过硬；而一个企业如果忽视技术投资，产品的技术含量不可能提高。<br>以下哪项可由上述论断推出？<br>Ⅰ.一个生产名牌产品的企业，不可能忽视技术投资。<br>Ⅱ.一个缺少技术含量的产品，不可能创成品牌。<br>Ⅲ.一个产品质量不过硬的企业，一定忽视了技术投资。","options":[{"label":"A","content":"只有Ⅰ"},{"label":"B","content":"只有Ⅱ"},{"label":"C","content":"只有Ⅰ和Ⅱ"},{"label":"D","content":"Ⅰ、Ⅱ和Ⅲ"}],"answer":"C","explanation":"题干逻辑关系为：创成名牌产品⇒质量过硬⇒提高技术含量⇒不忽视技术投资。肯定前件则肯定后件，Ⅰ可以推出；否定后件则否定前件，Ⅱ可以推出；否定前件不能否定后件，Ⅲ不能推出。故答案选C。","no":177},{"id":"1718789646977","type":"single","material":"","stem":"一位贫穷的农民喜欢这样教导他的孩子们：“在这个世界上，你不是富就是穷，不是诚实就是不诚实。由于所有穷人都是诚实的，所以，每个富人都是不诚实的。”<br>如果这个农民的结论能合逻辑地推导出来，其前提假设是：","options":[{"label":"A","content":"每个诚实的农民都是贫穷的"},{"label":"B","content":"每个诚实的人都是农民"},{"label":"C","content":"每个不诚实的人都是富裕的农民"},{"label":"D","content":"每个穷人都是诚实的"}],"answer":"A","explanation":"题干由“所有穷人都是诚实的”推出“所有富人都是不诚实的”，由于否前不能否后，要使这一结论成立，需要假设每个诚实的都不是富人，即每个诚实的农民都是穷人，A项是必须假设的。故答案选A。","no":178},{"id":"1718789646978","type":"single","material":"","stem":"某政府工程揽标，甲乙丙丁公司参与投标，在标底公布以前，各公司经理分别作出推测。<br>甲公司经理说：我们公司最可能中标，其他公司不可能。乙公司经理说：中标的不是甲公司就一定是我们公司。丙公司经理说：四个公司中会中标的一定是我们公司。丁公司经理说：中标的公司一定出自乙和丁公司。<br>若四人中只有一人预测成真，以下选项中哪项最可能为真？","options":[{"label":"A","content":"甲公司预测成真"},{"label":"B","content":"乙和丙公司预测失败"},{"label":"C","content":"甲和乙公司预测失败"},{"label":"D","content":"丁公司预测成真"}],"answer":"C","explanation":"从题干四人的猜测来看，甲公司和乙公司都有两人猜测中标，若假设这两个公司其中之一中标，则有两人猜测正确，与“只有一人预测成真”矛盾。故甲、乙两公司均未中标，则甲、乙公司预测均失败。无法确定是丙公司还是丁公司中标。答案选C。","no":179},{"id":"1718789646979","type":"single","material":"","stem":"刘阿姨非常注重健康，每天都要搭配营养食谱。对于食物的营养价值，她有自己的一套理念，比如，她认为：猕猴桃比苹果有营养，又因梨比桔子有营养，所以猕猴桃比桔子有营养。<br>以下除了哪项，都可以使刘阿姨的观点成立？","options":[{"label":"A","content":"苹果比梨有营养"},{"label":"B","content":"苹果比桔子有营养"},{"label":"C","content":"梨比称猴桃有营养"},{"label":"D","content":"猕猴桃与梨一样有营养"}],"answer":"C","explanation":"刘阿姨的论据为：猕猴桃＞苹果，梨＞桔子，结论：猕猴桃＞桔子。C项梨＞猕猴桃，无法确定猕猴桃与桔子间的关系，A、B、D三项都可以使结论成立。故答案选C。","no":180},{"id":"1718789646980","type":"single","material":"","stem":"李明的个子比同学都要矮，为了长高，他每天都打篮球。半年过去了，他的生长速度还是低于一般的同学。因此，他认为打篮球并不能帮助身体长高。<br>下面哪项如果为真，最能削弱李明的观点？","options":[{"label":"A","content":"如果不打篮球，李明会更矮"},{"label":"B","content":"如果踢足球，李明会更高"},{"label":"C","content":"和李明一起打篮球的王刚长高了很多"},{"label":"D","content":"和李明一起打篮球的陈维个子也没长高"}],"answer":"A","explanation":"题干的结论为“李明认为打篮球不能帮助身体长高”。如果A项为真，则说明打篮球确实让李明长高了，直接削弱题干论点，力度最强；B项“足球”在题干中并未涉及，属无关项；C项王刚长高了并不代表一定是打篮球的作用，削弱程度有限；D项在一定程度上加强了题干结论，排除。故答案选A。","no":181},{"id":"1718789646981","type":"single","material":"","stem":"陈先生认为吸烟与健康之间并无太大关系，原因是在其认识的人当中，好几个患有肺癌的人都是从来不吸烟的人。<br>以下各项如果为真，则哪项不能反驳陈先生上述观点？","options":[{"label":"A","content":"癌症的起因是许多医学工作者研究的课题，目前还没有一个确定的结论"},{"label":"B","content":"长期吸二手烟的人比起吸烟者本身更容易患上肺癌"},{"label":"C","content":"在陈先生认识的人当中吸烟的人都是年轻小伙子，不吸烟的都是体弱病残的老人"},{"label":"D","content":"排除患肺癌的人，在陈先生认识的人当中，吸烟者比从来不吸烟者患呼吸道类疾病的人明显要多"}],"answer":"A","explanation":"削弱型题目，可以使用排除法。论点为：吸烟与健康之间并无太大关系。要想削弱这个结论，就要说明，吸烟与健康之间有关系，选项中，B、C、D表述的都是这一内容，所以排除。选A。","no":182},{"id":"1718789646982","type":"single","material":"","stem":"某研究机构调查分析了208名有心痛和心律不齐等症状的病人，在开始接受手术治疗时通过问卷报告了自己对病情的看法，其中约20%的人非常担忧病情会恶化，有的人甚至还害怕因此死亡，其他人就没有那么多担忧。后来随访调查表明，那些术前有严重担忧情绪的人术后半年复发率高于其他人。研究人员认为担忧情绪不利于心脏病的康复。<br>以下哪项如果为真，最能支持上述结论？","options":[{"label":"A","content":"有研究表明担忧情绪会抑制大脑前额叶皮层活动，使人更抑郁"},{"label":"B","content":"研究人员发现那些有严重担忧情绪的人更关注自己的健康状况"},{"label":"C","content":"那些有严重担忧情绪的人血液中含有加重心脏病风险的化学物质"},{"label":"D","content":"担忧情绪对健康是一个潜在威胁，会导致癌症、糖尿病等多种疾病"}],"answer":"C","explanation":"题干推论是担忧情绪不利于心脏病的康复。A、B、D三项都与题干推论无关，C项说明了不利于心脏病康复的原因，直接支持了题干论述。故答案选C。","no":183},{"id":"1718789646983","type":"single","material":"","stem":"日常生活中，有些人喜欢用汤泡饭吃。对此，专家指出，这种吃饭方式是不可取的。<br>以下哪项说法如果为真能支持专家的观点？","options":[{"label":"A","content":"用汤泡饭吃，可加快饭菜通过咽喉、食管进入胃的速度"},{"label":"B","content":"用汤泡饭吃有助于防止便秘"},{"label":"C","content":"有些食物代谢产物溶解度低，容易在尿中析出，因此吃完饭后要大量喝汤"},{"label":"D","content":"用汤泡饭吃，会使消化系统的各道工序都乱了套，影响食物的消化"}],"answer":"D","explanation":"A、B两项支持了汤泡饭，削弱了专家的观点；C项饭后要大量喝汤与汤泡饭不是同一概念，属于无关项；D项说明这种吃饭方式不可取，支持了专家观点。故答案选D。","no":184},{"id":"1718789646984","type":"single","material":"","stem":"以前有几项研究表明，饮用咖啡会增加饮用者患胃溃疡的可能性。而一项最新的，更为可靠的研究得出结论是，饮用咖啡与胃溃疡发病率无关。估计这项研究成果公布以后，咖啡的消费量会大大增加。<br>上述推论基于下列哪项假设？","options":[{"label":"A","content":"尽管有些人知道饮用咖啡会增加患胃溃疡的可能性，却照样饮用"},{"label":"B","content":"现在许多人不喝咖啡完全是因为他们相信咖啡会引发胃溃疡"},{"label":"C","content":"人们从来也不相信饮用咖啡会更容易患胃溃疡的说法"},{"label":"D","content":"现在许多人喝咖啡是因为他们没有听过咖啡会导致胃溃疡的说法"}],"answer":"B","explanation":"题干的观点是：饮用咖啡与胃溃疡发病率无关的研究公布以后，咖啡的消费量会大大增加。A项有些人饮用咖啡不受这种说法的影响、C项人们不相信、D项人们从来没有听说过，即公布与否也不会对人们是否饮用咖啡有影响，即不会影响咖啡的销量，不能作为题干假设。B项指出，现在很多人不喝咖啡是因为相信咖啡会引起胃溃疡，即研究结果公布后会打消人们的顾虑，增加销量，是题干推论的假设。故答案选B。","no":185},{"id":"1718789646985","type":"single","material":"","stem":"“律师一定要懂得法律，我不是律师，所以，我不需要懂得法律。”下列与其推理形式相同的是：","options":[{"label":"A","content":"牛是动物，羊不是牛，所以羊不是动物"},{"label":"B","content":"所有说谎的人都是不可靠的，我很可靠，所以，我从不说谎"},{"label":"C","content":"教育规律是客观规律，客观规律是不能违背的，所以，教育规律也是不能违背的"},{"label":"D","content":"花都是红色的，雪花是白色的，所以雪花不是花"}],"answer":"A","explanation":"题干所给的推理形式为：P是S，Q不是P，所以Q不是S。<br>A项的推理形式为：P是S，Q不是P，所以Q不是S。与题干推理形式相同。<br>B项的推理形式为：所有P都不是S，Q是S，所以Q不是P。与题干推理形式不同。<br>C项的推理形式为：P是S，S是Q，所以P是Q。与题干推理形式不同。<br>D项的推理形式为：P是S，Q不是S，所以Q不是P。与题干推理形式不同。<br>故本题答案选A。","no":186},{"id":"1718789646986","type":"single","material":"","stem":"根据联合国粮农组织的统计，去年，中国牛奶总产量位居全球第七位。许多专家预计，随着乳制品越来越受欢迎，中国乳品生产将继续增长。目前，中国很大一部分乳品生产集中在内蒙古和新疆等北部地区。中国奶业协会预测，中国乳品产量每年将增长6%至9%。<br>以下哪项举措是基于以上论断的？","options":[{"label":"A","content":"据科学研究，牛奶含有丰富的人体所必需的营养，某家庭已为全家订了全年的鲜牛奶"},{"label":"B","content":"科学家经过研究后宣布，牛奶越新鲜，其营养价值越高，某幼儿园为儿童选择的就是本地品牌的鲜奶"},{"label":"C","content":"法国酸奶业巨头达能公司斥资7220万元人民币，将其在上海光明乳业股份有限公司所持股份从9.7%增至11.5%"},{"label":"D","content":"某品牌奶业公司在经过市场调研后，推出了各种水果味酸牛奶，融水果与牛奶于一体"}],"answer":"C","explanation":"题干论点是：中国乳品生产将继续增长。A、B、D三项均与乳品的生产增长无关，C项正是因为乳品生产将持续增长，所以增持了乳业公司的股票。故答案选C。","no":187},{"id":"1718789646987","type":"single","material":"","stem":"母狗生产后对它所生的狗崽立即显示出母性行为。而一只刚生产后的从未接触狗崽的母狗，在一个封闭的地方开始接触一只非自己生的狗崽，七天之后，这只母狗显示出明显的母性行为。如果破坏这只母狗的嗅觉，或者摘除狗崽产生气味的腺体，上述七天的时间将大大缩短。<br>上述断定最能推出下列哪项结论？","options":[{"label":"A","content":"不同母狗所生的狗崽发出不同气味"},{"label":"B","content":"狗崽的气味是母狗产生母性行为的重要诱因"},{"label":"C","content":"非己所生的狗崽的气味是母狗对其产生母性行为的障碍"},{"label":"D","content":"母狗的嗅觉是狗繁衍的障碍"}],"answer":"C","explanation":"由题干可知：在破坏母狗的嗅觉或者摘除狗崽的腺体后，母狗对非自己所生的狗崽显示母性的时间缩短，说明母狗是通过狗崽的气味而产生母性行为的，即非自己所生的狗崽的气味对母狗产生母性行为有阻碍作用，C项正确；A项，题干并未涉及不同母狗生的狗崽的气味，无法推出；B项，题干只是说影响，“诱因”属过度推断；D项为无关项。故答案为C。","no":188},{"id":"1718789646988","type":"single","material":"","stem":"现在，机载雷达和风切变探测器成为飞机的标准配置，先进的气象雷达不仅可以发现恶劣的天气状况，而且可以预测风切变，如果当飞机即将着陆时飞行员看到风切正在逼近，他不能选择立即降落，而是要围绕机场飞行，直到风切变消失，否则会造成空难。由此可以推出：","options":[{"label":"A","content":"当遇到风切变时，只要飞行员措施得当，空难是可以避免的"},{"label":"B","content":"飞行员如果在降落过程发生空难，肯定是遇到了风切变"},{"label":"C","content":"当飞行员在降落的过程中遇到风切变，空难将不可避免"},{"label":"D","content":"风切变往往是导致空难的一个重要气象因素"}],"answer":"D","explanation":"由题干可知，风切变逼近时，不采取相应的措施会造成空难，由此推不出A项；根据推理规则，B项也无法推出；C项说法绝对，题干只是说风切变逼近时不采取措施会发生空难，但并没有提及飞机遇到风切变的情况，即便遇到风切变，通过其他措施也可能避免发生空难；D项可以由题干推出。故答案为D。","no":189},{"id":"1718789646989","type":"single","material":"","stem":"只有加大查处、惩罚的力度，对贪腐官员决不姑息手软，才能让官员“不敢腐”；只有在权力运作的每个环节建立和完善相关制度，才能让官员“不能腐”。但是，如果官员缺乏必要的廉耻之心，单纯依靠制度，那么，他们一定会找到制度的漏洞。相反，如果官员有一定的廉耻之心，那么，即便存在一些制度漏洞，他们也不会有意利用，而是会克制自己，甚至会修补这些漏洞，真正做到“不想腐”。<br>根据以上陈述，可以推出的是：","options":[{"label":"A","content":"如果官员有一定的廉耻之心，一般不会发现制度的漏洞，即使发现了，也不会利用，只会去修补它们"},{"label":"B","content":"如果官员有一定的廉耻之心，就会加强自我约束，不会有意利用制度的漏洞，从心里清除腐败的念头"},{"label":"C","content":"如果官员缺乏必要的廉耻之心，只要加大查处、惩罚的力度，决不姑息手软，他们就“不敢腐”"},{"label":"D","content":"如果官员缺乏必要的廉耻之心，只要建立和完善权力运作各个环节的相关制度，他们就“不能腐”"}],"answer":"B","explanation":"题干可转化为充分条件假言命题：①不敢腐→加大查处、惩罚力度，对贪腐官员绝不姑息手软；②不能腐→在权力运作的每个环节建立和完善相关制度；③官员缺乏必要的廉耻之心，单纯依靠制度→找到制度的漏洞；④官员有一定的廉耻之心→不会有意利用漏洞，会克制自己。A项的“不会发现”与题干不符，排除；B项根据④肯定前件可推出肯定后件，正确；C项根据①肯定后件不能肯定前件，错误；D项根据②肯定后件不能肯定前件，错误。故答案选B。","no":190},{"id":"1718789646990","type":"single","material":"","stem":"住在A市的每一个人都乘坐公共汽车；没有一个人能够不关注汽油价格的上涨，除非他住在A市；每一个乘坐公共汽车的人都发牢骚。<br>根据上面的陈述，下列哪项必定为真？<br>Ⅰ.所有不关注汽油价格上涨的人都乘坐公共汽车<br>Ⅱ.不发牢骚的人当中没有一个不关注汽油价格的上涨<br>Ⅲ.所有发牢骚的人都不关注汽油价格的上涨","options":[{"label":"A","content":"Ⅰ"},{"label":"B","content":"Ⅰ和Ⅱ"},{"label":"C","content":"Ⅱ和Ⅲ"},{"label":"D","content":"Ⅰ、Ⅱ和Ⅲ"}],"answer":"B","explanation":"题干逻辑关系为：不关注汽油价格的上涨⇒住在A市⇒乘坐公共汽车⇒发牢骚。Ⅰ，肯定前件可以肯定后件，正确；Ⅱ，“没有一个不”＝“所有都”，否定后件可以否定前件，正确；Ⅲ，肯定后件不能肯定前件，错误。只有Ⅰ和Ⅱ正确。故答案选B。","no":191},{"id":"1718789646991","type":"single","material":"","stem":"甲乙丙三人在玩骰子游戏，骰子有六面，每面分别是一、二、三、四、五、六点，他们规定：如果出现一、三点面，甲赢；如果出现二、四面点面，乙赢；如果出现五、六点面，丙赢。甲说：“如果再少一点我也不会赢”。乙说：“如果再少一点的话我就赢了。”丙说：“如果再多一点也是我赢。”<br>那么，现在出现的点数是：","options":[{"label":"A","content":"三点"},{"label":"B","content":"五点"},{"label":"C","content":"四点"},{"label":"D","content":"二点"}],"answer":"B","explanation":"由丙说的话可知丙现在赢了，再多一点也是丙赢，即现在出现的点数是五。代入甲、乙的话也正确。故答案为B。","no":192},{"id":"1718789646992","type":"single","material":"","stem":"小曾、小孙、小石三个人是好朋友，他们每个人都有一个妹妹，且都比自己小11岁。三个妹妹的名字叫小英、小丽、小梅。已知小曾比小英大9岁，小曾与小丽年龄之和是52岁，小孙与小丽年龄之和是54岁。<br>由此可知，谁是谁的妹妹？","options":[{"label":"A","content":"小梅是小孙的妹妹，小丽是小曾的妹妹，小英是小石的妹妹"},{"label":"B","content":"小梅是小石的妹妹，小丽是小孙的妹妹，小英是小曾的妹妹"},{"label":"C","content":"小梅是小曾的妹妹，小丽是小石的妹妹，小英是小孙的妹妹"},{"label":"D","content":"小梅是小曾的妹妹，小丽是小孙的妹妹，小英是小石的妹妹"}],"answer":"C","explanation":"小曾、小孙、小石都比自己的妹妹大11岁，则每个人和妹妹的年龄应该分别为一奇一偶，加起来都应为奇数。小曾比小英大9岁则小英不是小曾的妹妹，排除B项；小曾与小丽的年龄和是52岁则小丽不是小曾的妹妹，排除A项；小孙和小丽的年龄和是54岁则小丽不是小孙的妹妹，排除D项。故答案选C。","no":193},{"id":"1718789646993","type":"single","material":"","stem":"小周、小吴、小郑三人中，一人是工人，一人是农民，一人是知识分子。已知：小郑的年龄比知识分子大；小周的年龄和农民不同；农民的年龄比小吴小。<br>根据以上情况，判断正确的是：","options":[{"label":"A","content":"小周是工人、小吴是知识分子、小郑是农民"},{"label":"B","content":"小周是知识分子、小吴是农民、小郑是工人"},{"label":"C","content":"小周是知识分子、小吴是工人、小郑是农民"},{"label":"D","content":"小周是工人、小吴是农民、小郑是知识分子"}],"answer":"C","explanation":"由“小周的年龄和农民不同”和“农民的年龄比小吴小”知小郑是农民，且小郑＜小吴；再由“小郑的年龄比知识分子大”可知，小周是知识分子；故小吴是工人。对比选项，答案选C。","no":194},{"id":"1718789646994","type":"single","material":"","stem":"甲、乙、丙三人被厦门大学、上海交大、中山大学录取，对于他们分别被哪所学校录取同学们做了如下猜测：<br>①甲被上海交大录取，丙被中山大学录取<br>②甲被中山大学录取，乙被上海交大录取<br>③甲被厦门大学录取，丙被上海交大录取<br>结果同学们的猜测各对了一半，那么甲、乙、丙的录取情况是：","options":[{"label":"A","content":"甲、乙、丙分别被厦门大学、上海交大、中山大学录取"},{"label":"B","content":"甲、乙、丙分别被上海交大、中山大学、厦门大学录取"},{"label":"C","content":"甲、乙、丙分别被中山大学、上海交大、厦门大学录取"},{"label":"D","content":"甲、乙、丙分别被厦门大学、中山大学、上海交大录取"}],"answer":"A","explanation":"用代入排除法。代入A，甲被厦门大学录取，根据题干中每人猜对一半及条件③，知丙被中山大学录取，乙被上海交大录取。①和②各对一半，A项符合。","no":195},{"id":"1718789646995","type":"single","material":"","stem":"一位社会学家对两组青少年做了研究。第一组成员每周看暴力内容的影视的时间平均不少于10小时；第二组则不多于2小时。结果发现，第一组成员中举止粗鲁者所占的比例远高于第二组。因此，此项研究认为，多看暴力内容的影视容易导致青少年举止粗鲁。<br>以下哪项如果为真，将对上述研究的结论提出质疑？","options":[{"label":"A","content":"第一组中有的成员的行为并不粗鲁"},{"label":"B","content":"第二组中有的成员的行为比第一组的成员粗鲁"},{"label":"C","content":"第一组中有的成员的文明行为是父母从小教育的结果，这使得他们能抵制暴力影视的不良影响"},{"label":"D","content":"第一组成员中有很多成员的粗鲁举止是从小养成的，这使得他们特别爱看暴力影视"}],"answer":"D","explanation":"削弱型题目。题干通过研究对比得出结论：多看暴力内容的影视容易导致青少年举止粗鲁。如果D项为真，则说明题干的论证是“因果倒置”，是由于举止粗鲁才喜欢看暴力影视，削弱了题干的论证。A、B、C三项都是举出两组中存在与结论不同的个例，但仅是个例对结论的削弱不大。因此，正确答案是D。","no":196},{"id":"1718789646996","type":"single","material":"","stem":"一座城市的发展，通常伴随的是日渐拥堵的上下班交通，高峰拥堵，也几乎成为每座城市发展祛之不掉的一块心病——为防迟到，人们只有揣着满身疲惫，提早上班乘车；夹在众多的乘客与包裹中，更是大汗淋漓的尴尬狼狈。有人提议，通过错开人们的上下班时间，达到抑制高峰、缓解拥堵的效果。<br>以下哪项如果为真，最能支持该项提议实施？","options":[{"label":"A","content":"有些人上班时间被调早，抑或下班时间被调晚，违背了一些上班族的意愿和生活习惯"},{"label":"B","content":"“错时上下班”是城市发展“消肿”的治标之策"},{"label":"C","content":"“错时上下班”使得各个行业、企业之间的重叠工作时间减少，可能会加大企业之间合作的运营成本"},{"label":"D","content":"“错时上下班”已经有了一套周密详实、通盘考虑的规划方案"}],"answer":"D","explanation":"题干的提议是：通过错开人们的上下班时间，达到抑制高峰、缓解拥堵的效果。A、C两项均指出此提议的缺点，削弱了该项提议的可行性；B项城市发展“消肿”与题干无关；D项指出该提议已有了一套周密详实的规划方案，具备可行性，能够支持该项提议实施。故答案选D。","no":197},{"id":"1718789646997","type":"single","material":"","stem":"燕窝是由雨燕科动物金丝燕及多种同属燕类衔食海中小鱼等生物后，经胃消化腺分泌出的黏液与绒羽筑垒而成的窝巢，燕窝被认为可以“化痰止咳，调理虚损劳疾”，被国人誉为高级滋补佳品。但最近有专家指出，燕窝的营养价值其实非常有限。<br>下列各项如果为真，哪项最能对专家的观点进行支持？","options":[{"label":"A","content":"燕窝价格贵，但并不是越贵的食物所提供的营养价值就越高"},{"label":"B","content":"据测定，燕窝的营养成分的含量与鸡蛋的营养成分的含量没有多大区别"},{"label":"C","content":"某省抽检的市场所售的燕窝中大部分均存在亚硝酸盐严重超标的现象"},{"label":"D","content":"燕窝必须长期服用才能提高机体免疫力，偶尔吃一两次，没有什么保健效果"}],"answer":"B","explanation":"专家的观点是燕窝的营养价值非常有限。若B项为真则燕窝的营养成分和鸡蛋的没有多大区别，即营养价值有限，支持了专家的观点。C项与专家观点无关；A项和D项并未否定燕窝的营养价值，不能支持专家的观点。选B。","no":198},{"id":"1718789646998","type":"single","material":"","stem":"一些广告设计者坚持将大牌明星作为广告设计的核心，事实上许多广受欢迎的广告中都有大牌明星的出现，但是，作为一种广告设计理念，大牌明星效应有它的弱点。研究表明，许多以大牌明星为设计核心的广告，观众能清晰地记住大牌明星在其中的表现，却几乎没有人能记得广告中被推销产品的名称，这使得人们对以大牌明星为设计核心的广告效力产生怀疑。<br>以下陈述哪项是上述论证所依赖的假设？","options":[{"label":"A","content":"以大牌明星为主题的广告往往令人感到高兴，但是这类广告比严肃的广告更不容易被记住"},{"label":"B","content":"在产品的名称设计上失败的广告不会增加产品的销量"},{"label":"C","content":"广告的最终目标是增加被推销产品的知名度"},{"label":"D","content":"如果启用不知名的演员参与广告，无法显示广告的高端性"}],"answer":"C","explanation":"题干指出大牌明星效应的弱点是观众能清晰地记住大牌明星的表现，几乎没有人记得广告中被推销产品的名称，得出人们对以大牌明星为设计核心的广告效力产生怀疑。要得到这一结论需在记不得产品名称和广告效力之间建立联系，即广告的最终目标是增加产品的知名度。选C。","no":199},{"id":"1718789646999","type":"single","material":"","stem":"在今年准备入学的大学生中，所有向甲大学申请奖学金的学生也同时向乙大学申请了奖学金，向乙大学申请奖学金的学生也向甲大学申请了奖学金。甲乙两所大学各同意给予半数的申请者每个人一个全额奖学金。因此，所有这些申请者就都获得了一份全奖。<br>上述推断基于下列哪项假设？","options":[{"label":"A","content":"所有申请奖学金的学生既符合甲大学的入学条件，又符合乙大学的入学条件"},{"label":"B","content":"甲、乙两所大学没有给同一个申请者以全额奖学金"},{"label":"C","content":"所有的申请者都愿意接受甲、乙两所大学的奖学金资助"},{"label":"D","content":"没有任何一位申请者向第三所大学提出奖学金申请"}],"answer":"B","explanation":"根据题干条件，可知向甲大学申请奖学金的学生和向乙大学申请奖学金的学生为全同关系，又因为甲乙两所大学各同意给予半数的申请者每个人一个全额奖学金，要使所有这些申请者都获得一份全奖，就必须保证这两所学校所给奖学金的学生没有重合的，否则会出现有的学生有两份全奖而有的学生没有的情况。故答案为B。","no":200},{"id":"1718789647000","type":"single","material":"","stem":"青海湖的湟鱼是一种珍稀鱼类。但自20世纪50年代，人们开始大量捕捞湟鱼，导致湟鱼资源量由最初的32万吨，按平均每年0.4万吨的速度减少，至2013年，湟鱼资源量仅为6.8万吨。某专家认为，照此速度，青海湖的湟鱼再过十几年就会灭绝。<br>以下哪项如果为真，最能反驳该专家的观点?","options":[{"label":"A","content":"《中国物种红色名录》已将湟鱼列为濒危物种，并采取多项措施进行了有效保护"},{"label":"B","content":"虽然一次性盗捕湟鱼50公斤以上就会构成犯罪，但盗捕者仍在增加"},{"label":"C","content":"一条两斤左右的湟鱼能卖到上百元，这使很多捕鱼者把捕鱼目标瞄向湟鱼"},{"label":"D","content":"刚刚过去的一年，青海湖的湟鱼减少量为0.3万吨"}],"answer":"A","explanation":"题干论点：按平均每年0.4万吨的速度减少，青海湖的湟鱼再过十几年就会灭绝。题干论据：自20世纪50年代，人们开始大量捕捞湟鱼，导致湟鱼资源量由最初的32万吨，按平均每年0.4万吨的速度减少，至2013年，湟鱼资源量仅为6.8万吨。要反驳专家观点，可以说明湟鱼不会灭绝。<br>A项，将湟鱼列为濒危物种，对其进行有效保护，捕杀湟鱼的人会变少，湟鱼就不会灭绝，削弱了题干论点。<br>B项，盗捕者仍在增加，说明捕杀湟鱼的行为仍在增加，湟鱼依旧在大量减少，支持了题干论点。<br>C项，因为湟鱼自身的经济价值，很多捕鱼者把捕鱼目标瞄向湟鱼，指出了湟鱼减少的原因，补充了题干论据，支持了题干论点。<br>D项，虽然过去一年中，湟鱼减少量为0.3万吨，低于平均值，但无法证明以后湟鱼的减少量，无法证明湟鱼是否会灭绝，无法削弱题干论点。","no":201},{"id":"1718789647001","type":"single","material":"","stem":"75年前，一头驯鹿因感染炭疽死亡后尸体保存在北极圈附近的冻土中，不久前附近的一名男童因感染炭疽死亡。有科学家推测，全球变暖使得北极圈的“永久冻土”开始融化，炭疽杆菌因此卷土重来。同时，一些“古老病毒”比如天花和黑死病的病原体也可能埋藏在这些永久冻土中。科学家正为此极度担忧。<br>以下陈述如果为真，哪项最有助于为科学家解忧?","options":[{"label":"A","content":"永久冻土是细菌长期保持活力的最理想场所，时间也许可以长达一百万年"},{"label":"B","content":"人类与细菌和病毒一直并存，如黑死病和天花，人类已进化出对抗它们的基因"},{"label":"C","content":"全球变暖让北半球国家变得更温暖，诸如疟疾等热带疾病开始发生于北半球"},{"label":"D","content":"如果病原体长时间没有接触到人类，那么我们的免疫系统对它不会有所防备"}],"answer":"B","explanation":"科学家的担忧为，全球变暖使得北极圈的“永久冻土”开始融化，炭疽杆菌因此卷土重来。同时，一些“古老病毒”比如天花和黑死病的病原体也可能埋藏在这些永久冻土中。如果这些病原体不出现或者人类可以对抗它们，科学家就可能不用担忧。<br>A项，指出永久冻土可以使细菌长期保持活力，那么全球变暖，那些埋藏在冻土中的<br>病原体就能够卷土重来，加剧了科学家的忧虑，排除。<br>B项，说明人类已进化出对抗天花和黑死病的基因，所以科学家没有必要担忧全球变暖使得这些“古老病毒”卷土重来，有助于为科学家解忧。<br>C项，指出全球变暖使得疟疾等热带疾病开始发生于北半球，而题干讨论的是埋藏在冻土中的病原体是否会卷土重来，为无关项，排除。<br>D项，指出免疫系统不会对长期没有接触人类的病原体有防备，那么全球变暖，一些“古老病毒”的病原体出现，人类也就不会有所防备，容易感染上，加剧了科学家的忧虑，排除。","no":202},{"id":"1718789647002","type":"single","material":"","stem":"蛋黄含有较多的胆固醇，有的人害怕胆固醇高，不敢吃蛋黄。近期一篇涉及50万中国人、随访时长近9年的研究报告提出，每天吃鸡蛋的人比起那些基本不吃鸡蛋的人，发生心血管事件风险降低11%,心血管事件死亡风险降低18%,尤其是出血性中风风险降低了26%,相应的死亡风险则降低了28%。考虑到脑中风是我国居民第一大死因，研究者提出，每天吃一个鸡蛋有利于心血管健康。<br>以下各项如果为真，哪项最能支持研究者的观点?","options":[{"label":"A","content":"来自日本的一项涉及4万人的追踪研究中，每天吃鸡蛋的人比起不吃鸡蛋的人，全因死亡率低了30%"},{"label":"B","content":"鸡蛋的营养十分丰富，钙、磷、铁、维生素A、维生素B的含量都比较高"},{"label":"C","content":"食物摄入胆固醇并不等于血胆固醇水平，且鸡蛋中含有的卵磷脂能有效阻止胆固醇和脂肪在血管壁上的沉积"},{"label":"D","content":"每天吃鸡蛋的人，教育水平和家庭收入都更高，饮食更加健康，生活更自律，更有可能补充维生素"}],"answer":"C","explanation":"题干论点：每天吃一个鸡蛋有利于心血管健康。题干论据：每天吃鸡蛋的人比起那些基本不吃鸡蛋的人，发生心血管事件风险降低11%,心血管事件死亡风险降低18%,尤其是出血性中风风险降低了26%,相应的死亡风险则降低了28%。要支持题干观点，可以指出鸡蛋对保持心血管健康存在的积极作用。<br>A项，通过研究数据表明每天吃鸡蛋可以降低全因死亡率，但未表明是否降低了心血管事件的死亡率，无法加强题干观点，排除。<br>B项，指出鸡蛋的营养丰富，但与题干主要论证的心血管健康无关，排除。<br>C项，表明鸡蛋中的卵磷脂能有效阻止胆固醇和脂肪在血管的沉积，从而降低发生心血管事件的风险，通过解释吃鸡蛋有利于心血管健康的原因，有力地支持了题干观点。<br>D项，指出每天吃鸡蛋的人教育水平和收入较高，饮食更健康，因此心血管事件死亡率低，属于另有他因，削弱了题干观点，排除。","no":203},{"id":"1718789647003","type":"single","material":"","stem":"广告的目的是说服消费者相信他们购买的商品物有所值，没有哪个商家会故意强调自己的产品价格高。<br>以下各项如果为真，最能加强上述论断的是：","options":[{"label":"A","content":"消费者认为便宜无好货，好货不便宜"},{"label":"B","content":"广告能激发消费者的购买欲"},{"label":"C","content":"广告能说服消费者去购买价格便宜的商品"},{"label":"D","content":"广告能说服消费者去购买质量好的商品"}],"answer":"D","explanation":"题干的论断为广告的目的是说服消费者相信他们购买的商品物有所值，而不是强调商品的价格高。要加强该论断，可以通过直接加强、补充论据等方法。<br>A项，说的是消费者本来的心理，并不涉及广告，不能支持题干论断。<br>B项，指出广告能激发购买欲，但无法说明广告能否说服消费者相信商品是物有所值的，不能支持题干论断。<br>C项，指出广告能说服消费者购买价格便宜的商品，但并没有说明这些便宜的商品是不是物有所值的，无法加强题干论断。<br>D项，说明广告能说服消费者购买质量好的商品，即广告强调的是商品的质量好，物有所值，而不是强调价格，支持了题干论断。","no":204},{"id":"1718789647004","type":"single","material":"","stem":"细胞因为发生了基因突变，出现不受控制地增殖分化，最终发展成为恶性肿瘤。在癌细胞表面存在着许多由突变基因编码的异常蛋白，按理说，这些异常蛋白应该被机体免疫系统及时识别，并引发免疫反应将癌细胞一举清除。然而，由于肿瘤细胞发展迅速、极善伪装，而且不断突变，面对凶猛机智的肿瘤细胞，原本强大的免疫细胞也显得有些“力不从心”,甚至还会对一些肿瘤细胞“视而不见”。在肿瘤微环境中形成的免疫抑制，更是让免疫系统陷入“瘫痪”。<br>根据上述信息，下列研究除哪项外，可能有助于研发有效的抗肿瘤药物?","options":[{"label":"A","content":"研究人员对每位患者的肿瘤细胞和健康细胞的DNA进行测序，以鉴定出肿瘤特异性突变，并确定相关的异常蛋白"},{"label":"B","content":"科学家利用免疫疗法，试图改造对肿瘤细胞“不上心”的免疫T细胞，使其重返战场"},{"label":"C","content":"科学家将恶性肿瘤患者和健康人的生活方式、个性特征进行对照研究，找出诱发肿瘤发病的风险因素"},{"label":"D","content":"科学家利用小鼠进行试验，将提取的肿瘤异常蛋白作为疫苗注射入小鼠体内，激发并增强其免疫反应"}],"answer":"C","explanation":"本题要求选择除哪项外都有助于研发有效的抗肿瘤药物，要研发有效的抗肿瘤药物，就要针对肿瘤细胞的特性，再对比选项进行解题。肿瘤细胞具有发展迅速、极善伪装、不断突变的特性。<br>A项，找出肿瘤细胞基因突变的原因，有助于研发有效的抗肿瘤药物，排除。<br>B项，解决了免疫细胞对肿瘤细胞“视而不见”的现象，有助于研发有效的抗肿瘤药物，排除。<br>C项，找出诱发肿瘤发病的风险因素，目的在于预防肿瘤，而题干说的是研发有效的抗肿瘤药物来治疗肿瘤，因此该项与题干论述无关。<br>D项，利用小鼠做实验，激发并增强其免疫反应，可以研发出适合人类的药物，有助于研发有效的抗肿瘤药物，排除。","no":205},{"id":"1718789647005","type":"single","material":"","stem":"人们普遍认为，保持乐观心态会促进健康。但一项对7万名50岁左右的女性进行的长达10年的追踪研究发现，长期保持乐观心态的被试与悲观的被试在死亡率上并没有差异，研究者据此认为，心态乐观与否与健康没有关系。<br>以下哪项如果为真，最能质疑研究者的结论?","options":[{"label":"A","content":"在这项研究的被试中悲观的人更多患有慢性疾病，虽然尚未严重到致命的程度"},{"label":"B","content":"与悲观的人相比，乐观的人患病后会更积极主动地治疗"},{"label":"C","content":"乐观的人往往对身体不会特别关注，有时无法及早发现一些致命性疾病"},{"label":"D","content":"女性更善于维持和谐的人际关系，而良好的人际关系有助于健康"}],"answer":"A","explanation":"题干由“长期保持乐观心态的被试与悲观的被试在死亡率上并没有差异”得出结论“心态乐观与否与健康没有关系”。要质疑研究者的观点，需寻找死亡率以外的其他能影响研究结果的因素。<br>A项，指出被试中悲观的有更多人患有慢性疾病，说明尽管死亡率没有差异，但健康状态是有差异的，即乐观更有利于健康，有力地削弱了题干结论。<br>B项，患病后是否更积极主动去治疗不代表健康与否，与论证无关。<br>C项，乐观者对身体是否关注，和题干乐观是不是有利于健康没有必然关系。<br>D项，女性的人际关系和健康的联系与题干论证无关。","no":206},{"id":"1718789647006","type":"single","material":"","stem":"<p>某研究小组汇集了140多种非人类灵长类动物的脑量数据，以研究灵长类动物大脑体积比其他脊椎动物大得多的原因。在研究中，研究人员不仅考虑了灵长类动物的社会化因素，如种群规模、社会体系、交配系统等，还研究了它们的饮食习性，即它们是食叶、食果，抑或属于杂食动物。研究人员据此认为，饮食习性是灵长类动物大脑体积大的主要原因。</p><p>以下哪项如果为真，最能支持上述结论?</p>","options":[{"label":"A","content":"灵长类动物的饮食习性对其体型发育有重要影响"},{"label":"B","content":"以往人们普遍接受的社会化因素决定灵长类动物大脑体积的观点只是一种假说"},{"label":"C","content":"研究结果并没有显示出在同种灵长类动物中，水果或树叶摄入量与大脑体积之间存在联系"},{"label":"D","content":"在这140多种灵长类动物中，食果动物的大脑体积，要明显大于食叶动物；杂食动物的大脑体积，也要大于食叶动物"}],"answer":"D","explanation":"题干结论：饮食习性是灵长类动物大脑体积大的主要原因。要支持该结论，只需说明饮食习性确实会影响灵长类动物的大脑体积即可。A项，说的是“饮食习性对其体型发育有重要影响”,而题干要论述的是饮食习性和大脑体积之间的关系，该项与题干结论无关，排除。B项，指出“社会化因素决定灵长类动物大脑体积的观点只是一种假说”,但不能说明饮食习性决定灵长类动物的大脑体积，无法支持题干结论，排除。C项，题干论述的是饮食习性与大脑体积之间的关系，在题干中已说明饮食习性指的是“食叶、食果，抑或属于杂食动物”,与该项中的“水果或树叶摄入量”无关，因此该项D项，指出食果、食叶、杂食动物的大脑体积不同，说明了饮食习性确实会影响灵长类动物大脑体积，支持了题干结论。","no":207},{"id":"1718789647007","type":"single","material":"","stem":"近日，有动物实验研究发现，在正常饮食中加入一定剂量的苦瓜水提取物，可降低Ⅱ型糖尿病小鼠的高血糖。这是由于苦瓜中含有一种类似胰岛素的物质，能够降低血糖。有人据此认为，Ⅱ型糖尿病患者多吃苦瓜有助于降低血糖水平。<br>以下哪项如果为真，最能质疑上述论证?","options":[{"label":"A","content":"苦瓜含糖量低，对血糖的影响小"},{"label":"B","content":"日常食用的苦瓜中，苦瓜水提取物含量极少"},{"label":"C","content":"苦瓜水提取物可能会导致血清总蛋白轻微降低"},{"label":"D","content":"苦瓜水提取物对I型糖尿病小鼠的血糖无显著影响"}],"answer":"B","explanation":"题干根据Ⅱ型糖尿病小鼠在食用苦瓜水提取物后血糖降低，得出“Ⅱ型糖尿病患者多吃苦瓜有助于降低血糖水平”这一结论。要质疑该结论，只需说明Ⅱ型糖尿病患者即使多吃苦瓜也不能降低血糖水平。<br>A项，“对血糖的影响小”无法说明多吃苦瓜不能降低血糖水平，不能质疑题干结论，排除。<br>B项，指出日常食用的苦瓜中，苦瓜水提取物含量极少，说明Ⅱ型糖尿病患者并不能靠多吃苦瓜降低血糖水平，削弱了题干结论。<br>C项，“血清总蛋白轻微降低”无法说明多吃苦瓜不能降低血糖水平，不能质疑题干结论，排除。<br>D项，“对I型糖尿病小鼠的血糖无显著影响”不代表对Ⅱ型糖尿病患者没有作用，不能质疑题干结论，排除。","no":208},{"id":"1718789647008","type":"single","material":"","stem":"微生物组在地球生态系统和人类健康中的作用超乎想象，它不仅将极大地帮助人类克服当今所面临的生存挑战，还能提供人类未来生存之道。这其中有一个道理，就是微生物之间能够相互协作，使得它们在生态系统中更稳定、更有效地发挥作用，并赋予微生物组具有超越单个微生物的更为强大的功能。<br>以下各项如果为真，最能支持上述观点的是：","options":[{"label":"A","content":"作为新兴产业的生物农药和生物肥料，近年来蓬勃发展，在国际上的市场份额也逐年快速递增"},{"label":"B","content":"酿酒微生物场所提供了多种多样的微生物资源，可以从中发掘高效纤维素降解霉菌、高乙醇合成酵母等"},{"label":"C","content":"美国“国家微生物组计划”正是为了在所有的生态系统、大自然及人造世界里推动最前沿的微生物科学研究"},{"label":"D","content":"将多种微生物一起培养，其生物系统的稳定性和适应能力都大为提高，对某些有害化合物的降解效率也提升了"}],"answer":"D","explanation":"题干结论：微生物之间能够相互协作，使得它们在生态系统中更稳定、更有效地发挥作用，并赋予微生物组具有超越单个微生物的更为强大的功能。要支持这一观点，只需说明微生物组比单个微生物的功能更强大即可。<br>A项，生物农药和生物肥料在国际上的市场份额逐年快速递增，与微生物组的功能无关，排除。<br>B项，“提供了多种多样的微生物资源”不能说明微生物组相较单个微生物具有更为强大的功能，此项为无关项，排除。<br>C项，“推动最前沿的微生物科学研究”也无法说明微生物组具有超越单个微生物的更为强大的功能，此项为无关项，排除。<br>D项，说明多种微生物一起培养具有比单个微生物更为强大的功能，增加了新的论据，支持了题干结论。","no":209},{"id":"1718789647009","type":"single","material":"","stem":"最近有一位科学家提出新观点：地球板块运动开始的时间不会晚于35亿年前，他的依据是：板块运动必然会让自然界深色的镁铁质岩石转变成浅色的长英质岩石。而在35亿年前，地球已经有浅色的长英质岩石出现了。<br>以下各项如果为真，最能质疑这位专家观点的是：","options":[{"label":"A","content":"以全球各地35亿年前的沉积层样品分析，其中含有长英质岩石颗粒的不足一半"},{"label":"B","content":"浅色的长英质岩石本质上是深色的镁铁质岩石“再生”而来的，而在数十亿年前，镁铁质岩石在地球上占有绝对的数量优势"},{"label":"C","content":"长英质岩石在自然界的占比比镁铁质岩石高出很多的解释似乎只有板块运动这一个，但早期的板块构造运动很可能是时断时续的，局部的"},{"label":"D","content":"35亿年前地球火山密布，火山爆发释放的岩浆会把镁铁质岩石深深埋在地下，这些镁铁质岩石会被熔化，进而转变成长英质岩石，但板块运动不是火山爆发的唯一原因"}],"answer":"D","explanation":"题干根据“35亿年前，地球已经有浅色的长英质岩石出现了”得出“地球板块运动开始的时间不会晚于35亿年前”的结论。要质疑该专家的观点，可以指出根据浅色的长英质岩石并不能判断出地球板块运动开始的时间。<br>A项，题干要论述的是能否通过浅色长英质岩石来判定地球板块运动开始的时间，而该项说的是“含有长英质岩石颗粒”的占比，与题干观点不一致，无法质疑题干结论，排除。<br>B项，题干要论述的是能否通过浅色长英质岩石来判定地球板块运动开始的时间，而该项说的是“镁铁质岩石”在地球上的数量，与题干观点不一致，无法质疑题干结论，排除。<br>C项，没有提到时间，无法说明根据浅色长英质岩石能否判定地球板块运动开始的时间，且“似乎只有板块运动这一个”是猜测，并非确定性的表述，无法质疑题干结论，排除。<br>D项，指出火山爆发会使镁铁质岩石转变成长英质岩石，但板块运动并不是火山爆发的唯一原因，说明不能根据35亿年前地球上有浅色的长英质岩石就判断出那时有地球板块运动，质疑了题干观点。","no":210},{"id":"1718789647010","type":"single","material":"","stem":"南极必须被视为“准全球公域”。通常认为，全球公域是指处于国家管辖范围以外的区域及其资源。它属于全人类共有，人人都可以使用。《南极条约》对南极领土主权问题的搁置奠定了南极作为“准全球公域”的法律基础，而“开放”“和平”“科研自由”等规定，实际上赋予了南极公域的性质。“南极应只用于和平目的”这一规定，使得南极地区成为冷战期间一块难得的净土：避免遭受战争摧残，而且成功实现了无核化。<br>以下各项如果为真，最能支持上述论点的是：","options":[{"label":"A","content":"南极大陆蕴藏着丰富的生物资源、水资源，市场潜能巨大"},{"label":"B","content":"南极治理的主导权长期掌握在少数科技发达的西方国家手中"},{"label":"C","content":"美国组建了南极支援特遣队，常驻新西兰负责空军的南极飞行行动"},{"label":"D","content":"若南极冰盖消融，海平面将上升57米，这直接关系到人类的共同命运"}],"answer":"D","explanation":"题干观点：南极必须被视为“准全球公域”。要支持该论点，可以说明南极关乎全人类的命运，应被视为“准全球公域”。<br>A项，指出南极市场潜能巨大，但不能说明南极应该被视为“准全球公域”,无法支持题干观点，排除。<br>B项，指出南极治理的主导权长期掌握在少数西方发达国家手中，说明实际上南极并不是“准全球公域”,无法支持题干观点，排除。<br>C项，指出美国组建了南极支援特遣队，也不能说明南极是“准全球公域”,无法支持题干观点，排除。<br>D项，说明南极关系到人类的共同命运，因此南极必须被视为“准全球公域”,支持了题干观点。","no":211},{"id":"1718789647011","type":"single","material":"","stem":"近几年，智能手机已成为手机市场上的主要销售产品，功能手机(非智能手机)的销售量则大幅度降低。某手机生产商预测：“智能手机很快将完全取代功能手机。”<br>以下哪项如果为真，能够反驳该手机生产商的预言?","options":[{"label":"A","content":"智能手机除具备通话、发短信等功能外，上网也方便，深受消费者喜爱"},{"label":"B","content":"很多老年人只会使用功能手机，手机是他们生活中必不可少的通信工具"},{"label":"C","content":"由于购买非智能手机的人越来越少，无生产商愿意再生产非智能手机"},{"label":"D","content":"智能手机为工作和娱乐提供了诸多便利，越来越多的人选择购买智能手机"}],"answer":"B","explanation":"题干论据：智能手机已成为市场上的主要销售产品，功能手机的销量则大幅度降低。题干论点：智能手机很快将完全取代功能手机。<br>A项，智能手机不仅具备功能手机的功能外，上网更方便，深受消费者喜爱，说明了智能手机比功能手机更具优势，支持了手机生产商的预言。<br>B项，老年人只会使用功能手机，说明了功能手机的不可替代性，即智能手机不能很快的完全取代功能手机，削弱了结论，反驳了手机生产商的预言。<br>C项，无生产商愿意再生产非智能手机，表明功能手机可能不再会被生产，支持了手机生产商的预言。<br>D项，智能手机为工作和娱乐提供了便利，越来越多的人选择购买智能手机，支持了手机生产商的预言。","no":212},{"id":"1718789647012","type":"single","material":"","stem":"某调查发现，患抑郁症的人平均每天使用手机的时间在122分钟以上，而没有患抑郁症的人平均每天使用手机的时间为59分钟。有人提出，玩手机可能会影响情绪，使用手机的时间越多，抑郁的可能性越大。<br>以下哪项如果为真，不能支持以上结论?","options":[{"label":"A","content":"长时间玩手机，尤其是睡前玩手机，可能会造成睡眠时间的不足，而导致情绪容易出问题"},{"label":"B","content":"长时间玩手机，会接触海量数据，这些数据不能及时处理，易造成情绪低迷、烦躁和疲劳，增加抑郁风险"},{"label":"C","content":"人把过多时间和精力放在手机上，必然和现实中的人接触减少，逃避面对现实是抑郁的特征之一"},{"label":"D","content":"长期玩手机的人，通常把大部分时间用在上网和打游戏，而不是和朋友聊天，缺少人际支持是抑郁的风险因素"}],"answer":"C","explanation":"题干论据：患抑郁症的人每天使用手机时间在122分钟以上，没有患抑郁症的人平均使用手机时间为59分钟。题干论点：玩手机可能会影响情绪，使用手机越多，抑郁症可能性越大。<br>A项，长时间玩手机会造成睡眠不足，而导致情绪容易出问题，支持了题干结论。<br>B项，长时间玩手机会接触海量数据，不及时处理易造成情绪低迷、疲劳，增加抑郁风险，支持了题干结论。<br>C项，说的是抑郁的特征，而不是玩手机时间和抑郁的关系，不能支持。<br>D项，长时间玩手机导致缺少人际支持引起抑郁，支持了题干结论。。","no":213},{"id":"1718789647013","type":"single","material":"","stem":"从1995年起，印度某地每年有数百名贫困儿童患上一种急性大脑疾病。患儿常在清晨出现癫痫症状，许多儿童很快死亡。这种情况通常发生于每年5—7月。该地区盛产荔枝，5—7月恰好是荔枝成熟的时间，因此有人怀疑这种疾病可能与荔枝有关。研究发现，所有荔枝中都含有亚甲环丙基甘氨酸和次甘氨酸，没熟的荔枝中这两种物质含量更高。研究者认为，这些患者属于次甘氨酸和亚甲环丙基甘氨酸中毒，疾病暴发确实与大量食用荔枝有关。<br>以下哪项如果为真，最能支持以上结论?","options":[{"label":"A","content":"所有患儿的尿样本中均检测出了亚甲环丙基甘氨酸和次甘氨酸"},{"label":"B","content":"居民根据官方建议限制了儿童每日吃荔枝数量，两年后患病人数大幅降低"},{"label":"C","content":"相比没有出现症状的儿童，生病儿童患病前吃过荔枝的可能性更高"},{"label":"D","content":"相比没有出现症状的儿童，生病儿童更有可能吃下生的或者腐烂的荔枝"}],"answer":"B","explanation":"题干论据：患儿发生疾病的时间与该地区荔枝成熟时间相同，且荔枝中含有亚甲环丙基甘氨酸和次甘氨酸。题干论点：患者属于次甘氨酸和亚甲环丙基甘氨酸中毒，疾病暴发确实与大量食用荔枝有关。<br>A项，患儿尿样中检出了亚甲环丙基甘氨酸和次甘氨酸，并不能证明与荔枝有关，无法支持结论。<br>B项，限制了每日吃荔枝的数量后病人数量大幅下降，从反面说明了疾病的暴发确实和吃荔枝有关系，支持了题干结论。<br>C项，生病儿童患病前吃过荔枝的可能性更高，属于不确定性的推测，无法支持结论。<br>D项，生病儿童更有可能吃下生的或腐烂的荔枝，属于不确定性的推测，无法支持结论。","no":214},{"id":"1718789647014","type":"single","material":"","stem":"许多大城市的中小学校门口，在每天早晚交通高峰期，都能看到接送孩子的车队长龙。有人认为，开车接送孩子上学是导致交通严重拥堵的原因。<br>以下哪项如果为真，最能削弱上述观点?","options":[{"label":"A","content":"由于中小学校车的使用率很低，大量家长都选择驾车接送孩子上学"},{"label":"B","content":"寒暑假期间早高峰的交通拥堵程度降低，并且空气污染程度也降低"},{"label":"C","content":"大城市的中小学校多位于城市的核心区，车流量和人流量本身就很大"},{"label":"D","content":"国家出台了划分学区的政策后，许多孩子可以就近上学"}],"answer":"C","explanation":"题干观点：开车接送孩子上学是导致交通严重拥堵的原因。要削弱题干的论证，可以切断题干的因果关系，即说明题干论据中的现象并不会导致题干论点中的结果。<br>A项，指出大量家长都选择驾车接送孩子上学，则交通严重拥堵确实有可能是这些家长开车接送孩子上学导致的，对题干有一定的支持作用，排除。<br>B项，寒暑假期间交通拥堵程度降低，从反面说明了交通拥堵是开车接送孩子上学导致的，支持了题干观点，排除。<br>C项，说明大城市的中小学校所在的城市核心区车流量和人流量本身就很大，容易造成交通拥堵，并非开车接送孩子导致的，削弱了题干观点。<br>D项，“孩子可以就近上学”与开车接送孩子上学是不是导致交通严重拥堵的原因无关，无法削弱题干的观点，排除。","no":215},{"id":"1718789647015","type":"single","material":"","stem":"好朋友问冰冰：“你是不是不能接受你没有被录取的结果?”这句话隐含的前提是：","options":[{"label":"A","content":"冰冰没办法接受自己没被录取"},{"label":"B","content":"冰冰应该接受她没被录取的结果"},{"label":"C","content":"冰冰没有被录取"},{"label":"D","content":"冰冰是个心理承受能力较差的人"}],"answer":"C","explanation":"冰冰好友的话是“你是不是不能接受你没有被录取的结果”,即询问冰冰对“没有被录取”这件事情的态度，所以“冰冰没有被录取”是题干问题隐含的前提。C项正确。<br>A项，冰冰对“没有被录取”这件事情的态度究竟是能接受还是不能接受，在题干中并未提及，不是题干这句话隐含的前提，排除。<br>B项，冰冰是否应该接受“没有被录取”这件事在题干中没有提及，不是题干隐含的前提，排除。<br>D项，冰冰的心理承受能力在题干中没有提及，不是题干隐含的前提，排除。","no":216},{"id":"1718789647016","type":"single","material":"","stem":"所有未来企业都是互联网企业，而任何互联网企业都面临竞争压力。因此，甲类工厂不是未来企业。<br>要使上述论证成立，需要补充以下哪项作为前提?","options":[{"label":"A","content":"甲类工厂不面临竞争压力"},{"label":"B","content":"互联网企业不都是甲类工厂"},{"label":"C","content":"甲类工厂是互联网企业"},{"label":"D","content":"互联网企业都是未来企业"}],"answer":"A","explanation":"题干根据“未来企业→互联网企业→面临竞争压力”得出“甲类工厂不是未来企业”的结论。要使题干论证成立，需建立“甲类工厂”与“互联网企业”或“甲类工厂”与“面临竞争压力”之间的联系。根据充分条件假言命题的推理规则，要得到否定的前件，就要否定后件，即需假设“甲类工厂不面临竞争压力”或“甲类工厂不是互联网企业”,A项是需要补充的前提。<br>B项，互联网企业不都是甲类工厂，即有的互联网企业不是甲类工厂，换位推理可得有的甲类工厂不是互联网企业。根据否定后件可以否定前件的推理规则可得，有的甲类工厂不是未来企业，与题干结论不同，题干结论中说的是甲类工厂的整体情况，因此该项不是题干结论成立所需的前提，排除。<br>C项，甲类工厂是互联网企业，肯定后件无法进行有效推理，得不出甲类工厂与未来企业之间的关系，因此该项不是题干结论成立所需的前提，排除。<br>D项，互联网企业都是未来企业，不涉及甲类工厂，得不出题干结论，因此该项不是题干结论成立所需的前提，排除。","no":217},{"id":"1718789647017","type":"single","material":"","stem":"人们常说，读书可以增长知识、陶冶性情。有专家指出，读书还可以治病，特别是对于由一些社会因素引起的心理疾病，如抑郁、压抑、恐慌、烦恼等，读书有很好的疗效。<br>以下哪项如果为真，最能支持上述专家的观点?","options":[{"label":"A","content":"读书能够促使患者转变思维方式，提高认知能力，重新认识世界和认识自己"},{"label":"B","content":"患者能够从阅读中有意无意获得情感上的认同和慰藉，释放内心的焦虑和不安"},{"label":"C","content":"汉代大学问家刘向十分重视读书的医疗作用，认为书犹药也，善读之可以医愚"},{"label":"D","content":"阅读能使大脑中产生一种神经肽，可以增强细胞免疫力，有益于人的身体健康"}],"answer":"B","explanation":"题干论点：读书还可以治病，特别是对于由一些社会因素引起的心理疾病。题干论据：读书可以增长知识、陶冶性情。<br>A项，患者通过读书可以重新认识世界认识自己，与论点中的心理疾病无关，无法支持专家观点。<br>B项，患者能够从阅读中获得慰藉，释放焦虑，直接指明论点是正确的，支持了专家的观点。<br>C项，读书可以医治愚蠢，与论点中的心理疾病无关，无法支持专家观点。<br>D项，阅读有益身体健康，与治疗心理疾病无关，无法支持专家观点。","no":218},{"id":"1718789647018","type":"single","material":"","stem":"绿茶的主要成分是茶多酚。近来通过大量动物实验发现，茶多酚具有抑制肿瘤细胞增殖、促进肿瘤细胞消亡的作用。但是，有些专家通过对大量人群的研究，并未发现饮茶越多癌症发病率就越低这一现象。据此，他们并不认为经常饮茶能够防癌。<br>以下哪项如果为真，则是上述专家做出结论最合理的假设?","options":[{"label":"A","content":"如果茶叶在生产、加工、运输过程中受到重金属、农药等致癌物的污染，则饮茶越多就越增加患癌风险"},{"label":"B","content":"如果人们长期饮茶但又奉行抽烟、喝酒、熬夜等不良生活习惯，则很难看出经常饮茶能带来防癌作用"},{"label":"C","content":"只有假定品种不同但分量相同的茶叶含有的茶多酚基本相同，才能得出经常饮茶能够防癌这一结论"},{"label":"D","content":"只有在大量人群中发现饮茶越多癌症发病率就越低这一现象，才能得出经常饮茶能够防癌这一结论"}],"answer":"D","explanation":"题干论点：他们并不认为经常饮茶能够防癌。题干论据：专家通过对大量人群的研究并未发现饮茶越多癌症发病率就越低这一现象。<br>A项，如果茶叶受到致癌物的污染，则饮茶越多越增加患癌风险，该项讨论的是受到致癌物污染的茶叶是否会增加风险，而论点讨论的是茶叶本身是否能够防癌，属于无关项。<br>B项，人们长期饮茶并且还奉行一些不良的习惯，就很难看出经常饮茶带来的防癌作用，肯定了饮茶能够防癌，削弱了题干论点。<br>C项，选项表述的是在什么情况下，能够得出茶叶防癌这一功效，而论点是在讨论茶叶是否能够防癌，二者话题不一致。<br>D项，在题干专家研究的现象和结论之间建立了联系，即如果不能发现大量人群中饮茶越多癌症发病率越低，就不能得出经常饮茶能防癌的结论，是题干得出结论最合理的假设。","no":219},{"id":"1718789647019","type":"single","material":"","stem":"某单位组织职工进行素质拓展培训，职工可自愿报名参加。老张碰到新来的员工小李，聊起此事，老张提醒小李说：“单位组织素质拓展培训，赶紧报名去吧。”小李说：“我手上工作没有处理完，不用报了。”<br>以下除哪项外，都可以作为小李的回答所包含的假设?","options":[{"label":"A","content":"如果工作处理好了，则要报名参加素质拓展培训"},{"label":"B","content":"只要我工作没有处理完，我就不必参加素质拓展培训"},{"label":"C","content":"凡是报名参加素质拓展培训的，都是已经处理完工作的"},{"label":"D","content":"只有工作处理完的人，才报名参加素质拓展培训"}],"answer":"A","explanation":"小李根据“手上工作没有处理完”得出“不用报名参加素质拓展培训”的结论，可见其假设了“报名参加素质拓展培训→工作处理完”。<br>A项，工作处理好了→报名参加素质拓展培训，混淆了充分条件和必要条件，不是小李的回答所包含的假设。<br>B项，工作没有处理完→不必参加素质拓展培训，否后则能否前，是小李的回答所包含的假设。<br>C项，报名参加素质拓展培训→已经处理完工作，是小李的回答所包含的假设。<br>D项，工作处理完←报名参加素质拓展培训，是小李的回答所包含的假设。。","no":220},{"id":"1718789647020","type":"single","material":"","stem":"航天器经过大气层返回地球时，会与大气层摩擦导致温度急剧升高。为使航天器克服“热障”安全返回地球。国外某研究机构在回收微小卫星EGG上做了新的技术尝试。EGG在下降过程中张开由二氧化碳充气扩张而成的半球形隔热减速伞，之后其受到的大气阻力显著增加，开始缓慢进入大气层并顺利落向地球。<br>上述技术尝试基于的前提是：","options":[{"label":"A","content":"航天器表层材料需具备耐受超高温的性能"},{"label":"B","content":"研究航天器耐热材料的成本比减速伞成本要高"},{"label":"C","content":"航天器落入大气层时过热是下降过程的常见难题"},{"label":"D","content":"航天器以较慢速度进入地球可减少摩擦导致的发热"}],"answer":"D","explanation":"本题要求选择题干的技术尝试基于的前提，可以结合反向代入法解题。反向代入法是指将选项的反面代入题干，即假设该选项不成立时，看题干论证是否成立，如果题干论证不成立了，则该选项就是题干的必需前提。<br>题干中的技术尝试是为了使航天器克服“热障”安全返回地球，即通过让航天器缓慢进入大气层来解决航天器与大气层摩擦导致温度急剧升高的问题，因此D项是其必需的前提，否则如果航天器以较慢的速度进入地球也无法减少摩擦导致的发热，题干中新的技术尝试就无法达到目的。A项表层材料的性能、B项材料的成本均与题干中的让航天器缓慢进入大气层从而减少发热这一技术无关；C项航天器过热也不是必需的前提。","no":221},{"id":"1718789647021","type":"single","material":"","stem":"专业教育的主要目的是帮助大学生尽可能全面地掌握各自专业领域的基础知识，而通识教育的目的则重在帮助大学生获得生活的意义和价值。因此有专家指出，相较于专业教育，通识教育对个人未来生活的影响更大。<br>下列哪项如果为真，最能支持该专家的断言?","options":[{"label":"A","content":"价值问题关乎人的幸福和尊严，值得在通识教育中予以探究和思考"},{"label":"B","content":"当今我国大学开设的专业教育类课程要远远多于通识教育类课程"},{"label":"C","content":"一个人如果没有专业知识，可能还能活下去；倘若没有价值追求，就将只是一具没有灵魂的躯壳"},{"label":"D","content":"没有专业知识，人很难应对未来生活的挑战；而不正确的价值追求，则会误导人的生活"}],"answer":"C","explanation":"题干中专家的观点：通识教育比专业教育对个人未来生活的影响更大。<br>A项说的是价值问题值得在通识教育中予以探索和思考，并没有说明通识教育和专业教育哪个对个人未来生活的影响更大，偏离论题，排除。<br>B项指出专业教育类课程比通识教育类课程多，则有可能专业教育比通识教育更重要，在一定程度上削弱了专家的观点，排除。<br>C项对比了专业教育和通识教育对人的影响，即没有专业教育可以活下去，而没有通识教育就没有了灵魂，显然没有灵魂更严重，说明了通识教育比专业教育对个人未来生活的影响更大，补充了论据，能够支持专家的观点，正确。<br>D项指出专业教育和通识教育对个人未来生活的影响都很大，两者都不可或缺，无法比较哪个影响更大，不能支持。","no":222},{"id":"1718789647022","type":"single","material":"","stem":"未取得教师资格证书的大学毕业生不能被某地区的学校录用为教师。该地区的师范大学历史系的所有学生在毕业前都必须取得教师资格证书。因此，任何一位该大学历史系的毕业生都可以在该地区被录用为教师。<br>下列哪项如果为真，能够使上述论证得以成立?","options":[{"label":"A","content":"每一个取得教师资格证书的人的教学水平都是相同的"},{"label":"B","content":"取得教师资格证书是大学毕业生在该地区被录用为教师的唯一条件"},{"label":"C","content":"该地区师范大学历史系取得教师资格证书的所有学生都能毕业"},{"label":"D","content":"想知道自己是否能胜任教师这一职业的唯一方法就是去参加教师资格证书考试"}],"answer":"B","explanation":"本题要求选择能够使题干论证成立的一项，在解题时需明确题干论证的论据和论点，并优先寻找论据与论点之间是否存在跳跃，如果存在跳跃，那么在两者之间建立联系即补充题干论证成立的前提。另外，也可以结合反向代入法进行解题，即依次将选项的反面代入题干，如果题干的结论不成立了，则该项即为题干论证成立的必要前提。<br>题干由该校历史系的所有学生在毕业前都必须取得教师资格证书，得出任何一位该大学历史系的毕业生都可以在该地区被录用为教师。题干在“取得教师资格证书”和“在该地区被录用为教师”之间存在跳跃，要使论证成立，需在两者之间建立起联系。B项说明了取得教师资格证是在该地区被录用为教师的唯一条件，是题干推理成立所需的前提，否则如果取得教师资格证不是唯一的条件，还有其他录用条件的话，那么题干结论将不能成立，因此B项当选。A项论述的是取得教师资格证书的人的教学水平问题、C项论述的是取得教师资格证书的学生能否毕业的问题、D项论述的是检验自己能否胜任教师这一职业的问题，均与题干论述的能否在该地区被录用为教师这一论述不一致，均为无关项，排除。","no":223},{"id":"1718789647023","type":"single","material":"","stem":"近两年，长江刀鱼的市场售价出现了明显回升。这是因为近两年刀鱼捕捞量只有二三十年前的几十分之一，和五年前相比也有不小的差距。<br>以上表述是以下列()项为前提假设的。","options":[{"label":"A","content":"每年三月下旬是刀鱼价格的巅峰期"},{"label":"B","content":"刀鱼有“长江第一鲜”的美誉"},{"label":"C","content":"长江刀鱼的捕捞作业受潮汛影响较大"},{"label":"D","content":"刀鱼的人工养殖难题依然没有解决"}],"answer":"D","explanation":"要求找出题干的前提，即能在论据和论点之间建立联系，用到的论证方法为搭桥论证。论点：长江刀鱼的市场售价明显回升。论据：最近两年刀鱼的捕捞量较之前少很多。<br>A项，只讲了每年三月下旬是刀鱼价格的巅峰期，属于无关项。<br>B项，无论刀鱼有没有“长江第一鲜”的美誉，对题干结论都没有影响，属于无关项。<br>C项，不管长江刀鱼捕捞受潮汛影响大还是小，如果通过人工养殖刀鱼能使其量的供应足够，其价格也不会有明显回升，排除。<br>D项，说明了刀鱼不仅捕捞量少，而且不能通过人工养殖解决刀鱼量少的问题，满足<br>不了人们的需求，其售价自然会出现明显回升。补充了论据，加强了题干论证，当选。","no":224},{"id":"1718789647024","type":"single","material":"","stem":"自闭症患者往往认知水平低下，一些自闭症患者会表现出述情障碍，即无法理解情感，缺乏对自身或他人情感的认知能力。由于缺乏情感认知能力，人们通常认为自闭症患者比较冷漠。<br>以下哪项如果为真，最能支持上述结论?","options":[{"label":"A","content":"在道德两难的困境中，自闭症患者会为了避免做出伤害性举动而承受强烈的情绪压力"},{"label":"B","content":"述情障碍的发生率在自闭症患者中高达50%左右，远远高于普通人"},{"label":"C","content":"自闭症患者也会对他人产生正常的共情反应，甚至会比普通人更加关注别人的情绪"},{"label":"D","content":"述情障碍虽会伴随自闭症出现，但二者并无必然联系，因为很多普通人也会出现"}],"answer":"B","explanation":"题干由一些自闭症患者会表现出述情障碍，得出“人们通常认为自闭症患者比较冷漠”的结论。<br>A项，自闭症患者承受强烈的情绪压力，据此无法得知自闭症患者给人留下的印象是什么,无法支持题干结论。<br>B项，说明自闭症患者中述情障碍的发生率比较高，远远高于普通人，导致自闭症患者给人们冷漠的印象，支持了题干结论。<br>C项，指出自闭症患者也会有共情反应，削弱了题干结论。<br>D项，述情障碍和自闭症并无必然联系，削弱了题干结论。","no":225},{"id":"1718789647025","type":"single","material":"","stem":"当人们在海洋游泳时，身体会释放一种看不见的电信号。科研人员根据这一情况研制了海洋隐形衣。该隐形衣通过屏蔽身体释放的电信号，使得鲨鱼等海洋生物无法发现人们的踪迹。这样，人们就可以近距离接触并观察鲨鱼等海洋生物。<br>以下哪项是科研人员假设的前提?","options":[{"label":"A","content":"有些海洋生物利用超声波进行信息交流、觅食、发现并躲避天敌"},{"label":"B","content":"部分鱼类视网膜中含有很多视锥细胞，能够敏锐地感受水中细微的光线变化"},{"label":"C","content":"鲨鱼等海洋生物是凭借人体释放的电信号来发现人们踪迹的"},{"label":"D","content":"该隐形衣非常轻薄，对人们在水下的活动不会形成阻碍"}],"answer":"C","explanation":"题干由海洋隐形衣通过屏蔽身体释放的电信号，使鲨鱼等海洋生物无法发现人们的踪迹，得出“人们可以近距离接触并观察鲨鱼等海洋生物”的结论。要求选择该论证成立的假设前提，需要在前提和结论之间建立联系。<br>A项，说明屏蔽电信号也无法阻止海洋生物发现人们的踪迹，削弱了题干观点。<br>B项，说明部分鱼类是靠光线感知的，也削弱了题干观点。削弱了题干观点。<br>C项，鲨鱼等海洋生物是通过人体释放的电信号来发现人们的踪迹的，所以穿了隐形衣就能避免被鲨鱼等海洋生物发现，是科研人员假设的前提。<br>D项，隐形衣不会对人们的水下活动形成阻碍，也不是必需的前提条件。","no":226},{"id":"1718789647026","type":"single","material":"","stem":"目前，人们通过在河流上筑坝建造水电站获得电能，但是地球上适合筑坝的地方为数不多，筑坝也会破坏生态环境。相比之下，海洋覆盖着70%的地球表面，海面上波涛滚滚，昼夜不息，蕴藏着巨大的能量，收集波浪能适合的海域广，生态环境破坏小。因此，收集波浪能用于发电将比在河流上筑坝发电更有优势。<br>以下哪项如果为真，不能质疑上述结论?","options":[{"label":"A","content":"据估计，全世界可开发利用的波浪能达2.5TW,目前一些小功率的波浪能设备已经推广应用于导航浮标、灯塔等"},{"label":"B","content":"河流的流向较为稳定，而波浪是海水的缓慢运动，方向并不固定，在此条件下设立的发电机效率非常低"},{"label":"C","content":"不管是在海床上建塔来支撑发电，还是把发电机固定在海床上都要耗费巨资，成本比河流电站要昂贵很多"},{"label":"D","content":"河水的水能易于收集，而深海地区及开阔洋面中的波浪能难以提取，可供利用的波浪能仅局限于靠近海岸的地方"}],"answer":"A","explanation":"题干结论：收集波浪能用于发电将比在河流上筑坝发电更有优势。论据：海洋蕴藏着巨大的能量，收集波浪能适合的海域广，生态环境破坏小。要质疑题干观点，可以从收集波浪能发电的可行性出发考虑，将能够质疑的选项排除就能得到正确答案。<br>A项，说明可开发利用的波浪能大，已经有部分设备推广应用，加强了题干结论。<br>B项，说明波浪发电机效率非常低，直接削弱了题干结论。<br>C项，从成本角度说明波浪发电的劣势，削弱了题干结论。<br>D项，收集难度大也削弱了题干结论。","no":227},{"id":"1718789647027","type":"single","material":"","stem":"在国家发展新兴产业的大背景下，某公司虽然在某产业长期处于领先地位，但上半年的生产数据显示，领先优势越来越小，在邀请专家进行企业诊断后，专家认为该公司领先优势缩小的原因在于公司虽然管理制度健全，但由于企业文化缺乏进取心，导致在好的政策环境下公司发展趋缓。<br>以下哪项如果为真，不能反驳专家的观点?","options":[{"label":"A","content":"相较沿海地区同类公司受益于健全的产业链，公司处于内地，其发展有所受限"},{"label":"B","content":"发展趋缓的原因在于长期以来公司下半年的生产数据一般高于上半年"},{"label":"C","content":"公司一直注重加强企业文化建设，形成了和谐的企业氛围"},{"label":"D","content":"企业文化并不是一个公司的核心竞争力，关键问题在于新产品研发力度不够"}],"answer":"C","explanation":"题干专家的观点：该公司领先优势缩小的原因在于企业文化缺乏进取心，导致在好的政策环境下公司发展趋缓。要反驳专家的观点，只有能够指出是其他原因导致的该公司领先优势的缩小就可以，将能够反驳的选项排除掉即可选出正确答案。<br>A项，说明公司发展趋缓的原因是处于内地，属于它因削弱，质疑了专家观点。<br>B项，说明上半年发展趋缓是正常的状态，与企业文化无关，质疑了专家观点。<br>C项，“公司加强企业文化建设”不代表公司发展趋缓不是由于企业文化缺乏进取心造成的，不能反驳专家的观点。<br>D项，说明公司发展趋缓是因为新产品研发力度不够，能够质疑专家的观点。。","no":228},{"id":"1718789647028","type":"single","material":"","stem":"社会经济越是发展，一个企业越是要勇于承担责任，产品的品质、品牌、社会责任，这三样一个都不能少，少了任何一个，消费者都不会买单。<br>下面哪项陈述，最能削弱以上观点?","options":[{"label":"A","content":"某名牌企业被检出产品的质量不达标，产品销售量明显降低"},{"label":"B","content":"某企业产品的质量较差，但凭借促销手段，销售量持续增长"},{"label":"C","content":"某名牌企业一直依法纳税，热心公益事业，销售量稳步提升"},{"label":"D","content":"某名牌企业在被爆出偷税漏税丑闻后，产品销售量明显降低"}],"answer":"B","explanation":"题干的推理规则：产品的品质、品牌、社会责任少了任何一个→消费者不会买单。否后得出否前，即，消费者买单→产品的品质、品牌、社会责任一个都不能少。<br>A项，质量不达标→销量降低，支持了题干观点。<br>B项，质量差，但凭借促销手段→销量增长，与题干中消费者买单→产品的品质、品牌、社会责任一个都不能少相矛盾，削弱了题干观点。<br>C项，依法纳税，热心公益事业→销量提升，支持了题干观点。<br>D项，偷税漏税→销量降低，支持了题干观点。","no":229},{"id":"1718789647029","type":"single","material":"","stem":"对多个省份的调查研究发现，对于外向者而言，花大量时间用于网络社交并不会影响与他人面对面交流的意愿，而内向者即使不进行网络社交也不会变成社交达人。因此，有研究者认为，网络社交会妨碍传统社交的担忧是毫无必要的。<br>以下哪项为真，最有助于支持上述结论?","options":[{"label":"A","content":"有许多花费大量时间在网络社交上的人不愿意与他人面对面交流"},{"label":"B","content":"无论采用哪种方式，大多数人参与社会活动的总时间是相对固定的"},{"label":"C","content":"在网络社交的帮助下，许多人在传统社交中的能力和自信得到了提升"},{"label":"D","content":"该研究由某大学开展，而在该校学生中，网络社交并不是主要的社交方式"}],"answer":"C","explanation":"题干结论：网络社交会妨碍传统社交的担忧是毫无必要的。要支持这一结论，只需说明网络社交确实不会影响传统社交即可。<br>A项，指出有许多在网络社交上花费大量时间的人不愿意与他人面对面交流，则网络社交实际上会影响传统社交，反驳了题干结论，排除。<br>B项，大多数人参与社会活动的总时间是相对固定的，所以网络社交多了会使传统社交变少，削弱了题干结论，排除。<br>C项，指出网络社交不仅不会妨碍传统社交，反而能提升传统社交能力，支持了题干结论。<br>D项，网络社交是否为主要的社交方式与网络社交是否会妨碍传统社交无关，无法支持题干结论。","no":230},{"id":"1718789647030","type":"single","material":"","stem":"某大学教授认为我国住房公积金制度自实行以来，只有一些有购房能力的缴存职工享受到了低息购房贷款，而对于那些收入较低且无购房能力的工薪阶层并没有起到住房保障作用。所以，住房公积金制度是一种“劫贫济富”的制度，国家应该取消住房公积金制度。<br>以下哪项如果为真，最能削弱该教授的观点?","options":[{"label":"A","content":"住房公积金制度是国家建立的一项强制性住房保障制度"},{"label":"B","content":"企业缴存部分的公积金对个人来说是一项额外收入"},{"label":"C","content":"民营企业的缴存职工因收入不高而没有购房能力"},{"label":"D","content":"外地务工人员一般不愿意在工作地买房"}],"answer":"B","explanation":"该大学教授认为，住房公积金制度是一种“劫贫济富”的制度，国家应该取消住房公积金制度。<br>A项指出住房公积金制度是强制性住房保障制度，因此不会根据人们的不同情况或不同需求采取不同的措施，在一定程度上加强了该教授的观点。<br>B项说明公积金是一种额外收入，不存在“劫贫济富”,削弱了该教授的观点。<br>C项说明确实存在没有购房能力的工薪阶层，那么即使他们缴存了公积金也无法用于买房，因此公积金对于他们来说并没有起到住房保障作用，加强了该教授的观点。<br>D项外地务工人员的购房意愿与公积金制度能否起到住房保障作用无关，排除。","no":231},{"id":"1718789647031","type":"single","material":"","stem":"一项研究发现，二氧化硅是一种植物容易吸收的硅元素形态，通过使用二氧化硅改善土壤，植物可沉淀出称为“植结石”的小颗粒。颗粒中含有的硅元素可减缓昆虫的发育，颗粒的石头质地还能磨损昆虫口器，从而降低植物的虫害程度。由此，有关研究人员建议，可以在那些农作物经常受昆虫侵害的地区土壤中加入这类硅元素。<br>以下哪项如果为真，最能反驳上述建议?","options":[{"label":"A","content":"各地区昆虫的耐药性及药物作用的敏感性都相同"},{"label":"B","content":"受昆虫侵害严重的地区，土壤中普遍缺乏硅元素"},{"label":"C","content":"农作物中的硅元素会对食用者的身体发育产生影响"},{"label":"D","content":"富含硅元素的农作物的口感比普通农作物更好"}],"answer":"C","explanation":"题干的建议：加入硅元素能降低农作物的虫害程度。A项与加入硅元素是否能降低农作物的虫害程度无关，排除。<br>B项说明硅元素与虫害有一定联系，在一定程度上加强了题干建议，排除。<br>C项指出此措施不具有可操作性，反驳了题干建议。<br>D项无法说明加入硅元素是否能够降低农作物的虫害程度，排除。","no":232},{"id":"1718789647032","type":"single","material":"","stem":"某调查小组对Y地区吸烟青少年群体调查发现，75%吸烟青少年来自二手烟家庭，父母至少有一人为吸烟者。因此，该地区二手烟家庭如果能大幅减少，新的吸烟青少年数量将显著减少。<br>以下哪项如果为真，最能支持上述论证?","options":[{"label":"A","content":"成年人的戒烟方法和青少年的戒烟方法是不同的"},{"label":"B","content":"吸烟青少年可以通过积极的干预而戒烟"},{"label":"C","content":"成年人和青少年学会吸烟的方式是相同的"},{"label":"D","content":"Y地区成长于二手烟家庭的青少年吸烟的比例比其他家庭高"}],"answer":"D","explanation":"题干论证：二手烟家庭大幅减少，新的吸烟青少年数量就会减少。<br>A项说的是戒烟方法，不能说明二手烟家庭减少，新的吸烟青少年是否会减少，排除。<br>B项说的也是戒烟方法，无法支持题干论证，排除。<br>C项指出成年人和青少年学会吸烟的方式相同，但仍然无法说明二手烟家庭如果减少，新的吸烟青少年是否会减少，不能支持题干论证，排除。<br>D项指出该地区二手烟家庭的青少年吸烟的比例比其他家庭高，说明二手烟家庭对青少年吸烟是有影响的，支持了题干观点。","no":233},{"id":"1718789647033","type":"single","material":"","stem":"一项调查发现，在牛奶人均消费量大的地区，癌症的发病率较高；而牛奶人均消费量少的地区，癌症发病率极低。有人据此得出结论：饮用牛奶会使癌症的发病率上升。<br>以下哪项如果为真，最能质疑上述结论?","options":[{"label":"A","content":"癌症发病率高的地区，其他疾病的发病率相对较低"},{"label":"B","content":"牛奶含钙量高，吸收好，而且睡前喝牛奶有助于睡眠"},{"label":"C","content":"调查中牛奶人均消费量大的地区，人口总数也相对较大"},{"label":"D","content":"牛奶人均消费量大的地区居民寿命较长，且罹患癌症的主要是中老年人"}],"answer":"D","explanation":"题干论点：饮用牛奶会使癌症的发病率上升。题干论据：在牛奶人均消费量大的地区，癌症发病率较高；而牛奶人均消费量少的地区，癌症发病率极低。要质疑这一论述，可以运用常用的另有他因、切断因果等方式。<br>A项，其他疾病发病率与题干论述无关，属于无关项。<br>B项，牛奶含钙高，吸收好且有益睡眠与题干论述无关，属于无关项。<br>C项，牛奶人均消费高的地区，人口总数也大，并没有指出癌症发病率的情况，不能质疑题干结论。<br>D项，牛奶人均消费量大的地区的居民寿命长，癌症患者主要是中老年人，说明癌症发病率高另有他因，质疑了题干结论。","no":234},{"id":"1718789647034","type":"single","material":"","stem":"毛囊干细胞是在毛囊中长期生活的细胞，终身为我们产生毛发。毛囊干细胞从血液中吸收葡萄糖，经过代谢，葡萄糖变为丙酮酸。这些丙酮酸一部分被细胞运输进线粒体，在线粒体中，丙酮酸进一步的代谢能够为细胞提供能量，另一部分丙酮酸将在细胞内进行后续的变化，产生新的代谢产物——乳酸。乳酸可以激活毛囊干细胞，使毛发生长得更快速。据此，有研究人员认为，通过药物提高乳酸的含量可以治疗脱发。<br>以下哪项如果为真，最能支持上述结论?","options":[{"label":"A","content":"葡萄糖的代谢功能是生命体自我修复的重要方式"},{"label":"B","content":"通过药物提供的乳酸能够直接作用于毛囊干细胞"},{"label":"C","content":"人为增加乳酸的含量不会对毛囊干细胞产生其他影响"},{"label":"D","content":"减少丙酮酸进入线粒体，可以使毛囊干细胞产生更多乳酸"}],"answer":"B","explanation":"题干论据：毛囊干细胞的吸收代谢过程中的乳酸可以激活毛囊干细胞，使毛发生长得更快。题干论点：通过药物提高乳酸的含量可以治疗脱发。要支持该结论，可以说明药物提高乳酸含量确实可以促进毛囊干细胞生发。<br>A项，葡萄糖的代谢功能是否是生命体自我修复的方式，与题干论证无关，属于无关项。<br>B项，指出药物提供的乳酸能够直接作用于毛囊干细胞，说明这种方式能够达到治疗脱发的目的，有力地支持了题干结论。<br>C项，人为增加乳酸的含量会不会对毛囊干细胞产生其他影响以及产生什么影响，并不能说明提高乳酸的含量可以治疗脱发，不能支持题干结论。<br>D项，产生更多乳酸和题干通过药物增加乳酸含量没有必然联系，不能支持题干结论。","no":235},{"id":"1718789647035","type":"single","material":"","stem":"科学家重建地球地质历史上的大气成分面临的难题之一就是缺少可用样品。近年来，不少人开始关注琥珀，他们认为相比其他有机材料，琥珀在长久的地质年代内，所保存的化学和同位素信息几乎不会改变，因此可以用于揭示不同年代的全球大气成分。<br>以下哪项如果为真，最能质疑上述结论?","options":[{"label":"A","content":"由于琥珀内部常保留着生物的形体，故能反映当时生态环境与生物的关系"},{"label":"B","content":"琥珀主要诞生于约4000万至6000万年前的始新世纪，其他年份并没有形成琥珀"},{"label":"C","content":"琥珀是由松柏科植物的树脂经压力和热力作用形成，由于时间漫长，数量极少"},{"label":"D","content":"琥珀的硬度较低，如果因搬运、储存不当而造成损害，会影响同位素检测的准确性"}],"answer":"B","explanation":"题干论据：相比其他有机材料，琥珀在长久的地质年代内，所保存的化学和同位素信息几乎不会改变。题干论点：琥珀可以用来揭示不同年代的全球大气成分。要质疑该结论，可以说明琥珀由于产生年代的限制，无法揭示不同年代的全球大气成分。<br>A项，琥珀内部保留着生物的形体，能够反映生态环境与生物的关系，与题干论证无关，属于无关项。<br>B项，琥珀只形成于始新世纪，其他年代没有琥珀，则无法通过琥珀对比不同年代的全球大气成分，有力地质疑了题干结论。<br>C项，琥珀形成所需要的时间漫长，因此琥珀数量少，与题干论证无关，属于无关项。<br>D项，琥珀需要妥善储存、搬运，否则会影响同位素检测的准确性，进而影响不同年代全球大气成分的对比，只提出了一种可能性，质疑力度不如B","no":236},{"id":"1718789647036","type":"single","material":"","stem":"人体的大脑与血液之间有一道“血脑屏障”,任何起安眠作用的物质首先必须能穿过这个屏障才能起效。牛奶中含有一种名为色氨酸的氨基酸能够穿过血脑屏障，制造诱发睡眠的荷尔蒙5-羟色胺，因此人们认为睡前喝牛奶是促进睡眠非常有效的方法。<br>以下哪项如果为真，最能削弱上述结论?","options":[{"label":"A","content":"皮肤温度上升，入睡速度就快，故而喝一杯热牛奶就如同洗热水浴一样，能够加快入睡速度"},{"label":"B","content":"小份的牛奶所含的色氨酸总量不足以让身体的激素水平发生较大的波动，只有喝大量的牛奶助眠效果才会好"},{"label":"C","content":"米饭等碳水化合物助眠效果更好，它们会刺激胰岛素的合成，让色氨酸以外的氨基酸进入肌肉组织，从而使色氨酸更易进入大脑"},{"label":"D","content":"牛奶中蕴含许多种类的氨基酸，这些物质进入血液后，会争抢穿过血脑屏障的通道，从而降低色氨酸穿过血脑屏障的能力"}],"answer":"D","explanation":"题干由起安眠作用的物质要穿过血脑屏障，且牛奶中的氨基酸能够穿过血脑屏障，得出人们睡前喝牛奶能有效促进睡眠。要削弱该结论，可以说明牛奶实际上起不到这样的作用。<br>A项，说明喝热牛奶能够加快入睡速度，对题干结论有一定支持作用，排除。<br>B项，需要喝大量牛奶助眠效果才会好，并没有否认牛奶的助眠作用，不能削弱题干结论，排除。<br>C项，碳水化合物的助眠效果更好，但不能说明牛奶没有助眠作用，无法削弱题干结论，排除。<br>D项，指出牛奶中色氨酸通过血脑屏障的能力会降低，并不能有效促进睡眠，削弱了<br>题干论述。","no":237},{"id":"1718789647037","type":"single","material":"","stem":"最近，英国科学家提出一种观点，认为海绵这种没有大脑，甚至没有任何神经细胞，在地球生活了数亿年的动物在远古时代曾经拥有神经细胞，但在随后的进化中放弃掉了。<br>如果以下各项为真，最能支持上述观点的是：","options":[{"label":"A","content":"海绵拥有打造神经系统所需要的基因，而对于海绵来说，无论是大脑还是简单的神经系统，都可能是“累赘”,是对能量的浪费"},{"label":"B","content":"研究发现，拥有复杂神经系统的栉水母，才是其他所有动物的“姊妹群”,是动物祖先的最佳代表"},{"label":"C","content":"已知年代最久远的拥有复杂大脑的动物出现时间远远早于海绵，它们拥有精密的类大脑结构，并拥有专门的神经网络"},{"label":"D","content":"一些寄生虫与它们的近亲相比，就因为寄生这种生活方式失去了复杂的神经系统；而海绵与它们的近亲相比，生活方式类似于寄生"}],"answer":"A","explanation":"题干的观点：海绵现在没有神经细胞是因为在进化中放弃掉了。<br>A项，说明了海绵可能曾经拥有神经系统的证据以及放弃了神经系统和大脑的原因，直接支持了观点。<br>B项，栉水母是动物祖先的代表，与题干观点无关，不能支持。<br>C项，拥有大脑的动物出现的时间早晚也与题干观点无关，不能支持。<br>D项，属于不当类比，不能支持题干观点。","no":238},{"id":"1718789647038","type":"single","material":"","stem":"据报道，国际上有不少科学家声称，在新西兰周围发现了一块名为“西兰洲”的新大陆，它符合大洲认定标准的全部要求，是世界第八大洲，相信在不久的将来，各国的地理课本将会被改写。<br>得出“各国的地理课本将会被改写”的结论必须基于的前提是：","options":[{"label":"A","content":"各国地理课本会因为“大陆”“大洲”等相关知识内容变化而改写"},{"label":"B","content":"认定大洲的标准具有权威性，并且在课本发行前不会改变"},{"label":"C","content":"各国地理课本目前没有关于“世界第八大洲”的任何内容"},{"label":"D","content":"各国地理课本本身都有关于“大陆”“大洲”等的内容"}],"answer":"A","explanation":"首先分析题干论证，找到其中的漏洞，能够将其补充完整即为正确答案。题干由不少科学家声称发现了名为“西兰洲”的新大陆，得出不久的将来，各国的地理课本将会被改写。<br>A项，地理课本会因为相关知识变化而改写，在论点和论据之间建立了联系，是得出题干结论基于的前提。<br>B项，只能说明新大陆认定标准的科学性，无法推出课本会改写，不是题干结论的前提。分享<br>C项，各国地理课本目前没有“世界第八洲”的内容，无法证明未来的课本会不会被改写，也不是题干结论前提。<br>D项，各国地理课本的内容，也不是题干结论必需的前提。","no":239},{"id":"1718789647039","type":"single","material":"","stem":"与意大利、德国等欧洲国家不同，美国被一些球迷称为“足球荒漠”,他们认为在美国，足球一直被视为边缘运动。<br>如果以下各项为真，最能反驳上述看法的是：","options":[{"label":"A","content":"美国足球队在世界杯等多项国际重大比赛上获得了傲人成绩，其在国际足联的排名有时甚至超过英格兰等传统足球强国"},{"label":"B","content":"美国足球联赛起步虽晚，但发展飞速，现在其联赛水平已经超过阿根廷、巴西等传统足球强国分享"},{"label":"C","content":"足球已经成为美国12~24岁年轻人的第二运动，其青少年足球人口绝对数量位居世界第一"},{"label":"D","content":"因为缺乏相应的足球文化土壤的培育，所以在美国从事足球运动的人都是真正热爱足球的人，没有复杂商业运作的足球运动更加纯粹"}],"answer":"C","explanation":"题干观点为足球在美国被视为边缘运动。要求选择最能反驳该观点的一项，只要能够说明在美国，足球属于社会主流运动即可。<br>A项，美国足球队在世界杯等重大比赛上获得傲人成绩，不代表足球在美国不是边缘运动，削弱力度较弱。<br>B项，美国足球联赛水平高，也不能说明足球在美国就不是边缘运动，削弱力度较弱。<br>C项，通过数据说明美国青少年足球人口众多，足球在美国并不是边缘运动，而属于主流运动，直接反驳了题干观点。<br>D项，得不出到底有多少人从事足球运动，不能证明其不是边缘运动，不能反驳。","no":240},{"id":"1718789647040","type":"single","material":"","stem":"传统社会能够提供的文化产品很少，公众的可选择性也很小，公众的兴趣爱好主动或被动地被聚拢到一起；进入现代社会，伴随着文化产业、网络和传媒的快速发展，娱乐方式也从传统的人际直接互动转变为借助于机器的人际间接互动，甚至是人机互动。公众的选择范围在极大扩展的同时，公众因选择的多样性而出现大量分流，随之而来的是共同兴趣爱好的消逝。<br>如果以下各项为真，最能反驳上述论证的是：","options":[{"label":"A","content":"网络社会的来临彻底改变了人与人之间的互动模式"},{"label":"B","content":"借助于移动互联网、日常交往最多的人可能根本就不在身边"},{"label":"C","content":"现代技术突破了传统差序格局，人际关系不再以地域为基础"},{"label":"D","content":"社会组织可以通过搭建联络平台组织相关活动来培养兴趣爱好"}],"answer":"D","explanation":"题干的论证是由于网络和传媒的快速发展，公众因选择的多样性出现分流，从而导致共同兴趣爱好的消逝。要求选择最能反驳该论证的一项，只要能够<br>说明公众的兴趣爱好并未随着现代社会的发展而消逝即可。<br>A项，人们的互动模式的改变，与兴趣爱好无关。<br>B项，说明移动互联网带来的改变，与兴趣爱好无关。<br>C项，说的是现代技术突破了地域的限制，与是否会导致共同兴趣爱好消逝无关。<br>D项，说明可以通过新的平台和方式来培养共同兴趣爱好，直接反驳了结论。","no":241},{"id":"1718789647041","type":"single","material":"","stem":"地方政府对经济的干预不仅表现在直接通过财政投资拉动经济增长，还表现为通过财政补贴、税收优惠、信贷优惠和降低土地等要素成本诱导性地干预企业的投资决策。国有企业因为与政府有密切的产权关系，其控制权主要掌握在政府手中，这就造成国有企业往往成为政府干预和调控经济的手段。<br>以下各项如果为真，最能支持上述结论的是：","options":[{"label":"A","content":"国有企业的投资决策通常会受到地方政府的直接指导和干预"},{"label":"B","content":"房地产行业前三强都是民营企业，它们多数都享受了信贷优惠"},{"label":"C","content":"钢铁、水泥和电解铝等产能过剩行业中既有国有企业，也有民营企业"},{"label":"D","content":"部分大中型国有企业被政府遴选为“重点企业”,享受税收、信贷优惠"}],"answer":"A","explanation":"题干结论：地方政府会诱导性地干预企业投资决策，国有企业往往成为政府干预和调控经济的手段。<br>A项，直接加强了结论。<br>B项，都是民营企业，不能支持结论。<br>C项，既有民营企业又有国有企业，且没有体现出政府的干预，也不能支持结论。<br>D项，部分国有企业受到政府干预，支持力度不如A","no":242},{"id":"1718789647042","type":"single","material":"","stem":"某景区举办萤火虫展，每天都会吸引大批游客来观赏。数日后，该景区萤火虫的数量急剧下降。景区负责人认为是游客的不文明行为破坏了萤火虫的生存环境。<br>以下哪项如果为真，能够支持景区负责人的观点?","options":[{"label":"A","content":"萤火虫对生存环境的要求很高"},{"label":"B","content":"游客不文明的行为在其他景区也存在"},{"label":"C","content":"自规范游客行为后萤火虫死亡数量急剧下降"},{"label":"D","content":"和萤火虫同类的昆虫数量受游客行为影响不大"}],"answer":"C","explanation":"景区负责人的观点：游客的不文明行为破坏了萤火虫的生存环境，导致萤火虫数量急剧下降。<br>A项，不能说明是否是游客的不文明行为破坏了环境。<br>B项，在其他景区的情况属于无关项。<br>C项，规范了游客行为后萤火虫死亡数量急剧下降，从反面说明了是游客的不文明行为导致萤火虫数量下降，支持了景区负责人的观点。<br>D项，其他昆虫数量也属于无关项。","no":243},{"id":"1718789647043","type":"single","material":"","stem":"一项研究显示，先让受试者参加消除某项偏见的学习，并给受试者播放与消除该偏见学习相关联的声音。之后，让受试者进入深度睡眠状态，同时重复播放那些相关联的声音，以重新激活消除该偏见的学习。结果发现，该偏见比睡眠前大大减少，且睡眠质量越高，偏见减少得越多。研究人员由此推测，睡眠干预可减少社会偏见与歧视。<br>以下哪项如果为真，最能支持上述论证?","options":[{"label":"A","content":"普通民众难以得到消除偏见学习的睡眠干预"},{"label":"B","content":"睡眠充足、睡眠质量高的人比其他人更不易产生偏见与歧视"},{"label":"C","content":"有身高歧视、相貌歧视的人经过睡眠干预后，歧视程度明显降低"},{"label":"D","content":"在接受睡眠干预的受试者中，有一部分人并不存在明显的偏见或歧视"}],"answer":"C","explanation":"题干由实验得出睡眠干预可减少社会偏见与歧视。选项中能够证明睡眠干预可减少社会偏见和歧视的即为正确答案。<br>A项，普通民众能不能得到睡眠干预，属于无关项。<br>B项，本身不容易产生偏见和歧视，属于无关项。<br>C项，通过举例说明有身高、相貌歧视的人在经过睡眠干预后歧视程度明显降低，说明睡眠干预确实可以减少社会歧视，有力地支持了论证。<br>D项，题干说的是偏见减少的量，原有的程度并不影响实验结果，不能支持题干论证。","no":244},{"id":"1718789647044","type":"single","material":"","stem":"如果向大气排放的CO₂累积超过32000亿吨，那么21世纪末，将升温控制在2℃以内的门槛就守不住了。有科学家认为，为了达到将升温幅度控制在2℃以内的目标，仅仅限制CO₂排放是不够的，必须在全球范围内大规模开展大气CO₂的回收行动，使大气污染程度得到有效控制和缓解。<br>若要使上述科学家的想法成立，最需要补充以下哪项作为前提?","options":[{"label":"A","content":"全球范围内普及关于气候变化的科学知识"},{"label":"B","content":"各国政府推出有效政策来控制CO₂排放量"},{"label":"C","content":"科学界整合资源来支持发展地球工程技术"},{"label":"D","content":"各地都建立能有效回收和储存CO₂的机制"}],"answer":"D","explanation":"题干结论：要在全球范围内大规模开展大气CO₂的回收行动，使大气污染程度得到有效控制和缓解。要求补充使该论证成立的前提，可用反证法来确定选<br>项是否为必需的前提。<br>A项，普及气候变化的科学知识与CO₂回收行动无关，不是题干所必须假设的。<br>B项，控制CO₂排放量与CO₂回收行动无关，不是题干所必须假设的。<br>C项，发展地球工程技术也与CO₂回收行动无关，不是题干所必须假设的。<br>D项，如果各地没有回收和储存CO₂的机制，就不能在全球开展CO₂回收行动，所以D项是题干推理成立必需的前提。","no":245},{"id":"1718789647045","type":"single","material":"","stem":"作为抗衰老药物，雷帕霉素延长寿命的秘密在于能够阻断mTOR通道——这也是控制着影响细胞生长繁殖流程的“主开关”之一。当食物充足时，这种通道从激素和营养物质中获得信号使细胞吸收营养并生长，但细胞进行新陈代谢和生长的过程中会产生激发细胞老化的副产物；当限制食物热量的摄入时，这个通道可以发出信号使细胞停止生长，借此来延缓衰老。雷帕霉素可能是目前已发现的最有效可靠的抗衰老药物。<br>以下哪项如果为真，不能支持上述结论?","options":[{"label":"A","content":"由于具有抑制细胞生长的作用，雷帕霉素被用于治疗某些癌症"},{"label":"B","content":"雷帕霉素在延缓衰老的同时，使人更易受到细菌和病毒的侵袭"},{"label":"C","content":"试验研究已经证明雷帕霉素能够延长酵母、蠕虫和果蝇的寿命"},{"label":"D","content":"雷帕霉素可以阻断mTOR通道，而不需要限制食物热量的摄入"}],"answer":"B","explanation":"题干结论：雷帕霉素是目前已发现的最有效可靠的抗衰老药物。<br>A项，说明雷帕霉素能够抑制细胞生长，支持了题干结论。<br>B项，虽然肯定了雷帕霉素延缓衰老的作用，但它会使人受到细菌和病毒的侵袭，说明它并不可靠，反驳了题干结论。<br>C项，说明雷帕霉素能够延长寿命，支持了题干结论。<br>D项，说明雷帕霉素有控制细胞生长的作用，也能支持题干结论。","no":246},{"id":"1718789647046","type":"single","material":"","stem":"正常情况下，人的大脑左前颞叶及眶额皮层会抑制位于大脑后部、负责处理眼部信号的视觉系统的神经活动。而在FTD(额颞叶痴呆)患者中，这两个区域可能无法发出抑制性信号，如此，大脑就是以一种全额的方式来处理视觉和声音。尽管额叶的损伤可能会导致患者出现一些病态的异常行为，但也会将患者的艺术敏感性或其他创造力释放出来。可以说，FTD是通向艺术殿堂的一扇窗。<br>如果以下各项为真，最能质疑上述结论的是：","options":[{"label":"A","content":"只有不到1%的FTD患者在患病期间能成为杰出艺术家"},{"label":"B","content":"20世纪最伟大的100名艺术家里，没有一个是FTD患者"},{"label":"C","content":"冥想或苦练能让右脑更具制造性进而开发出潜在艺术才能"},{"label":"D","content":"FTD患者患病后所获得的艺术才能只能是家庭遗传的结果"}],"answer":"D","explanation":"题干结论：FTD患者会因患病而释放艺术敏感性或其他创造力，可能会因此通向艺术殿堂。要求选择最能质疑该结论的一项，只要能说明FTD患者的艺术行为是其他原因引起的即能质疑。<br>A项，在一定程度上支持了题干结论。<br>B项，不能说明FTD没有作用，不能质疑。<br>C项，冥想或苦练，也与这个疾病无关，不能质疑。<br>D项，指出FTD患者患病后所获得的艺术才能只能是家族遗传的结果，也就意味着家族遗传才是关键，而不在于是否患有FTD,质疑了题干结论。","no":247},{"id":"1718789647047","type":"single","material":"","stem":"当一部小说赢得大奖之后，它在网上书店的口碑却往往会变差。但实际上，大赛评比中其他被提名的小说得分确实不如获奖的小说得分高。据此小李认为大赛评委们选不出真正好的小说。<br>如果以下各项为真，不能削弱小李观点的是：","options":[{"label":"A","content":"大奖提高了读者对获奖小说的期望值"},{"label":"B","content":"一部小说获奖后作者知名度会迅速提升"},{"label":"C","content":"得奖吸引了一些品味跟这本书不搭调的读者"},{"label":"D","content":"喜爱这类小说的读者对获奖小说评价很高"}],"answer":"B","explanation":"题干根据赢得大奖的小说在网上书店的口碑往往会变差，得出“大赛评委们选不出真正好的小说”这一结论。<br>A项，读者的期望值提高解释了口碑变差的原因，削弱了题干结论。<br>B项，作者的知名度与小说的口碑没有直接关系，为无关项。<br>C项，得奖后的小说吸引了不搭调的读者，也解释了口碑变差的原因，反驳了题干结论。<br>D项，喜爱得奖小说这类作品的读者对其评价很高，说明大赛评委们选出的确实是真正好的小说，反驳了题干结论。","no":248},{"id":"1718789647048","type":"single","material":"","stem":"<p>近日，某品牌楼盘开展优惠推广活动，销售情况明显变好，业内人士认为，该品牌楼盘的销量增长，得益于这一优惠推广活动。</p><p>以下哪项如果为真，最能削弱上述论证?</p>","options":[{"label":"A","content":"这一时期其他楼盘的销量均有不同幅度的增长"},{"label":"B","content":"该品牌楼盘开展的这一优惠活动并不比其他品牌的力度大"},{"label":"C","content":"购买该品牌楼盘的人，很少在乎这一优惠活动"},{"label":"D","content":"没有购买该品牌楼盘的人，也没有关注这一优惠活动"}],"answer":"C","explanation":"题干根据某品牌楼盘开展优惠推广活动销售情况变好，得出该楼盘销量增长得益于这一优惠推广活动的结论。要求选择能够削弱这一论证的一项，只要能够说明销量的增长并非由于优惠推广活动即可。A项，其他楼盘的情况为无关项，不能削弱。B项，优惠活动的力度比较为无关项，不能削弱。C项，指出购买该楼盘的人，很少在乎这一优惠活动，说明该品牌楼盘的销量增长并非因为优惠推广活动，削弱了题干结论。D项，没有购买该品牌楼盘的人也为无关项，不能削弱。","no":249},{"id":"1718789647049","type":"single","material":"","stem":"<p>业余的生态生物学家具有纯朴的科学力量：细致地观察了自然世界，他们的观察成果可以为专业生态生物学家所利用。例如东英格兰诺福克郡的马沙姆家族记录家族土地上的动植物生长周期长达211年之久。</p><p>以下哪项如果为真，能够削弱上述观点?</p>","options":[{"label":"A","content":"业余生态生物学家记录方法带来的偏差可通过专业的统计方法消除"},{"label":"B","content":"业余生态生物学家往往关注“叶子何时变黄”这类比较主观的问题"},{"label":"C","content":"观察最重要的是如何细致并系统地进行"},{"label":"D","content":"自然世界的丰富与奥妙需要更多的眼睛去发现"}],"answer":"B","explanation":"题干结论：业余生态生物学家的观察成果可以为专业生态生物学家所利用。要求选择能够削弱该观点的一项，只有说明业余生态生物学家的观察不能为专业生态生物学家利用即可。A项，偏差可以消除，则证明可以被利用，支持了题干结论。B项，指出业余生态生物学家往往关注比较主观的问题，因为主观性比较大，所以其观察成果未必可以为专业生态生物学家所利用，削弱了题干结论。C、D两项，与业余生态生物学家的观察无关，不能支持题干观点。","no":250},{"id":"1718789647050","type":"single","material":"","stem":"<p>某饭店宣布“新开发的排放油烟系统，虽然还未完成为期6个月的试验检验，但是至今并未发生故障，所以公司决定要安装在饭店后厨，毕竟这个系统可以更有效地解决油烟问题”。该饭店的主厨说：“我们不能使用未完成试验的排放油烟系统，6个月以后再说吧。\"</p><p>以下哪项最能支持主厨的反对意见?</p>","options":[{"label":"A","content":"能更有效地处理油烟的新系统也可能存在新问题"},{"label":"B","content":"尽管新的排放油烟系统比以前的难操作，但有一些新功能"},{"label":"C","content":"新的排放油烟系统保修期更长，维修方便"},{"label":"D","content":"许多安全事故都是排放油烟系统造成的"}],"answer":"A","explanation":"主厨的观点：即使排放油烟系统可以有效解决油烟问题，但也要等到6个月的试验检验完毕再安装。要支持该观点，可以说明不能使用未完成试验的排放油烟系统的原因。A项，指出新系统虽然油烟处理没有问题，但可能会出现其他问题，所以还得等到6个月的试验期完毕再安装，支持了主厨的观点。B项，并未说明现在不能安装这一新系统的原因，无法支持主厨的观点，排除。C项，说的是这一新系统的优点，无法说明现在不能安装新系统的原因，不能支持主厨的观点，排除。D项，题干论述的是目前不能使用新系统而要等到6个月的试验检验完成后再做决定的原因，针对的是这一新系统的情况，该项所述并不能说明这一新系统也会出现安全事故，无法支持主厨的观点，排除。","no":251},{"id":"1718789647051","type":"single","material":"","stem":"面对家长们对于某小学装修已两月的教室存在甲醛超标的质疑，该小学校长回应道：“所有的教室我都逐一去过，没有闻到异味，所以，甲醛不超标。”<br>以下哪项如果为真，最能反驳该小学校长的论证?","options":[{"label":"A","content":"不同的人对于味道的感受不同，校长闻起来无异味并不代表事实上无异味"},{"label":"B","content":"某新房装修完工三个多月后，经正规检测，甲醛依然超标"},{"label":"C","content":"即使装修后无异味的房间，在装修后几个月内通常都会有甲醛超标的可能"},{"label":"D","content":"甲醛是一种无色无味的气体，不能通过房间的味道来判断是否甲醛超标"}],"answer":"D","explanation":"该小学校长的论证是由“没有闻到异味”推出“甲醛不超标”,要反驳这一结论，可以切断两者之间的联系。<br>A项，说明校长闻起来无异味不代表真的无异味，并没有明确说明教室中的甲醛到<br>底超不超标，无法反驳校长的论证，排除。<br>B项，列举了某新房装修后的情况，但不代表教室中的甲醛一定超标了，无法反驳校长的论证，排除。<br>C项，只是说存在甲醛超标的可能性，但并未明确指出教室中就一定存在甲醛超标，削弱的力度较弱。<br>D项，指出甲醛是无色无味的，不能通过是否有异味来判断甲醛是否超标，直接否定了校长的判断依据，有力地反驳了校长的论证。","no":252},{"id":"1718789647052","type":"single","material":"","stem":"张女士特别爱美，多年来喜欢在冬天穿裙子以显示她婀娜多姿的身材。从去年冬天起，每到阴冷天，她都感觉到膝关节疼痛。后经医生诊断，她得了关节炎。于是张女士认为，阴冷天穿得少是导致关节炎的原因。<br>以下哪项如果为真，最能质疑张女士的观点?","options":[{"label":"A","content":"日本一些年轻女士喜欢冬天穿裙子，却并没有因为阴冷天穿得少而患上关节炎"},{"label":"B","content":"现代医学研究表明导致关节炎的根本原因是劳损、感染或创伤，阴冷天穿得少关节炎易发作"},{"label":"C","content":"张女士的姐姐和她生活在一个城市，多年来也喜欢在冬天穿裙子，但没得关节炎"},{"label":"D","content":"阴冷天穿得多的人群中也有很多得了关节炎，而且以中老年人居多"}],"answer":"B","explanation":"张女士的观点：阴冷天穿得少是导致关节炎的原因。要质疑该观点，可以切断喜欢冬天穿裙子以及得了关节炎之间的联系。<br>A项，指出日本一些年轻女士阴冷天穿得少但并没有患上关节炎，但这只是个别情况，不具有代表性，属于特殊反例，质疑的力度较弱，排除。<br>B项，说明了得关节炎的根本原因是劳损、感染或创伤，并非阴冷天穿得少导致的，即阴冷天只是一个表象，实际上另有他因，有力地质疑了题干观点。<br>C项，指出张女士的姐姐阴冷天穿得少但并没有患上关节炎，但这只是个别情况，不具有代表性，属于特殊反例，质疑的力度较弱，排除。<br>D项，说的是阴冷天穿得多的人的情况，并不能说明阴冷天穿得少是否会导致关节炎，无法质疑题干观点，排除。","no":253},{"id":"1718789647053","type":"single","material":"","stem":"茶叶是中国人喜爱的健康饮品。一般人将茶叶冲泡饮用几次之后，就将喝剩的茶叶倒掉。某专家对此指出，其实茶叶中能够溶解于水的物质是有限的，大量有营养的物质仍然保留在茶叶中，白白倒掉实在可惜，人们应该将喝剩的茶叶吃掉。<br>以下哪项如果为真，最能反驳该专家的观点?","options":[{"label":"A","content":"茶叶中许多没有营养的物质也不能溶于水"},{"label":"B","content":"茶叶中含有茶叶碱和微量元素，可以提神醒脑"},{"label":"C","content":"茶叶中多数农药残留和重金属吃下去会被人体吸收"},{"label":"D","content":"很多人将喝剩的茶叶留下来做茶饼、茶叶蛋等"}],"answer":"C","explanation":"题干的观点：为避免营养物质被浪费，人们应将喝剩的茶叶吃掉。要反驳该观点，可以通过直接反驳、另有他因、补充反向论据等方法。<br>A项，指出茶叶中没有营养的物质也不能溶于水，为无关项，无法反驳该专家的观点，排除。<br>B项，指出茶叶中的物质可以提神醒脑，说明吃掉茶叶有一定的好处，支持了该专家的观点，排除。<br>C项，指出获得营养的同时，茶叶中的有害物质也会被人体吸收，危害身体健康，有力地反驳了题干观点。<br>D项，指出很多人用喝剩的茶叶做茶饼、茶叶蛋等，为无关项，无法反驳该专家的观点，排除。","no":254},{"id":"1718789647054","type":"single","material":"","stem":"某专家对已故诺贝尔经济学奖得主的寿命进行统计，发现他们的平均寿命是85岁，其中超过90岁的占多数，还有不少过百岁的，去世时年龄最小的也高达74岁。该专家由此认为，获得诺贝尔经济学奖能使人长寿。<br>以下哪项如果为真，最能削弱上述专家的观点?","options":[{"label":"A","content":"诺贝尔经济学奖只颁给在世的学者，这一颁奖规则对已经长寿的学者极为有利"},{"label":"B","content":"获得诺贝尔经济学奖能带来功成名就的巨大身心愉悦，而愉悦的身心状态可延年益寿"},{"label":"C","content":"宏观经济学之父凯恩斯年仅63岁就去世了，很遗憾他没有获得诺贝尔经济学奖"},{"label":"D","content":"获得诺贝尔物理学奖的学者寿命也很长，但他们都没有获得过诺贝尔经济学奖"}],"answer":"A","explanation":"题干中专家的观点：获得诺贝尔经济学奖能使人长寿。要削弱该观点，可以通过直接削弱、因果倒置、另有他因等方法。<br>A项，说明是诺贝尔经济学奖的颁奖规则对长寿的学者有利，即长寿才有可能获得诺贝尔经济学奖，而不是诺贝尔经济学奖能使人长寿，属于因果倒置，削弱了专家的观点。<br>B项，解释了获得诺贝尔经济学奖为何能使人延年益寿，支持了专家的观点，排除。<br>C项，凯恩斯年仅63岁就去世了且没有获得诺贝尔经济学奖，无法说明获得诺贝尔经济学奖与长寿之间是否存在因果联系，不能削弱专家的观点，排除。<br>D项，说的是获得诺贝尔物理学奖的学者的情况，无法说明获得诺贝尔经济学奖与长寿之间是否存在因果联系，不能削弱专家的观点，排除。","no":255},{"id":"1718789647055","type":"single","material":"","stem":"有研究人员指出：“有些职业，比如写作、音乐创作、设计、策划、广告文案等，其从业人员的创意灵感往往出现在深夜。”<br>以下哪项如果为真，不能对该研究人员的观点提供支持?","options":[{"label":"A","content":"历史上那些最具创意头脑的人；有很多是“夜猫子”。比如席勒、福楼拜、普鲁斯特等人几乎一辈子都在深夜工作"},{"label":"B","content":"夜深人静时，忙碌紧张了一天的人们放松下来，大脑更能天马行空地发挥想象力，于是创意喷涌而出"},{"label":"C","content":"有研究者记录了150多位大作家和大艺术家的生活作息，其中按正常时间作息的占了大多数，只有26位是“夜猫子”"},{"label":"D","content":"音乐家对灵感的依赖非常强烈，一项针对美国音乐行业从业者的调查显示，“夜猫子”的比例达到90%以上"}],"answer":"C","explanation":"题干观点：有些职业，比如写作、音乐创作、设计、策划、广告文案等，其从业人员的创意灵感往往出现在深夜。<br>A项，指出历史上最具创意头脑的人几乎一辈子在深夜工作，说明深夜有利于他们的创意灵感出现，支持了题干观点。<br>B项，夜深人静，大脑更能天马行空地发挥想象力，创意喷涌而出，说明深夜有利于创意灵感出现，支持了题干观点。<br>C项，在150名大作家和大艺术家中，仅有26人是深夜工作，大部分都是按正常作息工作，说明大多数大作家和大艺术家的创意灵感不是出现在深夜，反驳了题干观点。<br>D项，90%的音乐家深夜工作，说明深夜有利于创意灵感出现，支持了题干观点。","no":256},{"id":"1718789647056","type":"single","material":"","stem":"开车是一项有风险的交通行为，驾驶员行车时的心理、生理和行为特性对驾驶安全影响很大，往往决定着潜在事故是否可能发生。研究认为，女驾驶员对复杂交通环境的辨别能力低，且在应激环境下反应不如男性积极，对突发事件不能应付。此外，男女驾驶员还有显著的身体条件方面的差异，视野、体力、空间能力等方面，男女间的平均差距都相当明显。由此，有人提出，相比男司机，女司机确实更有“马路杀手”的一面，即更容易造成严重的交通事故。<br>以下各项如果为真，哪项不能驳斥上述观点?","options":[{"label":"A","content":"女司机造成重大事故的概率远低于男司机，女司机肇事事故中死亡人数约为男司机的1/50"},{"label":"B","content":"相比男司机，女司机拥有更为良好的驾驶习惯，也更加注重不要超速，有利于行车安全"},{"label":"C","content":"领取驾驶证的女司机数量虽多，但真正开车的人并不多，以北京为例，男女司机的比例为7:3"},{"label":"D","content":"平均来说，同样里程的驾驶，男司机负全责的交通事故的发生率要远高于女司机"}],"answer":"C","explanation":"题干论据：研究认为，女驾驶员对复杂交通环境的辨别能力低，且在应激环境下反应不如男性积极，对突发事件不能应付。此外，男女驾驶员还有显著的身体条件方面的差异，视野、体力、空间能力等方面，男女间的平均差距都相当明显。题干论点：相比男司机，女司机确实更有“马路杀手”的一面，即更容易造成严重的交通事故。<br>A项，女司机造成重大事故的概率远低于男司机，女司机肇事事故中死亡人数约为男司机的1/50,说明了男司机比女司机更容易造成严重的交通事故，反驳了题干论点。<br>B项，女司机拥有更为良好的驾驶习惯，也更加注重不要超速，有利于行车安全，说明了女司机驾驶更安全，反驳了题干论点。<br>C项，男女司机的比例与题干论述无关，无法反驳题干论点。<br>D项，同样里程的驾驶，男司机负全责的交通事故的发生率要远高于女司机，也反驳了题干观点。","no":257},{"id":"1718789647057","type":"single","material":"","stem":"马兰：因为赵老师的课讲得特别好，学生都很喜欢他，所以他有资格参加学校十佳教师评选。<br>李溪：因为赵老师曾上课迟到造成教学事故，他不是合格的教师。所以，他没有资格参加学校十佳教师评选。<br>李溪的论证使用了以下哪项作为前提?<br>I.有些课讲得好的老师发生过教学事故<br>Ⅱ.凡有过教学事故的教师都不是合格教师<br>Ⅲ.只有合格教师才有参评学校十佳教师的资格","options":[{"label":"A","content":"仅I"},{"label":"B","content":"仅Ⅱ"},{"label":"C","content":"仅Ⅲ"},{"label":"D","content":"Ⅱ和Ⅲ"}],"answer":"D","explanation":"李溪的论证包含两个推理：①造成教学事故→不是合格教师；②不是合格教师→没有资格参加学校十佳教师评选。<br>I,李溪的论证中没有提及“课讲得好”的话题，为无关项，不是李溪的论证成立的前提。<br>Ⅱ,指出有教学事故的老师都不是合格的老师，在教学事故和不合格教师之间建立了联系，是推理①成立的前提。<br>Ⅲ,说明不合格的老师就没有资格参加学校十佳教师评选，在不合格教师和没有评选资格之间建立了联系，是推理②成立的前提。<br>要证明李溪论证成立，需要证明其论证中的两个推理均成立，即Ⅱ是推理①的前提、Ⅲ是推理②的前提，Ⅱ、Ⅲ均是论证成立的必要前提。","no":258},{"id":"1718789647058","type":"single","material":"","stem":"秋冬时节感冒多发，预防感冒的小技巧很受关注。网上一直流传：放置一颗洋葱在房间里，可以预防感冒，因为洋葱挥发出的含硫化合物有抑菌抗癌的作用，可净化室内空气。因此，在室内放几个切去两端的洋葱，就可以有效预防感冒。<br>以下各项如果为真，哪项最能驳斥以上观点?","options":[{"label":"A","content":"洋葱所含硫化物对肠道的细菌有一定抑制作用，但需要每天口服一定的量"},{"label":"B","content":"人类所患感冒中70%～80%的感冒是由病毒引起的，洋葱对病毒是没有抑制作用的"},{"label":"C","content":"实验证明，室内放置洋葱1小时后，室内细菌总数没有显著减少"},{"label":"D","content":"现有研究尚未发现食物可以有效吸附病菌和病毒"}],"answer":"B","explanation":"题干论点：室内放洋葱可以有效预防感冒。题干论据：洋葱挥发出的含硫化合物有抑菌抗癌的作用，可净化室内空气。<br>A项，指出洋葱可以抑制肠道细菌，与题干论点“洋葱可以预防感冒”无关，排除。<br>B项，指出大部分感冒是由病毒引起的，而洋葱无法抑制病毒，因此洋葱不能有效预防感冒，有力地反驳了题干观点。<br>C项，指出放置洋葱1小时后室内细菌总数未显著减少，说明细菌仍有减少，只是减少的不明显，在一定程度上加强了题干观点，排除。<br>D项，表明现有研究未发现食物能有效吸附病菌和病毒，未说明洋葱能否抑制感冒，无法削弱题干观点，排除。","no":259},{"id":"1718789647059","type":"single","material":"","stem":"宣称植物有意识、有感情的人，通常会引用美国人巴克斯特的实验。巴克斯特将一台测谎仪连在一盆植物的叶子上。这台测谎仪的设计原理是人在撒谎时，由于紧张，皮肤会出汗，导致皮肤电阻降低，通过测定皮肤电阻的变化可辨别人的情绪，进而判断人是否在撒谎。巴克斯特报告说，实验中当主试想到“我要烧掉那片叶子”时，测谎仪反应剧烈，指针猛然摆到了仪表的顶端并显示出连续的激烈波动，测谎仪绘制出类似于人在极度恐惧时会出现的图形。巴克斯特由此宣称：植物是有感情的。<br>以下哪项如果为真，最能驳斥以上观点?","options":[{"label":"A","content":"即使是巴克斯特也不能稳定地重复该实验，而巴克斯特对实验成功与失败的解释难以令人信服"},{"label":"B","content":"具有中枢神经系统的生物才有意识、有感情，植物没有任何神经系统"},{"label":"C","content":"巴克斯特所记录的测谎器曲线，可能是其他因素引起的，包括静电作用、房间里的机械振动、湿度的变化等"},{"label":"D","content":"巴克斯特的实验设计不够科学，没有对照组，也不符合客观、双盲等科学实验的必要条件"}],"answer":"B","explanation":"题干论点：植物是有感情的。题干论据：实验中当主试想到“我要烧掉那片叶子”时，测谎仪反应剧烈，指针猛然摆到了仪表的顶端并显示出连续的激烈波动，测谎仪绘制出类似于人在极度恐惧时会出现的图形。<br>A项，巴克斯特的实验具有不稳定性，说明该实验是不科学的，否定了题干论据，反驳了题干论点。<br>B项，因为具有中枢神经系统才有意识和感情，植物不具有中枢神经系统，所以植物没有意识和感情，直接反驳了巴克斯特的观点。<br>C项，举出其他因素的干扰原因，说明实验的数据可能存在错误，反驳了题干结论。<br>D项，巴克斯特的实验设计不科学，说明该项实验不科学，得出的结论并不可信。也反驳了题干结论。<br>A、C、D三项都是反驳了题干论据，说明实验不科学，B项直接反驳了题干论点，力度强于A、C、D","no":260},{"id":"1718789647060","type":"single","material":"","stem":"扶贫必扶智，让贫困地区的孩子们接受更好的教育是扶贫开发的重要任务，也是阻断贫困代际传递的重要途径。<br>以下哪项是上述论证的假设?","options":[{"label":"A","content":"贫困代际传递导致教育落后"},{"label":"B","content":"富有家庭大都接受良好教育"},{"label":"C","content":"扶贫工作难，扶智工作更难"},{"label":"D","content":"知识改变命运，教育成就财富"}],"answer":"D","explanation":"题干论据是让贫困地区的孩子们接受更好的教育是扶贫开发的重要任务，也是阻断贫困代际传递的重要途径。观点是扶贫必须扶智。要使观点成立就必须在二者之间建立联系。<br>A项，贫困代际传递导致教育落后，说明的是贫困代际传递的不良后果，没有涉及“扶贫”和“扶智”之间的联系，不能支持题干。<br>B项，富有家庭大都接受良好教育，说明的是在富有的基础上能接受良好的教育，不能说明是否是因为教育而富有，不能支持题干。<br>C项，扶贫工作难，扶智工作更难，仅是说明了扶贫工作和扶智工作的难度，不涉及二者之间的联系，不能支持题干。<br>D项，知识改变命运，教育成就财富，说明“智”可以改变贫困的现状。如果知识不能改变命运，教育不能成就财富，那么题干论述就不能成立，所以D项是题干论证成立的假设。","no":261},{"id":"1718789647061","type":"single","material":"","stem":"宇宙加速膨胀是因为物质之间相互排斥，减速膨胀是因为物质之间相互吸引。因此，要在此基础上解释宇宙的加速或减速膨胀，必须要有不同特性的物质在不同的时期占主导地位，从而产生强大的排斥力或吸引力。粒子物理标准模型中的所有粒子都产生吸引性引力，然而星系转动曲线的研究表明，在星系里面还有大量的、看不到的物质，这些物质可以产生非常强大的吸引性引力。<br>以上论证如果为真，那么星系转动曲线研究结论隐含了下列哪一项前提?","options":[{"label":"A","content":"粒子物理标准模型中的所有粒子产生的吸引性引力不足"},{"label":"B","content":"粒子物理标准模型中的粒子不是唯一的，存在其他粒子"},{"label":"C","content":"星系转动曲线的研究说明这个时期的宇宙正在加速膨胀"},{"label":"D","content":"星系转动曲线的研究说明存在超大质量、看不到的黑洞"}],"answer":"A","explanation":"题干根据星系转动曲线的研究得出结论：除了粒子物理标准模型中的粒子之外，在星系里面还有大量的、看不到的物质可以产生强大的吸引性引力。<br>A项是星系转动曲线研究结论所隐含的假设前提，意思是目前呈现出的星系转动曲线需要非常强大的吸引性引力，而粒子物理标准模型中的所有粒子都产生吸引性引力，只有当其所产生的吸引性引力不足时，才可以推出还存在别的物质，其吸引性引力很强大这一结论，因此该项是题干结论成立的必要条件。<br>B项，“存在其他粒子”并不是题干结论所隐含的前提，因为题干的结论表明肯定是有一些物质存在的，排除。<br>C项，题干已经说明物质之间是相互吸引的，宇宙应该减速膨胀，而非加速膨胀，排除。<br>D项，“黑洞”在题干中并未提及，无法说明星系里面是否存在能产生非常强大的吸引性引力的物质，该项为无关项，排除。","no":262},{"id":"1718789647062","type":"single","material":"","stem":"第二次世界大战之后的三十年，营养科学家的普遍共识是缺食性营养不良主要是由食品中的蛋白质缺乏造成的。提高食品中蛋白质含量曾是联合国粮农机构的重要事务。但近年有科学家研究认为，食品中的蛋白质缺乏是营养科学家的错误认识。<br>以下哪项如果为真，不能支持该科学家的观点?","options":[{"label":"A","content":"营养科学家对人类蛋白质需求的估计过于依赖动物研究，而动物研究会夸大人类对蛋白质的需求"},{"label":"B","content":"山药和木薯这样的低蛋白质农作物也能够满足人类对蛋白质的基本需求"},{"label":"C","content":"近年来，科学家培育高蛋白质谷物取得可喜成果，小麦蛋白质含量显著增加"},{"label":"D","content":"有些贫困地区的营养不良是由食物缺乏导致的，而不是由食物成分中蛋白质含量低造成的"}],"answer":"C","explanation":"题干结论：食品中的蛋白质缺乏导致缺食性营养不良是营养科学家的错误认识。<br>A项，说明营养科学家夸大了人类对蛋白质的需求，其结论可能是错的，能够支持科学家的结论。<br>B项，说明即使是低蛋白质农作物也能满足人类对蛋白质的基本需求，因此缺食性营养不良未必是食品中的蛋白质缺乏造成的，支持了科学家的结论。<br>C项，“小麦蛋白质含量显著增加”与题干要论述的缺食性营养不良究竟是不是由食品中的蛋白质缺乏造成的无关，不能支持科学家的观点。<br>D项，直接指出营养不良是食物缺乏导致的，而非食物中缺乏蛋白质，支持了科学家的观点。","no":263},{"id":"1718789647063","type":"single","material":"","stem":"随着新媒体技术的发展，患者在网上寻找医生信息的情况日益增多。为此，科研人员对美国28个典型医生评价商业网站展开研究。研究报告称，近60%的人在接受调查访问时表示，在选择医生时，网上评价对他们的选择非常重要。但对这28个网站的研究显示，允许用户根据“临床状况、医生性别、所说语言、所接受的保险”等条件进行搜寻的网站很少。研究人员得出结论说，对这些商业性医生评价网站而言，要找到相对准确的医生定量评价颇为困难。<br>以下各项如果为真，最能支持上述论证的是：","options":[{"label":"A","content":"病人通过医生评价网站能清楚地了解某位医生的治疗经验"},{"label":"B","content":"美国医生评价网站存在搜索机制烦冗且评价稀缺等问题"},{"label":"C","content":"通过调查，系统收集数据，才更有可能积累足够的评价"},{"label":"D","content":"调查发现有三分之一的抽样医生在所有网站都没有评价"}],"answer":"B","explanation":"题干根据“这28个网站中允许用户依据条件进行搜索的网站很少”,得出“对这些商业性医生评价网站而言，要找到相对准确的医生定量评价颇为困难”的结论。<br>A项，通过网站能了解某位医生的治疗经验，不能说明要找到相对准确的医生定量评价是否困难，该项为无关项，排除。<br>B项，指出了美国医生评价网站存在的问题，说明要找到相对准确的医生定量评价确实颇为困难，直接支持了题干观点。<br>C项，怎样“积累足够的评价”与找到相对准确的医生定量评价是否困难无关，排除。<br>D项，指出“有三分之一的抽样医生在所有网站都没有评价”,但抽样医生占总数的比例是多少无从得知，样本未必有代表性，且该项与题干中要论述的找到相对准确的医生定量评价是否困难无关，排除。","no":264},{"id":"1718789647064","type":"single","material":"","stem":"<p>1880—2012年，全球气温上升0.85℃。而气温每上升1℃,粮食产量就下降约5%。1981--2002年，由于气候变暖，全球玉米、小麦等作物产量均每年大幅下降4000万吨。因此，为了遏制全球变暖，保证全球的粮食安全，我们必须从自身做起，节能减排，控制碳排放总量。</p><p>以下各项如果为真，不属于以上结论必要前提的是：</p>","options":[{"label":"A","content":"玉米、小麦等作物的产量下降威胁着全球的粮食安全"},{"label":"B","content":"节能减排，控制碳排放总量对遏制全球变暖有积极影响"},{"label":"C","content":"除玉米、小麦等外的其他粮食作物没有因全球变暖而增产"},{"label":"D","content":"人类活动造成的碳排放量增多是全球日益变暖的原因之一"}],"answer":"C","explanation":"题干根据气候变暖导致玉米、小麦等作物产量下降，得出“为了遏制全球变暖，保证全球的粮食安全，我们必须从自身做起，节能减排，控制碳排放总量”的结论。A项，在论据和论点之间建立了联系，且如果玉米、小麦等作物的产量下降不会威胁全球的粮食安全，则由论据将无法得出题干结论，因此该项是题干论证成立的必要前提。B项，如果节能减排、控制碳排放总量无法遏制全球变暖的话，则题干结论中为了遏制全球变暖所做出的努力将达不到效果，题干结论将无法成立，因此该项是题干论证成立的必要前提。C项，即使其他粮食作物没有增产，但玉米、小麦等作物产量的下降也未必会威胁全球的粮食安全，题干结论不能必然得出，因此该项不是题干论证成立的必要前提。D项，如果人类活动造成的碳排放量增多不是全球变暖的原因之一，那么节能减排、控制碳排放总量就无法遏制全球变暖，题干结论将无法成立，因此该项是题干论证成立的必要前提。","no":265},{"id":"1718789647065","type":"single","material":"","stem":"水熊虫是一种小型水生动物，又称缓步动物。水熊虫是地球上已知生命力最强的生物，它可以在没有防护措施的条件下在极端压力环境中生存。缓步动物的奇特能力促使研究人员对其基因组展开调查。目前，对缓步动物的第一次基因组测序结果显示，在缓步动物演化过程中，通过水平基因转移(不同物种基因组之间的DNA转移),从其他物种中获得了大量基因。<br>以下各项如果为真，最能质疑上述观点的是：","options":[{"label":"A","content":"基因检测发现水熊虫体内有一种基因，其蛋白质能够抵抗人类培养细胞内的DNA损伤"},{"label":"B","content":"水熊虫可以在太空真空环境中长时间生存，在冰冻30多年之后也能成功复苏"},{"label":"C","content":"水熊虫从祖先那里继承所有基因，体内遗传物质中没有发现来自植物或者微生物的"},{"label":"D","content":"水熊虫体内遗传物质存在一种非常奇怪的“混搭”法，正是这种“混搭”才使水熊虫以更复杂的方式生长和发育"}],"answer":"C","explanation":"题干观点：在缓步动物演化过程中，通过水平基因转移，从其他物种中获得了大量基因。<br>A项，指出“水熊虫体内有一种基因，其蛋白质能够抵抗人类培养细胞内的DNA损伤”,但与水熊虫是否从其他物种中获得了大量基因无关，无法质疑题干观点，排除。<br>B项，指出了水熊虫的特性，但与水熊虫是否从其他物种中获得了大量基因无关，无法质疑题干观点，排除。<br>C项，直接指出水熊虫体内没有来自其他物种的遗传物质，说明其没有从其他物种中获得大量基因，质疑了题干观点。<br>D项，只是提到水熊虫体内基因可以“混搭”,并未提到其体内是否有来自其他物种的基因，不能质疑题干结论，排除。","no":266},{"id":"1718789647066","type":"single","material":"","stem":"高栓患有假性近视。为了使其视力恢复到正常状态，李大夫要求高栓停止打网络游戏。<br>为使李大夫的要求具有说服力，必须假设以下哪项?","options":[{"label":"A","content":"假性近视患者打网络游戏，将严重影响其视力恢复到正常状态"},{"label":"B","content":"打网络游戏是引起假性近视的主要原因"},{"label":"C","content":"李大夫经验丰富，他治愈了90%以上前来就诊的假性近视患者"},{"label":"D","content":"假性近视如果不及时缓解将导致真性近视"}],"answer":"A","explanation":"题干论据为高栓患有假性近视，为了使视力恢复正常状态，结论为李大夫要求高栓停止打网络游戏，“假性近视恢复到正常状态”和“打网络游戏”明显缺少联系。<br>A项，指出打网络游戏会影响视力恢复到正常状态，在“假性近视恢复到正常状态”和“打网络游戏”之间建立了联系，是题干论证必需的前提。<br>B项，打网络游戏是引起假性近视的主要原因，但并不意味着不打网络游戏就可以使视力恢复到正常状态<br>C项，李大夫治愈了90%以上前来就诊的假性近视患者，但没有在论据与结论之间建立联系。<br>D项，假性近视不及时缓解将导致真性近视，但没有在论据与结论之间建立联系。","no":267},{"id":"1718789647067","type":"single","material":"","stem":"酒类广告常会告诉人们，少喝一点酒没事，控制好饮酒量可能还对心脏有好处。<br>以下哪项如果为真，最能削弱上述结论?","options":[{"label":"A","content":"每个人的最佳饮酒量不同，要依据个人年龄、性别和叶酸摄入量等因素决定"},{"label":"B","content":"对于那些高密度脂蛋白低、有健康的饮食和大量运动的人来说，饮酒可能有益"},{"label":"C","content":"调查显示80%的酒类广告都承认过度美化和夸大饮酒的益处"},{"label":"D","content":"红葡萄酒中白藜芦醇和抗氧化剂等有益成分的含量有限"}],"answer":"C","explanation":"题干结论为少喝一点酒没事，控制好饮酒量可能对心脏有好处。<br>A项，每个人的最佳饮酒量不同，要依据个人年龄、性别等因素决定，不能削弱题干结论，为无关项。<br>B项，对于一些人来说，饮酒可能有益，加强了题干结论。<br>C项，指出大部分酒类广告过度美化和夸大饮酒的益处，直接指出题干酒类广告不靠谱，削弱了题干结论。<br>D项，红葡萄酒中白藜芦醇和抗氧化剂等有益成分的含量有限，说明喝红葡萄酒可能对身体有益，加强了题干结论。","no":268},{"id":"1718789647068","type":"single","material":"","stem":"共享单车作为一种新鲜事物，近来发展迅速。在城市的大街小巷，几乎到处可见共享单车的影子。共享单车构成城市一道新的亮丽风景线，也为人们的出行提供了方便。但是，有一些市民对整个自行车生产行业表示担忧，他们认为：共享单车的出现和大量投入使用，使得很多计划购买自行车的个人不再购买。因此，整个自行车行业的生产和销售量随之减少。<br>以下哪项如果为真，最能削弱这些市民的结论?","options":[{"label":"A","content":"不同品牌的自行车生产商将面临更激烈的市场竞争，有些厂家与共享单车运营公司合作，会生产和销售更多的自行车"},{"label":"B","content":"共享单车也存在很多的问题，比如，存在安全隐患，在有需求时不能及时找到，有一些民众仍愿意购买专属自己的自行车"},{"label":"C","content":"共享单车由共享单车所属公司委托自行车生产商生产，共享单车的数量远远超过了因个人需求而产生的购买量"},{"label":"D","content":"共享单车的使用需要网上申请账号，使用时需要进行微信扫码，很多中年人不会上网，因此他们更愿意自己购买自行车"}],"answer":"C","explanation":"题干论据：共享单车的出现和大量投入使用，使得很多计划购买自行车的个人不再购买。结论：整个自行车行业的生产和销售量会减少。<br>A项，有些厂家会生产和销售更多的自行车，不能代表整个自行车行业会增加生产和销售量，削弱力度较弱，待定。<br>B项，有一些市民仍愿意购买专属自己的自行车，也不能代表整个市民都仍愿意购买自行车，削弱力度有限，待定。<br>C项，指出“共享单车委托自行车生产商生产，单车数量远超个人需求”,即相比个人购买自行车，自行车生产厂商生产的共享单车数量更多，则生产的数量不仅没有减少，反而更多，有力地反驳了题干中市民的结论，削弱力度较强。<br>D项，中年人更愿意自己购买自行车，只是部分现象，对题干削弱力度较弱，待定。综合比较，C项最能削弱题干结论。","no":269},{"id":"1718789647069","type":"single","material":"","stem":"土卫二是土星的一颗被包裹在厚厚冰层中、含有海洋的小型卫星。近日，“卡西尼”号无人探测器探测到从土卫二表面的裂缝中喷出的汽柱中存在氢分子。科学家据此推断，在土卫二的岩石核心与位于其冰壳之下的海洋之间，很可能正在发生热液化学反应，这意味着土卫二几乎具备了孕育生命所必需的条件，未来人类可以对土卫二展开探索以寻找生命迹象。<br>以下哪项如果为真，最能质疑上述论证?","options":[{"label":"A","content":"“卡西尼”号探测器绕土星飞行了13年，未曾发现土卫二上存在生命"},{"label":"B","content":"在土卫二尚未发现生命所需的硫和磷"},{"label":"C","content":"地球上，海底热泉中的氢可以充当微生物的食物以及复杂生态系统的基础"},{"label":"D","content":"此前通过哈勃望远镜获得了木星卫星不存在生命迹象的证据"}],"answer":"B","explanation":"题干结论：未来人类可以对土卫二展开探索以寻找生命迹象。<br>A项，说的是之前未发现，并不代表以后也不会发现，无法质疑题干论证，排除。<br>B项，指出在土卫二尚未发现生命所需的硫和磷，说明土卫二无法孕育生命，削弱了题干结论。<br>C项，指出氢对微生物以及生态系统的作用，在一定程度上说明土卫二能够孕育生命，支持了题干结论，排除。<br>D项，说的是木星卫星的情况，与土卫二是否能够孕育生命无关，排除。","no":270},{"id":"1718789647070","type":"single","material":"","stem":"甲：“吃鱼可以使人聪明。”<br>乙：“对，我从小就不爱吃鱼，所以我就笨。”<br>为了使乙的论证成立，必须补充以下哪项作为前提?","options":[{"label":"A","content":"不爱吃鱼的人一定都笨"},{"label":"B","content":"聪明的人一定都爱吃鱼"},{"label":"C","content":"笨的人一定都不爱吃鱼"},{"label":"D","content":"爱吃鱼的人一定都聪明"}],"answer":"A","explanation":"题干中甲的观点：吃鱼→聪明。乙的观点：不爱吃鱼→笨。乙是否定甲的前件推出否定后件的错误推理。要使乙的论证成立，只需找到与乙的推理一致的一项即可。<br>A项的推理关系：不爱吃鱼→笨。与题干中乙的推理关系一致，是乙的论证成立所需的前提。<br>B项的推理关系：聪明→爱吃鱼。将该项进行逆否推理可得“不爱吃鱼→不聪明”,但不聪明不代表笨，与乙的观点略有不同，因此该项不是乙的论证成立所需的前提。<br>C项的推理关系：笨→不爱吃鱼。与题干中乙的推理关系不一致，排除。<br>D项的推理关系：爱吃鱼→聪明。与题干中乙的推理关系不一致，排除。","no":271},{"id":"1718789647071","type":"single","material":"","stem":"数十年来，在恐龙研究中存在这样一个观点：某些恐龙可以根据其骨骼差异来分辨性别。比如，雄性安氏原角龙与雌性的区别在于，雄性具有更宽的头盾，鼻子上的突起也更大。<br>以下哪项如果为真，最能支持上述观点?","options":[{"label":"A","content":"研究者重新分析恐龙化石原始数据，利用混合模型等统计方法进行检验，结果发现恐龙并不存在两性骨骼差异"},{"label":"B","content":"鸟类和鳄鱼是最接近恐龙的现存动物，雄性鳄鱼比雌性大得多，而鸟类的两性骨骼差异更加明显，如雄孔雀长着巨大的艳丽尾羽，而雌孔雀则朴实无华"},{"label":"C","content":"目前，有关恐龙的数据样本十分零散，某些恐龙物种的化石也没有获得足够的数量"},{"label":"D","content":"髓质骨富含钙质，能为蛋壳的生成贮存原料，仅存在于产卵雌性恐龙的长骨中"}],"answer":"D","explanation":"题干结论：某些恐龙可以根据其骨骼差异来分辨性别。<br>A项，直接说明恐龙并不存在两性骨骼差异，说明无法根据恐龙的骨骼差异来分辨性别，削弱了题干观点，排除。<br>B项，用接近恐龙的动物无法说明恐龙的真实情况，不能支持题干观点，排除。<br>C项，指出恐龙的数据样本零散，没有足够数量的化石，则据此得出的结论也许并不可靠，对题干结论有一定的削弱作用，排除。<br>D项，指出髓质骨仅存在于产卵雌性恐龙的长骨中，说明恐龙确实可以根据骨骼差<br>异来分辨性别，支持了题干观点。","no":272},{"id":"1718789647072","type":"single","material":"","stem":"随着年龄的增长，人们对物质的需求逐渐减少，而对精神的需求逐渐增多。因此，为了满足日益增长的精神需求，老年人应当比年轻时更积极地参加文体活动。<br>以下哪项如果为真，最能支持上述结论?","options":[{"label":"A","content":"随着社会的进步，老年人比年轻人有更多的精神需求"},{"label":"B","content":"比年轻时更积极参加文体活动的老年人生活更充实"},{"label":"C","content":"一些老年人的物质生活并不富足"},{"label":"D","content":"老年人的精神需求并不比年轻人多"}],"answer":"B","explanation":"题干结论：老年人应当比年轻时更积极地参加文体活动。<br>A项，说的是老年人与年轻人的对比，而题干所述是老年人与其年轻时候的对比，因此该项无法支持题干结论，排除。<br>B项，指出比年轻时更积极参加文体活动的老年人生活更充实，因此老年人确实应该比年轻时更积极地参加文体活动，支持了题干结论。<br>C项，一些老年人的物质生活并不富足，不能说明老年人应当比年轻时更积极地参加文体活动，无法支持题干结论，排除。<br>D项，老年人的精神需求并不比年轻人多，不能说明老年人应当比年轻时更积极地参加文体活动，无法支持题干结论，排除。","no":273},{"id":"1718789647073","type":"single","material":"","stem":"<p>水熊虫不吃不喝能够存活30年，可以忍受高达150℃的高温，可生存在深海和冰冷的太空中。它们惊人的生存能力使之能够躲过灭绝地球上绝大多数生命的大灾难，能够伤害水熊虫的力量只有恒星爆炸或者伽马射线大爆发。有专家由此断言，水熊虫是一种可生存到太阳灭亡那一天的地球生物。</p><p>以下哪项如果为真，最能支持上述专家的观点?</p>","options":[{"label":"A","content":"有些地球生物可以生存到太阳灭亡的那一天"},{"label":"B","content":"在太阳灭亡之前水熊虫不会遇到恒星爆炸或者伽马射线大爆发"},{"label":"C","content":"只有能够不吃不喝存活30年或忍受150℃的高温，才能生存到太阳灭亡的那一天"},{"label":"D","content":"只有不吃不喝存活30年，才能躲过恒星爆炸或者伽马射线大爆发"}],"answer":"B","explanation":"题干论点：水熊虫是一种可生存到太阳灭亡那一天的地球生物。论据：水熊虫不吃不喝能够存活30年，可以忍受高达150℃的高温，可生存在深海和冰冷的太空中。它们惊人的生存能力使之能够躲过灭绝地球上绝大多数生命的大灾难，能够伤害水熊虫的力量只有恒星爆炸或者伽马射线大爆发。A项，有些地球生物可以生存到太阳灭亡的那一天，但不知道有些生物是否包含水熊虫，因此，无法得知水熊虫是否可以生存到太阳灭亡的那一天，属于不确定项。B项，只有恒星爆炸或者伽马射线大爆发才能伤害水熊虫，而在太阳灭亡之前水熊虫不会遇到恒星爆炸或者伽马射线大爆发。通过补充论据的方式，支持了专家观点。C项，生存到太阳灭亡的那一天，推出不吃不喝存活30年或忍受150℃的高温，是由题干中的论点推出论据，推论方向错误，无法支持专家观点。D项，论据讨论的是水熊虫惊人的生存能力使之能够躲过灭绝地球上绝大多数生命的大灾难，而无法躲过恒星爆炸或者伽马射线大爆发的伤害。而D项讨论的是不吃不喝存活30年，是躲过恒星爆炸或者伽马射线大爆发的必要条件。两者讨论内容不同，无法支持专家观点。故正确答案选B。","no":274},{"id":"1718789647074","type":"single","material":"","stem":"大多数人的饮食中都含有过量的脂肪。而食物中的脂肪主要以甘油三酯的形式存在。在消化道中，脂肪酸被脂肪酶水解释放出来后，才能被吸收进入血液，重新合成甘油三酯。如果脂肪酶受到抑制，就能终止这一合成过程。对此，有研究者做了相关实验。他们将体重相当的雌性老鼠分成三组，第一组自由进食，第二组高脂饮食，第三组高脂饮食但在食物中添加了一种从茶叶中提取的“茶皂素”。结果发现，从第5周开始直至第10周实验结束时，第二组老鼠的体重就比第一组显著要高，但第三组和第一组相比却没有明显差异。由此，研究者们得出结论，茶皂素这种“天然产物”具有抑制脂肪酶的能力，人们喝茶的确能产生减肥效果。<br>以下哪项为真，最能质疑研究者们的上述结论?","options":[{"label":"A","content":"高脂饮食的老鼠，宫旁脂肪的重量大约常规饮食的老鼠们的2倍"},{"label":"B","content":"如果高脂饮食中加了茶皂素，则其宫旁脂肪就跟常规饮食的老鼠基本上一样"},{"label":"C","content":"实验中使用的茶皂素量太大，按同样比例一般人一天至少需要饮用五千克干茶"},{"label":"D","content":"老鼠和人的差异还是很大的，老鼠实验的结论对于人类只有一定的参考作用"}],"answer":"C","explanation":"题干论点：茶皂素这种“天然产物”具有抑制脂肪酶的能力，人们喝茶的确能产生减肥效果。论据：从第5周开始直至第10周实验结束时，第二组老鼠的体重就比第一组显著要高，但第三组和第一组相比却没有明显差异。<br>A项，高脂饮食老鼠的宫旁脂肪是常规饮食老鼠的2倍，但第三组和第一组相比却没有明显差异，说明茶皂素产生了减肥效果，通过补充论据的形式，支持了论点。<br>B项，高脂饮食中加了茶皂素后，第一组和第三组老鼠的相比没有明显差异，通过补充论据的形式，支持了论点。<br>C项，实验中使用的茶皂素量太大，远远超出一般人日常的饮茶量，即人们不可能通过日常喝茶获取同样比例的茶皂素，通过削弱论据的方式，质疑了论点。<br>D项，老鼠实验的结论对于人类只有一定的参考作用，即由老鼠的实验不能一定得出结论人们喝茶能减肥，在一定程度上削弱了结论，但力度不如C","no":275},{"id":"1718789647075","type":"single","material":"","stem":"某电视综艺节目播出后，节目导演声称该节目达到了当前同类节目的最高水准，因为该节目收视率比同类节目高2%。<br>以下哪项如果为真，最能削弱上述论证?","options":[{"label":"A","content":"参与该节目的嘉宾对节目评价不一"},{"label":"B","content":"观众本身就非常喜欢看电视综艺节目"},{"label":"C","content":"该导演的微博有几十万条批评此节目的评论"},{"label":"D","content":"节目的水准和收视率并无必然关联"}],"answer":"D","explanation":"题干中导演由该节目收视率比同类节目高2%,得出该节目达到了当前同类节目的最高水准的结论。D项切断了题干论据和论点之间的联系，从而削弱了论证。A项嘉宾的评价、B项观众本身喜好、C项批评此节目的评论均与该节目的水准无关，无法削弱题干论证。","no":276},{"id":"1718789647076","type":"single","material":"","stem":"所有市民都迫切希望加强城市绿化，但是需要市民们为一个绿化方案付费时，总有一些人认为即使他们不出钱也能享受到绿化的好处，所以他们拒绝承担费用。<br>以下哪项如果为真，是上述论证所需要的前提?","options":[{"label":"A","content":"这些人喜欢占小便宜"},{"label":"B","content":"这些人认为绿化应该由政府出资"},{"label":"C","content":"为绿化方案出钱具有强制性"},{"label":"D","content":"这些人认为总有人会付费"}],"answer":"D","explanation":"一些人认为即使他们不付费也可以享受到绿化的好处，隐含的前提是这些付费的方案总会有人付费的，不会因为他们不付费而导致绿化方案实施不了，D项是其所需前提。A项这些人是否喜欢占小便宜、B项绿化是否应该由政府出资、C项出钱是否具有强制性均与题干的论证过程无关，并非论证所需的前提。","no":277},{"id":"1718789647077","type":"single","material":"","stem":"有专家指出，判断名优白酒的真伪有简单的办法：价格低得离谱的名优白酒肯定都是假的，凡是打着某一名优白酒旗号在外公开销售的定制酒都是假的。而消费者如果从正规渠道购买，就能买到真的好酒，这些渠道一是正规超市或者大卖场；二是名优白酒品牌授权的旗舰店；三是名优白酒企业的官网电商。<br>以下哪项如果为真，最能质疑专家的观点?","options":[{"label":"A","content":"有些大卖场对进场商品的把关不严格，销售假冒伪劣商品的情况时有发生"},{"label":"B","content":"现今网络诈骗案件屡屡发生，假冒名优白酒企业官网销售的白酒肯定是假的"},{"label":"C","content":"某电视促销节目主持人声称，他们销售的名优白酒的价格虽然只有市价的一半，但绝对不是假酒"},{"label":"D","content":"某名优白酒企业生产的定制酒只用于企业内部接待，但它是真的"}],"answer":"A","explanation":"题干的推理规则：①价格低得离谱→假酒；②打着名优白酒旗号在外公开销售的定制酒→假酒；③从正规渠道购买→真的好酒。<br>A项是③的矛盾命题(前件真而后件假),说明题干推理是错误的，有力地质疑了专家的观点。<br>B项假冒的官网在上述推理中并不涉及，不能质疑。<br>C项电视促销节目主持人的话未必可信，不能质疑。<br>D项是企业内部接待用的，并非在外公开销售，不能质疑专家的观点。","no":278},{"id":"1718789647078","type":"single","material":"","stem":"数百年来，人类一直想要对深海生物有更深的认识。各地流传的神话故事中，几乎都会讲到深海巨怪。希腊、挪威等国家的许多有关人类探索海域的神话中，随处可见海蛇、大乌贼、巨鲨的存在。由此可见，在深海中，确实有不为人知的海底巨型生物。<br>以下哪项如果为真，最能加强上述论证?","options":[{"label":"A","content":"深海是传说中动物的最佳住所"},{"label":"B","content":"神话有很多是虚构的，并不可信"},{"label":"C","content":"深海相机确实拍摄到了生活在深海中的生物"},{"label":"D","content":"不同地域神话中的相似内容往往是现实的真实反映"}],"answer":"D","explanation":"题干根据各地流传的神话故事中都讲到了深海巨怪，推出深海中确实有海底巨型生物这一结论。<br>A项，深海是传说中动物的最佳住所与深海中是否真的有海底巨型生物无关，不能加强题干论证。<br>B项指出神话有很多是虚构的，在一定程度上削弱了题干论证。<br>C项中的生物不一定就是巨型生物，无法加强题干论证。<br>D项指出不同地域神话中的相似内容往往是现实的真实反映，建立了传说与现实之间的联系，能够加强题干论证。","no":279},{"id":"1718789647079","type":"single","material":"","stem":"甲国国民S开了一家糖果店。某日，S决定将牛轧糖、奶糖单价分别提高2.9元和1.8元；当天，乙国空军一架F-222战机坠毁。一个月后，S又将奶糖单价翻番，当天14时，丙国一架客机起飞不久后遇难。两个月后，S就糖果价格问题发表声明，称价格未调整到位，并将牛轧糖单价提高1.2元。当日，丁国某航空公司的一架客机在该国西北部附近坠毁。可见，S以糖果价格为武器，专门打击境外航空器。<br>下列选项如果为真，最能支持上述结论的是：","options":[{"label":"A","content":"飞机制造时，内部程序设定为主动接收S的糖果定价信息，遇到特定价格就坠毁"},{"label":"B","content":"坠毁的不仅有外国飞机，也有本国飞机；不仅有军用战机，也有民用客机"},{"label":"C","content":"S和某跨国恐怖组织关系密切，调整糖果价格前已得知恐怖袭击的详细计划"},{"label":"D","content":"S在销售给境外飞行员的糖果中植入炸弹，咬破后立即发生爆炸"}],"answer":"A","explanation":"题干结论：S以糖果价格为武器，专门打击境外航空器。<br>A项，飞机能主动接收S的糖果定价信息，当遇到特定价格时就会造成飞机坠毁，在S的糖果价格和飞机坠毁之间建立了联系，支持了题干结论。<br>B项，坠毁的也有本国飞机，和题干结论所说的专门打击境外航空器不符，对题干结论有一定削弱作用。<br>C项，S和跨国恐怖组织关系密切和在调整糖果价格前已得知恐怖袭击的详细计划，不能说明糖果价格和飞机坠毁之间的联系，不能支持题干结论。<br>D项，是直接以糖果炸弹作为武器，而不是糖果的价格，不能支持题干结论。","no":280},{"id":"1718789647080","type":"single","material":"","stem":"为什么一些灵长类动物的大脑尺寸比其他动物要大?原因通常被认为是社会行为，即灵长类动物生活于更大更复杂的社会群体中，为了更好地处理各种社会关系，它们需要更大的大脑。<br>以下哪项如果为真，不能质疑上述观点?","options":[{"label":"A","content":"通过灵长类动物的饮食特点而非社群复杂性，能够更容易预测其大脑的大小"},{"label":"B","content":"猩猩等一些灵长类动物通常是独居生活，但它们的大脑也很大"},{"label":"C","content":"大脑皮层的大小与大脑尺寸没有直接关联，但对于灵长类动物的认知、空间推理能力等非常重要"},{"label":"D","content":"灵长类动物中，食果类的大脑比食叶类大，这是因为果实在时间和空间上更分散，<br>找到果实是一项更为复杂的任务"}],"answer":"C","explanation":"题干观点：灵长类动物的大脑尺寸更大是因为灵长类动物要处理复杂的社会群体中的各种社会关系。<br>A项，表明灵长类动物大脑的大小可能与其饮食特点而不是社群复杂性有关，质疑了题干观点。<br>B项，通过猩猩的例子说明大脑尺寸大小与处理复杂的社会关系没有直接联系，质疑了题干观点。<br>C项，说的是大脑皮层的大小对灵长类动物的重要性，但并没有说明大脑尺寸大小的原因，与题干论证无关。<br>D项，举例说明灵长类动物大脑尺寸更大的原因可能是获取食物的方式复杂，而不是处理复杂的社会关系，质疑了题干观点。","no":281},{"id":"1718789647081","type":"single","material":"","stem":"在一场关于“传承和创新哪个更重要”的辩论赛中，正方和反方进行了激烈的辩论。正方二辩在发言中提出一种观点：“先后性就等于重要性。”<br>作为对上述观点的反驳，以下最为有力的是：","options":[{"label":"A","content":"正所谓“雄鸡一唱天下白”,但你总不能说天白就是雄鸡唱出来的吧"},{"label":"B","content":"我穿鞋时总习惯先穿左脚，再穿右脚，这就说明左脚比右脚更重要吗"},{"label":"C","content":"吃一碗面，加点醋是必要的。但你说是以吃面为主，还是以吃醋为主"},{"label":"D","content":"我必须先拧开瓶盖，才能喝到水。这不正说明拧瓶盖是必要的步骤吗"}],"answer":"B","explanation":"题干中的观点：先后性就等于重要性。要反驳该观点就要说明：先后性不等于重要性。<br>A项，“雄鸡一唱天下白”体现了先后顺序，但是天白不是雄鸡唱出来的，而且也没有涉及重要性的问题，不能反驳题干观点。<br>B项，通过穿鞋举例说明两只脚同样重要，即先后性不等于重要性，反驳了题干中的观点。<br>C项，吃面加醋没有涉及先后性和重要性，不能反驳题干中的观点。<br>D项，先拧开瓶盖，才能喝到水。强调的是先后顺序，但拧开瓶盖是喝上水的必要环节，不能说明拧开瓶盖就比喝水更重要，不能反驳题干中的观点。","no":282},{"id":"1718789647082","type":"single","material":"","stem":"有研究人员收集合并了30项纵向干预研究，其中11项评估了上涨不健康食品价格的影响，19项评估了降低健康食品价格的影响。合并分析结果显示，利用价格引导人们消费健康食品，有助于人们改进饮食习惯，对公共健康是有好处的。<br>以下哪项如果为真，能够削弱上述结论?","options":[{"label":"A","content":"水果和蔬菜的价格每降低10%,它们的销量就会增加14%"},{"label":"B","content":"食品和饮料价格的变化，只在短期内影响消费者的购买行为"},{"label":"C","content":"含糖饮料价格的变化，会影响人们的身体质量指数(BMI)"},{"label":"D","content":"不健康快餐的价格每上涨10%,它们的销量就会下降3%"}],"answer":"B","explanation":"题干论点：利用价格引导人们消费健康食品，有助于人们改进饮食习惯，对公共健康是有好处的。论据：11项评估了上涨不健康食品价格的影响，19项评估了降低健康食品价格的影响。<br>A项，水果和蔬菜属于健康食品，而价格每降低10%,销量就会增加14%,加强了题干结论。<br>B项，食品和饮料价格的变化，只能影响消费者短期的购买行为，即通过价格变化无法达到从根本上改进人们饮食习惯的目的，削弱了题干结论。<br>C项，选项中只涉及“含糖饮料价格”和“身体质量指数”,而未涉及“消费”,属于无关项。<br>D项，不健康快餐价格上涨，其销量会下降，人们因为价格而少买不健康食品，加强了题干结论。","no":283},{"id":"1718789647083","type":"single","material":"","stem":"由于我国大城市的房价和物价过高，导致生活成本明显高于中小城市，尤其是对于小城镇来讲，大城市的生活成本是小城镇的数倍。这样一来，势必限制了农村人口向大城市流入。因此，我国仅仅依靠发展大城市来实现城市化，是一条难以为继的艰难之路。<br>以下哪项是上述论证所隐含的前提?","options":[{"label":"A","content":"大城市吸纳农村人口的能力没有上限"},{"label":"B","content":"所有城镇都得到充分发展才能被称为城市化"},{"label":"C","content":"大城市对农村人口的吸引力远远大于中小城市"},{"label":"D","content":"要实现城市化，需要让城市充分吸纳农村人口"}],"answer":"D","explanation":"题干由大城市的房价和物价过高限制了农村人口向大城市流入，得出我国仅仅依靠发展大城市来实现城市化，是一条难以为继的艰难之路。要使论证成立，需在论据和论点之间建立联系。<br>A项，大城市吸纳农村人口的能力是否有上限与题干论述无关，属于无关项。<br>B项，未提及农村人口，也不是题干论证所隐含的前提。<br>C项，大城市吸引力大，也不能说明农村人口向大城市流入与城市化之间存在联系，为无关项。<br>D项，让城市充分吸纳农村人口是实现城市化的必要条件，是题干论证隐含的前提。","no":284},{"id":"1718789647084","type":"single","material":"","stem":"据统计，美国大约2000万人受螨虫过敏之扰。某大学的研究结果表明，相对于其他物种，美国东部和西海岸是螨虫的乐土，而西部内陆则是螨虫的地狱。因为螨虫只能生活在潮湿环境下。对此，专家建议，“如果你对螨虫过敏，住在美国和加拿大的干燥和高海拔地区，绝对是个不错的选择”。<br>以下哪项如果为真，最能有效支持上述专家的建议?","options":[{"label":"A","content":"住在美国西部内陆地区的对螨虫过敏人士数量要比居住在美国东部的多得多"},{"label":"B","content":"从潮湿地区搬到干旱地区的床垫、毯子和家具也会滋生螨虫"},{"label":"C","content":"很多对螨虫过敏的人士都表示他们在美国西部内陆出差期间过敏症状减轻了"},{"label":"D","content":"通过用防过敏罩子包裹床垫和毯子，每周更换床单，能有效抑制螨虫"}],"answer":"C","explanation":"专家的建议：对螨虫过敏的人适合住在美国和加拿大的干燥和高海拔地区。<br>A项没有涉及两个地方居住人数差异的原因，不明确这些人是不是因为干燥或高海拔才选择住在美国西部内陆地区的，不能支持专家的建议。<br>B项指出从潮湿地区搬到干旱地区后，一些物品也会滋生螨虫，因此让这些对螨虫过敏的人士住在干燥地区仍可能导致他们过敏，在一定程度上削弱了专家的建议。<br>C项很多对螨虫过敏的人到美国西部内陆出差期间过敏症状减轻了，说明了美国西部内陆确实对降低螨虫过敏有一定的作用，支持了专家建议。<br>D项提出了另一个抑制螨虫的方法，但无法说明专家的建议有没有效果，为无关项。","no":285},{"id":"1718789647085","type":"single","material":"","stem":"在某次电子产品促销会中，某款电子产品特别受消费者欢迎。促销会负责人总结经验时说，看来只有投入了大量广告费用做宣传的电子产品才有好的市场接受度。<br>以下哪项如果为真，最能质疑负责人的论述?","options":[{"label":"A","content":"某款电子产品的外观设计增加了更多科技元素，尽管没有做广告宣传，仍然受到市场欢迎"},{"label":"B","content":"最关注电子产品的广告群体是青年人，而参加此次促销会的消费者恰好青年人多"},{"label":"C","content":"某款电子产品投入了大量广告费用做宣传，但由于其价格过高，并不受市场欢迎"},{"label":"D","content":"某些电子产品投入了大量广告费用做宣传，但是实际上并不具备所宣传的部分功能"}],"answer":"A","explanation":"负责人的论述：投入大量广告费用做宣传的电子产品←有好的市场接受度。<br>A项说明了某款电子产品没有做广告宣传但是受到了市场的欢迎，即题干命题的前件为假、后件为真，是题干命题的矛盾命题，有力地质疑了负责人的论述。<br>B项说明广告确实起到了一定效果，对题干结论有加强的作用。<br>C项因价格过高没有受到市场欢迎，但是不确定广告是不是起了作用，不能质疑。<br>D项不具备所宣传的部分功能，同样不能说明广告与市场接受度的关系，为无关项。","no":286},{"id":"1718789647086","type":"single","material":"","stem":"有教育专家提出，如果采取按照年龄、学历水平和职称等级将教师平均分配到所有学校的办法来配置教育资源，实现教育公平，就能较好地解决目前因上重点学校竞争激烈而引起的社会问题。<br>以下哪项如果为真，最能削弱该教育专家的观点?","options":[{"label":"A","content":"很多重点学校老师表示支持"},{"label":"B","content":"绝大多数学生和家长表示反对"},{"label":"C","content":"一些重点学校老师要求到物价低的郊区学校工作"},{"label":"D","content":"普通学校的硬件设施建设比起重点学校存在明显差距"}],"answer":"D","explanation":"专家的观点：按各种条件将教师平均分配到所有学校，实现教育公平，就能解决相关的社会问题。<br>A项，很多老师支持无法说明该教育专家的方法有效或无效，排除。<br>B项，绝大多数学生和家长反对无法说明该教育专家的方法有效或无效，排除。<br>C项，一些老师要求到物价低的郊区学校工作也与该教育专家的方法是否有效果无关，排除。<br>D项指出学校的差距不仅和教师相关，还在于硬件设施建设，说明专家提出的方法达不到效果，削弱了专家的观点。","no":287},{"id":"1718789647087","type":"single","material":"","stem":"为了解对学校食堂的满意度，某大学进行了一项“我最满意的食堂”评比活动。通过让学生对食堂的饭菜质量、价格、服务态度、卫生状况等10项指标进行评分来反映其对食堂的满意度，学生给每个评分指标赋以1到10分的某一个分值，然后计算出10项评分指标的平均得分，从而得出学生对食堂的满意度。<br>实施这一项评比活动需要假设的前提是：<br>I.对饭菜质量、服务态度等指标的评价可以用数字来表达<br>Ⅱ.上述10项指标对学生来说同等重要<br>Ⅲ.该大学的每个学生都参与了这次评比活动","options":[{"label":"A","content":"仅I"},{"label":"B","content":"仅Ⅱ"},{"label":"C","content":"仅I和Ⅱ"},{"label":"D","content":"I、Ⅱ和Ⅲ"}],"answer":"C","explanation":"由题干可知，某大学要对学校食堂的满意度进行调查，且给出了评分标准。要求选择实施这一活动的前提条件。假设饭菜质量、服务态度等指标的评价不可以用数字来表达，评比活动就无法进行，I是必需的前提。假设10项指标对学生来说不是同等重要，则最终的平均得分就不是科学的，也就无法评测出满意度，Ⅱ是必需的前提。假设不是每个学生都参与了评比活动，也能得出评价结果，因为调查分为很多种形式，也可采用抽样调查进行，并不需要每一个人都参加，Ⅲ不是必需的前提。因此I和Ⅱ为评比活动需要假设的前提。","no":288},{"id":"1718789647088","type":"single","material":"","stem":"医生告诫人们，抽烟喝酒有害健康。但又有学者从统计学角度发现，一些根据习俗从不抽烟不喝酒的民族，平均寿命要比经常抽烟喝酒的民族短5~10岁。因此学者推测，抽烟喝酒虽然可能损伤肺和肝的功能，但不一定会影响人的寿命。<br>以下哪项如果为真，最能质疑上述观点?","options":[{"label":"A","content":"抽烟和喝酒的时候能让大脑获得欣快感，排解压力，感到愉悦"},{"label":"B","content":"那些根据习俗而杜绝烟酒的民族其饮食也相对单一，并且热量极高"},{"label":"C","content":"抽烟喝酒是肺癌和肝癌的重要原因，而这两种疾病位于疾病死亡谱的前两位"},{"label":"D","content":"烟酒可以刺激大脑分泌多巴胺，让人体各器官进入放松状态，促进身体修复"}],"answer":"B","explanation":"题干论点：抽烟喝酒虽然可能损伤肺和肝的功能，但不一定会影响人的寿命。论据：某些不抽烟不喝酒的民族平均寿命更低。<br>A项，只是说抽烟喝酒让人愉悦，和寿命没有直接关系，属于无关项。<br>B项，指出了这些不抽烟不喝酒的民族饮食单一，并且热量极高，这些很可能是他们寿命更低的原因。也就是因为这些民族的特殊性，是不能由此论据得出此结论的，指出了论证逻辑上存在漏洞，质疑了题干观点。<br>C项，说明抽烟喝酒是肺癌和肝癌的重要原因，而这两种疾病位于疾病死亡谱的前两位，有一定削弱力度。但是与B项相比，没有针对题干的论据和论证进行削弱，更没有针对题干的漏洞削弱，针对性不强，且死亡与寿命长短也没有必然联系。<br>D项，说烟酒可以刺激大脑分泌多巴胺促进身体修复，是在说烟酒的好处，在一定程度上支持了题干结论。","no":289},{"id":"1718789647089","type":"single","material":"","stem":"公元250年至800年，玛雅文明还十分发达。城市繁荣，庄稼收成也很喜人。气候记录显示，这一时期玛雅地区的降水量相对较高。此后玛雅文明开始衰落。从公元820年左右起，在连续95年的时间里，该地区开始经历断断续续的干旱，有些地方的干旱甚至持续了数十年之久。许多专家由此认为，9世纪的气候变化或许正是玛雅文明消亡的原因。<br>以下哪项如果为真，最能支持上述专家的观点?","options":[{"label":"A","content":"在9世纪衰退的玛雅城市大多分布在南部，使用木材进行的建造活动也大大减少"},{"label":"B","content":"和所有大型农耕文明一样，玛雅人的社会很大程度上依赖于农作物，干旱导致农产品减少，严重影响玛雅人的生存"},{"label":"C","content":"大多数玛雅城市是在公元850年到925年之间衰落的，和干旱发生的时间高度重合"},{"label":"D","content":"公元1000年至1075年期间，玛雅地区石雕和其他建造活动减少了将近一半，而那时当地又一次遭受了严重的旱灾"}],"answer":"B","explanation":"题干的观点：9世纪的气候变化或许正是玛雅文明消亡的原因。<br>A项，衰退的玛雅城市的地理位置与玛雅文明消亡的原因无关，无法支持题干结论。<br>B项，玛雅人的社会对农作物的依赖程度很深，气候变化又严重影响农作物的生产，因此气候变化很可能是玛雅文明消亡的原因，有力地支持了题干专家的观点。<br>C项，城市衰落的时间和干旱发生的时间重合，也不能说明干旱就是城市衰落的原因，无法支持题干结论。<br>D项，干旱的同时石雕和其他建造活动减少，与气候变化是否为玛雅文明消亡的原因无关，无法支持题干结论。","no":290},{"id":"1718789647090","type":"single","material":"","stem":"阿尔茨海默病是一种较为严重的疾病，4号基因突变曾被认为是阿尔茨海默病的一项致病因素。但近期有科学家提出导致这一复杂疾病的病因可能很简单，就是一些能引起脑部感染的微生物，如HSV-1病毒。<br>以下哪项如果为真，最能支持上述科学家的观点?","options":[{"label":"A","content":"携带4号突变基因同时感染了HSV-1病毒的人群罹患阿尔茨海默病的概率会比单独具有此类突变基因的群体高2倍分享"},{"label":"B","content":"当大鼠脑部受到HSV-1感染时，携带4号突变基因的大鼠产生的病毒DNA是正常大鼠的14倍"},{"label":"C","content":"有些携带4号突变基因的患者使用抗病毒药物治疗后，其病情有所好转"},{"label":"D","content":"在一些健康老年人的大脑中也存在着HSV-1病毒"}],"answer":"A","explanation":"题干的观点：导致阿尔茨海默病的原因并非4号基因突变，而是一些能引起脑部感染的微生物(HSV-1病毒)。<br>A项，指出同样情况下感染这种病毒的群体患病的概率更高，说明能引起脑部感染的微生物的确是阿尔茨海默病的病因，支持了题干观点。<br>B项，仅是产生的病毒DNA增多，并非阿尔茨海默病患病概率增加，不能支持题干观点。<br>C项，使用抗病毒药物治疗后病情好转，与能引起脑部感染的微生物是否会导致阿尔茨海默病无关，不能支持题干观点。<br>D项，健康老年人的大脑中存在该病毒，无法说明患阿尔茨海默病的病因是什么,不能支持题干观点。","no":291},{"id":"1718789647091","type":"single","material":"","stem":"复活节岛是位于太平洋上的一座孤岛。在报道中，复活节岛文明的衰落常作为一个警世故事，讲述人类肆意采伐棕榈树林，致使肥沃的土壤流失，最终导致岛中食物短缺，文明自此衰落。然而近日有专家提出，复活节岛文明的衰落与树木砍伐并无必然联系。<br>以下哪项如果为真，最能支持上述专家的观点?","options":[{"label":"A","content":"大约公元1200年，岛上居民开始砍伐棕榈树，用于建造木船，运送大型石质雕像"},{"label":"B","content":"考古发现，当岛上最后的树木(棕榈树)被砍伐之后，仍有大量原住居民生活着，其农业耕作的水平没有下降"},{"label":"C","content":"花粉分析表明，早在公元800年，森林的毁灭就已经开始，岛屿地层中的大棕榈树和其他树木的花粉越来越少"},{"label":"D","content":"1772年荷兰殖民者开始登陆复活节岛，并对当地居民进行奴役，那时岛上的土著人口是4000人，到1875年时仅有200人"}],"answer":"B","explanation":"题干的观点：复活节岛文明的衰落与树木砍伐并无必然联系。<br>A项，并不能说明复活节岛文明的衰落与树木砍伐之间是否存在必然联系，无法支持专家观点，排除。<br>B项，指出棕榈树被砍伐后农耕水平并没有下降，即复活节岛文明的衰落并不是因为棕榈树的砍伐，有力地支持了专家的观点。<br>C项，并没有说明复活节岛文明衰落的原因，无法支持专家观点，排除。<br>D项，说明文明的衰落可能与外来殖民者有关，但也不能否认与树木砍伐的关系，不能支持专家观点，排除。","no":292},{"id":"1718789647092","type":"single","material":"","stem":"英国“首席捕鼠官”虎斑猫拉里因为不勤于捕鼠，而被部分人以“未尽职工作”为由，要求下台，但同时一些媒体也发起支持行动，表示“权利义务不对等”,唐宁街(英国政府代称)没有任何理由让这位捕鼠官下课。<br>如果以下各项为真，最能支持媒体观点的是：","options":[{"label":"A","content":"调查显示，拉里任捕鼠官后，全国得到收养的流浪猫增加了20%,拉里的任职起到了良好的社会示范作用"},{"label":"B","content":"拉里天生不善捕鼠，它被选为捕鼠官并未经过唐宁街工作人员仔细考察"},{"label":"C","content":"唐宁街并未支付拉里薪水，其口粮全部由唐宁街工作人员花费购买"},{"label":"D","content":"由于外形可爱、性格温顺，拉里经常被安排额外的外交接待任务"}],"answer":"C","explanation":"媒体因觉得“权利义务不对等”,所以唐宁街没有任何理由让拉里下课。拉里作为“捕鼠官”的义务是捕鼠，而权利是因捕鼠而获得薪水。<br>A项，虽然起到了良好的示范作用，但此并非拉里的工作，不能支持媒体观点。<br>B项，说明题干中部分人的观点是正确的，也不能支持媒体观点。<br>C项，说明是唐宁街工作人员为拉里购买的口粮，所以实际上唐宁街并未为拉里发放薪水，拉里履行了捕鼠的义务却没有换来相应的薪水，所以“权利义务不对等”,加强了媒体观点。<br>D项，承担了其他任务不代表就对工作“尽责”了，同样不能支持媒体观点。","no":293},{"id":"1718789647093","type":"single","material":"","stem":"有人认为“意象”是一个外来词，是英文“image”的译文，并把它和20世纪初的英美意象派诗歌联系起来。但其实，意象是中国古代文艺理论固有的概念和词语，并不是外来的东西。<br>如果以下各项为真，最能证明“意象”在我国的原生性的是：","options":[{"label":"A","content":"英美意象派所提倡的“image”是指运用想象、幻想、譬喻所构成的各种具体鲜明的、可以感知的诗歌形象，与中国的“意象”含义不同"},{"label":"B","content":"很多主张把自己的情绪全部隐藏在意象背后，通过意象将它们暗示出来的英美意象派诗人实际上深受中国古代诗歌的影响"},{"label":"C","content":"我国古代诗歌的诞生远远早于英美诗歌，我国古代的传说故事是很多英美意象派诗人创作的灵感来源"},{"label":"D","content":"意象在南朝《文心雕龙》等著作中有提及，它没有确定的含义和一致用法，有的指意中之象，有的指意和象，有的接近于今天所说的艺术形象"}],"answer":"D","explanation":"题干观点为意象是我国文艺理论固有的概念和词语。<br>A项，说明英美意象的含义和中国意象的含义不同，不能证明中国意象的原生性。<br>B项，很多英美意象派诗人受中国古代诗歌的影响，但不确定是受哪些方面影响，不确定是受意象的影响，所以不能证明中国意象的原生性。<br>C项，诗歌诞生得早，然后给英美意象派诗人创作带来灵感，为无关项。<br>D项，说明我国在南朝的时候就有著作提出意象这一概念，远远早于西方，能够证明中国意象的原生性。","no":294},{"id":"1718789647094","type":"single","material":"","stem":"2015年5月8日，财政部、国家税务总局发文，烟草消费税由5%提高至11%,并加征从量税。有专家认为，“税价联动”会使香烟价格随着税率的提高而提高，购买香烟的人会因此减少，从控烟角度说，这无疑是件好事。<br>以下哪项如果为真，最能削弱上述结论?","options":[{"label":"A","content":"烟草产量不会受到售价的影响"},{"label":"B","content":"收入水平的提高使人们对香烟价格不太敏感"},{"label":"C","content":"世界上大多数国家的烟草消费税税率低于11%"},{"label":"D","content":"一些发达国家出现过提高烟草消费税后私烟泛滥的现象"}],"answer":"B","explanation":"题干结论：“税价联动”会使香烟价格随着税率的提高而提高，购买香烟的人会因此减少。<br>A项，产量与购买人数无直接联系，为无关项。<br>B项，收入水平的提高使得人们对香烟的价格不太敏感，也就意味着即使香烟价格提高，也不会影响购买香烟的人的数量，有力地削弱了结论。<br>C项，其他国家的税率情况为无关项，不能削弱。<br>D项，一些发达国家的情况与我国的情况相关性较弱，不能削弱。","no":295},{"id":"1718789647095","type":"single","material":"","stem":"研究人员对中风幸存者进行分组实验。他们让一组中风幸存者在研究人员的监督下进行为期3个月的户外健步走锻炼。另一组不进行运动，而是接受治疗性按摩。实验结束后，研究人员发现在持续6分钟的测试中，步行组的人比按摩组的人走得更远，能比后者多走17.6%。研究者认为，身体适度受损的中风幸存者仅通过简单廉价的运动就能获得更好的效果。<br>以下哪项如果为真，最能削弱上述论证?","options":[{"label":"A","content":"步行组的平均年龄为72岁，按摩组的平均年龄为65岁"},{"label":"B","content":"与按摩组相比，体质的改善使得步行组中风幸存者生活质量更高"},{"label":"C","content":"步行组中风幸存者还服用了相关治疗药物，按摩组停服了相关药物"},{"label":"D","content":"研究证明，对身体严重受损的中风幸存者来说，接受按摩的效果更佳"}],"answer":"C","explanation":"题干通过两组中风幸存者进行的对比实验，得出结论：身体适度受损的中风幸存者仅通过简单廉价的运动就能获得更好的效果。<br>A项，年龄大小属于无关项。<br>B项，承认了运动的作用，对论证有一定程度的支持作用。<br>C项，两组人员除了运动外还存在吃药与否这一不同，据此得出题干的结论并不恰当，削弱了题干论证。<br>D项，涉及的是身体严重受损的中风者，也与题干结论无关。","no":296},{"id":"1718789647096","type":"single","material":"","stem":"很多家长认为，孩子不听话，“打屁屁”惩罚一下，至少能让孩子注意到自己的行为不当，变得更听话一些。还有一些人坚持“不严加管教会惯坏孩子”的传统信念，认为“打屁屁”是为孩子好。研究者对16万名儿童在过去5年里的经历进行研究，通过收集“打屁屁”行为的原数据加以分析，发现：打屁股会在儿童成长过程中造成智商低、攻击性行为高等多种负面影响。<br>以下哪项如果为真，最能支持上述结论?","options":[{"label":"A","content":"最新调查显示，智商相对较低的孩子大多数经常被家长打屁股"},{"label":"B","content":"本身不听话且更容易惹祸的孩子更有可能受到父母的严厉惩罚"},{"label":"C","content":"研究报告称全球大约80%的父母都有以打屁股管教孩子的经历"},{"label":"D","content":"被打屁股而困惑的孩子只懂得按家长要求去做而不会独立思考"}],"answer":"D","explanation":"题干结论：打屁股会在儿童成长过程中造成智商低、攻击性行为高等多种负面影响。<br>A项，指出不是因为打屁股造成智商低，而是因为智商低才被打屁股，属于因果倒置，削弱了题干结论。<br>B项，指出哪些小孩更容易受到惩罚，与题干论断无关。<br>C项，打屁股管教孩子的比例也是无关项。<br>D项，指出打屁股使孩子不会独立思考，造成了负面影响，支持了题干结论。","no":297},{"id":"1718789647097","type":"single","material":"","stem":"某机构为研究“轻断食”与人体健康的关系，招募一批志愿者做试验。志愿者分为两组，试验期6个月，饮食推荐量实行同一标准。第一组志愿者，每个月中有5天连续断食，第1天，热量摄入被减至推荐量的一半，后4天每日仅为推荐量的三分之一。第二组志愿者，在试验期中的每一天都正常饮食。试验结果显示，第一组志愿者的身体状况得到明显改善。由此研究人员得出结论：“轻断食”使志愿者体内产生较多酮体，氧化应激和炎症标志物水平均有所下降。<br>以下哪项如果为真，最能削弱研究人员的结论?","options":[{"label":"A","content":"所招募志愿者的身体机能和应激反应等本身就有差异"},{"label":"B","content":"实行连续断食的某位志愿者的身体炎症得到较大缓解"},{"label":"C","content":"试验开始之前志愿者体检显示相关健康指标基本相似"},{"label":"D","content":"第二组的某位志愿者在试验结束后健康水平有所下降"}],"answer":"A","explanation":"题干通过两组志愿者的对比试验，得出结论：“轻断食”使志愿者体内产生较多的酮体，氧化应激和炎症标志物水平均有所下降。<br>A项，指出两组志愿者的身体机能和应激反应本身就有差异，也就意味着试验的样本是不科学的，削弱了研究人员的结论。<br>B项，“某位志愿者”的情况属于个例，不能削弱题干观点。<br>C项，实验起始条件相似属于加强项。<br>D项，“某位志愿者”的情况属于个例，且说的是健康水平，属于无关项。","no":298},{"id":"1718789647098","type":"single","material":"","stem":"某科研机构提出潮湿的沙子是古埃及人在沙漠中搬运巨大石块和雕像的关键。研究人员指出，古埃及人将沉重的石块放上滑橇后，先在滑橇前铺设一层潮湿的沙子，再牵引它们，这种搬运方式起到了意想不到的效果。在实验中，研究人员使用流变仪测试沙子的硬度，以证实需要多少牵引力才能使一定数量的沙子变形，并在此基础上设计了牵引模型，从中发现将潮湿的沙子铺在滑橇前能更容易移动重物，而且沙子所含水分决定了沙子的硬度和牵引力。<br>如果以下哪项为真，最能支持上述结论?","options":[{"label":"A","content":"在一幅古埃及墓室壁画中，一名男子站在滑橇前方，似乎正在浇水"},{"label":"B","content":"滑橇牵引力与沙子硬度成反比，潮湿沙子的硬度是干燥沙子的两倍"},{"label":"C","content":"实验证明，铺设在滑橇前的潮湿沙子容易堆积，形成较大滑动阻力"},{"label":"D","content":"一个实验室版的埃及滑橇被成功建造，能够模拟古埃及工地的实况"}],"answer":"B","explanation":"题干通过研究得出“潮湿的沙子是古埃及人在沙漠中搬运巨大石块和雕像的关键”这一结论。<br>A项，仅是壁画的内容，真实性有待考证，“似乎”的加强力度太弱。<br>B项，为题干结论成立提供了科学理论，支持了题干。<br>C项，说明潮湿的沙子容易形成阻力，削弱了题干结论。<br>D项，能模拟成功并不能说明潮湿的沙子就是沙漠搬运巨大石块和雕像的关键，为<br>无关项。","no":299},{"id":"1718789647099","type":"single","material":"","stem":"英国一项研究发现，人只要在每餐饭前半小时喝一杯500毫升的水，并坚持3个月，体重就能减轻2~4千克。研究团队邀请了84位超重的成人，随机分成2组，其中41位被要求在餐前喝500毫升水，另外43位则照常生活。3个月后，团队发现三餐前喝水的人，平均体重下降了4.3千克；而餐前没喝水的人，平均体重只下降了0.81千克。研究人员说，没有喝水的那组人，“平均运动量”比餐前饮水的人更高，这说明餐前喝适当的水真能减肥。<br>以下哪项如果为真，最能支持上述结论?","options":[{"label":"A","content":"餐前喝水的那组人同时也注意控制饮食"},{"label":"B","content":"餐前没喝水的人中有的体重减轻了4千克"},{"label":"C","content":"除了餐前喝水，两组的其他情况都是一样的"},{"label":"D","content":"餐前没喝水的人就餐中会喝更多的汤和饮料"}],"answer":"C","explanation":"题干通过对比试验得出“餐前喝适当的水真能减肥”的结论。<br>A项，说明餐前喝水的那组注意控制饮食，则减肥的原因可能是控制饮食，削弱了题干观点。<br>B项，只是个例，在一定程度上削弱了题干结论。<br>C项，指出两组除餐前喝水不同外，其他情况都一样，说明了对比试验的可靠性，能够支持题干结论。<br>D项，餐中喝更多的汤和饮料不代表体重一定会增加，不能支持结论。","no":300},{"id":"1718789647100","type":"single","material":"","stem":"提高能源使用效率，鼓励能源灵活利用是美国减少温室气体排放政策的一个必要环节。它需要采用智能技术，包括通过智能表将能源使用信息从需求方或客户发送到能源公司等。该信息可用于制定和实施更高效的能源使用条例。但英国消费者对此态度不一，因为将该技术用于监控和支持能源高效率使用行为时，居民个人及家庭的能源数据不得不被动分享。所以，个人使用能源相关数据的被动分享有可能成为推广智能技术的主要障碍。<br>以下哪项如果为真，最能支持上述论证?","options":[{"label":"A","content":"60%的被调查者表示，不愿意因数据被动分享而降低个人能源使用比例"},{"label":"B","content":"60%的被调查者表示，数据的被动分享大大增加个人隐私被侵犯的风险"},{"label":"C","content":"60%的被调查者表示，那些关心气候变化的人更可能接受数据被动分享"},{"label":"D","content":"60%的被调查者表示，数据不可能不被分享，否则智能技术不可能应用"}],"answer":"B","explanation":"题干结论：个人使用能源相关数据的被动分享有可能成为推广智能技术的主要障碍。<br>A项，“个人能源使用比例”与题干论述的“提高能源使用效率”不同，不能支持题干结论。<br>B项，指出60%的被调查者认为，数据的被动分享大大增加个人隐私被侵犯的风险，因此大家就会对数据被动分享更加抵触，有力地支持了论证。<br>C项，与题干无关。<br>D项，在一定程度上削弱了题干结论。","no":301},{"id":"1718789647101","type":"single","material":"","stem":"有观点认为，意识体验是由一些特定脑区的特定神经集群以特定方式活动而突现的。当脑接收视觉刺激时，首先是脑后部的神经元对视觉刺激表征进行处理，然后投射到脑前部，在那里执行预测和计划的功能。当人对某个视觉刺激加以注意时，这些集群会得到加强，其中神经元的活动增强，同步性也增大。它们的信号在脑的前部和后部之间来回传输，最后在和其他集群的竞争中胜出。<br>以下各项如果为真，最能削弱上述观点的是：","options":[{"label":"A","content":"不同的意识体验是由一些特殊的神经元集群所介导甚至产生的"},{"label":"B","content":"意识是由脑整体功能在量上的增加所产生，是在含有大量神经递质的环境中大群发放神经元的整体性质"},{"label":"C","content":"初级视皮层中有大量神经元集群对来自左眼的刺激有猛烈发放，但其对意识毫无贡献"},{"label":"D","content":"同意识相关的特定脑区和神经元有着特殊的性质，不同的意识觉知归于特定的脑内连接"}],"answer":"B","explanation":"题干结论：意识体验是由一些特定脑区的特定神经集群以特定方式活动而突现的。<br>A项，指出不同的意识体验是由一些特殊的神经元集群所介导甚至产生的，加强了题干结论。<br>B项，说明意识是脑整体产生的，而非特定脑区产生的，削弱了题干结论。<br>C项，视皮层对意识是否有贡献属于无关项。<br>D项，属于无关项，不能削弱题干观点。","no":302},{"id":"1718789647102","type":"single","material":"","stem":"有报道称，已婚者一般比独身者寿命长，所以独身的压力一定对健康有损耗。<br>以下哪项如果为真，最能支持上述论证?","options":[{"label":"A","content":"独身者寿命短于同龄已婚者"},{"label":"B","content":"独身者会比已婚者的压力更大"},{"label":"C","content":"已婚者寿命不尽相同"},{"label":"D","content":"人的寿命受多种因素影响"}],"answer":"B","explanation":"题干根据“已婚者一般比独身者寿命长”得出“独身的压力对健康有损耗”的结论。<br>A项，只是说独身者寿命短，但是并不能说明是因为独身者压力大对健康的损耗，没有支持作用。<br>B项，说明独身者确实比已婚者压力大，能够支持题干结论。<br>C项已婚者的寿命和D项人的寿命，均与独身压力无关，也不能支持。","no":303},{"id":"1718789647103","type":"single","material":"","stem":"在过去的12个月中，某市新能源电动汽车的销售量明显上升。与之相伴随的是，电视、网络等媒体对新能源电动汽车的各种报道也越来越多。于是，有电动车销售商认为，新能源电动汽车销售量的提高主要得益于日益增多的媒体报道所起的宣传作用。<br>以下哪项如果为真，最能削弱该电动车销售商的观点?","options":[{"label":"A","content":"对新能源电动汽车进行报道的人中有不少是环保人士，他们喜欢宣传电动汽车"},{"label":"B","content":"有些消费者因为传统汽车摇号的中签率低转而购买新能源电动汽车"},{"label":"C","content":"个别消费者购买新能源电动汽车，是因为能够获得政府补贴"},{"label":"D","content":"看过关于新能源电动汽车报道的人，几乎都不购买该类型汽车"}],"answer":"D","explanation":"电动车销售商的观点：新能源电动汽车销售量的提高主要得益于日益增多的媒体报道所起的宣传作用。<br>A项，指出进行报道的人是环保人士，他们喜欢宣传电动汽车，但无法说明新能源电动汽车的销售量提高到底是不是因为报道增多，不能削弱题干观点，排除。<br>B项，说的是有些消费者购买新能源电动汽车的原因，但依然无法否认媒体报道的宣传作用，不能削弱题干观点，排除。<br>C项，说的是个别消费者购买新能源电动汽车的原因，但未必具有代表性，依然无法否认媒体报道的宣传作用，不能削弱题干观点，排除。<br>D项，指出看过关于新能源电动汽车报道的人，几乎都不购买该类型汽车，因此其销售量的提高就不是媒体报道宣传的作用，有力地削弱了销售商的观点。","no":304},{"id":"1718789647104","type":"single","material":"","stem":"在大气层的自然状态下，自由落体会受到空气阻力的干扰。要排除这种干扰，就要创造一种真空环境。在伽利略所处的时代，人们无法用技术手段创造出真空环境。因此，伽利略只能在思维中撇开空气阻力的因素，设想真空中的落体运动，从而得出自由落体定律，推翻了亚里士多德关于落体的结论。<br>要使伽利略得出的自由落体定律成立，必须以下列哪项为前提?","options":[{"label":"A","content":"当时的人们都能进行同样的思维实验"},{"label":"B","content":"伽利略的思维实验符合真空状态的运动规律"},{"label":"C","content":"伽利略在比萨斜塔通过现实实验进行了验证"},{"label":"D","content":"伽利略设想了各种可能性"}],"answer":"B","explanation":"自由落体定律需要在真空的条件下才能推出，但是当时没有创造真空的技术，伽利略只能在思维中设想真空落体的情况来推出自由落体定律。要想使自由落体定律成立，只能以伽利略的这种真空设想的思维完全符合真空状态的运动规律为前提。B项即题干必需的前提。","no":305},{"id":"1718789647105","type":"single","material":"","stem":"蝙蝠体内携带大量的病毒，会给人类和其他动物造成致命危险，但蝙蝠自身仿佛不受这些病毒的影响，为什么呢?科学家认为这或许与蝙蝠是唯一一种能够飞行的哺乳动物有关。蝙蝠在上亿年适应飞行的进化过程中，它们的很多系统发生了变化，包括防御和免疫系统。一般来说，人类和其他动物机体的免疫反应有助于身体抵御病毒，但对某种病毒的过度免疫反应又有可能引发严重疾病，而蝙蝠的免疫系统恰恰能在与病毒共生的过程中达到一种平衡。<br>以下推论中，正确的一项是：","options":[{"label":"A","content":"蝙蝠是一种最为古老的哺乳动物的物种，迄今有上亿年的进化历史"},{"label":"B","content":"蝙蝠机体的免疫系统会抵御病毒侵袭，又不会引发过度强烈的免疫反应"},{"label":"C","content":"蝙蝠作为一种古老的生物，已经进化出可以防御各种病毒的超级基因"},{"label":"D","content":"蝙蝠可以飞行是其能大规模广泛传播致命病毒的最重要的原因"}],"answer":"B","explanation":"A项，“蝙蝠是一种最为古老的哺乳动物的物种”在题干中未提及，无法推出。<br>B项，由“而蝙蝠的免疫系统恰恰能在与病毒共生的过程中达到一种平衡”可知，该项正确。<br>C项，题干仅是说蝙蝠的很多系统发生了变化，但可以防御各种病毒的超级基因在题干中未提及，无法推出。<br>D项，蝙蝠能大规模广泛传播致命病毒的最重要的原因在题干中也未提及，无法推出。","no":306},{"id":"1718789647106","type":"single","material":"","stem":"据介绍，北半球人口相对密集，燃烧化石燃料等人类活动不断推高碳排放量，因此北半球大气中的二氧化碳浓度在2013年已达到400PPM这一标杆水平。相对来说，南半球人类活动较少，而南极洲更是人烟稀少，但即便如此，2017年6月南极洲的二氧化碳浓度也达到了400PPM这一标杆值。<br>根据以上信息，下列推论正确的是：","options":[{"label":"A","content":"人类活动对地球的影响已经深入极地"},{"label":"B","content":"二氧化碳浓度升高对南极洲地貌有深远影响"},{"label":"C","content":"南极洲二氧化碳浓度不会再降到400PPM以下"},{"label":"D","content":"北极的二氧化碳浓度在四五年前就远超南极"}],"answer":"A","explanation":"A项，从人类活动使南极洲的二氧化碳浓度也达到了400PPM这一标杆可以推出人类活动对地球的影响已经深入极地了。<br>B项，题干只提到南极洲的二氧化碳浓度达到了400PPM,并未体现二氧化碳浓度升高对极地地貌有深远影响，不能推出。<br>C项，题干并未涉及二氧化碳浓度会不会下降的问题，南极洲二氧化碳浓度不会再降到400PPM以下同样无法推出。<br>D项，题干只提到北半球二氧化碳浓度达到400PPM比南极洲二氧化碳浓度达到<br>400PPM早四五年，北半球和北极并不是一个概念，北极的二氧化碳浓度在四五年前就远远超出，不能推出。","no":307},{"id":"1718789647107","type":"single","material":"","stem":"随着个体化医疗和临床癌症基因组研究的发展，基因检测服务需求越来越广泛。基因组学技术和靶向治疗能够为癌症患者带来巨大益处，在癌症研究领域使用基因组学技术治疗疾病对患者来说很有吸引力，所以网络上提供基因检测服务的公司越来越受追捧。但专家发现，大部分网站提供的个体化癌症诊断或治疗的基因检测项目中至少有一项没有临床应用价值。<br>由此可以推出：","options":[{"label":"A","content":"网络基因检测公司的有些服务没有临床意义"},{"label":"B","content":"并非所有的基因检测项目都是科学、准确的"},{"label":"C","content":"并非所有的基因检测项目都是跟癌症有关的"},{"label":"D","content":"个体化医疗的推广促进了基因组研究的开展"}],"answer":"A","explanation":"A项，根据“大部分网站提供的个体化癌症诊断或治疗的基因检测项目中至少有一项没有临床应用价值”可知，该项说法正确。<br>B项，题干中说的是“基因检测项目中至少有一项没有临床应用价值”,但不代表其不科学、不准确，该项无法推出，排除。<br>C项，“没有临床应用价值”不代表与癌症无关，该项无法推出，排除。<br>D项，根据“随着个体化医疗和临床癌症基因组研究的发展”可知，个体化医疗的推广和基因组研究的开展是并列关系，并非个体化医疗的推广促进了基因组研究的开展，该项无法推出，排除。","no":308},{"id":"1718789647108","type":"single","material":"","stem":"作为中国传统的经典艺术形式，书法相当独特。事实上，在现当代中国文化遭遇东西文化碰撞的情况下，涉及传统文化领域的表述面临两类尴尬：满足于传统的经验式表述，很难融入现当代语境，仿佛以文言文应对现代社会之沟通；借助西方美学、艺术理论解读传统书法，又近于隔靴搔痒，颇似传统心态解读西方文明，如同借助风水观审视修建铁路、铺设电网。<br>如果上述言论为真，那么可以推出下列()项。","options":[{"label":"A","content":"传统经验式表述很难在现当代语境中广泛传播书法之美"},{"label":"B","content":"借助西方艺术理论无法解读书法"},{"label":"C","content":"借助西方美学解读传统书法是用传统心态解读西方文明的表现"},{"label":"D","content":"书法十分独特，因此其他传统文化领域的表述并没有遭遇和书法类似的尴尬"}],"answer":"A","explanation":"A项可以由题干中“满足于传统的经验式表述，很难融入现当代语境，仿佛以文言文应对现代社会之沟通”推出。题干“借助西方美学、艺术理论解读传统书法，又近于隔靴搔痒，颇似传统心态解读西方文明”意思是说借助西方理论比较难解读传统书法，而不是B项所讲的“无法解读”,说法绝对，排除B题干“……颇似传统心态解读西方文明”,讲的是“颇似”,而不是C项的“……是用传统心态解读西方文明的表现”,说法绝对，排除C题干没有讲到其他传统文化领域的情况，D项属于无中生有，排除。","no":309},{"id":"1718789647109","type":"single","material":"","stem":"在互联网产业集群区块链技术落地应用生态系统中，有着几千万的注册会员，他们组成了庞大的消费者群体，也是互联网产业集群的具体对应物。作为传统意义上的消费者，千百年来通过自身商业消费行为，这个群体创造的价值见证了一代又一代的富翁、成功者、层出不穷的首富，他们过着纸醉金迷、灯红酒绿、令人羡慕的生活，享受着财富带来的豪宅、豪车、地位、荣耀，他们的子女可以获得优质的教育机会，得到父辈所有资源的传承。这些固然有着个人努力的成分，但是肯定与千百万人购买和使用了他们的产品与服务息息相关。<br>由此可以推出：","options":[{"label":"A","content":"互联网产业集群区块链技术的掌握者获取了大量财富"},{"label":"B","content":"互联网产业集群区块链技术的掌握者提供了吸引人的产品和服务"},{"label":"C","content":"与历史上的时代宠儿一样，互联网产业集群区块链技术是一种造富手段"},{"label":"D","content":"互联网产业集群区块链技术是未来互联网的发展趋势"}],"answer":"C","explanation":"题干讲述了在互联网产业集群区块链技术影响下，和其相关的群体的一些生活景象和产生的现象，需根据题干信息对比分析选项看是否可以推出。<br>A项，题干中只提到了该生态系统中有几千万的会员，并未提到“区块链技术的掌握者”,无法推出。<br>B项，题干中并未提到“区块链技术的掌握者”,无法推出。<br>C项，题干中提到区块链技术拥有庞大的消费者群体，而消费者造就了无数富豪，可以推出互联网产业集群区块链技术是一种造富手段，正确。<br>D项，“发展趋势”在原文中没有提及，无法推出。","no":310},{"id":"1718789647110","type":"single","material":"","stem":"某公司公布了公司员工年终考核结果，现择其一部分内容列表如下：<div class=\"image-block\"><img src=\"assets/img/2197a139ffef42.png\" alt=\"图片_rId5\"></div>\n根据上述信息，下列论断最为准确的是：","options":[{"label":"A","content":"由于所列人员分处不同的年龄段，所以所列的考核结果一定是所有的考核结果类型"},{"label":"B","content":"由于所列人员不一定展示所有的考核结果类型，所以所列的考核结果可能不是所有的考核结果类型"},{"label":"C","content":"由于所列人员并非公司的所有人员，所以所列的考核结果一定不是所有的考核结果类型"},{"label":"D","content":"由于所列人员涉及了所有的部门，所以所列的考核结果一定是所有的考核结果类型"}],"answer":"B","explanation":"题干给出了8名员工的年终考核结果，根据表格内具体内容，再结合选项进行分析。<br>A项，题干所列人员分出不同年龄段，但相同年龄段的考核结果类型不一定相同，所以不能推出考核结果一定是所有的考核结果类型，无法推出。<br>B项，由于所列人员不一定展示所有的考核结果类型，所以所列的考核结果可能不是所有的考核结果类型，强调的是一种可能性，可以推出。<br>C项，题干所列人员并非公司的所有人员，但其他人员有可能也符合以上这些考核结果类型，因此也有可能列出了所有的考核结果类型，无法推出。<br>D项，题干所列人员涉及了所有的部门，但有一个部门可以有多种考核结果类型，因此不一定就列出了所有的考核结果类型，无法推出。","no":311},{"id":"1718789647111","type":"single","material":"","stem":"猫的粪便中含有弓形虫，养猫的人可能会感染上“弓形虫病”。这种病症状跟流感很像，但对少数免疫力低下的人如孕妇，也会有致命的危险。有统计显示，许多养宠物的英国人和美国人患有弓形虫病。弓形虫病还可能通过影响多巴胺的分泌，诱发抑郁和焦虑；患弓形虫病，也可能加剧精神分裂症和双向情感障碍的症状。<br>根据上述描述，以下推论正确的是：","options":[{"label":"A","content":"猫本身并不会患弓形虫病"},{"label":"B","content":"不养猫的人不会患上弓形虫病"},{"label":"C","content":"孕妇养猫会导致胎儿的发育畸形"},{"label":"D","content":"猫便处理不当会威胁养猫人的身心健康"}],"answer":"D","explanation":"A项，题干只提到了猫的粪便中含有弓形虫，无法推出猫本身是否有弓形虫病，错误。<br>B项，否定前项无法推出否定的后项，由养猫的人可能患上弓形虫病无法推出不养猫的人不会患上弓形虫病，错误。<br>C项，题干只说弓形虫病对孕妇可能有致命的危险，无法推出是否会导致胎儿发育畸形，错误。<br>D项，猫便中含有弓形虫，养猫的人处理不当可能会感染弓形虫病，从而影响身心健康，正确。","no":312},{"id":"1718789647112","type":"single","material":"","stem":"汽车行业作为制造业中技术含量、智能化程度和产业集中度较高的代表，已经成为德国“工业4.0”的先导阵地。长期处于2.0工业思维的中国汽车制造业要在全球占有一席之地，进行技术创新与变革和拥有丰富经验的资深人才必不可少，而高薪和福利成为吸引人才的制胜法宝。<br>由此可以推出：","options":[{"label":"A","content":"如果能够吸引到资深人才，中国汽车制造业的改革就能成功"},{"label":"B","content":"高薪和福利是很多中国职场人士选择职业时的一个重要关注点"},{"label":"C","content":"不进行技术变革，中国汽车制造业就不能在全球占有一席之地"},{"label":"D","content":"德国汽车制造业在世界汽车行业具有举足轻重的地位和影响力"}],"answer":"C","explanation":"由题干中关键词“必不可少”可确定逻辑关系，根据所给逻辑关系来判断选项正确与否。题干的逻辑关系为：中国汽车制造业要在全球占有一席之地→进行技术创新与变革和拥有丰富经验的资深人才。<br>A项，因为题干中并未提及汽车制造业如何才能变革成功的问题，由题干无法推出。<br>B项，题干只说“高薪和福利成为吸引人才的制胜法宝”,但并未涉及“中国职场人士”的全部情况，不能由题干推出。<br>C项，否定后件可以推出否定前件，正确。<br>D项，也不能由题干信息得出。","no":313},{"id":"1718789647113","type":"single","material":"","stem":"目前在野生动物园管理方面，主要是依据《城市动物园管理规定》等相关规定、通知、意见。相关文件中虽然有动物园安全管理方面的规定，但并没有明确规范野生动物园自驾游。不过，每个野生动物园在自驾游方面都有自己的规定。<br>如果上述陈述属实，则下列哪项推断是正确的?","options":[{"label":"A","content":"在野生动物园进行自驾游并非没有规则可以遵循"},{"label":"B","content":"在野生动物园自驾游可以不必遵守《城市动物园管理规定》"},{"label":"C","content":"《城市动物园管理规定》不允许野生动物园开展自驾游项目"},{"label":"D","content":"《城市动物园管理规定》中有关安全管理的规定有重大疏漏"}],"answer":"A","explanation":"题干的细节信息：①相关文件中有动物园安全管理方面的规定，但并没有明确规范野生动物园自驾游；②每个野生动物园在自驾游方面都有自己的规定。<br>A项，由题干的细节信息②可以得知，在野生动物园进行自驾游可以遵循各动物园在自驾游方面的规定，可以推出。<br>B项，由题干的细节信息①可以得知，文件只是没有明确规范，但没有说明不必遵守，无法推出。<br>C项，由题干的细节信息①可以得知，文件只是没有明确规范，但没有说明不允许开展自驾游，无法推出。<br>D项，题干只涉及自驾游，未涉及安全管理的重大疏漏，无法推出。","no":314},{"id":"1718789647114","type":"single","material":"","stem":"科学研究表明，评判性的阅读是一个要求很高且需要付出相当大耐性的阅读过程。在进行审慎评判的过程中，阅读者需要放缓阅读速度，并用手中的笔随时在文章中标记出需要注意的各项重点，从而使阅读内容很好地结合阅读者的读后感想以及相关结论和疑问。因而在这一过程中，阅读者需要成为一个积极的参与角色。<br>下列最能概括上述内容的是：","options":[{"label":"A","content":"评判性的阅读是一个缓慢、枯燥但十分必要的阅读过程"},{"label":"B","content":"阅读者需要养成质疑所阅读的内容的习惯"},{"label":"C","content":"评判性的阅读应该发生在我们每天的阅读过程之中"},{"label":"D","content":"评判性的阅读需要集中注意力并认真思考"}],"answer":"D","explanation":"题干主旨大意：“评判性的阅读”需要付出相当大的耐性，需要慢速阅读并在文章中标记重点，以此展现出读者的读后感以及相关结论和疑问。<br>A项，“枯燥”在题干中并未提及，无法得出。<br>B项，题干中说的是“疑问”而非“质疑”,属于偷换概念，无法得出。<br>C项，题干并未说明要每天都进行评判性的阅读，属于无中生有，无法得出。<br>D项，指出评判性的阅读需要集中注意力并认真思考，符合题干内容，可以得出。","no":315},{"id":"1718789647115","type":"single","material":"","stem":"<p>某公司近两年的业绩均呈下滑趋势。该公司拟采取裁员政策，以淘汰不合格的员工。不合格的员工一定是存在的，但是如何确定哪一位员工是不合格的却是一个需要深入思考的问题。比如，一个在同一岗位上工作超过5年的员工可能比一个刚刚转岗进入新岗位的员工的工作效率高。但是一直在原岗位工作的员工可能不如转岗后依然可以完成岗位工作的员工的综合素质强。</p><p>由此可以推出：</p>","options":[{"label":"A","content":"该公司为扭转业绩而实行裁员政策是不可取的"},{"label":"B","content":"该公司应通过调动员工岗位来扭转业绩"},{"label":"C","content":"该公司应通过员工的在岗时间来评定该员工的工作能力"},{"label":"D","content":"该公司还没有找到扭转公司业绩的有效措施"}],"answer":"D","explanation":"题干中公司想要通过裁员来淘汰不合格的员工，以扭转业绩下滑的趋势，但是并不能确定哪个是不合格的员工，因此这一措施并不能有效实施，可以推出D。由题干只能推出不能确定员工是否合格，并不能推出实行裁员的政策是否可取，A项不能推出。B项，调动员工岗位题干未提及，不能推出。C项，“通过员工在岗时间来评定工作能力”与题干内容不符，不能推出。","no":316},{"id":"1718789647116","type":"single","material":"","stem":"研究显示，黑、灰色汽车是盗贼的最爱，亮色汽车很少被问津，白色汽车失窃率最低。心理学家分析认为，偷车贼往往有“黑暗型人格”,选择和自己性格颜色相反的汽车倒卖，让他们感觉不踏实。相比新款或豪车而言，盗车贼偏好有着三年车龄左右的大众车型，这种车保值且好转手。<br>根据上文，最有可能推出的是：","options":[{"label":"A","content":"三年车龄的红色大众车型最易被盗"},{"label":"B","content":"暗色系汽车在二手车市场最为畅销"},{"label":"C","content":"崭新的白色豪华汽车不容易被盗"},{"label":"D","content":"最畅销的车型也是最易被盗的车型"}],"answer":"C","explanation":"A项，红色不是容易被盗的颜色，“最易被盗”太过绝对。<br>根据题干只能得知偷车贼偏爱暗色系汽车，并不能由此说明其在二手车市场上最为畅销，B项不能推出。<br>根据题干可知，崭新的、白色的、豪华的汽车均属于相对不容易被盗的汽车，进而可知C项正确。<br>D项，最畅销的车型和最易被盗的车型没有必然联系，不能推出。","no":317},{"id":"1718789647117","type":"single","material":"","stem":"“同票同权”体现了对农民参政权利的尊重，有利于让更多基层代表反映广大农民真实的心声、愿望，也有利于在建设社会主义新农村的过程中构建和谐城乡格局。<br>由此可以推出：","options":[{"label":"A","content":"“同票同权”是建设和谐社会的必由之路"},{"label":"B","content":"“同票同权”会提高农民参政的积极性"},{"label":"C","content":"政府加大了对农民参政权利的重视力度"},{"label":"D","content":"农民的参政权利需要依靠有效的政策加以保障"}],"answer":"B","explanation":"题干的细节信息：①对农民参政权利的尊重；②有利于让更多基层代表反映广大农民真实的心声、愿望；③有利于在建设社会主义新农村的过程中构建和谐城乡格局。<br>A项，建设和谐社会未在题干的细节信息中涉及，无法推出。<br>B项，“同票同权”能反映广大农民真实的心声、愿望，因此会提高农民参政的积极性，可以推出。<br>C项，细节信息①只涉及对农民参政权利的尊重，未涉及对农民参政权利的重视力度，无法推出。<br>D项，农民的参政权利需要依靠有效的政策加以保障，未在题干的细节信息中涉及，无法推出。","no":318},{"id":"1718789647118","type":"single","material":"","stem":"在一项实验中，研究者让大学生回忆他们在高中时期的成绩，并告知他们，研究者将会从高中获取其真实成绩，所以撒谎没有任何意义。结果显示：参与者回忆起的成绩有五分之一都和实际不符，而不同等级的成绩，被误记的概率也是不同的。分数越高越不容易记错：得了A的时候总是能准确地被回忆起来，但得了F的时候却难以被想起。<br>根据上述信息，可以推出的是：","options":[{"label":"A","content":"错误的记忆可以保护我们对公平正义的信念"},{"label":"B","content":"错误的记忆让我们自我感觉良好，利于健康"},{"label":"C","content":"人们记忆中的成绩可能比真实的成绩更优秀"},{"label":"D","content":"一般来说，人们最擅长的就是对细节的遗忘"}],"answer":"C","explanation":"A项，题干中只是让大学生回忆他们在高中时期的成绩，并不涉及“对公平正义的信念”,因此该项无法推出。<br>B项，题干中只是让大学生回忆他们在高中时期的成绩，“利于健康”在题干中并未提及，因此该项无法推出。<br>C项，通过得了A的时候总是能准确地被回忆起来，得了F的时候却难以被想起，可以看出，人们更能记住优秀的成绩而难以想起不好的成绩，则记忆中的成绩可能比真实成绩更优秀，因此该项可以推出。<br>D项，能记住优秀的成绩代表人们并非对所有的细节都会遗忘，该项说法错误。","no":319},{"id":"1718789647119","type":"single","material":"","stem":"早期宇宙只含有最轻的元素：氢和氦。重一点的元素，如碳，只在恒星发生核反应时产生，并在恒星爆炸时散发出来，存在于随后形成的气云之中。最近发现某气云在40亿年前就含有碳，那时该处宇宙中只有年龄不超过20亿年的恒星。<br>由此可以推出：","options":[{"label":"A","content":"气云中的碳此后形成了恒星的一部分"},{"label":"B","content":"截至目前无一恒星与气云同样古老"},{"label":"C","content":"气云中也同时含有氢和氦两种元素"},{"label":"D","content":"该气云中碳的形成不超过60亿年"}],"answer":"D","explanation":"由题干信息可知，碳只有在恒星发生核反应时产生，然后在恒星爆炸时散发出来，才能存在于之后形成的气云之中。<br>A项，气云中的碳是否参与恒星的形成文中无涉及，无法推出。<br>B项，恒星爆炸形成气云，但是否存在新的恒星与气云同样古老文中没有涉及，无法推出。<br>C项，气云中的具体成分文中无涉及，无法推出。<br>D项，该气云在40亿年前就含有碳，而那时该处宇宙中恒星的最大年龄为20亿年，碳的形成不可能早于恒星的形成，所以该气云中碳的形成不超过60亿年，可以推出。","no":320},{"id":"1718789647120","type":"single","material":"","stem":"有研究发现，那些每天坐着看电视和工作总计达10小时的女性，与每天通常坐8小时的女性相比，患结肠癌的风险增加8%,患子宫癌的风险增加10%,而且无论研究对象在不坐时有多活跃，都不会影响这个结果。<br>由此可以推出：","options":[{"label":"A","content":"缺乏运动可能是某些癌症的首要病因"},{"label":"B","content":"久坐可能对女性健康造成不良的影响"},{"label":"C","content":"工作之余的体育锻炼可以强身健体"},{"label":"D","content":"上班族职业女性的身体健康状况堪忧"}],"answer":"B","explanation":"A项，题干只说每天坐10小时的女性与每天坐8小时的女性相比，患相应疾病的风险增加，并不代表缺乏运动是这些疾病的首要病因，该项属于过度推断，排除。<br>B项，根据女性坐的时间越长，患结肠癌、子宫癌等疾病的风险就越高，可知久坐可能对女性健康造成不良影响，该项正确。<br>C项，题干只涉及久坐对女性的影响，并未提到体育锻炼的作用，该项无法由题干推出。<br>D项，题干只说久坐会对女性健康产生影响，但是上班族并不一定都需要久坐，所以不能推出上班族职业女性的身体状况堪忧，该项属于过度推断，排除。","no":321},{"id":"1718789647121","type":"single","material":"","stem":"研究者对一万名平均年龄65岁的男女进行追踪研究，评估他们是否存在抑郁以及中风发病情况。研究开始时这些人均无中风史。研究发现，持续存在重度抑郁症与中风风险增加一倍以上相关，而那些无抑郁症状或症状较轻的参与者的中风风险则并未增加。曾经存在重度抑郁症状的患者，即使其症状在访谈期间已然缓解，他们的中风风险仍然与那些始终存在重度抑郁症的人相比无显著差异。<br>以上陈述如果为真，可以推出：","options":[{"label":"A","content":"重度抑郁极有可能会发展演变为中风"},{"label":"B","content":"中风患者人群中患抑郁症的概率也比较高"},{"label":"C","content":"正患有或曾患有重度抑郁均是中风的风险因素"},{"label":"D","content":"抑郁和中风均为老年常见疾病，经常一起发病"}],"answer":"C","explanation":"题干只是说重度抑郁症和中风风险增加相关，A项属于过度推断。题干并未提及中风患者人群中患抑郁症的概率，B项推不出。<br>C项，可以推出。<br>D项，抑郁和中风是否一起发病，也不能推出。","no":322},{"id":"1718789647122","type":"single","material":"","stem":"地铁每节车厢门旁边通常会有警告标志：“停车请拉下紧急制动开关，擅动将负法律责任。”<br>上述警告标志适用的情况是：<br>I.一些乘客会无故使用或误用紧急制动开关<br>Ⅱ.在某些特殊情况下，可能有乘客需要使运行的列车停下","options":[{"label":"A","content":"只有情况I适用"},{"label":"B","content":"只有情况Ⅱ适用"},{"label":"C","content":"情况I和Ⅱ都适用"},{"label":"D","content":"情况I和Ⅱ都不适用"}],"answer":"C","explanation":"题干给出了地铁车厢门旁的警告标志，由两句话组成，分别理解这两句话的含义，分析这两句话分别适用于何种情况，即可得出答案。题干的警告标志“停车请拉下紧急制动开关”,说明在某些特殊情况下，可能有乘客需要使运行的列车停下，那么此时可以拉下紧急制动开关，即情况Ⅱ适用；“擅动将负法律责任”说明在正常情况下是不允许拉下开关的，但一些乘客可能会无故或误用紧急制动开关，此时将要负法律责任，即情况I适用。","no":323},{"id":"1718789647123","type":"single","material":"","stem":"一天，某老年服务中心管理人员给老年人安排活动：上午，在服务中心养老的男性老年人练习太极，女性老年人参加合唱练习；午休后，体力较弱的老年人安排室内活动，体力较强的老年人在室外活动。<br>由此可以推出的是：","options":[{"label":"A","content":"在该中心养老的张婆婆午休后在室内活动"},{"label":"B","content":"并非在该中心养老的男性老年人上午都练习太极"},{"label":"C","content":"在该中心养老的男性老年人午休后不能在室外活动"},{"label":"D","content":"有部分在该中心养老的老年人可能不参加任何活动"}],"answer":"D","explanation":"A项，题干中说“午休后，体力较弱的老年人安排室内活动”,由于不知道张婆婆的体力情况，该项无法推出。<br>B项，等值于“有的在该中心养老的男性老年人上午不练习太极”,与题干中的“上午，在服务中心养老的男性老年人练习太极”矛盾，该项无法推出。<br>C项，题干中说“午休后，体力较弱的老年人安排室内活动，体力较强的老年人在室外活动”,由于不知道男性老年人的体力情况，该项无法推出。<br>D项，说的是可能的情况，是一种推测，可以由题干推出。","no":324},{"id":"1718789647124","type":"single","material":"","stem":"调查显示，中国消费者对奢侈品品牌的忠诚度远远低于西方消费者，对许多中国消费者而言，高价格仍然很重要，物有所值仍然比品牌重要，而且现阶段甚至比质量还重要。<br>由此可以推出：","options":[{"label":"A","content":"中国消费者喜欢购买价格高且物有所值的奢侈品"},{"label":"B","content":"中国消费者购买奢侈品时往往不会考虑价格因素"},{"label":"C","content":"中国消费者不甚关注知名奢侈品的价格及其质量"},{"label":"D","content":"比起知名度来，奢侈品的价格更吸引中国消费者"}],"answer":"A","explanation":"A项，由“高价格仍然很重要，物有所值仍然比品牌重要，而且现阶段甚至比质量还重要”可以推出。<br>B项，由“对许多中国消费者而言，高价格仍然很重要”可推出B项错误。<br>C项，由“对许多中国消费者而言，高价格仍然很重要”可知，消费者会关注价格。<br>D项，题干中说“高价格仍然很重要，物有所值仍然比品牌重要，而且现阶段甚至比质量还重要”,没有提到价格与品牌知名度的比较，D项无法推出。","no":325},{"id":"1718789647125","type":"single","material":"","stem":"研究小组利用超级计算机模拟宇宙，并结合多种其他计算，证明了在我们这个加速膨胀的宇宙中，描述大尺度时空结构的因果关系网络曲线图，是一个具有显著聚类特征的幂函数曲线，和许多复杂网络如互联网、社交网、生物网络等惊人的相似。<br>由此可以推出：","options":[{"label":"A","content":"人脑研究有助于了解宇宙的结构"},{"label":"B","content":"宇宙就是一个大脑或一台计算机"},{"label":"C","content":"复杂系统演化存在某种相似法则"},{"label":"D","content":"宇宙万物的演化遵循同样的规律"}],"answer":"C","explanation":"A项，人脑研究题干并未涉及，无法推出。<br>B项，宇宙就是一个大脑或计算机，与题干说法不符。<br>C项，由“具有显著聚类特征的幂函数曲线，和许多复杂网络如互联网、社交网、生物网络等惊人的相似”可知，题干重点强调互联网和宇宙具有相似的运行规律，可以推出。<br>D项，遵循同样的规律，与题干说法不符。","no":326},{"id":"1718789647126","type":"single","material":"","stem":"一项研究发现，生活贫困能够导致人们的某种基因发生变化，这种基因能够增强负责应对恐慌的大脑区域活动，比如杏仁核的活动增加会导致患上抑郁症的风险增加。同时，较低的社会经济状况与低水平的血清素之间也存在关联，进而增加抑郁症的患病风险。研究员还发现，这种基因变化也会传递给后代。<br>根据上述研究，可以得知：","options":[{"label":"A","content":"生活贫困会通过影响生理而对精神健康产生作用"},{"label":"B","content":"社会经济地位较高的人群患抑郁症的风险较低"},{"label":"C","content":"穷困阶层因基因的变化而使得贫穷和疾病多代延续"},{"label":"D","content":"杏仁核活动增强的同时，血清素水平降低"}],"answer":"A","explanation":"A项，生活贫困会通过影响生理而对精神健康产生影响，由题干较低的社会经济状况与低水平的血清素之间也存在关联，进而增加抑郁症的患病风险，可以推出此结论。分享<br>B项，社会经济地位较高的人在题干中没有体现，所以无法推出此结论。<br>C项，题干只是说基因变化会遗传给后代，并未提到会使贫穷和疾病多代延续，无法推出此结论。<br>D项，杏仁核与血清素在题干中并未提到有相关性，无法推出彼此关系。","no":327},{"id":"1718789647127","type":"single","material":"","stem":"根据统计结果，2006年至2016年，我国处于世界前1%的高被引论文为1.69万篇，占世界总数的12.8%,超过德国排在世界第3位；我国近两年间发表的论文得到大量引用，被引用次数进入本学科前1‰的国际热点论文为5篇，占世界总数的18.0%,世界排名首次达到第3位。此外，我国8个学科领域的论文被引用次数排名世界第2位，包括农业科学、化学、计算机科学、工程技术、材料科学、数学、药学与毒物学、物理学。这表明，近年来我国科技论文的国际影响力持续提升。<br>由此可以推出：","options":[{"label":"A","content":"近两年国家创新驱动发展战略取得明显实效"},{"label":"B","content":"排名靠前的高被引论文占比和论文的国际影响力密切相关"},{"label":"C","content":"我国农业科学处于世界前1%的高被引论文占世界总数超过12.8%"},{"label":"D","content":"近两年间发表的被引用次数进入本学科前1‰的国际热点论文总数超过2000篇"}],"answer":"B","explanation":"题干根据一系列数据得出“近年来我国科技论文的国际影响力持续提升”的结论。<br>A项，“国家创新驱动发展战略”在题干中并未涉及，无法由题干推出，排除。<br>B项，根据题干一系列数据和最后得出的结论可知该项正确。<br>C项，题干中说的是“我国处于世界前1%的高被引论文为1.69万篇，占世界总数的12.8%”,并未明确指出是“农业科学”,因此该项由题干内容无法得出，排除。<br>D项，根据“我国近两年间发表的论文得到大量引用，被引用次数进入本学科前1%的国际热点论文为5篇”可知该项错误，排除。","no":328},{"id":"1718789647128","type":"single","material":"","stem":"在现代音乐制作领域中，音乐创作被弃之一旁，取而代之的是音乐工业，它如同其他工业领域一样，强调的是标准化和一致性，因而流行音乐最典型的特征包括朗朗上口的曲调、副歌以及标准化节奏(一节四拍)。<br>下列()项最适合作为上文论述的结论。","options":[{"label":"A","content":"现代流行音乐的典型特征是由音乐工业的要求决定的"},{"label":"B","content":"音乐工业对标准化和一致性的要求与其他工业没有区别"},{"label":"C","content":"音乐创作在现代已经完全消失了"},{"label":"D","content":"流行音乐应该具备的典型特征包括朗朗上口的曲调、副歌以及标准化节奏(一节四拍)"}],"answer":"A","explanation":"根据题干“音乐创作被弃之一旁，取而代之的是音乐工业……因而流行音乐最典型的特征包括……”可知，现代流行音乐的典型特征是因为音乐工业的要求，A项正确。文段只是提到音乐工业也像其他工业一样强调标准化和一致性，而不是说其标准和一致性没有区别，B项错误。音乐创作并非完全消失，C项过于绝对。文中讲的是流行音乐最典型的特征，而D项讲的是流行音乐“应该具备”什么,和文意不符。","no":329},{"id":"1718789647129","type":"single","material":"","stem":"每个世纪都有哲学家和艺术家提出“美”和“丑”的定义，但是至今也没有一个完全一致的定义。<br>假设定义“丑是美的反面”为真，那么:","options":[{"label":"A","content":"任何事物都有美丑两面"},{"label":"B","content":"没有美也就没有丑"},{"label":"C","content":"不美不丑是存在的"},{"label":"D","content":"美和丑是无法辨别的"}],"answer":"B","explanation":"“丑是美的反面”可以理解为丑和美是矛盾的，二者非此即彼，即同一事物要么是美的，要么是丑的，既不会同时存在美丑两面，也不会存在不美不丑的情况，A、C两项错误。由于“丑是美的反面”为真，那么没有美也就没有美的反面，即没有丑，B项正确。D项，对于美和丑的辨别题干中没有提到，不能推出。","no":330},{"id":"1718789647130","type":"single","material":"","stem":"在人际交往的过程中，容貌是最容易观察到的属性特征。和容貌普通的人相比，容貌有吸引力的个体，往往被认为具有较高的能力、较为积极的人格特征和较好的人际关系，甚至收入水平和个人幸福指数也会比较高。在工作中，当相同的任务被不同人完成时，通常顾客会对容貌姣好员工的服务质量给予相对较高的评价。<br>由此可以推出：","options":[{"label":"A","content":"随着容貌吸引力越来越大，人们对其个性特征的评价越来越好"},{"label":"B","content":"企业应选择容貌姣好的人为员工，以提高顾客的服务满意度"},{"label":"C","content":"简历不应附带照片，因为照片会影响招聘者决策的公平性"},{"label":"D","content":"发表文章时提供作者的照片，可以提高读者对文章质量的评价"}],"answer":"B","explanation":"A项，题干中并没有程度的比较变化，不能推出。<br>B项，根据题干“通常顾客会对容貌姣好员工的服务质量给予相对较高的评价”,说明选择容貌姣好的人为员工，确实可以提高顾客的服务满意度，可以推出。<br>C项，题干中说的是人际交往过程中和工作中，并没有提到简历招聘，不能推出。<br>D项，在题干中并未提及，不能推出。","no":331},{"id":"1718789647131","type":"single","material":"","stem":"外界环境中的阳光辐射、空气污染等都会使人体产生更多活性氧自由基。体内活性氧自由基正是人类衰老的根源，而抗氧化剂可以有效清除体内多余的自由基。<br>如果以上描述为真，下列哪项一定是正确的?","options":[{"label":"A","content":"清除体内多余的自由基，要么避免阳光辐射和空气污染，要么摄入抗氧化剂"},{"label":"B","content":"人的衰老速度可能由环境决定，也可能受抗氧化剂的影响"},{"label":"C","content":"严重的空气污染会影响人的衰老速度和抗氧化剂的效果"},{"label":"D","content":"抗氧化剂能够有效延长人的寿命"}],"answer":"B","explanation":"A项，题干只说抗氧化剂可以有效清除体内多余的自由基，但并未说明避免阳光辐射和空气污染也具有同样的作用，该项无法由题干推出。<br>B项，题干的意思为，外界的环境会使人产生更多的活性氧自由基；体内的活性氧自由基是人类衰老的根源，而抗氧化剂可以清除多余的自由基。所以人的衰老速度可能由环境决定，也可能受抗氧化剂的影响，该项说法正确。<br>C项，根据题干信息，严重的空气污染可能会影响人的衰老速度，但是否会影响抗氧化剂的效果在题干中并未提及，无法推出。<br>D项，题干论述的是衰老，而非寿命，该项无法由题干推出。","no":332},{"id":"1718789647132","type":"single","material":"","stem":"柠烯，俗称柠檬精油。它通常被用于制作柑橘香味剂，是很多空气清新剂、身体喷雾剂等芳香剂重要的化学成分之一。柠烯本身并不可怕，因为该化学物质对人体不会形成大的危害，事实上，它可被用于食品的调味剂。然而柠烯一旦被喷入空气中，很快就会有所变化。研究表明，当柠烯暴露于普遍存在于空气的臭氧中时，两个柠烯分子会形成一个单分子化合物——甲醇。当房间中大量的柠烯被转化成甲醇时，其影响将迥然不同。<br>由此可以推出：","options":[{"label":"A","content":"使用空气清新剂，可能会对我们自身有害处"},{"label":"B","content":"柠烯被用作食品的调味剂时，会对人体产生危害"},{"label":"C","content":"如果房间中测出甲醇浓度高，则说明使用了太多芳香剂"},{"label":"D","content":"在生活中，我们应该尽量避免使用含有柠烯成分的物品"}],"answer":"A","explanation":"A项，由题干最后两句柠烯在臭氧中会形成甲醇，可知A项正确。<br>B项，题干说“柠烯本身并不可怕，因为该化学物质对人体不会形成大的危害，事实上，它可被用于食品的调味剂”,因此B项错误。<br>C项，造成房间甲醇浓度高的原因有很多，并不一定是使用了太多芳香剂。<br>D项，是否应该避免使用含有柠烯成分的物品，题干中并未提及，不能推出。","no":333},{"id":"1718789647133","type":"single","material":"","stem":"在日常的阅读与交流中，人们往往根据他们的常识来理解读到或听到的一句话究竟是什么含义。为了方便说不同语言的人们之间的交流，科学家们希望能够发明一种翻译机器。目前各种类型的翻译机器虽然能够很容易地掌握各种语言的语法规则，但要它们拥有人们的常识却完全是另外一回事，科学家在现阶段还难以做到让翻译机器准确理解日常语句的含义并在此基础上进行准确的翻译。<br>下列哪项可以从上文中推导出来?","options":[{"label":"A","content":"翻译机器不可能掌握一种语言的语法规则"},{"label":"B","content":"在日常交流中，人们对比较简单的语句的理解往往不会诉诸语法规则"},{"label":"C","content":"对日常语句的准确理解依赖于人们的常识"},{"label":"D","content":"翻译机器如果能掌握一种语言的语法规则，就能理解该语言中的语句含义"}],"answer":"C","explanation":"题干的细节信息：①人们往往根据他们的常识来理解读到或听到的一句话究竟是什么含义；②翻译机器能够很容易地掌握各种语言的语法规则，但难以做到准确理解日常语句的含义并在此基础上进行准确的翻译。<br>A项，不可能掌握一种语言的语法规则，与细节信息②相矛盾，无法推出。<br>B项，文中只说在日常的阅读与交流中，人们往往根据常识来理解读到或听到的话的含义，却没有说是不是会诉诸语法规则，无法推出。<br>C项，对日常语句的准确理解依赖于人们的常识，符合细节信息①,可以推出。<br>D项，翻译机器如果能掌握一种语言的语法规则，就能理解该语言中的语句含义，与细节信息②相矛盾，无法推出。","no":334},{"id":"1718789647134","type":"single","material":"","stem":"两个小组参加汽车零部件拆装速度测试比赛。所有参赛者平均每人每天8小时可以拆装18组零部件。其中，第一小组的平均速度是每人每天8小时拆装26组零部件；第二小组的平均速度是每人每天8小时拆装14组零部件。通过测试赛，该汽车零部件的制造商认为该零部件的设计需要进一步简化。<br>由此可见：","options":[{"label":"A","content":"第一小组的参赛者动手能力均优于第二小组"},{"label":"B","content":"第二小组的参赛人员比第一小组的参赛人员多"},{"label":"C","content":"所有参赛者的零部件拆装速度均不达标"},{"label":"D","content":"所有参赛者的动手能力在比赛结束后都得到加强"}],"answer":"B","explanation":"由题干可知，所有人平均每人每天可以拆装18组零部件，第一组为26组，和总平均值差额为8组；第二组为14组，和总平均值差额为4组，通过比例可知第二组人数要比第一组人数多，B项正确。<br>A项，题干中只给出平均值，不能推出每个人的情况，“均优于”推不出。<br>C项，是否达标在题干中并未提及，不能推出。<br>D项，动手能力有没有提升的问题在题干中也未提及，不能推出。","no":335},{"id":"1718789647135","type":"single","material":"","stem":"车主信息会影响汽车保费，比如年龄较大、女性、高学历的车主，保费相对较低，25岁以下的年轻人保费较高，出过交通事故的车主保费高；另外，汽车价格、车型、车龄甚至颜色都会影响保险费用。高价新车不一定比低价旧车保费贵。因为新车、好车的防盗装置、安全装置多；特定车型颜色鲜艳的车保费贵，比如爱开红色跑车的人，性格比较奔放，开车时相对不太谨慎。<br>根据上文，最有可能推出的是：","options":[{"label":"A","content":"有过交通事故的红色跑车的18岁男性车主所交的保费高"},{"label":"B","content":"开豪华跑车的女性要比开平价汽车的男性所交的保费高"},{"label":"C","content":"大龄、有研究生学历并购买新车的女性车主所交的保费低"},{"label":"D","content":"谨慎细致的车主要比奔放活泼的车主所交的保费低"}],"answer":"A","explanation":"由题干可知，涉及保费高低的因素有：车主年龄、性别、学历、是否出过<br>交通事故、车价、车龄、车型、车的颜色等。<br>A项，有过交通事故、红色、年龄属于25岁以下、男性均是保费较高的因素，最有可能推出。<br>B项，女性的保费比男性低，且高价新车不一定比低价旧车的保费贵，因此B项可能性低。<br>C项，尽管大龄和高学历女性保费较低，但是新车的保费还受很多方面的影响，因此不一定低。<br>D项，还受很多其他方面的影响，也不一定会低。","no":336},{"id":"1718789647136","type":"single","material":"","stem":"诚信乃立身之本。然而，文章抄袭、高考舞弊、民族作假、官员贪污受贿等被屡屡曝光，一旦道德体系坍塌，社会将无法继续正常运转。通过查询信用记录中的信用状况，可以在很大程度上缓解社会信息不对称问题，并对失信者形成心理上的威慑。<br>由此可以推出：","options":[{"label":"A","content":"“信用身份证”具有权威的证明力和公信力"},{"label":"B","content":"诚信证明并非保证诚信的关键"},{"label":"C","content":"诚信缺失，社会道德体系面临崩溃的边缘"},{"label":"D","content":"“信用身份证”是维护和重建社会诚信的有益尝试"}],"answer":"D","explanation":"题干的细节信息：①一旦道德体系坍塌，社会将无法继续正常运转；②通过查询信用记录中的信用状况，可以在很大程度上缓解社会信息不对称问题，并对失信者形成心理上的威慑。<br>A项，题干只提到通过查询信用记录中的信用状况，可以对失信者形成心理上的威慑，它是否具有权威的证明力和公信力无从得知，无法推出。<br>B项，题干只提到通过查询信用记录中的信用状况，可以在很大程度上缓解社会信息不对称问题，未涉及保证诚信的关键，无法推出。<br>C项，题干只提到一旦道德体系坍塌，社会将无法继续正常运转，未涉及崩溃的边缘，无法推出。<br>D项，题干提出通过查询信用记录中的信用状况，可以在很大程度上缓解社会信息不对称问题，并对失信者形成心理上的威慑。因此，“信用身份证”是维护和重建社会诚信的有益尝试。可以推出。","no":337},{"id":"1718789647137","type":"single","material":"","stem":"按照科学的本义，科学是理性；哲学是高度理性化的，它当然也是科学。所以，在哲学的历史上，它长期扮演了包罗万象的“科学的科学”这样的角色，直到马克思主义哲学诞生，才正确处理好科学同哲学的关系。但在古老的大学里，哲学博士才是真正的科学博士。<br>根据这段文字，下列推断正确的是：","options":[{"label":"A","content":"科学一直是哲学的一个分支"},{"label":"B","content":"马克思主义哲学科学与哲学完全割裂了关系"},{"label":"C","content":"哲学和科学都是理性的"},{"label":"D","content":"科学是哲学，哲学是科学"}],"answer":"C","explanation":"题干的细节信息：①哲学是高度理性化的，它当然也是科学；②马克思主义哲学诞生，才正确处理好科学同哲学的关系。<br>A项，哲学是高度理性化的，它当然也是科学，说明哲学是科学的一种，科学的范围更大，因此，科学一直是哲学的一个分支的推断错误。<br>B项，马克思主义哲学诞生，才正确处理好科学同哲学的关系，推不出马克思主义哲学科学与哲学完全割裂了关系。<br>C项，科学是理性，哲学是科学的一种，所以哲学和科学都是理性的，推断正确。<br>D项，哲学是高度理性化的，它当然也是科学，说明哲学是科学，但根据题干无法推出科学是哲学，推断错误。","no":338},{"id":"1718789647138","type":"single","material":"","stem":"美联储对以华尔街为中心的证券交易市场影响同样是巨大的。美国政府本身没有货币发放权，美国政府要获得美元，必须将美国的未来税收以国债的形式抵押给美联储，纽约联邦储备银行代理发行美国政府各种债券，并投入证券交易市场。更重要的是，美联储对美元发放数量和利率的调整直接影响华尔街的走势，甚至全球经济。<br>根据以上论述，可以推出的是：","options":[{"label":"A","content":"美元的发放和利率的调整可能是美国政府影响世界经济的一个重要手段"},{"label":"B","content":"美联储是美国联邦政府的一个部门"},{"label":"C","content":"美联储发行美元的条件是美国政府将税收以国债的形式抵押给美联储"},{"label":"D","content":"美联储具体履行美国中央银行的职能"}],"answer":"A","explanation":"题干的细节信息：①美联储可以影响华尔街的走势、证券交易市场和全球经济；②如果美国政府要获得美元，就必须将美国的未来税收以国债的形式抵押给美联储。<br>A项，根据细节信息①可知，美元的发放和利率的调整可能是美国政府影响世界经济的一个重要手段，可以推出。<br>B项，美联储与美国联邦政府的关系，未在题干中涉及，无法推出。<br>C项，根据细节信息②可知，美国政府将未来税收以国债形式抵押给美联储，是美国政府获得美元的充分条件，而不是美联储发行美元的充分条件，无法推出。<br>D项，美国中央银行未在题干中涉及，无法推出。","no":339},{"id":"1718789647139","type":"single","material":"","stem":"南方地区种植棉花一般使用营养钵育苗。但是使用营养钵育苗常遇到草害问题，严重抑制棉苗生长发育。草害仅由以下两种原因之一引起：一是新选址的苗床来不及翻耕，留下的残余杂草繁殖；二是施入了未彻底腐熟的肥料，杂草籽被带入苗床，使之快速繁殖。因此，要在棉花播种后出苗前施用除草剂，可选用48%拉索乳油或72%都尔乳油，都能有效防止杂草危害。<br>由此可以推出：","options":[{"label":"A","content":"若没有杂草繁殖影响，使用棉花营养钵育苗就不会遇到草害"},{"label":"B","content":"在棉花出苗后施用除草剂的效果不佳"},{"label":"C","content":"种植棉花时有效防止了杂草危害，说明选择了上述两种除草剂中的一种"},{"label":"D","content":"使用棉花营养钵育苗的棉苗生长发育不好，说明遇到了草害问题"}],"answer":"A","explanation":"由题干可知，使用营养钵育苗遇到草害仅由两种原因造成，而两种都是因为杂草的繁殖。<br>A项，没有杂草繁殖的影响，使用棉花营养钵育苗就不会遇到草害，可以推出。<br>B项，在出苗前施用除草剂的原因不一定是出苗后施用效果不佳，无法推出。<br>C项，题干只说这两种除草剂能有效防止杂草危害，可以看成充分条件假言命题，肯定后件无法肯定前件，即防止了杂草危害也有可能是其他原因导致的，无法推出。<br>D项，题干只说使用棉花营养钵育苗常遇到草害问题，但棉苗生长不好还可能是遇到了其他问题，无法推出。","no":340},{"id":"1718789647140","type":"single","material":"","stem":"<p>研究发现，妈妈在怀孕期间经常吃什么,孩子将来就会喜欢吃什么。这是因为当胎儿在母体子宫内发育时，它会认为母体摄入的所有食物成分都是安全的，并在神经系统中记住食物的味道，作为自己今后寻找食物的依据。</p><p>以上研究中不能得出下列哪一结论?</p>","options":[{"label":"A","content":"如果孕妇怀孕期间营养不良，孩子出生后会挑食，不喜欢吃有营养的食物"},{"label":"B","content":"经常吃肉食的孕妇应注意均衡饮食，从而预防孩子出生以后过于偏爱肉食"},{"label":"C","content":"孕妇需要注意尽量不饮酒，如果胎儿感受到酒精的味道，以后酗酒的可能性会增大"},{"label":"D","content":"孕妇要保持健康的饮食习惯，多吃健康食物，有助于孩子今后拥有健康的饮食习惯"}],"answer":"A","explanation":"研究发现母亲在怀孕时经常吃什么,孩子将来就会喜欢吃什么。A项，题干说的是喜欢吃的食物种类的问题，而该项说的是营养不良，孕妇怀孕期间营养不良不一定是吃的东西没有营养，并且题干指出胎儿会在神经系统中记住食物的味道，而食物有没有营养是不能从味道上判断出来的，因此该项不能由题干研究得出。B项，孕妇经常吃肉食，孩子将来也会喜欢吃肉食，因此为了预防孩子以后偏爱肉食，孕妇应该注意均衡饮食，与题干的研究结论相符。C项，孕妇如果饮酒，孩子将来酗酒的可能性会增大，因此为了防止这种情况，孕妇要注意尽量不饮酒，与题干的研究结论相符。D项，孕妇拥有健康的饮食习惯，孩子将来也会拥有健康的饮食习惯，与题干的研究结论相符。","no":341},{"id":"1718789647141","type":"single","material":"","stem":"研究表明，近15年来全球平均气温没有显著的增温趋势，这似乎与温室气体排放造成全球变暖的大背景相矛盾。但温度变化是动力温度和辐射温度两部分造成的，对其气候效应的研究既要考虑气候系统动力因子的年代际变化，更要量化人类活动造成的辐射温度的作用。事实上，动力温度在近15年出现显著的降温趋势，而辐射温度持续上升，两者相互抵消，造成了近年来全球气温的增温停滞。<br>下列推论中正确的是：","options":[{"label":"A","content":"气候系统动力因子的年代际变化“冷却”了大气温度"},{"label":"B","content":"动力温度和辐射温度均增高导致全球变暖的大趋势"},{"label":"C","content":"气温稳定取决于动力温度与辐射温度的相同变化"},{"label":"D","content":"动力气候降温不显著造成了15年前的全球变暖"}],"answer":"A","explanation":"根据“动力温度在近15年出现显著的降温趋势，而辐射温度持续上升，两者相互抵消”可知A项正确，而C项错误。<br>根据题干，全球平均气温增温与否是由动力温度和辐射温度决定的，动力温度降温，辐射温度增温也有可能引起全球平均气温增温的趋势，故B项说法错误。<br>D项为无中生有。","no":342},{"id":"1718789647142","type":"single","material":"","stem":"有研究表明，运动，特别是大量运动，会提高人体内血清基的水平。在某种程度上，人的心情由体内血清基的水平决定。抗抑郁药物可以通过提高体内血清基的水平来起作用。<br>下列论断一定正确的是：<br>I.提高体内血清基水平，要么大量运动，要么吃抗抑郁药物<br>Ⅱ.人的心情，可能由运动量决定，也可能受抗抑郁药物影响<br>Ⅲ.大量运动会影响人的心情，或影响抗抑郁药物的疗效","options":[{"label":"A","content":"I"},{"label":"B","content":"Ⅱ"},{"label":"C","content":"I和Ⅱ"},{"label":"D","content":"Ⅱ和Ⅲ"}],"answer":"D","explanation":"题干只说明：运动和抗抑郁药物能够提高血清基水平，进而影响心情，但并未说血清基水平只受这两种方式影响，故I错误、Ⅱ正确。Ⅲ为选言命题，其中一个肢命题为真则整个命题为真，故Ⅲ正确。","no":343},{"id":"1718789647143","type":"single","material":"","stem":"大脑边缘系统驱动情绪产生，该系统在青春期期间快速发育，而前额叶皮层神经网络发育则相对较晚，主要负责提供合理判断和冲动控制。现在已经确知，前额叶皮层要到20岁左右才能完成发育成熟，而如今青春期却在不断提前，二者不匹配的时间跨度正在延长。<br>由此可以推出：","options":[{"label":"A","content":"人的某些行为与年龄的冲突是大脑存在的天然缺陷所致"},{"label":"B","content":"形成青少年行为特点的原因在于人体调控功能的晚发育"},{"label":"C","content":"人脑的独特结构使人类可以控制冲动行为的时间跨度延长"},{"label":"D","content":"人脑控制功能与边缘系统的失衡是青少年产生冲动行为的关键"}],"answer":"D","explanation":"A项，人的某些行为与年龄的冲突是因为驱动情绪产生的大脑边缘系统在青春期期间快速发育，而负责合理判断和冲动控制的前额叶皮层要到20岁左右才能发育成熟，二者存在时间跨度，并非大脑的天然缺陷所致，该项无法推出。<br>B项，题干并未提及人体调控功能晚发育的情况，该项无法推出。<br>C项，题干中说的是“二者不匹配的时间跨度正在延长”,而非可以控制冲动行为的时间跨度延长，该项无法推出。<br>D项，由题干可知，驱动情绪产生的大脑边缘系统与负责判断和控制的前额叶皮层发育成熟时间不一致，导致青少年产生冲动行为，该项正确。","no":344},{"id":"1718789647144","type":"single","material":"","stem":"随着“二孩政策”的实施，母乳喂养越来越多地成为广大年轻女性在生儿育女过程中不可回避的话题。医学专家建议，婴儿出生后最初6个月最好进行纯母乳喂养，而父母也都希望为孩子提供最好的营养。但统计显示，近年来我国0—6个月大婴儿的纯母乳喂养率却明显偏低，婴儿6个月内的纯母乳喂养率在农村为30%,在城市仅为16%。<br>以下各项如果为真，则除了哪项均能解释上述统计结果?","options":[{"label":"A","content":"职场女性往往因工作压力大、工作环境不允许等原因而陷入母乳喂养困窘"},{"label":"B","content":"母乳喂养可降低儿童患病率，给孩子健康带来的益处可一直延续到成人期"},{"label":"C","content":"很多母亲并不了解母乳喂养的种种优势，反而把配方奶粉想象得过于美好"},{"label":"D","content":"母亲因为夜晚哺乳而影响睡眠质量，她们的工作生活节奏被哺乳完全打乱"}],"answer":"B","explanation":"在题干明确矛盾现象后，排除掉能对题干现象进行合理化解释、说明该现象存在的原因的选项，剩下的即正确答案。题干矛盾现象为，父母们都希望通过母乳给孩子最好的营养，但是近年来的统计显示母乳的喂养率偏低。A项因职场女性的压力和工作环境等原因，C项因为不了解母乳喂养的种种优势，D项因为母乳喂养会影响母亲的工作生活，均能解释母乳喂养偏低的现象；B项是母乳喂养的优势，不能解释题干现象。","no":345},{"id":"1718789647145","type":"single","material":"","stem":"一般来说，幼儿的体温因阳光照射而上升的幅度比成人小。可是人们发现，在汽车车厢内，如果温度较高，幼儿很容易中暑，而成人几乎很少出现这一现象。甚至在45℃的高温环境下待在车厢里一小时，也不会中暑。<br>以下哪项如果为真，最能解释上述现象?","options":[{"label":"A","content":"在0~3岁的幼儿中，年龄越小的孩子，抵抗能力越弱"},{"label":"B","content":"随着年龄的增长，人体内的水分占体液总量的比例变小，体温的变化也不再明显"},{"label":"C","content":"车内属于密闭空间，当室外气温达到25℃~29℃时，车内温度就能达到45℃,而成人在车内感到不适时很可能会打开车窗"},{"label":"D","content":"中暑多在丧失了相当于体重3%的水分时发生，幼儿体重相对应的体表面积更大，能更快地吸收热量，由于汗腺数目与大人相同，水分流失速度更快"}],"answer":"D","explanation":"题干现象：幼儿体温因阳光照射而上升的幅度比成人小，但在车厢内温度较高的话更容易中暑。题目要求选择最能解释题干现象的一项，正确的选项必须与矛盾双方相容。<br>A项，年龄小的孩子抵抗力低，不能说明抵抗力低就容易中暑，不能解释题干中的矛盾。<br>B项，随着年龄增长，体温的变化不明显，只能说明成年人不容易中暑，不能解释幼儿更容易中暑。<br>C项，成人在车内感到不适时很可能会打开车窗，与题干矛盾无关，无法解释。<br>D项，说明了幼儿更容易中暑的原因是水分流失速度更快，解释了题干矛盾的现象。","no":346},{"id":"1718789647146","type":"single","material":"","stem":"随着移动支付的普及和知识内容消费观念的逐渐养成，知识付费逐渐成为人们普遍接受的学习方式。自2015年以来，各种知识付费平台纷纷上线，用户数量快速增长，相关报告显示，2017年我国知识内容付费用户规模达1.88亿人，知识付费正在成为人们从海量信息中突围的利器。<br>以下哪项如果为真，最能解释上述现象?","options":[{"label":"A","content":"知识付费能满足人们低门槛、高效率的学习需要"},{"label":"B","content":"粉丝可以通过知识付费方式随时向知识偶像请教"},{"label":"C","content":"知识付费可以随时满足广大网友广泛的兴趣爱好"},{"label":"D","content":"当代青年人对于新知识和新技能的渴求日趋提高"}],"answer":"A","explanation":"题干中的现象是知识付费逐渐成为人们普遍接受的学习方式。<br>A项，说明知识付费满足了人们的学习需要，所以会被人们普遍接受，解释了题干中的现象。<br>B项，粉丝和知识偶像都是特定人群，样本不具有代表性，不能完全解释题干中的现象。<br>C项，知识付费满足的是兴趣爱好，而题干说的是学习，不能完全解释题干中的现象。<br>D项，当代青年人学习新知识和新技能不一定非得通过知识付费的方式，不能解释题干中的现象。","no":347},{"id":"1718789647147","type":"single","material":"","stem":"某市高新区离老城区较远，且公交车班次很少。高新区企业的员工大部分居住在老城区，他们经常会因为无法按时坐上公交车而迟到。为此，公交车公司增加了大量高新区与老城区之间的公交车班次，以满足这些员工的乘车需求。但是经过一段时间的观察，情况并没有得到改善，这些员工依然经常迟到。<br>以下哪项为真，最能解释上述现象?","options":[{"label":"A","content":"高新区的许多企业都调整了上班时间"},{"label":"B","content":"部分原本开车上班的高新区企业员工改为乘坐公交车"},{"label":"C","content":"由于道路狭窄，公交车班次大量增加后经常出现长时间塞车"},{"label":"D","content":"许多原本乘坐公交车上班的高新区企业员工改为开车或乘坐出租车"}],"answer":"C","explanation":"题干现象：公交车班次大量增加之后，原来迟到的员工依然迟到。要解释该现象，就要说明还存在其他情况会导致员工迟到。<br>A项，企业调整了上班时间，但并没有说明是往前调还是往后调，无法解释员工迟到的现象，排除。<br>B项，原本开车上班的员工改为乘坐公交车，也不能说明员工仍然迟到的原因，无法解释题干现象，排除。<br>C项，说明了由于道路狭窄，虽然公交车的班次增加了但是长时间塞车，所以原来迟到的员工依然迟到，很好地解释了题干的矛盾。<br>D项，原本乘坐公交车上班的员工改为开车或乘坐出租车，不能说明员工仍然迟到的原因，无法解释题干现象，排除。","no":348},{"id":"1718789647148","type":"single","material":"","stem":"早在20世纪80年代，3D打印技术便横空出世，人们认为它将掀起一场革命，能改变产品的设计和制造模式，甚至改变我们的世界。然而，直到目前为止，它的应用并没有像预言那样广泛地取代传统制造行业。<br>以下哪项如果为真，最能解释这个现象?","options":[{"label":"A","content":"可用于工厂规模化生产产品的3D打印设备价格不菲"},{"label":"B","content":"可用3D打印技术批量生产产品需要耗费更高成本"},{"label":"C","content":"在制造某些产品上，3D打印技术还不够成熟"},{"label":"D","content":"掌握3D打印技术的专业人才不足"}],"answer":"B","explanation":"题干现象：预计3D打印技术将改变产品的设计和制造模式。然而，直到目前为止它的应用并没有广泛取代传统制造业。<br>A项，指出3D打印设备价格不菲，但不代表其无法取代传统制造业，有可能批量生产可以在一定程度上降低成本，因此该项无法解释题干现象，排除。<br>B项，指出采用3D打印技术批量生产产品需要耗费更高成本，应用它取代传统制造业是非常不划算的，因此可以很好地解释题干现象。<br>C项，说的是制造某些产品时3D打印技术还不够成熟，有可能大部分产品还是可以用3D打印技术制造的，因此该项的解释力度有限，排除。<br>D项，掌握3D打印技术的专业人才不足，说的是客观情况，解释的力度有限，相比之下，B项说的是3D打印技术本身的问题，更能解释题干现象。","no":349},{"id":"1718789647149","type":"single","material":"","stem":"欧洲临床营养学杂志的一篇研究成果：啤酒肚并非后天喝大量啤酒导致，而是遗传基因所致。<br>以下哪项事件可以由上述结论解释?","options":[{"label":"A","content":"某A,男，26岁，家族肥胖，运动教练，经常饮酒，但是腹部肌肉状态良好"},{"label":"B","content":"某B,男，40岁，父母较瘦弱，因肝炎戒酒，但是啤酒肚依然存在"},{"label":"C","content":"某C,女，30岁，办公室工作者，长期坐姿使用电脑，腹部赘肉较多"},{"label":"D","content":"某D,男，22岁，家族肥胖，其酒精过敏，体重超重，有啤酒肚"}],"answer":"D","explanation":"题干结论：啤酒肚是遗传基因所致。<br>A项，家族肥胖但该男性的腹部肌肉状态良好，说明啤酒肚并非遗传基因所致，与题干结论不符，排除。<br>B项，父母较瘦弱但该男性的啤酒肚依然存在，不能说明啤酒肚是遗传基因所致，与题干结论不符，排除。<br>C项，因工作而导致腹部赘肉较多，并未涉及啤酒肚和遗传基因的情况，不能用题干结论解释，排除。<br>D项，家族肥胖且该男性有啤酒肚，因为该男性酒精过敏不能饮酒，所以他的啤酒肚是家族肥胖遗传所致，可以由题干结论解释。","no":350},{"id":"1718789647150","type":"single","material":"","stem":"有了汽车自动驾驶系统，人们是否就可以不用再学如何开车了?恐怕还没那么简单。尽管现在的汽车在纯自动驾驶系统控制下发生意外事故的概率已经只有人工驾驶的百分之一，但A国相关部门依然否决了纯自动驾驶汽车上市的申请。<br>以下哪项最不可能是A国相关部门做出否决的原因?","options":[{"label":"A","content":"纯自动驾驶状态下发生交通事故的主体责任难以认定"},{"label":"B","content":"再高明的计算机系统也无法代替人进行伦理判断，而交通环境中却有可能面临是撞人还是撞车这样的选择困境"},{"label":"C","content":"提高汽车驾驶技术考核要求，并加强宣传良好驾驶习惯，也能够降低交通意外事故概率"},{"label":"D","content":"纯自动驾驶汽车上市对传统汽车产业的冲击巨大，会影响本国汽车产业链"}],"answer":"C","explanation":"题干矛盾：在纯自动驾驶系统控制下发生意外事故的概率已经只有人工驾驶的百分之一，但A国相关部门依然否决了纯自动驾驶汽车上市的申请。<br>A项，主体责任难以认定，体现了纯自动驾驶系统可能导致的问题，可以解释。<br>B项，无法代替人进行伦理判断，体现了纯自动驾驶系统自身的不足，可以解释。<br>C项，提高要求和加强宣传可以降低交通意外事故概率，但这并不能否认纯自动驾驶汽车的优势，无法解释。<br>D项，影响本国汽车产业链，体现了纯自动驾驶系统对本国经济带来的不利影响，可以解释。","no":351},{"id":"1718789647151","type":"single","material":"","stem":"某连锁品牌酒店建在某一文化古城，入住率一直不温不火，而且入住旅客主要是该品牌酒店的会员。酒店经理决定将酒店的现代化元素改造成与古城风貌一致的古朴风格。改造完毕后，入住率没有显著提升，周边酒店的入住率却有所下降。<br>以下哪项如果为真，最能说明以上现象?","options":[{"label":"A","content":"最近文化古城举办旅游月活动，吸引了大量游客，古城的管理面临巨大挑战"},{"label":"B","content":"酒店外观改造后，吸引了不少新旅客，但原会员的入住率却降低了"},{"label":"C","content":"周边的酒店也进行了外观改造，增添了更多的古朴元素，更显古色古香"},{"label":"D","content":"该酒店的经理并没有在文化古城经营酒店的经验，很多经营策略其实并未得到品牌总部的支持"}],"answer":"B","explanation":"题干现象：改造完毕后，该酒店的入住率没有显著提升，周边酒店的入住率却有所下降。<br>A项，古城的管理面临巨大挑战，与酒店入住率的高低没有直接关系，属于无关项。<br>B项，新旅客增加，原会员减少，综合在一起导致了该酒店入住率没有显著提升。并且新旅客增加可能会抢夺周边酒店的游客，而减少的原会员不一定会去周边的酒店，综合在一起导致了周边酒店的入住率有所下降，可以说明题干现象。<br>C项，周边的酒店也进行了外观改造，说明该古城中的所有酒店都改造了，但无法说明题干现象。<br>D项，只提到该酒店经理缺乏经验，没有提到周边酒店的情况，无法说明上述现象。","no":352},{"id":"1718789647152","type":"single","material":"","stem":"近年来，很多学生选择了去海外留学。他们认为镀金可以为未来就业增加竞争力。然而，《2017海归就业力调查报告》中的数据显示：海归回国求职并不容易，79.3%的海归认为自己在就业中存在一定劣势。<br>以下哪项如果为真，最能解释上述现象?","options":[{"label":"A","content":"大部分海归的实际薪资水平达不到其期望值"},{"label":"B","content":"牛津等海外名校毕业生依然受到雇主的青睐"},{"label":"C","content":"海归身份的受欢迎程度与行业有较大的关系"},{"label":"D","content":"多数海归不熟悉国内的就业形势与企业需求"}],"answer":"D","explanation":"题干观点①:镀金可以为未来就业增加竞争力；观点②:海归回国求职并不容易，79.3%的海归认为自己在就业中存在一定劣势。<br>A项，薪资待遇问题与就业劣势问题之间没有联系，未在海归镀金和就业劣势之间建立联系，不能解释题干矛盾。<br>B项，海外名校毕业生依然受到雇主的青睐，与题干矛盾相悖，不能解释题干矛盾。<br>C项，海归是否受欢迎与行业之间的关系，并不能解释为什么大部分海归在求职中存在劣势，不能解释题干矛盾。<br>D项，多数海归不熟悉国内的就业形势与企业需求，即海归自己的认识与实际的就业形势有差距，可以解释题干矛盾。","no":353},{"id":"1718789647153","type":"single","material":"","stem":"某市实体零售店的数量由2013年的3800家，增加到了2017年的4500家。但这几年来，该市实体零售店的销售额在整个零售业中所占的比例并没有增加，反而有所下降。<br>以下哪项为真，最不能解释上述现象?","options":[{"label":"A","content":"这几年来该市实体零售店的整体销售额显著下降"},{"label":"B","content":"这几年来该市非实体零售店的整体销售额迅速增加"},{"label":"C","content":"这几年来该市零售业的整体销售额有了大幅度的提升"},{"label":"D","content":"这几年来该市非实体零售店数量的增长速度快于实体零售店"}],"answer":"D","explanation":"题干中的矛盾是实体零售店的数量增加，而销售额占整个零售业的比例却不升反降。由于实体零售店销售额占整个零售业的比例=实体零售店销售额/整个零售业销售额=实体零售店销售额/(实体零售店销售额+非实体零售店销售额),A项指出分子减少，B、C两项指出分母增加，均能解释该比例不升反降的现象。D项是说零售店的数量方面，不涉及销售额，为无关项，不能解释题干现象。","no":354},{"id":"1718789647154","type":"single","material":"","stem":"过去10年，全世界烟草销量下降2%,而Z国的烟草销量却增长21%,每年达到2.5万亿支，Z国的烟草消费总量占全世界消费总量的45%以上。<br>下列最能对这一现象做出解释的是：","options":[{"label":"A","content":"Z国已经出台了所有室内公共场所和某些室外公共场所的禁烟令"},{"label":"B","content":"Z国成年男性的吸烟率超过半数，每年约有100万人死于与吸烟有关的疾病"},{"label":"C","content":"烟草广告对香烟销售起到了极大的促进作用"},{"label":"D","content":"其他国家的烟草消费税远远高于Z国"}],"answer":"D","explanation":"题干中的矛盾：全世界烟草销量下降2%,而Z国的烟草销量却增长21%。<br>A项，Z国出台禁烟令，烟草销量应该下降，但事实却是增长.与题干相矛盾.无法解释。<br>B项，Z国的吸烟率和与吸烟相关疾病的死亡人数，均不能说明Z国的烟草销量和<br>全世界的烟草销量有差异的原因，无法解释。<br>C项，烟草广告对香烟销售有极大的促进作用，全世界烟草销量应该增长，但事实却是下降，与题干相矛盾，无法解释。<br>D项，其他国家烟草消费税远远高于Z国，故在Z国进行烟草消费比较便宜，因此Z国的烟草销量才会远远高于其他国家，可以解释。","no":355},{"id":"1718789647155","type":"single","material":"","stem":"近年来，随着高校进一步扩招，大学毕业生也日益增多，社会劳动力市场出现了供过于求的局面，就业压力大增，部分地区高校毕业生就业率还不到一半的水平。但同时也出现了另外一种现象，大专生的就业形势普遍好于本科生。<br>下列选项中，无助于解释上述现象的是：","options":[{"label":"A","content":"大专生就业期望值比本科生低"},{"label":"B","content":"本科生理论知识强但动手能力相对较弱"},{"label":"C","content":"社会对技能型人才需求扩大"},{"label":"D","content":"大专生不比本科生聪明"}],"answer":"D","explanation":"题干中的矛盾：大学毕业生日益增多，社会劳动力市场出现了供过于求的局面，就业压力大增，部分地区高校毕业生就业率还不到一半的水平。但是大专生的就业形势普遍好于本科生。<br>A项，大专生就业期望值比本科生低，对工作要求低，所以找到工作的概率较大，可以解释。<br>B项，工作更看重动手能力，本科生动手能力弱，所以就业形势没有专科生好，可以解释。<br>C项，专科更偏重技能型人才的培养，社会对技能型人才的需求扩大，所以专科生就业形势好于本科，可以解释。<br>D项，大专生不比本科生聪明，与题干矛盾相悖，无法解释。","no":356},{"id":"1718789647156","type":"single","material":"","stem":"由于按揭贷款的利率下调，人们每月还贷压力减小，因此一家机构预测某地的商品房销售量会增长，但实际上，销售量并未出现明显增长。<br>下列哪项如果为真，最能解释以上现象?","options":[{"label":"A","content":"当地一直存在人口外流的现象"},{"label":"B","content":"本地的商品房价格没有明显下降"},{"label":"C","content":"有的开发商取消了购房优惠政策"},{"label":"D","content":"因经济环境不好，当地人均收入下降"}],"answer":"D","explanation":"题干现象：人们每月的还贷压力减小，但房地产销售量并未出现明显增长。<br>A项，人口外流现象与商品房销售量并无明显联系，无法解释题干现象。<br>B项，商品房价格没有明显下降，但不代表价格一定上升了，还可能保持稳定，这种情况下仍无法解释题干现象。<br>C项，只是有的开发商的情况，不具有代表性，无法解释题干现象。<br>D项，指出经济环境不好，当地的人均收入下降，即尽管还贷压力减小了，但人们的购房压力并没有减轻，所以房地产销售量没有上升，很好地解释了题干现象。","no":357},{"id":"1718789647157","type":"single","material":"","stem":"若在一墓穴中发掘出墓主的印章和墓志铭，就能确定该墓穴是墓主的真墓。在西高穴大墓中，没有发掘出曹操的印章和墓志铭。故西高穴大墓不是真的曹操墓。<br>以下哪项的论证方式与题干最为类似?","options":[{"label":"A","content":"若在墓穴中发现刻有“魏武王”之类字样的随葬品，就能说明那个墓穴是曹操的。在西高穴大墓中发现了刻有“魏武王常用格虎大戟”的石碑等随葬品。故该墓是曹操墓"},{"label":"B","content":"十八岁的人还没有面对过社会上的问题，而任何没有面对过这些问题的人不能够进行投票。所以，十八岁的人不能够进行投票"},{"label":"C","content":"只有持有深水合格证，才能进入深水池。高亮没有深水合格证，所以，他不能进入深水池"},{"label":"D","content":"如果我有翅膀，我就能飞翔。我没有翅膀，所以，我不能飞翔"}],"answer":"D","explanation":"本题要求选择与题干的论证方式最为类似的一项，即只进行结构的比较，可以先将题干内容抽象成字母表示的论证结构，再将选项与之进行对比。<br>题干论证方式：如果A,那么BC不是A,所以C不是B是充分条件假言命题通过否定前件推出否定后件的错误推理。<br>A项的论证方式：如果A,那么BC是A,所以C是B是充分条件假言命题通过肯定前件推出肯定后件的正确推理，与题干不同。<br>B项的论证方式：如果A(没有面对过社会上的问题),那么B(不能进行投票)。C是A(十八岁的人还没有面对过社会上的问题),所以C是B(十八岁的人不能进行投票)。是充分条件假言命题通过肯定前件推出肯定后件的正确推理，与题干不同。<br>C项的论证方式：只有A(持有深水合格证),才B(进入深水池)。C不是A(他没有深水合格证),所以C不是B(他不能进入深水池)。是必要条件假言命题通过否定前件推出否定后件的正确推理，与题干不同。<br>D项的论证方式：如果A(有翅膀),那么B(能飞翔)。C不是A(我没有翅膀),所以C不是B(我不能飞翔)。是充分条件假言命题通过否定前件推出否定后件的错误推理，与题干相同。","no":358},{"id":"1718789647158","type":"single","material":"","stem":"去年全年，某地区因驾驶员酒驾导致的交通事故数量是因驾驶员疲劳驾驶导致的交通事故数量的2倍。因此，在禁止疲劳驾驶方面的宣传工作要比禁止酒驾的宣传工作做得更好。<br>下列()项问题的答案最能对上述结论做出评价。","options":[{"label":"A","content":"交通事故的数量是否与交通安全方面的宣传工作有直接关系"},{"label":"B","content":"在下一个年度中，因疲劳驾驶而导致的交通事故数量是否会增加"},{"label":"C","content":"是不是所有疲劳驾驶的驾驶员都会出交通事故"},{"label":"D","content":"如果加大禁止酒驾的宣传力度，能在多大程度上降低酒驾导致的交通事故数量"}],"answer":"A","explanation":"本题要求选择能对题干结论做出评价的题目，需要先对题干论证进行分析，然后分析选项，寻找能对题干论证起到正反两方面评价作用的那一项。题干根据酒驾导致的交通事故数量是疲劳驾驶导致的交通事故数量的2倍，得出在禁止疲劳驾驶方面的宣传工作比禁止酒驾的宣传工作做得更好。<br>A项，问题的答案能够对题干结论做出评价，如果交通事故数量跟宣传工作没有直接关系，则削弱了题干结论，反之则加强了题干结论。<br>B项，说的是下一个年度，与题干结论无关。<br>C项，只涉及疲劳驾驶，不能对题干结论起正反两方面的评价作用。<br>D项，只涉及酒驾，不能对题干结论起正反两方面的评价作用。","no":359},{"id":"1718789647159","type":"single","material":"","stem":"昨天你们IT部门进行了一次服务器升级，晚上我的电脑就不能开机了，你们能不能把服务器恢复原状?分享<br>以下归因方式与题干最相似的是：","options":[{"label":"A","content":"作为家长，不能让孩子输在起跑线上，所以请选择小星星幼儿智力开发"},{"label":"B","content":"你要是不好好读书，将来就考不上大学，找不着工作，我看你该怎么办"},{"label":"C","content":"琼斯总统提高了税收，暴力犯罪数量随之上升，因此，不应当提高税收"},{"label":"D","content":"物价上涨是通货膨胀的主要原因，所以控制住物价，就抑制了通货膨胀"}],"answer":"C","explanation":"题干的归因方式为：因为服务器升级，所以电脑不能开机，因此要求把服务器恢复原状。<br>A项，因为不能让孩子输在起跑线上，所以家长选择智力开发。与题干归因方式不同。<br>B项，因为不好好读书，所以考不上大学，找不到工作。与题干归因方式不同。<br>C项，因为提高税收，所以犯罪数量上升，因此不应当提高税收。与题干归因方式相同。<br>D项，因为物价上涨是通货膨胀的主要原因，所以控制住物价，就抑制了通货膨胀。与题干归因方式不同。","no":360},{"id":"1718789647160","type":"single","material":"","stem":"某出版商认为：加工成本在近5年上升了10%～12%;原材料成本上升了10%~13%;销售及广告成本上升了10%以上。将所有这些加起来的话，总成本至少上升了30%。这仅是对大型出版社而言，如果是小出版社，总成本至少上升了40%。可见，书价的上涨主要是成本的上涨造成的，因此我反对提高作家的版权收入。<br>对上述论证的评价，最恰当的是：","options":[{"label":"A","content":"未提供加工成本上涨的具体证据"},{"label":"B","content":"忽略了导致书价上涨的其他原因"},{"label":"C","content":"错误地计算了总成本上涨的比例"},{"label":"D","content":"忽略了对中型出版社的统计数据"}],"answer":"C","explanation":"题干论点：书价的上涨主要是成本的上涨造成的，因此我反对提高作家的版权收入。论据：加工成本在近5年上升了10%～12%;原材料成本上升了10%~13%;销售及广告成本上升了10%以上。将所有这些加起来的话，总成本至少上升了30%。<br>A项，是否提供加工成本上涨的具体证据与书价上涨的主要原因无关，无法评价。<br>B项，题干说的是成本的上涨造成书价的上涨，是否存在其他导致书价上涨的原因与题干论述无关，无法评价。<br>C项，总成本上涨的比例=(总成本-五年前总成本)/五年前总成本，而题干论据中给出的是加工成本、原材料成本、销售及广告成本较五年前各项成本上涨的比例，其各自上涨的比例之和并不等于总成本上涨的比例，因此该项指出了题干论证的错误，是对题干论证最恰当的评价。<br>D项，是否对中型出版社的数据进行统计与书价上涨的主要原因无关，无法评价。","no":361},{"id":"1718789647161","type":"single","material":"","stem":"所有优秀的物理学家都具有良好的数学运用能力，张杰没有良好的数学运用能力，所以张杰不是优秀的物理学家。<br>下述推理中与上述推理在结构形式上最为相似的是：","options":[{"label":"A","content":"H公司今年招聘的人才都具有良好的专业背景和综合素质，小刘具有良好的专业背景和综合素质，所以小刘是今年H公司招聘的人才"},{"label":"B","content":"所有年满七十周岁的人都可以领到老年人生活补贴，王老师今年七十五周岁，他可以领到老年人生活补贴"},{"label":"C","content":"所有条件适宜的环境都能使企鹅蛋孵化，但T岛上企鹅蛋没有孵化，所以T岛的环境不是适宜的"},{"label":"D","content":"所有被顶尖高校录取的学生都是聪明的学生，李可没有被顶尖高校录取，所以李可不是聪明的学生"}],"answer":"C","explanation":"题干的推理结构：所有A都是B,C不是B,所以C不是A<br>A项的推理结构：所有A都是B,CB项的推理结构：所有A都是B,CC项的推理结构：所有A都是B,CD项的推理结构：所有A都是B,C<br>是B,所以C是A与题干不同。<br>是A,所以C是B与题干不同。<br>不是B,所以C不是A与题干相似。不是A,所以C不是B与题干不同。","no":362},{"id":"1718789647162","type":"single","material":"","stem":"入室抢劫者Q或者是从窗户进入房间的，或者是从屋门进入房间的。经查实，Q不是从屋门进入房间的，所以，他一定是从窗户进入房间的。<br>以下哪项与上述论证的结构最为相似?","options":[{"label":"A","content":"新近考古发掘的一幅字画要么是唐代的，要么是宋代的。经鉴定，这幅字画是唐代的，所以，它一定不是宋代的"},{"label":"B","content":"某晚午夜时分，天上最亮的星星或者是牛郎星，或者是织女星。经证实，该时刻天上最亮的星星不是织女星，所以，一定是牛郎星"},{"label":"C","content":"如果一个数能被8整除，它就能被4整除。某个数X不能被4整除，所以，X也不能被8整除"},{"label":"D","content":"小华通常上网或者是收发邮件，或者是QQ聊天，或者是打游戏。星期天下午她上网没有进行QQ聊天，所以，她一定收发邮件了"}],"answer":"B","explanation":"题干的论证结构：或者A,或者B非B,所以A是相容选言命题，否定其中一个选言肢，则肯定另外一个选言肢。<br>A项的论证结构：要么A,要么BA,所以，非B不相容选言命题，肯定其中一个选言肢，则否定另外一个选言肢，与题干不同。<br>B项的论证结构：或者A,或者B非B,所以A是相容选言命题，否定其中一个选言肢，则肯定另外一个选言肢。与题干相同。<br>C项的论证结构：如果A,那么B非B,所以非A充分条件假言命题否后得否前，与题干不同。<br>D项的论证结构：或者A,或者B,或者C非B,所以A只否定了三个选言肢的其中一个，不能得出确定性的结论，与题干不同。","no":363},{"id":"1718789647163","type":"single","material":"","stem":"考勤主管：“你为什么迟到，不知道上班有时间规定吗?”<br>工作人员：“我这是第一次迟到，我以前从来没有迟到过。”<br>下列各项中出现的逻辑错误与题干最为类似的是：","options":[{"label":"A","content":"甲：“今天天气真好，可以一起去游玩吗?”<br>乙：“今天的天气这么好，不适合游玩。”"},{"label":"B","content":"警官：“这个东西是你偷的吧?”<br>嫌疑人：“我发誓我没有偷过任何东西。”"},{"label":"C","content":"妈妈：“你不是喜欢吃鱼吗?为什么不多吃点?”<br>孩子：“我今天心情特别好，从来没有这么好过。”"},{"label":"D","content":"丙：“昨天那个人讲得太好了，不是吗?”<br>丁：“是的，而且那个人还很友好。”"}],"answer":"C","explanation":"题干中考勤主管问的是工作人员知不知道上班有时间规定，而工作人员却转移了话题，将话题引到自己从来没迟到上面，答非所问。<br>A项，乙回答的甲的提问，不存在逻辑错误。<br>B项，嫌疑人通过没偷过任何东西来反驳警官的话，不存在逻辑错误。<br>C项，属于答非所问，和题干逻辑错误最为类似。<br>D项，不存在答非所问的逻辑错误。","no":364},{"id":"1718789647164","type":"single","material":"","stem":"一次，皇帝称赞《文选》中郭璞的《游仙诗》写得好，石动筒听了说：“如果让我来写，肯定胜过他一倍。”皇帝听了很不高兴，就令他也写一首，看看如何“胜过一倍”。石动筒说：“郭璞的《游仙诗》里有两句写：‘青溪千余仞，中有一道士。’我做两句：‘青溪二千仞，中有二道士。’这难道还不胜过他一倍?”<br>这则故事中的石动筒所犯的逻辑错误是：","options":[{"label":"A","content":"偷换概念"},{"label":"B","content":"自相矛盾"},{"label":"C","content":"因果倒置"},{"label":"D","content":"错误类比"}],"answer":"A","explanation":"题干中石动筒说，如果他来写肯定胜过郭璞一倍，皇帝理解的“胜过一倍”,是整首诗的意境，而石动筒却将“胜过一倍”偷换成数字关系上的一倍，属于偷换概念","no":365},{"id":"1718789647165","type":"single","material":"","stem":"一对夫妻吵架后，丈夫气愤地说：“你该记住，无论什么时候，男人的思考总是对的，判断准确无误。而女人却是恰恰相反。”妻子听后马上回答：“是呀，你选我做妻子是绝对正确的，而我选你做丈夫是大错特错的。”<br>对于妻子的上述回答，最恰当的评价是：","options":[{"label":"A","content":"使用转移话题的方式，回避双方观点分歧，达到安抚对方情绪的效果"},{"label":"B","content":"由两个对象某些相似的性质，推断出它们在其他性质上也有可能相似"},{"label":"C","content":"表面上顺应对方的话题，真实意图却是以隐含的话意驳斥对方的诡辩"},{"label":"D","content":"通过列举一个与之相关的例子，来证明对方的论断的真实性和有效性"}],"answer":"C","explanation":"妻子的回答表面上顺应了丈夫的观点(男人正确而女人错误),但实际上以隐含的方式讽刺了丈夫的说法。C项正确。A项，“安抚对方情绪”说法错误。B项，妻子的话并未体现“两个对象某些相似的性质”。D项，含义与妻子的意思相悖。","no":366},{"id":"1718789647166","type":"single","material":"","stem":"一名茶叶经销商在对客人介绍一种茶叶时说：“这种茶叶产自云山，而大名鼎鼎的云山茶正是产自云山，所以这就是正宗的云山茶。”<br>以下与该经营商介绍茶叶时的逻辑最为相似的是：","options":[{"label":"A","content":"三班的学生都勤奋好学，小李是三班的学生，所以小李勤奋好学"},{"label":"B","content":"飞驰牌汽车产自某国，刚才那辆汽车不是飞驰牌，所以肯定不是该国产的"},{"label":"C","content":"所有司机都必须有驾照，小郑有驾照，所以小郑是司机"},{"label":"D","content":"好医生需要具备精湛的医术和高尚的医德，小陈二者兼备，所以他是好医生"}],"answer":"C","explanation":"题干的逻辑关系：a是b,c是b,所以a是C<br>A项的逻辑关系：a是b,c是a,所以c是B与题干不同。<br>B项的逻辑关系：a是b,c不是a,所以c不是B与题干不同。<br>C项的逻辑关系：a是b,c是b,所以c是A与题干相似。<br>D项的逻辑关系：a是b且d,c是b且d,所以c是A与题干不同。","no":367},{"id":"1718789647167","type":"single","material":"","stem":"液体都能够流动。水能够流动，所以水是液体。以下与上述推理在结构上最为相似的一项是：","options":[{"label":"A","content":"哲学家都爱思考。李教授是哲学家，所以他爱思考"},{"label":"B","content":"哺乳类动物都是恒温动物。蛇不是哺乳类动物，所以蛇不是恒温动物"},{"label":"C","content":"平板电脑都有触摸屏。手机有触摸屏，所以手机是平板电脑"},{"label":"D","content":"工作态度端正就能取得好的业绩。小刘取得好业绩，所以他工作态度端正"}],"answer":"C","explanation":"题干推理结构为：所有A是B,C是B,所以C是AA项，推理结构为：所有A是B,C是A,所以C是B<br>B项，推理结构为：所有A是B,C非A,所以C非B<br>C项，推理结构为：所有A是B,C是B,所以C是A<br>D项，推理结构为：A→B,C是B,所以C是A(虽然全称直言命题也可以转化成假言命题形式，但是D项形式上就是假言命题，与题干不同。)<br>综上。","no":368},{"id":"1718789647168","type":"single","material":"","stem":"一条鳄鱼抢走了一个小孩，它对孩子的母亲说：“我会不会吃掉你的小孩?答对了，孩子还给你；答错了，我就吃了他。”孩子母亲说：“你会吃了他吧。”母亲的回答让鳄鱼陷入了一种选择困境，这就是所谓的“鳄鱼悖论”。<br>根据上述情景，以下哪一项描述有相似的困境或悖论?","options":[{"label":"A","content":"裁缝说：“世上没有我做不出来的衣服。”公主说：“世上没有让我满意的衣服。”国王最后说：“你们都说得不对。”"},{"label":"B","content":"小偷去保险箱偷珠宝，发现箱子有两个按钮，只有触动其中一个才能打开箱子。绿色按钮下面写着“按我，打不开”,红色按钮下面写着“不按我，能打开”。"},{"label":"C","content":"狐狸抓到一只鸡，对鸡说：“如果我现在心情好，就放你走；心情不好，就吃掉你。你说我心情好还是不好?猜对了就放你走。”鸡赶紧说：“你的心情很好。”"},{"label":"D","content":"家里花瓶打碎了，肯定是大宝或小宝干的。妈妈问是谁打的。大宝说：“是小宝打的。”小宝说：“不是大宝打的。”原来他们都在说谎。"}],"answer":"B","explanation":"题干的情景“鳄鱼悖论”是一个二难悖论，即母亲的回答无论对错，鳄鱼吃或不吃孩子都会与之前的许诺产生矛盾。<br>A项，“没有做不出来的衣服”和“没有让我满意的衣服”,国王无论回答对或不对，都不会产生矛盾，不属于二难悖论。<br>B项，无论小偷按绿色或红色的按钮都不能打开箱子，与触动一个按钮才能打开箱子矛盾，属于二难悖论。<br>C项，当狐狸心情不好的时候，小鸡回答“你心情好”就会被吃掉，不属于二难悖论。<br>D项，他们都在说谎，那花瓶就是大宝打碎的，不属于二难悖论。","no":369},{"id":"1718789647169","type":"single","material":"","stem":"狗不嫌家贫，子不嫌母丑。爱自己家乡的人不会说家乡的坏话，张三就从不说家乡的坏话。可见，他是一个多么爱自己家乡的人啊!<br>以下哪项的推理方式与上述最为相似?","options":[{"label":"A","content":"灯不挑不亮，话不挑不明。如果没有听到张处长这番话，我还在纠结要不要报名参加行业大赛，现在一切都清楚了。看来，张处长的话太重要了"},{"label":"B","content":"不入虎穴，焉得虎子?巨大的成功往往伴随着巨大的风险，李四投资股票获得高额回报。可见，他承担了多大的风险啊"},{"label":"C","content":"玉不琢不成器，人不学要落后。追求进步的人不会不爱学习的，王教授退休后一直无所事事，不爱学习。可见，王教授已不是一个追求进步的人了"},{"label":"D","content":"人不可貌相，海水不可斗量。一个有才能的人不会将他的才能显示出来，李先生就从来没有显示过他的才能。可见，他是一个多么有才能的人啊"}],"answer":"D","explanation":"题干推理：爱自己家乡→不说家乡坏话，张三不说家乡坏话→他爱自己的家乡，通过肯定后件得出肯定的前件，是错误的推理。<br>A项：没有听到张处长的话→还在纠结，现在清楚了→听到张处长的话，通过否定后件得出否定前件，与题干推理方式不同。<br>B项：巨大成功→巨大风险，高额回报→巨大风险，通过肯定前件得出肯定后件，与题干推理方式不同。<br>C项：追求进步→爱学习，王教授不爱学习→不是一个追求进步的人，通过否定后件得出否定前件，与题干推理方式不同。<br>D项：有才能→不显示才能，李先生不显示才能→他有才能，通过肯定后件得出肯定的前件，与题干推理方式相同。","no":370},{"id":"1718789647170","type":"single","material":"","stem":"<p>江海之所以能为百谷王者，以其善下之，故能为百谷王。是以圣人欲上民，必以言下之；欲先民，必以身后之。</p><p>下列（ &nbsp; ）项与以上论证方法最为相似。</p>","options":[{"label":"A","content":"名不正，则言不顺；言不顺，则事不成。事不成，则礼乐不兴；礼乐不兴，则刑罚不中；刑罚不中，则民无所措手足。故君子名之必可言也，言之必可行也"},{"label":"B","content":"春风朝煦，萧艾蒙其温；秋霜宵坠，芝蕙被其凉。是以威以齐物为肃，德以普济为弘"},{"label":"C","content":"木受绳则直，金就砺则利，君子博学而日参省乎己，则知明而行无过矣"},{"label":"D","content":"假舆马者，非利足也，而致千里；假舟楫者，非能水也，而绝江河。君子生非异也，善假于物也"}],"answer":"B","explanation":"题干的意思：江海之所以能够成为百川河流所汇往的地方，乃是由于它善于处在低下的位置，所以能够成为百川之王。因此，圣人要领导人民，必须用言辞对人民表示谦下；要想成为人民的表率，必须把自己放在人民的后面，先惠于民。题干为类比论证，即通过将“江海”类比为“圣人”来表达观点。","no":371},{"id":"1718789647171","type":"single","material":"","stem":"在某公司的一次会议上，甲说：“我们部门的工作不受重视，什么事总是低人一头!”乙听了说：“你不想低人一头，那就只能选择努力高人一头了。”<br>与题干中乙所犯的逻辑错误相同的是：","options":[{"label":"A","content":"文学作品的叙述方法，不是顺叙，就是倒叙，二者必居其一"},{"label":"B","content":"经验主义不能一概反对。例如，工作经验就不应该反对"},{"label":"C","content":"我很相信一位哲人的名言：世界上没有任何东西是可信的"},{"label":"D","content":"凡是犯罪行为都是违法行为，所以违法行为都是犯罪行为"}],"answer":"A","explanation":"由题干乙的话可知其表达的意思是“非此即彼”,即不低人一头，就必须高人一头，犯了“非黑即白”的逻辑错误。<br>A项，文学作品的叙述方式有很多种，包括顺叙、倒叙、平叙、插叙等，而选项却指出不是顺叙就是倒叙，同样犯了“非黑即白”的逻辑错误。<br>B项，经验主义和工作经验不是同一概念，犯了“混淆概念”的逻辑错误。<br>C项，先说相信一位哲人的名言，后又说世界上没有任何东西是可信的，既然没有东西是可信的，那么哲人的名言也是不可信的，犯了“自相矛盾”的逻辑错误。<br>D项，犯罪行为不等同于违法行为，犯罪必定违法，违法不一定犯罪，违法行为达到量刑的才算犯罪，达不到量刑的其他违法行为不属于犯罪，犯了“混淆概念”的逻辑错误。","no":372},{"id":"1718789647172","type":"single","material":"","stem":"老张：“你在这摆摊属于占道经营。”<br>小王：“这是中心北路又不是中山北道，我占什么道。”<br>以下哪项与上述对话方式最相似?","options":[{"label":"A","content":"甲：“你这种执法行为一点人情味都没有!”<br>乙：“我严格执法是为了保障人民群众的生命财产安全。”"},{"label":"B","content":"甲：“你成天打游戏是在虚度年华。”<br>乙：“我只有在游戏中才觉得年华没有虚度。”"},{"label":"C","content":"甲：“你工作时间不能抽烟。”<br>乙：“我抽烟时从不工作。”"},{"label":"D","content":"甲：“你这种说法是栽赃陷害。”<br>乙：“你这种说法是血口喷人。”"}],"answer":"C","explanation":"题干中老张说的“占道经营”中的“道”指的是实际的道路，小王说的“道”指的是道路的名称。属于偷换概念。<br>A项，乙只是对自己的执法行为做出了解释，以此来反驳甲的说法。这里并未涉及偷换概念，与题干不一致。<br>B项，甲、乙二人对打游戏是否虚度年华的理解不同，甲认为打游戏虚度年华，乙的想法则相反。这里并未涉及偷换概念，与题干不一致。<br>C项，甲说的“工作时间”指的是上班期间，乙则将其说成“进行工作的时间”。属于偷换概念，与题干一致。<br>D项，甲、乙二人都在指责对方冤枉自己。这里并未涉及偷换概念，与题干不一致。","no":373},{"id":"1718789647173","type":"single","material":"","stem":"某投资公司在评价一个项目时说：我们挑选投资项目，主要是看项目的技术门槛和未来市场需求量，而不是当前的业务增长率。现在新的可投资项目这么多，短期内发展很迅速但很快就被其他项目追赶上来的也不少，这显然不是我们想要的。这个项目在一年内营业额就增加了5倍，倒是很有必要怀疑它将来的状况。<br>以下和该投资公司评价项目的逻辑最为类似的是：","options":[{"label":"A","content":"婚姻生活是否幸福取决于夫妻双方的和谐程度，而不是家庭收入，有些收入高的夫妻，婚姻生活反而不幸福"},{"label":"B","content":"通过票房评价一部电影并不靠谱，一部电影即使票房再高，观众的口碑也不一定好"},{"label":"C","content":"某足球队在选拔新队员时，除了关注他们的技术水平，更看重他们的训练状态和发展潜力"},{"label":"D","content":"歌手要成功，天赋和优秀的市场推广缺一不可。那些失败的歌手，要么没有天<br>赋，要么市场推广做得不好"}],"answer":"A","explanation":"投资公司评价的逻辑：挑选项目主要看A条件(技术门槛和未来市场需求量),而不是B条件(当前的业务增长率),有些B条件(当前的业务增长率)很好的项目，长远来看并不好。<br>A项，婚姻生活取决于A条件(双方的和谐程度),而不是B条件(家庭收入),有些B条件(家庭收入)好的夫妻，生活并不幸福。与题干逻辑类似。<br>B项，评价电影不能看A条件(票房),一部电影A条件(票房)好，但B条件(观众口碑)不一定好。与题干逻辑不同。<br>C项，某足球队选拔新队员时除了看A条件(技术水平),更看重B条件(训练状态和发展潜力)。与题干逻辑不同。<br>D项，歌手要成功，A条件(天赋)和B条件(优秀的市场推广)缺一不可。那些失败的歌手，要么没有A条件(天赋),要么没有B条件(优秀的市场推广)。与题干逻辑不同。","no":374},{"id":"1718789647174","type":"single","material":"","stem":"理论认为，反物质是正常物质的反状态，当正反物质相遇时，双方就会相互湮灭抵消，发生爆炸并产生巨大能量。有人认为，反物质是存在的，因为到目前为止没有任何证据证明反物质是不存在的。<br>以下哪项与题干中的论证方式相同?","options":[{"label":"A","content":"圣女贞德的审问者们曾对她说，我们没有证据证明上帝与你有过对话，你可能是在胡编乱造，也可能是精神失常"},{"label":"B","content":"动物进化论是正确的，例如始祖鸟就是陆地生物向鸟类进化过程中出现的一类生物"},{"label":"C","content":"既然不能证明平行世界不存在，那么平行世界就是存在的"},{"label":"D","content":"长白山天池有怪兽，因为有人看见过怪兽在天池内活动的踪迹"}],"answer":"C","explanation":"题干是通过不能证明反物质是不存在的而推出反物质是存在的，即不能证明A为假，因此推出A为真，为“诉诸无知”的错误推理。<br>A项，根据没有证据证明上帝与你有过对话，推出你可能是在胡编乱造，也可能是精神失常，即不能证明A为真，因此推出B或C该论证最后推出了其他的结论，而没有说明前面所述的情况为真或为假，与题干论证方式不同。<br>B项，通过具体的事例来论证观点，并非“诉诸无知”,与题干论证方式不同。<br>C项，通过不能证明平行世界是不存在的而推出平行世界是存在的，即不能证明A为假，因此推出A为真，为“诉诸无知”的错误推理，与题干论证方式相同。<br>D项，根据有人看见过怪兽活动的踪迹推出有怪兽存在，并非“诉诸无知”,与题干论证方式不同。","no":375},{"id":"1718789647175","type":"single","material":"","stem":"辛迪是非洲大草原上的一只“明星”狮子，狮子是非洲大草原的动物之王，因此辛迪是非洲大草原的动物之王。<br>以下哪项与上述论证方式不一样?","options":[{"label":"A","content":"公司决定解雇市场部的全部员工，赵小姐是市场部的新员工，所以她也同样面临公司的解雇"},{"label":"B","content":"大家都喜欢看电视剧，《大宅门》是电视剧中的精品，自然是人人都喜欢看"},{"label":"C","content":"创业者代表了社会发展的希望，张明是杰出的创业者，因此，张明代表了社会发展的希望"},{"label":"D","content":"无领导小组讨论是一种常用的面试形式，公司招聘必然会用到面试，因此无领导小组讨论一定会被用在公司招聘中"}],"answer":"A","explanation":"题干的论证方式：第一个“狮子”特指“辛迪”,第二个“狮子”泛指“非洲大草原上的狮子”,而结论将二者的概念偷换。<br>A项，市场部的全部员工包含市场部的新员工，市场部的新员工包含赵小姐，因此，解雇市场部的全部员工，自然也就解雇赵小姐，与题干论证方式不一样。<br>B项，电视剧泛指所有的电视剧，《大宅门》特指一部电视剧，而结论将二者的概念偷换，与题干论证方式一样。<br>C项，创业者泛指所有的创业者，张明特指一个创业者，而结论将二者的概念偷换，与题干论证方式一样。<br>D项，招聘面试是泛指所有的面试方式，无领导小组讨论特指一种面试方式，而结论将二者的概念偷换，与题干论证方式一样。","no":376},{"id":"1718789647176","type":"single","material":"","stem":"课间休息时，一位同学帮老师擦了黑板，老师回到教室后询问是谁擦的黑板。<br>他问了四位同学，得到以下回答：<br>(1)或者班长擦了，或者学习委员擦了；<br>(2)如果纪律委员没擦，那么班长也没擦；<br>(3)如果卫生委员没擦，那么班长擦了；<br>(4)班长和学习委员都没擦。<br>实际上，四位同学的回答中只有一句是假的。据此可以推出擦黑板的是：","options":[{"label":"A","content":"纪律委员"},{"label":"B","content":"学习委员"},{"label":"C","content":"卫生委员"},{"label":"D","content":"班长"}],"answer":"C","explanation":"本题给出四个条件，并指出其中“只有一句是假的”,在解题时可以寻找这四个条件中是否存在矛盾关系或下反对关系，如果存在则可以据此判断其他条件的真假。<br>根据题干条件，(1)和(4)是矛盾命题，必有一真一假，根据“四位同学的回答中只有一句是假的”可知，(2)和(3)是真的。(2)的推理关系：纪律委员没擦→班长没擦。<br>(3)的推理关系：卫生委员没擦→班长擦了。(2)和(3)可构成连锁推理：卫生委员没擦→班长擦了→纪律委员擦了。由于题干已经明确说明是一位同学擦了黑板，所以班长没擦，否则班长和纪律委员都擦了，与题干条件不符。则由班长没擦可推出卫生委员擦了。","no":377},{"id":"1718789647177","type":"single","material":"","stem":"明知要早睡，却忍不住熬夜追剧；明知吸烟、酗酒有害健康，却挡不住烟酒的诱惑；明知运动有益，却一步都懒得走……生活中，很多人并不缺少健康常识，他们更多的是缺乏一种自律精神。自律的人都会早睡，都会忌口，都坚持运动。如果一个人坚守自律精神，就不会放纵自己，就能够维护自己的生理节律，过上健康幸福的生活。<br>根据以上陈述，可以得出以下哪项?","options":[{"label":"A","content":"所有坚持运动的人都很自律"},{"label":"B","content":"有的缺乏自律精神的人不缺少健康常识"},{"label":"C","content":"一个人如果不坚守自律精神，就会放纵自己"},{"label":"D","content":"维护自己生理节律的人都能过上健康幸福的生活"}],"answer":"B","explanation":"题干中包含“如果……·就……”一类的关键词，可见其主要考查假言命题，需注意区分充分条件假言命题和必要条件假言命题的推理规则，并注意能否将不同类型的假言命题转化成同一类型，进而构成连锁推理，辅助解题。根据“很多人并不缺少健康常识，他们更多的是缺乏一种自律精神”可推出B项正确；题干推理：①自律的人→都早睡、忌口、坚持运动；②坚守自律精神→不会放纵自己→维持生理节律，过上健康幸福的生活；A项肯后不能肯前，错误；C项否前不能否后，错误；D项推不出。","no":378},{"id":"1718789647178","type":"single","material":"","stem":"某演艺中心是某市标志性建筑，在出现大型活动时，该演艺中心除了平时启用的安全出入口，还有5个平时不开放的、供紧急情况下启用的出入口。这些紧急出入口的启用需要遵循以下规则：<br>(1)如果启用1号，那么必须同时启用2号且关闭5号。<br>(2)不允许同时关闭3号和4号。<br>(3)只有关闭4号，才能启用2号或者5号。<br>那么,如果启用1号，以下哪项也同时启用?","options":[{"label":"A","content":"2号和4号"},{"label":"B","content":"3号和5号"},{"label":"C","content":"2号和3号"},{"label":"D","content":"4号和5号"}],"answer":"C","explanation":"整理条件：①启用1号→启用2号且关闭5号；②启用3号或启用4号；③启用2号或5号→关闭4号。已知启用1号，根据条件①,可知启用2号且关闭5号。结合条件③,可知关闭4号。再由条件②可知启用3号。所以，启用2号和3号。","no":379},{"id":"1718789647179","type":"single","material":"","stem":"H市在公共场所中的每一块绿地都配备了垃圾桶。这些垃圾桶或者标有“可回收垃圾”,或者标有“不可回收垃圾”。<br>如果上述陈述为真，则下列()项一定为真。<br>I.H市配备的垃圾桶上有的标有“可回收垃圾”<br>Ⅱ.如果H市有一块绿地没有配备垃圾桶，那么该绿地不属于公共场所<br>Ⅲ.如果H市有块绿地配备了标有“不可回收垃圾”的垃圾桶，那么它属于公共场所","options":[{"label":"A","content":"只有I"},{"label":"B","content":"只有Ⅱ"},{"label":"C","content":"只有Ⅲ"},{"label":"D","content":"I和Ⅱ"}],"answer":"B","explanation":"题干中出现了“或者……或者……\"”“如果……那么……”等关键词，可知其考查复言命题。先分析题干中给出的推理，然后根据推理规则分析选项的正误。<br>题干推理关系：①公共场所→每一块绿地都配备垃圾桶；②垃圾桶→或者标有“可回收垃圾”,或者标有“不可回收垃圾”。<br>I.由②可知，相容选言命题只要一个肢命题为真该命题即为真，则可能不存在标有“可回收垃圾”的垃圾桶，I不一定为真；<br>Ⅱ.由①充分条件假言命题否后则否前，可知Ⅱ一定为真；<br>Ⅲ.充分条件假言命题肯定后件无法进行有效推理，则Ⅲ无法推出。综上，只有Ⅱ一定为真。","no":380},{"id":"1718789647180","type":"single","material":"","stem":"校学术委员会开会讨论新一轮的重点学科建设规划。王教授主张：既要重点建设教育科学，也要建设自然地理学；赵教授提出：只有重点建设计算机信息工程，才能建设自然地理学；李教授认为：如果要重点建设教育科学和自然地理学，那么也要建设计算机信息工程。经过充分讨论，在上述三位教授的意见中，学术委员会最后只采纳了其中一位的意见。<br>根据以上陈述，下列()项符合学术委员会的决定。","options":[{"label":"A","content":"重点建设计算机信息工程和自然地理学，但是不建设教育科学"},{"label":"B","content":"重点建设教育科学和计算机信息工程，但是不建设自然地理学"},{"label":"C","content":"重点建设计算机信息工程，但是不建设教育科学和自然地理学"},{"label":"D","content":"重点建设自然地理学和教育科学，但是不建设计算机信息工程"}],"answer":"D","explanation":"此题考查必然性推理，可根据推理规则解题。因为只有一位的意见被采纳，也可尝试代入排除法。<br>方法一：整理题干信息，王教授：既要重点建设教育科学，也要建设自然地理学；<br>赵教授：建设自然地理学→重点建设计算机信息工程；<br>李教授：重点建设教育科学和自然地理学→建设计算机信息工程。<br>充分条件假言命题只有在前件真且后件假时为假，如果建设计算机信息工程，那么赵教授和李教授的意见均为真，不符合题意，因此不建设计算机信息工程，排除A、B、C将D项代入，王教授的意见为真，赵教授和李教授的意见为假，符合题意。答案：D<br>方法二：代入A项，王教授的意见为假，赵教授和李教授的意见均为真，与题意不符，排除。<br>代入B项，王教授的意见为假，赵教授和李教授的意见均为真，与题意不符，排除。<br>代入C项，王教授的意见为假，赵教授和李教授的意见均为真，与题意不符，排除。<br>代入D项，王教授的意见为真，赵教授和李教授的意见均为假，与题意符合。","no":381},{"id":"1718789647181","type":"single","material":"","stem":"文化自信是主体对自身文化的认同、肯定和坚守。文化自觉是文化自信的前提，没有深刻的文化自觉，就不可能有高度的文化自信。没有高度的文化自信，就没有文化的繁荣昌盛，就没有中华民族的伟大复兴。<br>由上文推知，下列一定正确的是：","options":[{"label":"A","content":"没有深刻的文化自觉，就没有中华民族的伟大复兴"},{"label":"B","content":"有了高度的文化自信，就会有中华民族的伟大复兴"},{"label":"C","content":"没有文化的繁荣昌盛，就一定没有深刻的文化自觉"},{"label":"D","content":"只要有了高度的文化自信，就会有文化的繁荣昌盛"}],"answer":"A","explanation":"根据“没有”“就”等关键词，可知道本题考查假言命题。<br>题干逻辑关系：没有深刻的文化自觉→没有高度的文化自信→没有文化的繁荣昌盛→没有中华民族的伟大复兴。<br>A项，没有深刻的文化自觉(肯定前件),就没有中华民族的伟大复兴(肯定后件),充分条件假言命题肯前肯后，可以推出。<br>B项，有了高度的文化自信(否定前件),就会有中华民族的伟大复兴(否定后件),充分条件假言命题否前不能否后，不可以推出。<br>C项，没有文化的繁荣昌盛(肯定后件),就一定没有深刻的文化自觉(肯定前件),充分条件假言命题肯后不能肯前，不可以推出。<br>D项，只要有了高度的文化自信(否定前件),就会有文化的繁荣昌盛(否定后件),充分条件假言命题否前不能否后，不可以推出。","no":382},{"id":"1718789647182","type":"single","material":"","stem":"只有具有良好的逻辑思维能力并且具有物理学专业背景的人，才能胜任这个岗位。<br>如果上述判断为真，以下哪项不可能为真?","options":[{"label":"A","content":"物理学专业博士小赵胜任了这个岗位"},{"label":"B","content":"从未学习过物理学知识的小李，胜任了这个岗位"},{"label":"C","content":"小刘具有物理学专业背景，但他不能胜任这个岗位"},{"label":"D","content":"小孙不能胜任这个岗位，但他的逻辑思维能力是大家公认的"}],"answer":"B","explanation":"题干中包含“只有……·才……\"”这一关键词，可将其转化成充分条件假言命题，再运用相应的推理规则进行解题。<br>题干的推理关系：能胜任这个岗位→具有良好的逻辑思维能力并且具有物理学专业背景。B项小李“从未学习过物理学知识”,说明其没有物理学专业背景，否定了题干推理的后件，能够推出否定的前件，即小李不能胜任这个岗位，因此B项必然为假。A、C、D三项均可能为真。","no":383},{"id":"1718789647183","type":"single","material":"","stem":"没有出席今晚宴会的人，要么没有被邀请，要么没有时间。据此，可以推出：","options":[{"label":"A","content":"被邀请的才能参加今晚的宴会"},{"label":"B","content":"有时间且被邀请的不会参加今晚宴会"},{"label":"C","content":"没被邀请的也不一定不出席今晚宴会"},{"label":"D","content":"被邀请的即使有时间也不一定出席今晚宴会"}],"answer":"C","explanation":"本题考查充分条件假言命题，解题时还要结合选言命题的推理规则。题干推理：没有出席宴会→要么没被邀请，要么没时间。<br>A项推理：参加宴会→被邀请，“参加宴会”否定了题干充分条件假言命题的前件，无法进行有效推理，A项不能推出。<br>B、D两项均否定了后件，能推出否定前件，即“一定会出席宴会”,错误。<br>C项可能为真。","no":384},{"id":"1718789647184","type":"single","material":"","stem":"近日来，南方某地持续降雨，导致很多人工养鱼池被淹。因此，有几位养鱼专家就鲫鱼和鲤鱼的价格走势进行预测：<br>李强说：只有鲫鱼价格上涨，鲤鱼价格才会上涨；<br>孙振说：鲫鱼和鲤鱼的价格至少有一种会上涨；<br>王刚说：只有鲤鱼价格不上涨，鲫鱼价格才不上涨；并且如果鲤鱼价格不上涨，则鲫鱼价格不上涨。<br>假如事实证明三位专家的预测均为真，则以下哪项必须为真?","options":[{"label":"A","content":"鲫鱼价格上涨，鲤鱼价格不上涨"},{"label":"B","content":"鲫鱼价格不上涨，鲤鱼价格上涨"},{"label":"C","content":"鲫鱼和鲤鱼的价格都上涨"},{"label":"D","content":"鲫鱼和鲤鱼的价格都不上涨"}],"answer":"C","explanation":"题干中包含“只有……·才……”“如果……则……”一类的关键词，可以将三人的话转化为复言命题的推理形式，再结合推理规则进行解题。<br>李强的推理：鲫鱼涨价←鲤鱼涨价；孙振的推理：鲫鱼涨价或鲤鱼涨价；王刚的推理：“鲤鱼不涨价←鲫鱼不涨价”并且“鲤鱼不涨价→鲫鱼不涨价”。<br>若A项为真，鲫鱼涨价，鲤鱼不涨价，则王刚的预测为假，不满足“三位专家的预测均为真”,排除。<br>若B项为真，鲫鱼不涨价，鲤鱼涨价，则李强和王刚的预测都为假，不满足“三位专家的预测均为真”,排除。<br>若C项为真，鲫鱼和鲤鱼都涨价，则三人的推测均为真，正确。<br>若D项为真，鲫鱼和鲤鱼都不涨价，则孙振的预测为假，不满足“三位专家的预测均为真”,排除。","no":385},{"id":"1718789647185","type":"single","material":"","stem":"张某死了，法医表明是自杀身亡。张某的两个邻居甲和乙对前来调查的赵警察说了以下事情：<br>甲：“如果张某死于谋杀，他老婆李某脱不了干系，这段时间她正和张某闹离婚。”乙：“张某不是死于自杀，就是死于谋杀，不可能是意外。”<br>赵警察听了甲和乙的话以后，做出如下两个判断：<br>①如果甲和乙说的都是对的或都是错的，那么张某就是死于意外。<br>②如果甲、乙两人中一人讲的是错的，那么张某就不是死于意外。<br>经查明事实后发现，赵警察的判断都是正确的。<br>根据以上信息，可以得出以下哪项?","options":[{"label":"A","content":"张某死于谋杀"},{"label":"B","content":"张某死于自杀"},{"label":"C","content":"张某死于意外"},{"label":"D","content":"李某杀了张某"}],"answer":"A","explanation":"如果甲、乙二人说的话都对，则张某不可能死于意外，和判断①矛盾，不符；如果甲、乙二人说的话都错，则张某死于谋杀，但和李某无关，也不符合判断①;所以甲、乙二人中一人讲的是错的，张某不是死于意外，则乙的话为真，甲的话为假，张某死于谋杀，但和李某无关。","no":386},{"id":"1718789647186","type":"single","material":"","stem":"某单位的孔、陈、孟、刘4人需要分配到甲、乙、丙、丁4个村庄开展扶贫工作，每人各去一个村庄。根据工作需要，分配满足如下条件：<br>(1)若孔去甲村庄，则刘去丁村庄；<br>(2)要么陈去乙村庄，要么孟去丙村庄，两者仅有一项成立；<br>(3)孟去丁村庄。<br>如果上述条件均得到满足，则可以得出以下哪项?","options":[{"label":"A","content":"孔去丙村庄，刘去甲村庄"},{"label":"B","content":"孔去甲村庄，刘去丙村庄"},{"label":"C","content":"孔去丙村庄，刘去乙村庄"},{"label":"D","content":"孔去乙村庄，刘去丙村庄"}],"answer":"A","explanation":"题干中包含三个条件：①孔去甲→刘去丁；②要么陈去乙，要么孟去丙，仅有一项成立；③孟去丁。结合①和③,否后推否前，可知孔不去甲。结合②和<br>③可知陈去乙。那么孔去丙，刘去甲。","no":387},{"id":"1718789647187","type":"single","material":"","stem":"只有在阳光因雨滴的存在而发生偏移且偏移前被水面反射的情况下，才会出现倒影彩虹。昨天一场瓢泼大雨后，没有人在滴水湖看见倒影彩虹。<br>如果上述陈述为真，则下列哪项必定为真?<br>I.只有在阳光因雨滴而发生了偏移，才会出现这种偏移被水面反射的情况<br>Ⅱ.昨天滴水湖上空既没有出现阳光因雨滴而偏移的情况，也没有出现这种偏移被水面反射的情况<br>Ⅲ.如果阳光因雨滴而发生了偏移，那么这种偏移肯定不会被水面反射","options":[{"label":"A","content":"只有I"},{"label":"B","content":"只有Ⅱ"},{"label":"C","content":"只有Ⅲ"},{"label":"D","content":"I、Ⅱ和Ⅲ均不真"}],"answer":"D","explanation":"根据关键词“只有……·才……\"”,可以确定题干逻辑关系为必要条件假言命题，需明确其推理规则。题干是一个必要条件假言命题。阳光因雨滴的存在而发生偏移且偏移前被水面反射←出现倒影彩虹。没有人看见倒影彩虹，否定了这个命题的后件，不能得出任何确定性的结论。<br>I未在题干中涉及，无法判断真假。<br>Ⅱ没有人在滴水湖看见倒影彩虹，否定后件不能否定前件，而Ⅱ则是否定前件的表述，判断为假。<br>Ⅲ未在题干中涉及，无法判断真假。<br>综上所述，I和Ⅲ无法判断真假，Ⅱ为假。","no":388},{"id":"1718789647188","type":"single","material":"","stem":"如果李锐会英语了，那么王伟、文瑞和张敏也肯定会英语。由此可以得知：","options":[{"label":"A","content":"如果李锐、文瑞和张敏都会英语，那么王伟也肯定会英语"},{"label":"B","content":"李锐如果不会英语，那么王伟、文瑞和张敏中至少有一个不会英语"},{"label":"C","content":"如果张敏不会英语，那么李锐和文瑞都不会英语"},{"label":"D","content":"如果王伟、文瑞不会英语，那么张敏不会英语"}],"answer":"A","explanation":"根据“如果”“那么”等关键词，可知本题考查假言命题的推理规则。<br>题干推理：李锐会英语→王伟、文瑞和张敏都会英语。<br>A项，肯定前件能得出肯定后件，可以推出。<br>B项，否定前件不能得出有效的结论，无法推出。<br>C项，否定联言命题的部分肢命题不能否定剩余的肢命题，无法推出<br>D项，否定联言命题的部分肢命题不能否定剩余的肢命题，无法推出。","no":389},{"id":"1718789647189","type":"single","material":"","stem":"某公司招聘业务经理，小张和小李前来应聘。小张说：“如果我做了业务经理，我会积极进取，开拓新业务。”小李说：“如果我做了经理，我会优化管理，精减人员。”最终，他们其中一人当上了业务经理，并顺利实现了自己的工作主张。<br>由此可知，以下说法必定为真的是：","options":[{"label":"A","content":"该公司不仅开拓了新业务，还精减了人员"},{"label":"B","content":"如果该公司开拓了新业务，那么肯定是小张当上了业务经理"},{"label":"C","content":"如果该公司精减了人员，那么肯定是小李当上了业务经理"},{"label":"D","content":"如果该公司没有开拓新业务，就肯定精减了人员"}],"answer":"D","explanation":"本题要求选择说法一定为真的一项，可以将题干信息转化为充分条件假言命题，再根据推理规则进行判断。<br>题干小张的话可以转化为：做经理→积极进取，开拓新业务。小李的话可以转化为：做经理→优化管理，精减人员。已知要么小张当经理，要么小李当经理，则根据推理规则，即要么开拓新业务，要么精减人员。<br>A项，不相容选言命题不能两个选言肢均正确，排除。<br>B项，充分条件假言命题肯定后件不能肯定前件，为无效推理，排除。<br>C项，充分条件假言命题肯定后件不能肯定前件，为无效推理，排除。<br>D项，没有开拓新业务，否定了小张推理的后件，可以得出否定的前件，即小张没有做经理，因此小李一定做经理，根据小李的推理，肯定前件可以肯定后件，即一定精减了人员，正确。","no":390},{"id":"1718789647190","type":"single","material":"","stem":"<p>医生赵某才智出众，他是人大代表。</p><p>如果上述断定为真，则以下各项能判断真假的是：</p><p>I.只有才智出众，才能成为人大代表</p><p>Ⅱ.所有才智出众的人都不是人大代表</p><p>Ⅲ.不是所有才智出众的人都是人大代表</p>","options":[{"label":"A","content":"只有Ⅱ"},{"label":"B","content":"只有Ⅲ"},{"label":"C","content":"I和Ⅱ"},{"label":"D","content":"Ⅱ和Ⅲ"}],"answer":"A","explanation":"题干为联言命题，即赵某才智出众，且赵某是人大代表。","no":391},{"id":"1718789647191","type":"single","material":"","stem":"什么才是伟大的文学作品?它必须同时具备丰满的情节，细腻的描述，能将主人公的命运置身于时代的大背景下，最终展现世世代代流淌于人类血液中的共性。<br>由此可以推出：","options":[{"label":"A","content":"一部文学作品之所以伟大在于它具备丰满的情节"},{"label":"B","content":"只关注个人世界的作品也能够成为伟大的文学作品"},{"label":"C","content":"不能体现人类共性的作品不是伟大的文学作品"},{"label":"D","content":"情节丰满、描述细腻、能将主人公命运置身于时代大背景下的作品就是伟大的文学作品"}],"answer":"C","explanation":"题干中出现“必须”这一逻辑关联词，将其翻译为假言命题，根据推理规则进行推理即可。由题干条件可知，第二句话是一部作品成为伟大的文学作品的必要条件，即伟大的文学作品→丰满的情节，细腻的描述，能将主人公的命运置身于时代的大背景下，最终展现世世代代流淌于人类血液中的共性。<br>A项，可以理解为一部作品因为具备丰满的情节而伟大，即肯定了题干假言命题后件中的一个联言肢，无法推出肯定的前件，错误。<br>B项，只关注个人世界的作品是否为伟大的文学作品在题干中没有体现，错误。<br>C项，否定后件推出否定前件，正确。<br>D项，肯定后件不能肯定前件，错误。","no":392},{"id":"1718789647192","type":"single","material":"","stem":"通常情况下，伤害行为的受害者会通过法律渠道表达利益诉求。但是，如果制度不公或失效，就会引发更多的社会伤害行为：不但强势者可能会进一步伤害弱势者，而且他们也可能受到弱势者的伤害；弱势者也可能对其他弱势者造成伤害，造成“弱势对弱者的欺凌”。这样一来，整个社会就会弥漫着一股戾气，给日常生活带来严重的不安与不快。<br>由此可以推出：","options":[{"label":"A","content":"只有制度不公或失效，强势者才会伤害弱势者"},{"label":"B","content":"如果制度不公或失效，弱势者就会伤害强势者"},{"label":"C","content":"只有制度公正且有效，才能防止引发更多的社会伤害行为"},{"label":"D","content":"如果制度公正且有效，就能给日常生活带来安宁与快乐"}],"answer":"C","explanation":"题干中是一个充分条件假言命题：制度不公或失效→引发更多的社会伤害行为(强势者可能会进一步伤害弱势者，也可能受到弱势者的伤害；弱势者也可能对其他弱势者造成伤害)→给日常生活带来严重的不安与不快。<br>A项，混淆了充分条件和必要条件，推不出。<br>B项，根据题干可知，如果制度不公或失效，弱势者可能会伤害强势者，选项表述过于绝对，推不出。<br>C项，否定后件可以否定前件，不引发更多的社会伤害行为→制度公正且有效，C项可以推出。<br>D项，否前不能否后，无法推出。","no":393},{"id":"1718789647193","type":"single","material":"","stem":"某研究所人员结构状况如下：所有女性都拥有博士学位，有的男博士有高级职称，但所里也存在既没有博士学位也没有高级职称的人员。<br>根据以上陈述，可以推出以下哪项?","options":[{"label":"A","content":"有的男性没有高级职称"},{"label":"B","content":"有的女性有高级职称"},{"label":"C","content":"所有男性都拥有高级职称"},{"label":"D","content":"有的女性没有高级职称"}],"answer":"A","explanation":"本题涉及直言命题和复言命题，可以利用相关命题的推理规则进行解题。<br>由题干可知，有的人员“既没有博士学位也没有高级职称”,这是一个联言命题。根据“所有女性都拥有博士学位”,否定了上述联言命题的一个联言肢，则可以否定整个联言命题，可推出所有女性并非“既没有博士学位也没有高级职称”,那么“既没有博士学位也没有高级职称”的只能为男性，而联言命题为真，其所有联言肢均为真，可知有的男性没有高级职称，A项正确、C项错误。<br>前面已经推出所有女性并非“既没有博士学位也没有高级职称”,结合“所有女性都拥有博士学位”可推出存在以下两种情况：①所有女性都拥有博士学位，但都没有高级职称，此时B项错误；②所有女性都拥有博士学位，也都有高级职称，此时D项错误。","no":394},{"id":"1718789647194","type":"single","material":"","stem":"在摩天大楼里工作的人大多数都是白领阶层，英语水平四级以上是成为外企白领的必要条件，外企中只有白领阶层的办公地点设在摩天大楼里。<br>根据以上描述，以下哪项是不正确的?","options":[{"label":"A","content":"在摩天大楼里的白领不一定是在外企工作"},{"label":"B","content":"外企中英语水平四级以上的未必是白领"},{"label":"C","content":"英语水平四级以上的白领可能不在摩天大楼里工作"},{"label":"D","content":"外企中英语水平四级以下者可能在摩天大楼里工作"}],"answer":"D","explanation":"题干包含“必要条件”“只有”等关键词，可将题干信息转化为假言命题，再结合推理规则进行解题。<br>题干推理：①大多数在摩天大楼里工作的人→白领阶层；②外企白领→英语水平四级以上；③在摩天大楼工作的外企职员→外企白领阶层。<br>A项，根据上述推理无法得出“在摩天大楼里的白领”与“在外企工作”之间的联系，说明在摩天大楼里的白领不一定是在外企工作的，该项可能为真。<br>B项，根据②肯定后件、否定前件，该项可能为真。<br>C项，根据上述推理无法得出“英语水平四级以上的白领”与“在摩天大楼里工作”之间的联系，说明英语水平四级以上的白领可能不在摩天大楼里工作，该项可能为真。<br>D项，根据②否定后件可推出否定前件，即英语水平四级以下者→不是外企的白领阶层，再根据③否定后件可推出否定前件，即不是外企白领阶层→不在摩天大楼里工作或不是外企职员，因为已经明确其是外企职员，所以一定不在摩天大楼里工作，因此该项错误。","no":395},{"id":"1718789647195","type":"single","material":"","stem":"甲、乙、丙、丁四个小孩在院子里踢球，突然球飞向玻璃窗，玻璃碎了。房屋主人出来问四个小孩是谁踢碎的。甲说：“是丁干的。”乙说：“不是我干的。”丙说：“是甲干的。”丁说：“甲是在诬陷。”<br>已知他们当中只有一个人说假话。那么踢碎玻璃的是：","options":[{"label":"A","content":"甲"},{"label":"B","content":"乙"},{"label":"C","content":"丙"},{"label":"D","content":"丁"}],"answer":"A","explanation":"考查直言命题的对当关系。甲和丁说的话矛盾，必有一真一假。由“只有一个人说假话”，则乙、丙说的必为真，所以，是甲踢碎的。故答案选A。","no":396},{"id":"1718789647196","type":"single","material":"","stem":"对任何人而言，只要在做自己喜欢的事，就不算是浪费时间。不是所有事情的价值都浮于表面，让你一眼就可以辨明。如果一个人一生都做自己不喜欢的但有用的事，这样的人生就显得平淡。<br>根据以上陈述，下列正确的是：","options":[{"label":"A","content":"只有小王做了自己喜欢的事，他才不算是浪费时间"},{"label":"B","content":"只要做自己喜欢的事，这些事的价值就可以辨明"},{"label":"C","content":"小王做的有的事情的价值浮于表面，容易辨明"},{"label":"D","content":"如果小王的一生丰富多彩，那么他或者做了自己喜欢的事，或者做了没用的事"}],"answer":"D","explanation":"由题干可得：①做自己喜欢的事⇒不算浪费时间；②有的事情的价值不是浮于表面⇒不能一眼辨明；③一生都做自己不喜欢但有用的事⇒人生平淡。根据①,A项错把充分条件假言命题当作必要条件假言命题；根据①②无法推出B项；根据②,C项否前不能否后；根据③,D项否后则否前，正确。故答案为D。","no":397},{"id":"1718789647197","type":"single","material":"","stem":"一个民族必须具有民族的自信心、自尊心和民族凝聚力，这个民族才能够自立于世界。如果丧失了它，这个民族就没有了希望，而民族的自尊心、自信心和民族凝聚力又是基于对文化的优秀传统有所认识和了解，才开始萌生的。<br>所以：","options":[{"label":"A","content":"一个民族只要继承自己的传统，自然就会有凝聚力"},{"label":"B","content":"一个民族要增强自信心、自尊心和民族凝聚力，首先要加强优秀的民族文化传统的教育"},{"label":"C","content":"一个民族要增强其自信心、自尊心和民族凝聚力，首先要大力发展经济，“财大才能气粗”"},{"label":"D","content":"民族的优秀传统文化已扎根于民族成员之中，不需要外界的努力也能为其成员所认识"}],"answer":"B","explanation":"题干的逻辑关系是：民族能够自立于世界⇒必须具有民族的自信心、自尊心和民族凝聚力⇒对文化的优秀传统有所认识和了解。A项肯定后件不能肯定前件，错误；B项肯定前件可以肯定后件，正确；C项“大力发展经济”题干并未提及，是无关项；D项在题干中也没有体现。故答案选B。","no":398},{"id":"1718789647198","type":"single","material":"","stem":"对于本届世界杯足球赛，德国队和巴西队谁能进入决赛，甲乙丙丁四人作出下列预测：<br>甲：我认为巴西队不可能进入决赛<br>乙：或者是德国，或者是巴西<br>丙：如果德国能进决赛，那么巴西队一定进不了决赛<br>丁：德国和巴西都能进决赛<br>结果只有一人的预测是假的，由此可以推出：","options":[{"label":"A","content":"德国和巴西都能进入决赛"},{"label":"B","content":"甲的话是假的"},{"label":"C","content":"德国能进入决赛，并且丙的话是真的"},{"label":"D","content":"巴西队能进决赛，德国队进不了决赛"}],"answer":"C","explanation":"分析甲、乙、丙、丁四个人的话，可知丙和丁的话矛盾，必有一真一假，由只有一假可知甲和乙的话为真。故巴西不可能进入决赛，德国可以进决赛，即丙的话为真。故答案为C。","no":399},{"id":"1718789647199","type":"single","material":"","stem":"小王比小李高，小赵比小钱高，小李比小孙矮，小孙比小钱矮。<br>据此，我们知道：","options":[{"label":"A","content":"小李比小赵矮"},{"label":"B","content":"小王比小赵高"},{"label":"C","content":"小孙比小王矮"},{"label":"D","content":"小孙比小赵高"}],"answer":"A","explanation":"由题干中已知的信息可知，身高关系为：小赵>小钱>小孙>小李，小王>小李，所以可以推出A项正确。","no":400},{"id":"1718789647200","type":"single","material":"","stem":"某机关田径运动会有3个短跑项目，分别是60米、100米和200米。老张、老王和老李分别参加了其中的一种，而且三人参赛的项目还不一样。小张、小王和小李作了以下猜测：<br>小张：老张参加了60米，老王参加了100米。<br>小王：老李没参加100米，老王参加了60米。<br>小李：老张没参加60米，老王参加了200米。<br>如果他们的猜测都对了一半，则以下哪项为真？","options":[{"label":"A","content":"老张、老王和老李分别参加200米、100米和60米"},{"label":"B","content":"老张、老王和老李分别参加60米、200米和100米"},{"label":"C","content":"老张、老王和老李分别参加100米、60米和200米"},{"label":"D","content":"老张、老王和老李分别参加200米、60米和100米"}],"answer":"A","explanation":"排除法。根据题意，三人参赛的项目不一样，他们的猜测都对了一半。小张小李对老张陈述矛盾，所以老王参加了100米或200米中的一个，答案在A或B中，又根据小王的表述，老李没参加100米。所以正确答案是A。","no":401},{"id":"1718789647201","type":"single","material":"","stem":"现在女性化妆品种类繁多，且不断出新，但每一种新产品的面世都能带来一股购买的热潮，并拥有一大群顾客，因此，有人认为，生产化妆品是没有什么风险的。<br>下列哪项如果为真，最能削弱上述论证？","options":[{"label":"A","content":"有一些生产化妆品的企业面对合资企业产品及进口化妆品的竞争不得不转产"},{"label":"B","content":"不断有新产品面世，就一定不断有老产品被淘汰"},{"label":"C","content":"爱美是女人的天性，所以化妆品永远会有市场"},{"label":"D","content":"人们对某种化妆品的需求量总是有限的"}],"answer":"D","explanation":"题干由“每一种新化妆品面世都能带来一股购买的热潮，并拥有一大群顾客”，推出“生产化妆品是没有什么风险的”。A项一些企业的情况属于特例，削弱力度较弱；B项说明老产品会被淘汰而存在一定风险，但企业也可以不断推出新产品，所以削弱力度较弱；C项加强了题干；D项，说明人们对化妆品的需求量总是有限的，当市场饱和时则存在巨大风险，削弱了题干论证，力度最强。故答案选D。","no":402},{"id":"1718789647202","type":"single","material":"","stem":"在我们这个高速发展的社会，拆迁和建设的速度早已超出了人们的想象。而城市的发展总是伴随着城市的拆迁和建设，因此，有人认为，城市的发展是导致城市拆迁和建设的根本原因。<br>以下哪项如果为真，最能削弱上述结论：","options":[{"label":"A","content":"很少进行拆迁和建设的城市，往往都会发展得比较缓慢"},{"label":"B","content":"除城市发展外，工业化也是导致城市拆迁和建设的原因"},{"label":"C","content":"城市的发展过程必然会带来了很多正面的和负面的影响"},{"label":"D","content":"经济发展水平的提高，促进城市发展，带动城市的拆迁和建设"}],"answer":"D","explanation":"题干结论为：城市的发展是导致城市拆迁和建设的根本原因。A项支持了题干观点，排除；B项指出工业化是导致城市拆迁和建设的原因，但并不代表城市发展不是根本原因；C项为无关系，排除；D项说明经济发展水平的提高才是城市拆迁和建设的根本原因，削弱了题干观点。故答案选D。","no":403},{"id":"1718789647203","type":"single","material":"","stem":"一项关于肥胖症患者的研究发现，肥胖症患者60%以上患有抑郁症，由此推测，肥胖症患者由于肥胖，承受了巨大的心理压力，从而更易患上抑郁症。<br>以下最能削弱上述论证的一项是：","options":[{"label":"A","content":"抑郁症患者更容易暴饮暴食"},{"label":"B","content":"遗传因素是抑郁症的重要原因"},{"label":"C","content":"许多抑郁症患者并不肥胖"},{"label":"D","content":"我们身边有很多快乐的肥胖者"}],"answer":"A","explanation":"题干的观点为：肥胖症患者更容易患上抑郁症。A项说明是因为得了抑郁症更容易暴饮暴食而患上肥胖症，题干推论为因果倒置；B项为无关项；C、D两项仅指部分，削弱力度较弱。故答案选A。","no":404},{"id":"1718789647204","type":"single","material":"","stem":"据调查显示，1990年有70%的肝病患者都有酗酒行为。这说明，酗酒将极大增加患肝病的危险。<br>以下哪项如果为真，最能削弱上述结论？","options":[{"label":"A","content":"1990年世界酗酒的人数比1989年增加了70%"},{"label":"B","content":"其他原因也有可能增加患肝病的危险"},{"label":"C","content":"没有酗酒史的人也会患有肝病"},{"label":"D","content":"70%有酗酒行为的人并未患有肝病"}],"answer":"D","explanation":"题干根据70%的肝病患者都有酗酒行为，推出酗酒将极大增加患肝病的危险。A项，1990年酗酒的人数与题干论述无关，无法削弱题干结论。B项，其他原因可能增加患肝病的危险，无法说明酗酒是否会增加患肝病的危险，无法削弱题干结论。C项，不酗酒的人也患有肝病，也无法说明酗酒是否会增加患肝病的危险，无法削弱题干结论。D项，大部分酗酒的人没有得肝病，说明酗酒不能增加患肝病的危险，直接削弱了题干结论。故本题选D。","no":405},{"id":"1718789647205","type":"single","material":"","stem":"陈先生认为吸烟与健康之间并无太大关系，原因是在其认识的人当中，好几个患有肺癌的人都是从来不吸烟的人。<br>以下各项如果为真，则哪项不能反驳陈先生上述观点？","options":[{"label":"A","content":"癌症的起因是许多医学工作者研究的课题，目前还没有一个确定的结论"},{"label":"B","content":"长期吸二手烟的人比起吸烟者本身更容易患上肺癌"},{"label":"C","content":"在陈先生认识的人当中吸烟的人都是年轻小伙子，不吸烟的都是体弱病残的老人"},{"label":"D","content":"排除患肺癌的人，在陈先生认识的人当中，吸烟者比从来不吸烟者患呼吸道类疾病的人明显要多"}],"answer":"A","explanation":"削弱型题目，可以使用排除法。论点为：吸烟与健康之间并无太大关系。要想削弱这个结论，就要说明，吸烟与健康之间有关系，选项中，B、C、D表述的都是这一内容，所以排除。选A。","no":406},{"id":"1718789647206","type":"single","material":"","stem":"一项新的研究表明，存在于舌头上的能检测甜味的蛋白质，也存在于肠道。研究人员据此推测，肠道同样能尝出糖果的味道。这项研究的负责人说：“其实，肠道与舌头品尝甜味的方式是一样的。”<br>下列哪项最能支持上述推测？","options":[{"label":"A","content":"只要有这种检测甜味的蛋白质，就能尝到甜味"},{"label":"B","content":"除了甜味，肠道还能尝到酸味"},{"label":"C","content":"除了肠道，还有其它器官能够尝到甜味"},{"label":"D","content":"味觉可以通过其它感觉表达出来"}],"answer":"A","explanation":"加强型题目。题干由“肠道和舌头上都存在一种能检测甜味的蛋白质”，推测出“肠道也能品尝到甜味”。A项如果为真，根据肠道中存在这种蛋白质，即可推出肯定的后件，也即题干的推测，从而支持了题干推测。肠道是否能尝到酸味、是否有其它器官能尝到甜味、味觉是否能通过其它感觉表达出来，都与题干的推理无关，B、C、D三项都是无关项。故答案选A。","no":407},{"id":"1718789647207","type":"single","material":"","stem":"日常生活中，有些人喜欢用汤泡饭吃。对此，专家指出，这种吃饭方式是不可取的。<br>以下哪项说法如果为真能支持专家的观点？","options":[{"label":"A","content":"用汤泡饭吃，可加快饭菜通过咽喉、食管进入胃的速度"},{"label":"B","content":"用汤泡饭吃有助于防止便秘"},{"label":"C","content":"有些食物代谢产物溶解度低，容易在尿中析出，因此吃完饭后要大量喝汤"},{"label":"D","content":"用汤泡饭吃，会使消化系统的各道工序都乱了套，影响食物的消化"}],"answer":"D","explanation":"A、B两项支持了汤泡饭，削弱了专家的观点；C项饭后要大量喝汤与汤泡饭不是同一概念，属于无关项；D项说明这种吃饭方式不可取，支持了专家观点。故答案选D。","no":408},{"id":"1718789647208","type":"single","material":"","stem":"作家在其晚期的作品中没有像其早期那样严格遵守小说结构的成规。由于最近发现的一部他的小说的结构像他早期的作品一样严格地遵守了那些成规，因此该作品一定创作于他的早期。<br>上面论述所依据的假设是：","options":[{"label":"A","content":"作家在其创作晚期比早期更不愿意打破某种成规"},{"label":"B","content":"随着创作的发展，作家日益意识不到其小说结构的成规"},{"label":"C","content":"在其职业生涯晚期，该作家是其时代唯一有意打破小说结构成规的作家"},{"label":"D","content":"作家在其创作生涯的晚期没有写过任何模仿其早期作品风格的小说"}],"answer":"D","explanation":"题干结论是：该作品一定创作于早期，前提是：早期作品严格遵守了小说结构的成规，且这篇小说像早期作品一样遵守了成规。要推出结论，就要排除作品是晚期写的可能性，因此D项是必须假设的，否则如果在晚期时写过模仿早期作品风格的小说，则作品也可能是晚期的。A项不能得出该作品创作于早期，反而可以得出创作于晚期的结论；B、C两项作为假设都不能得出最后的结论。故答案选D。","no":409},{"id":"1718789647209","type":"single","material":"","stem":"某经济杂志《财富》为了了解S城市人们的收入及消费情况，在某期杂志中设计了一个问卷调查，调查其家庭收入情况，从而了解S市民的收入及消费情况，根据问卷回收统计，财富杂志因此得出，S城市的市民平均家庭年收入超过20万。以下哪项如果为真，最能削弱上述结论？","options":[{"label":"A","content":"很多大企业主最近不在S城市，去H城市参加一个企业论坛"},{"label":"B","content":"参加问卷调查的人数远远超过预计人数"},{"label":"C","content":"《财富》杂志的读者都是经济比较富裕的人士，而工薪阶层很少看该杂志"},{"label":"D","content":"《财富》杂志的层级还不高，富裕阶层一般都不看"}],"answer":"C","explanation":"题干由统计《财富》杂志某期的问卷调查结果得出，S城市的市民平均家庭年收入超过20万。C项指出《财富》杂志的读者都是经济比较富裕的人，则其样本不具有代表性，不能反映S城市的整体收入状况，削弱了题干结论。答案选C。","no":410},{"id":"1718789647210","type":"single","material":"","stem":"随着网络的普及，电子版图书也越来越多，其中包括电子版的文学名著而且价格很低。人们只要打开电脑，在网上几乎可以浏览到任何一本名著。电子版文学名著的问世，会改变大众的阅读品味，有利于造就高素质读者群体。<br>以下最能削弱上述结论的一项是：","options":[{"label":"A","content":"对文学没有兴趣的人不会因为文学名著的价钱高低或者是否方便而阅读文学名著"},{"label":"B","content":"文学名著的普及率一直不如娱乐杂志、时事报刊等大众读物"},{"label":"C","content":"许多读者认为阅读电子书籍的感觉不如阅读印刷书籍的那么好，宁愿选择印刷版读物"},{"label":"D","content":"在互联网上阅读文学名著仍然需要收费"}],"answer":"A","explanation":"题干由“电子版图书越来越多且价格便宜阅读方便”推出“电子版文学名著的问世会改变阅读品味，有利于造就高素质读者”。A项指出对文学没有兴趣的人不会受到价格或者是否方便的影响，即题干结论不成立，最能削弱。B项为无关项；C项许多读者的偏好削弱程度有限；题干已经指出价格便宜，因此D项也不能削弱。故答案选A。","no":411},{"id":"1718789647211","type":"single","material":"","stem":"只有加大查处、惩罚的力度，对贪腐官员决不姑息手软，才能让官员“不敢腐”；只有在权力运作的每个环节建立和完善相关制度，才能让官员“不能腐”。但是，如果官员缺乏必要的廉耻之心，单纯依靠制度，那么，他们一定会找到制度的漏洞。相反，如果官员有一定的廉耻之心，那么，即便存在一些制度漏洞，他们也不会有意利用，而是会克制自己，甚至会修补这些漏洞，真正做到“不想腐”。<br>根据以上陈述，可以推出的是：","options":[{"label":"A","content":"如果官员有一定的廉耻之心，一般不会发现制度的漏洞，即使发现了，也不会利用，只会去修补它们"},{"label":"B","content":"如果官员有一定的廉耻之心，就会加强自我约束，不会有意利用制度的漏洞，从心里清除腐败的念头"},{"label":"C","content":"如果官员缺乏必要的廉耻之心，只要加大查处、惩罚的力度，决不姑息手软，他们就“不敢腐”"},{"label":"D","content":"如果官员缺乏必要的廉耻之心，只要建立和完善权力运作各个环节的相关制度，他们就“不能腐”"}],"answer":"B","explanation":"题干可转化为充分条件假言命题：①不敢腐→加大查处、惩罚力度，对贪腐官员绝不姑息手软；②不能腐→在权力运作的每个环节建立和完善相关制度；③官员缺乏必要的廉耻之心，单纯依靠制度→找到制度的漏洞；④官员有一定的廉耻之心→不会有意利用漏洞，会克制自己。A项的“不会发现”与题干不符，排除；B项根据④肯定前件可推出肯定后件，正确；C项根据①肯定后件不能肯定前件，错误；D项根据②肯定后件不能肯定前件，错误。故答案选B。","no":412},{"id":"1718789647212","type":"single","material":"","stem":"住在A市的每一个人都乘坐公共汽车；没有一个人能够不关注汽油价格的上涨，除非他住在A市；每一个乘坐公共汽车的人都发牢骚。<br>根据上面的陈述，下列哪项必定为真？<br>Ⅰ.所有不关注汽油价格上涨的人都乘坐公共汽车<br>Ⅱ.不发牢骚的人当中没有一个不关注汽油价格的上涨<br>Ⅲ.所有发牢骚的人都不关注汽油价格的上涨","options":[{"label":"A","content":"Ⅰ"},{"label":"B","content":"Ⅰ和Ⅱ"},{"label":"C","content":"Ⅱ和Ⅲ"},{"label":"D","content":"Ⅰ、Ⅱ和Ⅲ"}],"answer":"B","explanation":"题干逻辑关系为：不关注汽油价格的上涨⇒住在A市⇒乘坐公共汽车⇒发牢骚。Ⅰ,肯定前件可以肯定后件，正确；Ⅱ,“没有一个不”＝“所有都”，否定后件可以否定前件，正确；Ⅲ,肯定后件不能肯定前件，错误。只有Ⅰ和Ⅱ正确。故答案选B","no":413},{"id":"1718789647213","type":"single","material":"","stem":"将刚出生的小猫的一只眼睛挡住两周，那只眼睛就会永久失去正常视力，这说明出生初期是正常视力发育的关键时期。<br>那么下列选项中最能支持以上说法的是？","options":[{"label":"A","content":"刚出生的小动物通常视力不好"},{"label":"B","content":"成年人蒙住一只眼两周后，另一只眼视力正常"},{"label":"C","content":"当儿童戴墨镜时，视力会受影响"},{"label":"D","content":"四个月大的动物比刚出生的小动物，蒙眼两周所产生的影响小"}],"answer":"D","explanation":"题干说法是出生初期是正常视力发育的关键时期。A项“视力不好”与是否是发育关键期无关；B项“成年人”、C项“儿童”都不属于出生初期，与题干说法无关；D项说明越大蒙眼产生的影响越小，即说明出生初期是正常视力发育的关键时期，支持了题干说法。故答案选D。","no":414},{"id":"1718789647214","type":"single","material":"","stem":"《都市日报》和《都市晚报》都有一个专门的校对小组负责防止错别字出现在每天刊出的报纸中。但是，《都市日报》发表的文章中2%的文字有错误，而《都市晚报》却没有出现此类错误。因此，《都市晚报》的校对小组在发现错别字方面比《都市日报》的校对小组更有效率。<br>以下哪项是上述论证所必须假设的？","options":[{"label":"A","content":"大多数在《都市日报》上发表的文章中都或多或少有错别字出现"},{"label":"B","content":"在《都市晚报》上发表的文章，在校对之前至少是有错别字存在的"},{"label":"C","content":"总体上看，《都市晚报》校对小组的成员比《都市日报》校对小组的成员素质更高"},{"label":"D","content":"一份报纸错别字数量的多少是衡量该报纸编辑工作是否细致的一个重要标准"}],"answer":"B","explanation":"题干根据“《都市日报》发表的文章中2%的文字有错误，而《都市晚报》却没有此类错误”得出“《都市晚报》的校对小组在发现错别字方面比《都市日报》的校对小组更有效率”这一结论。B项是必须假设的，否则如果在《都市晚报》上发表的文章本身就没有错别字，则题干结论不成立；A、C、D三项为无关项，不是必须假设的。故答案选B。","no":415},{"id":"1718789647215","type":"single","material":"","stem":"“燃素说”是一种关于燃烧的解释理论。三百年前的化学家们认为火是由无数细小而活泼的微粒构成的物质实体，这种火微粒构成的火的元素被命名为燃素。然而“燃素说”后来被证明是个错误的理论，因此“燃素说”中的理论实体“燃素”也是不存在的。<br>若使上述推理过程有效，则还需添加以下作为前提的是：","options":[{"label":"A","content":"错误的理论中的理论实体都是错误的"},{"label":"B","content":"错误的理论中的理论实体都是不存在的"},{"label":"C","content":"只有错误的理论才会构建错误的理论实体"},{"label":"D","content":"只有错误的理论才会构建不存在的理论实体"}],"answer":"B","explanation":"题干由“燃素说”被证明是个错误的理论，推出“燃素说”中的理论实体“燃素”也是不存在的。两者之间缺乏错误的理论与理论实体不存在的关系，B项为需要补充的前提。故答案选B。","no":416},{"id":"1718789647216","type":"single","material":"","stem":"亮亮、明明、强强参加今年高考，都准备报考军事院校，考完后在一起议论自己考试可能的结果，并且各自发表了自己的想法。亮亮说：“嘻嘻，我肯定能考上重点军事院校。”明明说：“唉！我肯定考不上重点军事院校了。”强强说：“啊哈!要是不论重点不重点，我考上肯定是没有问题的。”高考成绩公布后，三位同学中考上重点军事院校、一般军事院校、没有考上军事院校的各一人。此外，三位同学中有一位同学当初预测是正确的，另外两位同学的预测正好相反。<br>由此，可以推出：","options":[{"label":"A","content":"亮亮没考上军事院校，明明考上一般军事院校，强强考上重点军事院校"},{"label":"B","content":"亮亮没考上军事院校，明明考上重点军事院校，强强考上一般军事院校"},{"label":"C","content":"亮亮考上一般军事院校，明明没考上军事院校，强强考上重点军事院校"},{"label":"D","content":"亮亮考上一般军事院校，明明考上重点军事院校，强强没考上军事院校"}],"answer":"B","explanation":"题干条件：①亮亮考上重点军事院校；②明明考不上重点军事院校；③强强考上重点或者一般军事院校。根据题干可知，三个条件中只有一个为真。假设①为真，亮亮考上了重点军事院校，②为假，则明明也考上了重点军事院校，与“三位同学中考上重点军事院校、一般军事院校、没有考上军事院校的各一人”矛盾，所以①必然为假，亮亮没有考上重点军事院校。假设②为真，明明考不上重点军事学院，③为假，强强考不上军事院校，那么没有人考上重点军事院校，与“三位同学中考上重点军事院校、一般军事院校、没有考上军事院校的各一人”矛盾，所以②必然为假，明明考上了重点军事学院。因为①②均为假，所以③一定为真，即强强能考上军事院校，根据明明考上了重点军事院校、亮亮没考上军事院校可知，强强考上了一般军事院校。故本题选B。","no":417},{"id":"1718789647217","type":"single","material":"","stem":"某饭店宣布“新开发的排放油烟系统，虽然还未完成为期6个月的试验检验，但是至今并未发生故障，所以公司决定要安装在饭店后厨，毕竟这个系统可以更有效地解决油烟问题。”该饭店的主厨说：“我们不能使用未完成试验的排放油烟系统，6个月以后再说吧。”<br>以下哪项最能支持主厨的反对意见？","options":[{"label":"A","content":"能更有效地处理油烟的新系统也可能存在新问题"},{"label":"B","content":"尽管新的排放油烟系统比以前的难操作，但有一些新功能"},{"label":"C","content":"新的排放油烟系统保修期更长，维修方便"},{"label":"D","content":"许多安全事故都是排放油烟系统造成的"}],"answer":"A","explanation":"主厨的观点为：即使排放油烟系统没问题，也要等到6个月的试验检验完毕再安装。A项支持了主厨的观点，虽然油烟处理没有问题了，但可能会出现其他新问题，所以还得等到6个月的试验期完毕再安装。B、C、D三项为无关项，故答案选A。","no":418},{"id":"1718789647218","type":"single","material":"","stem":"甲乙丙三人在玩骰子游戏，骰子有六面，每面分别是一、二、三、四、五、六点，他们规定：如果出现一、三点面，甲赢；如果出现二、四面点面，乙赢；如果出现五、六点面，丙赢。甲说：“如果再少一点我也不会赢”。乙说：“如果再少一点的话我就赢了。”丙说：“如果再多一点也是我赢。”<br>那么，现在出现的点数是：","options":[{"label":"A","content":"三点"},{"label":"B","content":"五点"},{"label":"C","content":"四点"},{"label":"D","content":"二点"}],"answer":"B","explanation":"由丙说的话可知丙现在赢了，再多一点也是丙赢，即现在出现的点数是五。代入甲、乙的话也正确。故答案为B。","no":419},{"id":"1718789647219","type":"single","material":"","stem":"小曾、小孙、小石三个人是好朋友，他们每个人都有一个妹妹，且都比自己小<br>11岁。三个妹妹的名字叫小英、小丽、小梅。已知小曾比小英大9岁，小曾与小丽年龄之和是52岁，小孙与小丽年龄之和是54岁。<br>由此可知，谁是谁的妹妹？","options":[{"label":"A","content":"小梅是小孙的妹妹，小丽是小曾的妹妹，小英是小石的妹妹"},{"label":"B","content":"小梅是小石的妹妹，小丽是小孙的妹妹，小英是小曾的妹妹"},{"label":"C","content":"小梅是小曾的妹妹，小丽是小石的妹妹，小英是小孙的妹妹"},{"label":"D","content":"小梅是小曾的妹妹，小丽是小孙的妹妹，小英是小石的妹妹"}],"answer":"C","explanation":"小曾、小孙、小石都比自己的妹妹大11岁，则每个人和妹妹的年龄应该分别为一奇一偶，加起来都应为奇数。小曾比小英大9岁则小英不是小曾的妹妹，排除B项；小曾与小丽的年龄和是52岁则小丽不是小曾的妹妹，排除A项；小孙和小丽的年龄和是54岁则小丽不是小孙的妹妹，排除D项。故答案选C。","no":420},{"id":"1718789647220","type":"single","material":"","stem":"现在人们常常提到大学毕业生就业难。但据统计，今年我国就业市场空缺岗位与求职人数的比率一般大于1，劳动力市场的需求大于供给。而在求职人群中，大学毕业生的文化水平较高。因此，我国大学毕业生实际上不存在就业难的问题。<br>以下信息如果为真，能够有效反驳上述结论的是：","options":[{"label":"A","content":"当前经济下行压力较大，不少企业严控用工成本，已经开始裁员"},{"label":"B","content":"劳动力市场最紧缺的一些岗位主要是适合高级技工的岗位"},{"label":"C","content":"大学毕业生愿意从事的岗位往往竞争激烈"},{"label":"D","content":"一些高级技能人才的收入水平要高于大学毕业生"}],"answer":"B","explanation":"题干由“劳动力市场的需求大于供给”推出“我国大学毕业生实际上不存在就业难问题”的结论。B项指出最紧缺的岗位主要适合高级技工，而非大学毕业生，因此大学毕业生还是存在就业难问题的，削弱了题干结论。A项为无关项；C项说的是大学毕业生的自主意愿，可能岗位需求是存在的，只是大学毕业生不愿意去，并不能说明存在就业难问题，排除；D项也为无关项。故答案选B。","no":421},{"id":"1718789647221","type":"single","material":"","stem":"某科研机构研发了一项神经刺激技术，他们在实验中对一批滑雪选手实施了该刺激，持续数周后发现，相比未接受刺激的选手，接受刺激选手的跳跃能力和协调性分别提高了10%和15%。本国体育部门计划与该机构合作，在滑雪运动员的训练、比赛中推广使用这一技术。<br>以下哪项为真，最能质疑该国体育部门的计划？","options":[{"label":"A","content":"未接受刺激的运动员通过正常训练也能提高跳跃能力和协调性"},{"label":"B","content":"这项合作会增加该国体育部门的经费支出"},{"label":"C","content":"该国是传统滑雪强国，滑雪成绩长期处于世界领先地位"},{"label":"D","content":"这项技术会降低运动员的专注力，而专注力是能力发挥的前提"}],"answer":"D","explanation":"因为神经刺激技术能使滑雪运动员的跳跃能力和协调性分别都有提高，所以体育部门计划推广使用这一技术。D项说明了这项技术会降低运动员的专注力，而专注力是能力发挥的前提，则有可能实施了这个技术后，即使能力提高了也没办法发挥，达不到预想的结果，有力地质疑了体育部门的计划。故答案选D。","no":422},{"id":"1718789647222","type":"single","material":"","stem":"小区居民代表说：“附近垃圾处理厂引起的污染危害了本小区居民的健康。”垃圾处理厂负责人说：“责任不在本厂。我们的研究表明，贵小区居民健康受损是由变异病菌引起的。”<br>下列哪一项如果成立，则能最有力削弱垃圾处理厂负责人的论断？","options":[{"label":"A","content":"垃圾处理厂的研究没有涉及该厂排出的有害物质的危害"},{"label":"B","content":"小区居民的生活方式近年来没有什么变化"},{"label":"C","content":"垃圾处理厂负责人所说的变异病菌由来已久"},{"label":"D","content":"垃圾处理厂引起的污染催生了变异病菌"}],"answer":"D","explanation":"垃圾处理厂负责人的观点为“小区居民的健康受损不是由垃圾处理厂引起的，而是由变异病菌引起的”。D项指出垃圾处理厂引起的污染催生了变异细菌，说明小区居民的健康受损归根结底还是由垃圾处理厂引起的，削弱了垃圾处理厂负责人的观点。A、B两项是无关项，C项支持了垃圾处理厂负责人的论断。故答案选D。","no":423},{"id":"1718789647223","type":"single","material":"","stem":"甲、乙、丙三个盒子，甲盒子上写着“鞋子不在此盒子中”，乙盒子上写着“鞋子在甲盒子中”，丙盒子上写着“鞋子不在此盒子中”。这三句话只有一句是真，那么：","options":[{"label":"A","content":"鞋子在甲盒子中"},{"label":"B","content":"鞋子在乙盒子中"},{"label":"C","content":"鞋子不在任何盒子中"},{"label":"D","content":"鞋子在丙盒子中"}],"answer":"D","explanation":"甲盒子上的话和乙盒子上的话为矛盾关系，二者必有一真一假，由题干中三句话中只有一真，可知丙盒子上的话“鞋子不在此盒子中”为假，可推出鞋子就在丙盒中。故答案选D。","no":424},{"id":"1718789647224","type":"single","material":"","stem":"一种汽车要畅销，必须领导时尚潮流；一种汽车，只有把握流行趋势，才能领导时尚潮流；而一个汽车设计师如果没有良好的观察力，他设计的汽车就不可能把握流行趋势。<br>以下哪项结论可以从题干的断定中推出？<br>Ⅰ.一个畅销汽车设计师，不可能没有良好的观察力。<br>Ⅱ.一种没有把握流行趋势的汽车，不可能畅销。<br>Ⅲ.一个没有领导时尚潮流的汽车设计师，一定没有良好的观察力。","options":[{"label":"A","content":"只有Ⅱ"},{"label":"B","content":"只有I和Ⅲ"},{"label":"C","content":"只有I和Ⅱ"},{"label":"D","content":"Ⅰ、Ⅱ和Ⅲ"}],"answer":"C","explanation":"题干推理关系：①汽车畅销⇒领导时尚潮流；②领导时尚潮流⇒把握流行趋势；③把握流行趋势⇒设计师具有良好观察力。①②③连锁推理得到Ⅰ正确。①②连锁推理，根据推理规则得到Ⅱ正确。②③连锁推理可得一个充分条件假言命题：④领导市场潮流⇒设计师有良好观察力。否定④的前件不能否定后件，Ⅲ不能推出。故本题选C。","no":425},{"id":"1718789647225","type":"single","material":"","stem":"某教科书编委会目前编的一本书中有甲、乙、丙、丁、戊、己六个章节，但校对的时候发现目前的章节安排是不合理的，必须删除某些章节才能保持整本书内容的精炼性、概括性。已知：<br>（1）如果保留章节甲，那么必须保留章节乙和章节丙<br>（2）如果保留章节戊，则必须同时删除章节丁和章节丙<br>（3）只有保留章节戊，才能保留章节己<br>（4）章节甲是重要的信息，不能删除<br>以上各项如果为真，则以下哪项一定为真？","options":[{"label":"A","content":"保留章节戊并且删除章节丙"},{"label":"B","content":"同时保留章节丙和章节丁"},{"label":"C","content":"保留章节戊并且删除章节丁"},{"label":"D","content":"同时删除章节戊和章节己"}],"answer":"D","explanation":"题干条件有：①如果保留甲，就必须同时保留乙和丙；②如果保留戊，必须同时删除丁和丙；③只有保留戊，才能保留己；④甲不能删除。由①④可知甲、乙、丙保留。由②可知，戊应该被删除，再根据③可推出，己被删除。因此，应该同时删除戊和己。故本题选D。","no":426},{"id":"1718789647226","type":"single","material":"","stem":"甲、乙、丙朋友三人，一位是山东人，一位是河北人，一位是山西人。现在只知道：丙比山西人年龄大，甲和河北人不同岁，河北人比乙年龄小。<br>由此可以推知：","options":[{"label":"A","content":"山西人年龄最小"},{"label":"B","content":"甲不是山西人"},{"label":"C","content":"河北人比甲年龄小"},{"label":"D","content":"河北人比山东人年龄大"}],"answer":"A","explanation":"由“甲和河北人不同岁”和“河北人比乙年龄小”可知河北人是丙，再由“丙比山西人年龄大”和“河北人比乙年龄小”可知乙是山东人，甲是山西人。即山东人（乙）>河北人（丙）>山西人（甲）。故本题选A。","no":427},{"id":"1718789647227","type":"single","material":"","stem":"某市举办民间文化艺术展演活动，小李、小张、大王和老许将作为剪纸、苏绣、白局和昆曲的传承人进行现场展演，每人各展演一项，展演按序一一进行。主办方还有如下安排：<br>（1）老许的展演要排在剪纸和苏绣的后面；<br>（2）白局、昆曲展演时小李只能观看；<br>（3）大王的展演要在剪纸前面；<br>（4）小张的展演要在昆曲和老许展演的前面。<br>根据上述安排，可以得出以下哪项？","options":[{"label":"A","content":"小李展演剪纸，排在第1位"},{"label":"B","content":"大王展演苏绣，排在第2位"},{"label":"C","content":"小张展演昆曲，排在第3位"},{"label":"D","content":"老许展演白局，排在第4位"}],"answer":"D","explanation":"由（1）可知老许不展演剪纸和苏绣，由（2）可知小李不展演白局和昆曲，由（3）可知，大王不展演剪纸，由（4）可知小张和老许都不展演昆曲","no":428},{"id":"1718789647228","type":"single","material":"","stem":"调查表明，国家放开二孩生育政策后，虽然有许多夫妻担心生得起养不起，但还是有很多夫妻有生育二孩的意愿。预计不久的将来，中国人口会有一个快速增长。<br>下列哪项如果为真，最能加强上述结论？","options":[{"label":"A","content":"生育技术有保障"},{"label":"B","content":"养育二孩有保障"},{"label":"C","content":"家庭收入快速增加"},{"label":"D","content":"国民经济快速增长"}],"answer":"B","explanation":"题干由“虽然许多夫妻担心生得起养不起，但有很多夫妻有生育二孩的意愿”推出“不久的将来，中国人口会有一个快速增长”。A项生育技术有保障不能证明夫妻最后会生育，为无关选项，B项养育二孩有保障则可以不用担心养不起，夫妻就可以实现生育二孩的意愿，支持了题干结论；C项家庭收入的快速增加不一定可以达到养育二孩所需要的收入水平，不能加强；同理，D项国民经济增长不代表夫妻双方可以达到养育二孩所需要的经济水平，不能加强。故本题选B。","no":429},{"id":"1718789647229","type":"single","material":"","stem":"粘菌素是一种20世纪50年代研发的，是多粘菌素类化合物的一种，它有着终极药物的称号，医生会尽可能避免使用这种药物，因为它会损伤患者的肾脏，因此，和其他抗生素对比细菌很难对粘菌素产生耐药性，研究人员发现，全世界范围内的细菌都存在一种抵抗粘菌素——一种终极抗生素的基因，因此有人认为粘菌素无法治疗细菌感染。<br>以下各项为真，最能支持上述观点的是：","options":[{"label":"A","content":"粘菌素的耐药基因存在于一种质粒DNA回路中，而且细菌之间共享了这种耐药基因"},{"label":"B","content":"曾经历史上出现过现存抗生素无法治疗细菌感染的案例"},{"label":"C","content":"大肠杆菌能够将其耐药性传递给其他与它不相干的细菌"},{"label":"D","content":"粘菌素被普遍用于农业，让猪长膘，并阻止农场动物患病"}],"answer":"A","explanation":"题干观点是粘菌素无法治疗细菌感染。A项说明细菌间共享了粘菌素的耐药基因，直接支持了题干观点；B项以前出现过不能说明现在也会出现，不能加强；C项大肠杆菌属于无关项；D项也不能加强题干观点。故答案选A。","no":430},{"id":"1718789647230","type":"single","material":"","stem":"威尔和埃克斯这两家公司，对使用他们的字处理软件的顾客，提供24小时的热线电话服务。既然顾客仅在使用软件有困难时才打电话，并且威尔收到的热线电话比埃克斯收到的热线电话多四倍，因此，威尔的字处理软件一定是比埃克斯的字处理软件难用。<br>下列哪项如果为真，则最能够有效地支持上述论证？","options":[{"label":"A","content":"拥有埃克斯字处理软件的顾客数比拥有威尔字处理软件的顾客数多三倍"},{"label":"B","content":"埃克斯收到的关于字处理软件的投诉信比威尔多两倍"},{"label":"C","content":"这两家公司收到的热线电话数量逐渐上升"},{"label":"D","content":"威尔热线电话的号码比埃克斯的号码更公开"}],"answer":"A","explanation":"加强型题目。题干由“威尔收到的热线电话比埃克斯收到的多四倍”得出结论：威尔的字处理软件比埃克斯的难用。如果A项为真，则拥有埃克斯的字处理软件的顾客更多，但埃克斯收到的热线电话更少，加强了题干的论据，从而支持了结论；B项和D项都削弱了结论；C项是无关项。","no":431},{"id":"1718789647231","type":"single","material":"","stem":"挪威研究人员分析了该国过去几十年里230万份出生记录，以及相应孕妇的健康数据，结果发现，如果母亲怀孕期间出现妊娠剧吐症状，女儿后来怀孕时也出现该症状的可能性是其他人的3倍。研究还表明，孕妇妊娠剧吐与腹中胎儿是否含有来自丈夫一方的相关基因没有关系，导致这一症状的基因只可能来自母亲。因此研究人员认为妊娠剧吐与父亲的基因无关，而是由母亲遗传给女儿。<br>以下哪项如果为真，最能削弱上述结论？","options":[{"label":"A","content":"女儿和母亲生活的自然和家庭环境（气候、饮食习惯等）比较类似"},{"label":"B","content":"一项亚洲研究表明，母亲有妊娠剧吐，女儿出现的可能性是其他人的1.5倍"},{"label":"C","content":"研究表明，外婆怀孕时有妊娠剧吐，外孙女出现的可能性是其他人的3倍"},{"label":"D","content":"在过去几十年中，挪威妇女吸烟的比例逐年上升，而吸烟与妊娠剧吐有关"}],"answer":"A","explanation":"题干结论是妊娠剧吐与父亲的基因无关，而是由母亲遗传给女儿。A项说明妊娠剧吐并不是由母亲遗传给女儿，而是由于自然和家庭环境的原因引起的，即题干结果是另有他因，削弱了题干结论；B、C两项加强了题干结论；D项是无关项。故答案选A。","no":432},{"id":"1718789647232","type":"single","material":"","stem":"有调查表明，学生玩手机时间过长会影响学习成绩。因此，学校做出决定，禁止学生在上课期间使用手机。<br>以下最能质疑该学校决定的一项是：","options":[{"label":"A","content":"学生上课期间使用手机查询学习资料"},{"label":"B","content":"学生使用手机有利于提高交往能力"},{"label":"C","content":"禁止使用手机会引起学生的不满情绪"},{"label":"D","content":"学生主要在课余时间里使用手机"}],"answer":"D","explanation":"题干中学校决定禁止学生在上课期间使用手机，来避免学生因玩手机而影响成绩。D项指出学生基本不在上课期间使用手机，即学校的决定无法起到作用，最能质疑题干。A项只能说明上课期间用手机并不影响学习，而学校的目的是避免学生玩手机时间过长而影响学习，力度较弱；B、C两项为无关项。故答案选D。","no":433},{"id":"1718789647233","type":"single","material":"","stem":"有人向某市政府提议应该在所有新建的房屋内安装一种起火时会自动激发的洒水器。但是一位房地产开发商认为，既然90%的房屋着火都是被家庭成员扑灭的，所以安装室内自动洒水器对灭火意义不大。<br>以下哪项如果为真，则最能削弱房地产开发商的观点？","options":[{"label":"A","content":"大多数人都没有经过灭火技能的正规训练"},{"label":"B","content":"在住宅内安装烟雾探测器比安装洒水器要便宜得多"},{"label":"C","content":"该市消防队奔赴火场的时间要比全国平均时间短"},{"label":"D","content":"住宅着火导致的大部分财产损失是因为起火时家人都不在场"}],"answer":"D","explanation":"题干开发商的观点是：90%的房屋着火都是被家庭成员扑灭的，安装室内自动洒水器对灭火意义不大。D项指出起火时家人不在场是导致大部分财产损失的原因，即安装自动洒水器很有必要，直接反驳了开发商的观点。A项灭火技能、B项烟雾探测器、C项时间短，均与题干无关。故答案选D。","no":434},{"id":"1718789647234","type":"single","material":"","stem":"一项最新研究发现，经常喝酸奶可降低儿童患蛀牙的风险。在此之前，也有研究人员提出酸奶可预防儿童蛀牙，还有研究显示，黄油、奶酪和牛奶对预防蛀牙并没有明显效果。虽然多喝酸奶对儿童的牙齿有保护作用，但酸奶能降低蛀牙风险的原因仍不明确。目前一种说法是酸奶中所含的蛋白质能附着在牙齿表面，从而预防有害酸侵蚀牙齿。<br>以下哪项如果为真，最能支持这项研究发现？","options":[{"label":"A","content":"黄油、奶酪和牛奶的蛋白质成分没有酸奶丰富，对儿童牙齿的防蛀效果不明显"},{"label":"B","content":"儿童牙龈的牙釉质处于未成熟阶段，对抗酸腐蚀的能力低，人工加糖的酸奶会增加蛀牙的风险"},{"label":"C","content":"有研究表明，儿童每周至少食用4次酸奶可将蛀牙发生率降低15%"},{"label":"D","content":"世界上许多国家的科学家都在研究酸奶对预防儿童蛀牙的作用"}],"answer":"C","explanation":"加强型题目。题干中要求支持的研究发现是：经常喝酸奶可以降低儿童患蛀牙的风险。其依据是：酸奶所含的蛋白质能附着在牙齿表面，从而预防有害酸侵蚀牙齿。C项指出儿童每周至少食用4次酸奶可降低蛀牙发生率，也就是说酸奶可以预防蛀牙，直接加强了题干的结论。A项虽然也起到一定的加强作用，但只是对论据起到了一定的加强作用，加强程度不如C项强。B项说明酸奶会增加蛀牙的风险，为削弱项；D项科学家都在研究，并没有得出一个确定的结论，因此不能加强结论。故答案选C。","no":435},{"id":"1718789647235","type":"single","material":"","stem":"某国针对一项政策议题的网络民调结果显示，支持者占46%，反对者占54%。而针对投票率的调查则显示，50岁以上中老年人的投票率达到78%，而18～40岁年轻人的投票率仅在43%。因此，此次网络民调的结果并没有反映出真实的民意，支持者的声音被反对者的声音掩盖了。<br>以下哪项如果为真，是作出上述结论最合理的假设？","options":[{"label":"A","content":"反对者大多是中老年人，支持者大多是年轻人"},{"label":"B","content":"该国50岁及以上中老年人口的比例大大超过年轻人的比例"},{"label":"C","content":"网络调查对象主要覆盖的是年轻人群和高知人群，他们多是坚定的支持者"},{"label":"D","content":"老年人中反对者比例较低，他们不易受网络影响，同时还被主流声音忽视"}],"answer":"A","explanation":"题干由老年人的投票率大大高于年轻人的投票率得出结论——网络民调中反对者远多于支持者，不能反映真实民意。中间缺乏”老年人多”和“反对者多”之间的联系，所以应在这两者之间建立联系，A项是得出题干结论的合理的假设。B项中老年人占总人口的比例大不能建立起两个概念之间的联系。C、D两项对题干结论起到反驳作用。故本题选A。","no":436},{"id":"1718789647236","type":"single","material":"","stem":"韩国人爱吃酸菜，翠花爱吃酸菜，所以，翠花是韩国人。以下哪个选项最明确地显示了上述推理的荒谬？","options":[{"label":"A","content":"所有的N国人都是大鼻子，乔治是N国人，所以，乔治是大鼻子"},{"label":"B","content":"会走路的动物都有腿，桌子有腿，所以，桌子是会走路的动物"},{"label":"C","content":"雪村爱翠花，翠花爱吃酸菜，所以，雪村爱吃酸菜"},{"label":"D","content":"所有金子都闪光，所以，有些闪光的东西是金子"}],"answer":"B","explanation":"题干的推理形式为所有C是B，A是B，故A是C。只有B项与之推理形式相似。","no":437},{"id":"1718789647237","type":"single","material":"","stem":"人口平均预算寿命是反映一个国家和地区人民健康水平的重要指标。第六次全国人口普查显示，2010年我国人口平均预期寿命达74.83岁，而建国初期我国人口平均预期寿命只有35岁左右。因此，六十多年前人们认为的老年人现在看起来其实只是中年人。以下哪项如果为真，最能削弱上述观点？","options":[{"label":"A","content":"建国以来，新生婴儿死亡数量的减少是人口平均预期寿命增加的最重要原因"},{"label":"B","content":"建国初期，国家正从战乱转向和平，全国形势仍不稳定，人口数量远低于现在"},{"label":"C","content":"建国初期，生活环境比艰苦，人们的营养水平比现在差得多"},{"label":"D","content":"随着医学的发展，医疗水平比建国初期有很大提高"}],"answer":"A","explanation":"题干由人口平均预期寿命增加推出结论：六十多年前人们认为的老年人现在看起来其实只是中年人。A项说明人口平均预期寿命增加是另有他因，即新生婴儿死亡数量的减少，而非老年人的寿命延长，从而削弱了题干观点；B、C、D三项均没有涉及人均寿命，属于无关项。故答案选A。","no":438},{"id":"1718789647238","type":"single","material":"","stem":"如果不能从根本上消除恐怖主义产生的源头，那么世界的和平与发展将受到极大影响。<br>由此可见：","options":[{"label":"A","content":"恐怖主义产生的源头没有从根本上得到消除"},{"label":"B","content":"世界的和平与发展至今都受到极大的影响"},{"label":"C","content":"只有从根本上消除恐怖主义产生的源头，才能保障世界的和平与发展"},{"label":"D","content":"只要从根本上消除恐怖主义产生的源头，那么世界的和平与发展将获得保障"}],"answer":"C","explanation":"题干是一个充分条件假言命题，A、B两项是其中两个肢命题，不能确定真假；否定前件不能否定后件，D项错误；否定后件可以否定前件，即世界和平与发展得到保障⇒从根本上消除恐怖主义产生的源头，再根据充分条件与必要条件的转化关系，C项正确。","no":439},{"id":"1718789647239","type":"single","material":"","stem":"因为青少年缺乏判断力，容易模仿可参照的学习对象，所以必须对青少年影视、书籍、网络等进行附加限制，近年来就有多篇新闻报道过青少年模仿影视情节，造成人身伤害的事例，在这点上应当吸取教训。<br>以下哪项为真，最能支持上述论断？","options":[{"label":"A","content":"青少年暴力模仿对象主要来自于家庭和同辈群体"},{"label":"B","content":"对影视进行分级，对青少年观影进行指导，有效降低了青少年犯罪率"},{"label":"C","content":"青少年暴力行为与当年最红的影视作品中主人公的行为一样"},{"label":"D","content":"与其他人相比，青少年更容易模仿影视情节"}],"answer":"B","explanation":"题干的论证关系是：容易模仿可参照的学习对象→必须对青少年影视、书籍、网络等进行附加限制。A项说明没有必要对青少年影视、书籍、网络等进行附加限制，削弱了题干的论证；B项说明对影视进行限制后能降低犯罪率，直接加强了题干论点；C项不能说明其行为是模仿之后的结果；D项只是说青少年更容易模仿，并不能说明其暴力行为来自对影视情节的模仿，加强力度不如B项。故答案选B。","no":440},{"id":"1718789647240","type":"single","material":"","stem":"如果你不会指法，那么你就不会打字；你就不可能使用电脑来写论文，除非你会打字。<br>以下（   ）项最符合上述的推论。","options":[{"label":"A","content":"如果你会指法，那么你就能使用电脑来写论文"},{"label":"B","content":"如果你不能使用电脑来写论文，那么你就不可能会指法"},{"label":"C","content":"如果你能使用电脑来写论文，那么你至少会指法"},{"label":"D","content":"如果你能打字，你就有可能使用电脑来写论文"}],"answer":"C","explanation":"“你就不可能使用电脑来写论文，除非你会打字。”这说明“会打字”是“用电脑写论文”的必要条件。“如果你不会指法，那么你就不会打字”说明“会指法”是“会打字”的必要条件。由此可知，“会指法”是“使用电脑写论文”的必要条件。故C正确。","no":441},{"id":"1718789647241","type":"single","material":"","stem":"有统计数据披露，中国科学院新增的35名院士中，八成是高校或研究机构的现任官员；中国工程院新增的48名院士中，超过85%是现任官员；工程院60岁以下新当选的院士，均有校长、院长、副院长等职务。所以有人认为，“官员身份”在院士评选中起了非常大的作用。<br>以下哪一项最能对上述结论构成反驳？","options":[{"label":"A","content":"院士评选没有规定官员不能当选"},{"label":"B","content":"有官员身份的学者占整体的比例不大"},{"label":"C","content":"许多非常优秀的学者担任了行政职务"},{"label":"D","content":"优秀的官员可以兼任学者"}],"answer":"C","explanation":"题干由新增院士中官员的比例高得出结论：“官员身份”在院士评选中起了非常大的作用。A项官员是否能当选与“官员身份”是否起到作用没有关系，为无关项；C项说明是学术水平才是造成“官员身份”的原因，则仍是学术水平在院士评选中起了作用，削弱了结论；B、D项说明官员身份起到了作用，加强了结论。故答案选C。","no":442},{"id":"1718789647242","type":"single","material":"","stem":"甲、乙、丙、丁四人一起去看话剧，买了4张连在一起的座位票。四人各自随机拿了一张票，分别猜了一下座位情况：<br>甲说：“我好像坐在乙旁边。”<br>乙说：“我的左手边不是甲就是丙。”<br>丙说：“我肯定是坐在丁旁边。”<br>丁说：“甲应该是坐在我的左手边。”<br>假如他们四人都猜错了，那么他们面向荧幕从左到右的正确座位可能是：","options":[{"label":"A","content":"丙、甲、丁、乙"},{"label":"B","content":"甲、丙、丁、乙"},{"label":"C","content":"乙、丁、丙、甲"},{"label":"D","content":"丁、乙、丙、甲"}],"answer":"D","explanation":"本题考查的是可能性选项，即合理的情况不止一种，故可从选项着手，排除不可能的选项。由于四人的话都是错的，由乙的话可知乙的左手边是丁，排除C；由丙的话可知丙、丁不相邻，排除B；由丁的话可知甲不在丁的左手边，排除A。故本题选D。","no":443},{"id":"1718789647243","type":"single","material":"","stem":"地方政府对经济的干预不仅表现在直接通过财政投资拉动经济增长，还表现为通过财政补贴、税收优惠、信贷优惠和降低土地等要素成本诱导性地干预企业的投资决策。国有企业因为与政府具有密切的产权关系，其控制权主要掌握在政府手中，这就造成国有企业往往成为政府干预和调控经济的手段。<br>以下各项如果为真，最能支持上述结论的是：","options":[{"label":"A","content":"国有企业的投资决策通常会受到地方政府的直接指导和干预"},{"label":"B","content":"房地产行业前三强者是民营企业，它们多数都享受了信贷优惠"},{"label":"C","content":"钢铁、水泥和电解铝等产能过剩行业中既有国有企业，也有民营企业"},{"label":"D","content":"部分大中型国有企业被政府遴选为“重点企业”，享受税收，信贷优惠"}],"answer":"A","explanation":"题干的结论为：地方政府会诱导性地干预企业投资决策，国有企业往往成为政府干预和调控经济的手段。A项直接加强了结论；B项都是民营企业，不能支持结论；C项既有民营又有国营，且没有体现出政府的干预，也不能支持结论；D项部分国有企业受到政府干预，支持力度不如A项。故答案选A。","no":444},{"id":"1718789647244","type":"single","material":"","stem":"由于按揭贷款的利率下调，人们每月还贷压力减小，因此一家机构预测某地的商品房销售量会增长，但实际上，销售量并未出现明显增长。<br>下列哪项如果为真，最能解释以上现象？","options":[{"label":"A","content":"当地一直存在人口外流的现象"},{"label":"B","content":"本地的商品房价格没有明显下降"},{"label":"C","content":"有的开发商取消了购房优惠政策"},{"label":"D","content":"因经济环境不好，当地人均收入下降"}],"answer":"D","explanation":"题干的现象是：人们每月的还贷压力减小，房地产销售量并未出现明显增长。D项指出经济环境不好当地的人均收入下降，即尽管还贷压力减小了，但人们的购房压力并没有减轻，所以房地产销售量没有上升，很好地解释了题干现象。A、B、C三项均不能有效解释题干现象。故答案选D。","no":445},{"id":"1718789647245","type":"single","material":"","stem":"周末，小李要去酒店参加一次同学聚会，如果不下雨的话他将步行去酒店，否则就乘坐公交车。5点步行出发可以准时到酒店，坐公交则需要更早出发。<br>已知小李准时到达酒店，则下列推测一定正确的是：","options":[{"label":"A","content":"周末没有下雨"},{"label":"B","content":"小李去酒店没有坐公交"},{"label":"C","content":"小李去酒店是步行的"},{"label":"D","content":"小李肯定在5点前（含5点）出发了"}],"answer":"D","explanation":"题干逻辑关系是：不下雨⇒步行，下雨⇒坐公交车；准时到酒店⇒5点步行出发或5点前坐公交车。由“准时到酒店”可推出，D项正确。其他三项都不能确定真假。故答案选D。","no":446},{"id":"1718789647246","type":"single","material":"","stem":"在摩天大楼里工作的人大多数都是白领阶层，英语水平四级以上是成为外企白领的必要条件，外企中只有白领阶层的办公地点设在摩天大楼里。<br>根据以上描述，以下哪项是不正确的？","options":[{"label":"A","content":"在摩天楼里的白领不一定是在外企工作"},{"label":"B","content":"外企中英语水平四级以上的未必是白领"},{"label":"C","content":"英语水平四级以上的白领可能不在摩天大楼里工作"},{"label":"D","content":"外企中英语水平四级以下者可能在摩天大楼里工作"}],"answer":"D","explanation":"题干推理为：①外企白领⇒英语水平四级以上；②在摩天大楼里工作的人⇒白领阶层。否定后件可否定前件，外企中英语水平四级以下者不可能为白领阶层，也就不可能在摩天大楼里工作，D项不正确；其余项均可能正确。故选D。","no":447},{"id":"1718789647247","type":"single","material":"","stem":"母狗生产后对它所生的狗崽立即显示出母性行为。而一只刚生产后的从未接触狗崽的母狗，在一个封闭的地方开始接触一只非自己生的狗崽，七天之后，这只母狗显示出明显的母性行为。如果破坏这只母狗的嗅觉，或者摘除狗崽产生气味的腺体，上述七天的时间将大大缩短。<br>上述断定最能推出下列哪项结论？","options":[{"label":"A","content":"不同母狗所生的狗崽发出不同气味"},{"label":"B","content":"狗崽的气味是母狗产生母性行为的重要诱因"},{"label":"C","content":"非己所生的狗崽的气味是母狗对其产生母性行为的障碍"},{"label":"D","content":"母狗的嗅觉是狗繁衍的障碍"}],"answer":"C","explanation":"由题干可知：在破坏母狗的嗅觉或者摘除狗崽的腺体后，母狗对非自己所生的狗崽显示母性的时间缩短，说明母狗是通过狗崽的气味而产生母性行为的，即非自己所生的狗崽的气味对母狗产生母性行为有阻碍作用，C项正确；A项，题干并未涉及不同母狗生的狗崽的气味，无法推出；B项，题干只是说影响，“诱因”属过度推断；D项为无关项。故答案为C。","no":448},{"id":"1718789647248","type":"single","material":"","stem":"在一次选派学生出国学习交流的讨论中，某辅导员说：“张力各方面表现优秀，我想大家都会同意他出国。”但是，他接着又说：“张力各方面表现优秀，我想没有谁不会不同意的。”<br>由此可以推出：","options":[{"label":"A","content":"该人说话前后矛盾，无法判断该人的意思"},{"label":"B","content":"该人反对张力出国学习交流"},{"label":"C","content":"该人同意张力出国学习交流"},{"label":"D","content":"大家都不反对张力出国学习交流"}],"answer":"A","explanation":"辅导员第一句话表明大家都同意，第二句话“没有谁不会不”是三重否定，等同于否定，即大家不同意，前后明显矛盾。故答案选A。","no":449},{"id":"1718789647249","type":"single","material":"","stem":"小丁把2005年年度统计报告交给樊局长过目，樊局长一眼就看出其中一个统计数字有问题，他对小丁说：“这个统计数字有误，请查查是原始数据有误，还是计算有误？”小丁又仔细地计算了一遍，结果表明计算错了。<br>据此，我们可以认为：","options":[{"label":"A","content":"原始数据有问题"},{"label":"B","content":"原始数据没有错"},{"label":"C","content":"不能肯定原始数据是否错了"},{"label":"D","content":"能够肯定原始数据是否错了"}],"answer":"C","explanation":"题干是相容的选言命题。根据相容选言命题推理规则：肯定一个选言肢，不能否定其余选言肢，则“计算有误”无法判断“原始数据是否有误”。故答案选C。","no":450},{"id":"1718789647250","type":"single","material":"","stem":"没有一个科学家的生命长到能够研究一个物种的演化，却可以通过研究化石和利用自然发展模拟环境等方式，推演出物种发展的过程。这一原则同样适用于对植物的研究，通过推演可以拼凑出生长了几百年甚至上千年的树木的生长过程。<br>以下哪项为真，最能支持上述论断？","options":[{"label":"A","content":"科学研究中的方法和原则可以通用"},{"label":"B","content":"科学研究中对某一阶段事物发展的研究不具备价值"},{"label":"C","content":"对于树木生长过程的研究需要非常长的周期"},{"label":"D","content":"现有的科技手段能够支撑对树木生长过程进行推演"}],"answer":"D","explanation":"题干结论是科学家通过推演可以拼凑出生长了几百年甚至上千年的树木的生长过程。要使这一结论成立，就要保证这种复杂的推演是可行的，即D项，故D项最能支持题干论断。题干已经明确指出这一原则同样适用于对植物的研究，故不需要A项作为支持；B项是无关项；C项研究需要的周期长短也与题干无关。故答案选D。","no":451},{"id":"1718789647251","type":"single","material":"","stem":"在诱惑和选择更多的现代社会，意志力更为重要，有研究者通过意志力试验得出结论：我们每天从同一账户提取意志力用于各种不同任务。因此，一次只做一件事。如果你一心多用，你也许可以暂时兼顾一下，但是随着意志力的消耗，你越来越可能犯严重错误。<br>以下哪项是上述论证所必需的假设？","options":[{"label":"A","content":"你的意志力是有限的，使用就会消耗"},{"label":"B","content":"你一整天做的各种事情之间存在隐秘的关系"},{"label":"C","content":"意志力像肌肉一样，长期锻炼就会增强"},{"label":"D","content":"意志力处于损耗状态时，你觉得烦人的事比平常更烦人，你更容易说让自己后悔的话"}],"answer":"A","explanation":"题干结论为一心多用的话越来越可能犯严重错误。因为我们每天从同一账户提取意志力用于各种不同任务，所以必须假设意志力会随着任务的增多而消耗，即A项。B、D项为无关项；C项削弱了题干论证。故答案选A。","no":452},{"id":"1718789647252","type":"single","material":"","stem":"某网络游戏中有黑天使和白天使，白天使在中了魔法时会说假话，其余时候说真话；黑天使在中了魔法时会说真话，其余时候说假话。某骑士去寻找公主所在的城堡，在他的面前有标号为1、2、3、4的四条道路，他先后问了两个白天使、两个黑天使哪一条是通往城堡的正确道路，有一个黑天使指了1号路，一个黑天使指了4号路，两个白天使都指了3号路。<br>已知四个天使中有两个中了魔法，则通往城堡的正确道路是：","options":[{"label":"A","content":"1号路"},{"label":"B","content":"2号路"},{"label":"C","content":"3号路"},{"label":"D","content":"4号路"}],"answer":"B","explanation":"因两个黑天使指的路不一样，说明他们中至少有一个说假话，则没中魔法。那么至少有一个白天使中了魔法，但两个白天使指的路都一样，说明两个白天使都中了魔法，说假话。可知两个黑天使都没有中魔法，也说假话，所以1、3、4号路都是错的，正确的道路是2号。故答案选B。","no":453},{"id":"1718789647253","type":"single","material":"","stem":"笑容，原本是拉近人与人之间的距离、表达善意的最恰当、最美好的方式，然而，许多笑容也可能有着其他含义。在很多情况下，我们可以分出笑容到底是真诚的还是虚伪的。<br>下列最有可能支持上述论断的是：","options":[{"label":"A","content":"真笑和假笑有着不同的含义，在很多情况下难以区分"},{"label":"B","content":"真笑才能拉近人与人之间的距离"},{"label":"C","content":"对于真笑或假笑，不同的人有着不同的理解"},{"label":"D","content":"人在伪装善意的时候，所展露出来的笑与真心流露的笑是完全不同的"}],"answer":"D","explanation":"题干结论是我们可以分出笑容的真诚和虚伪。A、C两项削弱了题干结论。B项没有涉及对真笑容和假笑容的区分，是无关项。D项说真假笑容是完全不同的，则真假笑容能够被区分，支持了题干结论。故本题选D。","no":454},{"id":"1718789647254","type":"single","material":"","stem":"在一次班会上，老师问大家：“成功的心态应该是怎样的？”郑磊说：“要不断地努力奋斗，活到老学到老。”刘连说：“要保持知足的心态，肯定自己已经取得的成绩。”老师说：“你们的观点都是好的，结合起来才准确：成功的心态既要不断努力，也要知足常乐。”<br>根据老师的说法不能推出的是：","options":[{"label":"A","content":"郑磊和刘连的观点都不全面"},{"label":"B","content":"一个具有知足常乐心态的人，可能是具有成功心态的人"},{"label":"C","content":"一个具有成功心态的人，必定是具有不断努力心态的人"},{"label":"D","content":"不断努力的心态和知足常乐的心态同等重要"}],"answer":"D","explanation":"由老师的话“成功的心态既要不断努力也要知足常乐”可知郑磊和刘连的观点都不全面，A项正确；老师的话是一个充分条件假言命题“成功的心态⇒不断努力和知足常乐”，B项是一种可能性，可以推出；C项肯定前件可以推出肯定后件，而其后件是一个联言命题，C项也可以推出；D项二者是否同等重要并没有涉及，因此不能推出。故答案选D。","no":455},{"id":"1718789647255","type":"single","material":"","stem":"保护思想自由的人争论说，思想自由是智力进步的前提条件，因为思想自由允许思考者追求自己的想法，而不管这些想法会冒犯谁，以及会把他们引到什么方向，然而，一个人必需挖掘出与某些想法相关的充分联系，才能促使智力进步，为此，思考者需要思考法则，所以，关于思想自由的论证是不成立的。<br>以下哪项陈述为真，能够合乎逻辑地得出上文的结论？","options":[{"label":"A","content":"思想自由能够引发创造力，而创造力能够帮助发现真理"},{"label":"B","content":"思考者把他的思想路线局限于某一正统思想，这会阻碍他们的智力进步"},{"label":"C","content":"在那些保护思想自由的社会里，思考者总是缺乏思考法则"},{"label":"D","content":"没有思想法则，思考者就不能拥有思想自由"}],"answer":"D","explanation":"题干在思考法则与思想自由之间缺乏逻辑关系，如果不需要思考法则也可以由思想自由推导出智力进步，则反驳是不成立的，D项在二者之间建立了联系，表明思考法则是思想自由的必要条件，完善了推理。故答案选D。","no":456},{"id":"1718789647256","type":"single","material":"","stem":"现在，不少民意调查都是以在线投票的方式来进行的，但这种调查往往忽略了没有上网习惯的人群的意见，有研究表明：没有上网习惯的人群的意见对民意调查的结果有着十分重要的影响。假设在线投票的人都如实表达了自己的意见，那么以下哪项结论最有可能从上述断定中推出来？","options":[{"label":"A","content":"在进行民意调查时，在线投票这种方式比别的方式更重要"},{"label":"B","content":"在进行民意调查时，街头访谈、电话调查等方式比在线投票更困难"},{"label":"C","content":"在线投票的结果一般能够完全反映民意"},{"label":"D","content":"在线投票的结果通常很难完全反映民意"}],"answer":"D","explanation":"由题干可知在线投票的人都如实表达了自己的意见，但没有上网习惯的人群的意见对民意调查的结果有重要的影响，说明非在线投票部分的人群的意见与在线投票的可能有所差异，即在线投票的结果通常很难完全反映民意。故答案选D。","no":457},{"id":"1718789647257","type":"single","material":"","stem":"有苹果、草莓、香蕉、桔子四种水果，甲、乙、丙、丁四个人每人领一种。甲：“我领到了苹果。”乙：“我领到了桔子。”丙：“甲说谎，他领到了香蕉。”丁：“我领到了草莓。”<br>如果只有两个人说的是真话，则一定可以推出的是：","options":[{"label":"A","content":"乙领到的是桔子"},{"label":"B","content":"丁领到的是草莓"},{"label":"C","content":"丙领到的不是香蕉"},{"label":"D","content":"甲领到的不是苹果"}],"answer":"C","explanation":"甲、丙的话可以转换为：甲：甲领苹果，丙：甲没领苹果且领香蕉，二人必有一假，可以同假，为上反对关系。此时可以假设甲、丙二人均说假话，则甲不领苹果；丙整体为假而前半句为真，所以丙后半句为假，所以甲不领香蕉，乙、丁两人都说真话，分别领到桔子和草莓，这时甲没有领取任何水果，与题干信息矛盾，故甲、丙二人不可同假，故二人一真一假，又四个人的话两真两假，则乙和丁必有一真一假。<br>若甲的话为假，则丙的话为真，此时甲领到了香蕉，苹果被乙和丁之间说假话的人领到，而说假话的人所说的水果被丙领到，这时四个人的水果领取情况为：甲：香蕉；乙：桔子或苹果；丙：桔子或草莓；丁：草莓或苹果。<br>若甲的话为真，则甲领到了苹果，此时若丙领到香蕉，则乙和丁为两真或者两假，这和之前已经推出的乙和丁必有一真一假矛盾，故乙和丁之中说假话的人领到了香蕉，而说假话的人所说的水果被丙领到，这时四个人的水果领取情况为：甲：苹果；乙：桔子或香蕉；丙：桔子或草莓；丁：草莓或香蕉。<br>综上所述，无论如何，都不可能是丙领到香蕉，C项一定可以推出。故答案为C。","no":458},{"id":"1718789647258","type":"single","material":"","stem":"一篇学位论文只有通过了学术诚信审查并获得外审专家的一致通过，才能进入论文答辩环节。<br>下列各项中，除了哪项都符合题干的断定？","options":[{"label":"A","content":"一篇学位论文即便通过了学术诚信审查、获得了外审专家的一致通过，也不一定能进入答辩环节"},{"label":"B","content":"一篇学位论文进入了答辩环节，说明它不仅通过了学术诚信审查而且获得了外审专家的一致通过"},{"label":"C","content":"一篇学位论文要进入答辩环节，通过学术诚信审查和获得外审专家的一致通过，两者缺一不可"},{"label":"D","content":"一篇学位论文不能进入答辩环节，这说明它或者没有通过学术诚信审查，或者没有获得外审专家的一致通过"}],"answer":"D","explanation":"题干是一个必要条件假言命题，进入论文答辩环节⇒通过学术诚信审查并获得外审专家一致通过。肯定前件则肯定后件，因此B、C两项正确；但肯定后件或者否定前件都不能进行有效推理，得不出任何确定的结论，故A项正确，D项错误。故答案选D。","no":459},{"id":"1718789647259","type":"single","material":"","stem":"张导演在为联欢会的最后三个节目进行排序，相邻的节目不能属于同一种类。张导演要从三个小品节目、三个歌曲节目、三个舞蹈节目中进行选择。要排好最后这三个节目，还要满足如下条件：<br>（1）如果第一个节目是小品，则第二个节目是舞蹈；<br>（2）如果第二个节目是歌曲，则第一个节目是舞蹈；<br>（3）如果第三个节目是小品或者舞蹈，则第二个节目是歌曲。<br>请问以下哪项是节目安排的可能次序？","options":[{"label":"A","content":"节目一：小品节目二：舞蹈节目三：舞蹈"},{"label":"B","content":"节目一：小品节目二：歌曲节目三：舞蹈"},{"label":"C","content":"节目一：歌曲节目二：小品节目三：舞蹈"},{"label":"D","content":"节目一：舞蹈节目二：小品节目三：歌曲"}],"answer":"D","explanation":"由“相邻的节目不能属于同一种类”排除A项；B项不符合条件（1），排除；C项不符合条件（3），排除；D项符合题意。故答案选D。","no":460},{"id":"1718789647260","type":"single","material":"","stem":"小王：从举办奥运会的巨额耗费来看，观看各场奥运比赛的票价应该要高得多，是奥运会主办者的广告收入降低了票价，因此，奥运会的现场观众从奥运会拉的广告中获得了经济利益。<br>小李：你的说法不能成立，谁来支付那些看来导致奥运会票价降低的广告费用？到头来还不是消费者，包括作为奥运会现场观众的消费者，因为厂家通过提高商品的价格把广告费用摊到了消费者的身上。<br>下列能够有力地削弱小李对小王反驳的一项是：","options":[{"label":"A","content":"奥运会的票价一般要高于普通的体育比赛的票价"},{"label":"B","content":"奥运会的举办带有越来越浓的商业色彩，引起了普遍的不满"},{"label":"C","content":"利用世界性体育比赛做广告的厂家越来越多，广告费用也越来越高"},{"label":"D","content":"各厂家的广告支出总体上是一个常量，只是在广告形式上有所选择"}],"answer":"D","explanation":"从题干可以知道，小李的观点主要是：由于广告厂商通过提高商品价格，将高额的广告费用转嫁到观众头上，这样奥运会的观众没有从奥运会拉的广告中获得经济利益。要削弱这种说法，就要找出与之相悖的选项。A项是无关项；B项虽然是事实，但却不能证明小李的说法；C项恰好证明了小李的观点；D项由于广告支出是常量，所以广告商也不会因此提高商品价格，消费者能从中获益，削弱了小李的观点。","no":461},{"id":"1718789647261","type":"single","material":"","stem":"由于附近小区住户的不断入住，某银行今年的业务数量比去年有大幅度增加，但是年底结算时发现利润并没有大幅度提高。<br>以下哪项为真，最能解释这个现象？","options":[{"label":"A","content":"银行办理的业务主要是短期业务"},{"label":"B","content":"相比去年，业务的总额并没有增加"},{"label":"C","content":"创造利润多的业务项目的数量并没有增加"},{"label":"D","content":"银行的管理水平不高，成本一直居高不下"}],"answer":"C","explanation":"题干要解释的现象是：某银行业务数量比去年有大幅度增加，但利润并没有大幅度提高。C项说明创造利润多的业务项目的数量并没有增加，故利润没有大幅度提高，很好地解释了题干现象。A项与该现象无关；B项不能解释利润有提高；D项说明以前成本也高，不能解释题干现象。故答案选C。","no":462},{"id":"1718789647262","type":"single","material":"","stem":"审判员在法院工作，这些人在法院工作，所以这些人是审判员。<br>与上述推理的方式最为相似的是？","options":[{"label":"A","content":"动物是由细胞构成的，植物是由细胞构成的，微生物是由细胞构成的。所以全部生物都是由细胞构成的"},{"label":"B","content":"钟表是有一定构造，有规律的；世界也是有一定构造，有规律的；既然钟表是人制造出来的，世界也必然是人创造出来的"},{"label":"C","content":"经过对最近3个月销售的液态奶的跟踪调查，没有发现因有质量问题而退货或者投诉的。因此，可以说这批液态奶是合格的"},{"label":"D","content":"中子是基本粒子，中子是不带电的。因此有些粒子是不带电的"}],"answer":"B","explanation":"题干是一个错误的三段论推理。A项是归纳推理；B项也是错误的三段论推理；C项是错误的概率归纳推理；D项是正确的三段论推理。故答案选B","no":463}]};
